    CONSTRAINT github_runtime_authority_selection_tail_shape CHECK (((preparation_selection_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (preparation_selection_owner_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (preparation_selection_generation > 0) AND (octet_length(preparation_selection_descriptor_digest) = 32) AND (preparation_selection_claimed_at_ms >= 0) AND (preparation_selection_expires_at_ms > preparation_selection_claimed_at_ms) AND ((preparation_selection_expires_at_ms - preparation_selection_claimed_at_ms) <= 900000) AND (activation_selection_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (activation_selection_owner_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (activation_selection_generation > 0) AND (octet_length(activation_selection_input_digest) = 32) AND (activation_selection_claimed_at_ms >= 0) AND (activation_selection_expires_at_ms > activation_selection_claimed_at_ms) AND ((activation_selection_expires_at_ms - activation_selection_claimed_at_ms) <= 900000) AND (materialization_selection_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (materialization_selection_owner_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (materialization_selection_generation > 0) AND (octet_length(materialization_selection_descriptor_digest) = 32) AND (materialization_selection_claimed_at_ms >= 0) AND (materialization_selection_expires_at_ms > materialization_selection_claimed_at_ms) AND ((materialization_selection_expires_at_ms - materialization_selection_claimed_at_ms) <= 900000))),
    CONSTRAINT github_runtime_authority_state CHECK ((state = ANY (ARRAY['claimed'::text, 'minting'::text, 'mint_retry_pending'::text, 'indeterminate'::text, 'ready'::text, 'revoke_pending'::text, 'quarantined'::text, 'rejected'::text, 'revoked'::text]))),
    CONSTRAINT github_runtime_authority_state_shape CHECK (((((state = 'claimed'::text) AND (mint_claim_expires_at_ms IS NOT NULL) AND (mint_started_at_ms IS NULL) AND (next_mint_at_ms IS NULL) AND (indeterminate_at_ms IS NULL) AND (safe_erase_after_ms IS NULL) AND (envelope_schema IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (rejected_at_ms IS NULL) AND (quarantine_at_ms IS NULL) AND (revoke_attempt_count = 0) AND (revoke_claim_fence = 0) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (last_revoke_failure_kind IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL) AND (state_updated_at_ms = mint_claimed_at_ms)) OR ((state = 'minting'::text) AND (mint_claim_expires_at_ms IS NULL) AND (mint_started_at_ms = state_updated_at_ms) AND (next_mint_at_ms IS NULL) AND (indeterminate_at_ms IS NULL) AND (safe_erase_after_ms IS NULL) AND (envelope_schema IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (rejected_at_ms IS NULL) AND (quarantine_at_ms IS NULL) AND (revoke_attempt_count = 0) AND (revoke_claim_fence = 0) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (last_revoke_failure_kind IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL)) OR ((state = 'mint_retry_pending'::text) AND (mint_claim_expires_at_ms IS NULL) AND (mint_started_at_ms IS NOT NULL) AND (next_mint_at_ms IS NOT NULL) AND (last_mint_rejection_kind IS NOT NULL) AND (indeterminate_at_ms IS NULL) AND (safe_erase_after_ms IS NULL) AND (envelope_schema IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (rejected_at_ms IS NULL) AND (quarantine_at_ms IS NULL) AND (revoke_attempt_count = 0) AND (revoke_claim_fence = 0) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (last_revoke_failure_kind IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL)) OR ((state = 'indeterminate'::text) AND (mint_claim_expires_at_ms IS NULL) AND (mint_started_at_ms IS NOT NULL) AND (next_mint_at_ms IS NULL) AND (indeterminate_at_ms = state_updated_at_ms) AND (safe_erase_after_ms IS NULL) AND (envelope_schema IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (rejected_at_ms IS NULL) AND (quarantine_at_ms IS NULL) AND (revoke_attempt_count = 0) AND (revoke_claim_fence = 0) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (last_revoke_failure_kind IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL)) OR ((state = 'ready'::text) AND (mint_claim_expires_at_ms IS NULL) AND (mint_started_at_ms IS NOT NULL) AND (next_mint_at_ms IS NULL) AND (commit_disposition = 'deliverable'::text) AND (provider_expires_at_ms IS NOT NULL) AND ((provider_expires_at_ms)::numeric > ((state_updated_at_ms)::numeric + (60000)::numeric)) AND (envelope_schema IS NOT NULL) AND (ready_at_ms = state_updated_at_ms) AND (revoke_pending_at_ms IS NULL) AND (rejected_at_ms IS NULL) AND (quarantine_at_ms IS NULL) AND (revoke_attempt_count = 0) AND (revoke_claim_fence = 0) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (last_revoke_failure_kind IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL)) OR ((state = 'revoke_pending'::text) AND (mint_claim_expires_at_ms IS NULL) AND (mint_started_at_ms IS NOT NULL) AND (next_mint_at_ms IS NULL) AND (safe_erase_after_ms IS NOT NULL) AND (envelope_schema IS NOT NULL) AND (revoke_pending_at_ms IS NOT NULL) AND (rejected_at_ms IS NULL) AND (quarantine_at_ms IS NULL) AND (((revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NOT NULL) AND (next_revoke_at_ms >= revoke_pending_at_ms) AND (next_revoke_at_ms <= safe_erase_after_ms)) OR ((revoke_claim_owner_id IS NOT NULL) AND (next_revoke_at_ms IS NULL))) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL)) OR ((state = 'quarantined'::text) AND (mint_claim_expires_at_ms IS NULL) AND (safe_erase_after_ms IS NOT NULL) AND (envelope_schema IS NOT NULL) AND (quarantine_at_ms = state_updated_at_ms) AND (state_updated_at_ms < safe_erase_after_ms) AND (rejected_at_ms IS NULL) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason IS NULL)) OR ((state = 'rejected'::text) AND (mint_claim_expires_at_ms IS NULL) AND (mint_started_at_ms IS NOT NULL) AND (next_mint_at_ms IS NULL) AND (last_mint_rejection_kind IS NOT NULL) AND (indeterminate_at_ms IS NULL) AND (safe_erase_after_ms IS NULL) AND (envelope_schema IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (rejected_at_ms = state_updated_at_ms) AND (quarantine_at_ms IS NULL) AND (revoke_attempt_count = 0) AND (revoke_claim_fence = 0) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (last_revoke_failure_kind IS NULL) AND (revoked_at_ms IS NULL) AND (terminal_reason = ANY (ARRAY['provider_mint_rejected'::text, 'provider_mint_retry_expired'::text]))) OR ((state = 'revoked'::text) AND (mint_claim_expires_at_ms IS NULL) AND (envelope_schema IS NULL) AND (revoke_claim_owner_id IS NULL) AND (next_revoke_at_ms IS NULL) AND (rejected_at_ms IS NULL) AND (revoked_at_ms = state_updated_at_ms) AND (terminal_reason IS NOT NULL) AND (((terminal_reason = ANY (ARRAY['superseded_before_mint'::text, 'request_expired_before_mint'::text])) AND (mint_started_at_ms IS NULL) AND (indeterminate_at_ms IS NULL) AND (safe_erase_after_ms IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (quarantine_at_ms IS NULL)) OR ((terminal_reason = 'indeterminate_authority_expired'::text) AND (mint_started_at_ms IS NOT NULL) AND (safe_erase_after_ms IS NULL) AND (ready_at_ms IS NULL) AND (revoke_pending_at_ms IS NULL) AND (quarantine_at_ms IS NULL)) OR ((terminal_reason = ANY (ARRAY['provider_revocation_confirmed'::text, 'provider_authority_expired'::text, 'conservative_authority_expired'::text])) AND (mint_started_at_ms IS NOT NULL) AND (safe_erase_after_ms IS NOT NULL) AND ((ready_at_ms IS NOT NULL) OR (revoke_pending_at_ms IS NOT NULL)) AND (quarantine_at_ms IS NULL)) OR ((terminal_reason = 'quarantined_authority_expired'::text) AND (mint_started_at_ms IS NOT NULL) AND (safe_erase_after_ms IS NOT NULL) AND (quarantine_at_ms IS NOT NULL))))) IS TRUE)),
    CONSTRAINT github_runtime_authority_state_time_monotonic CHECK (((state_updated_at_ms >= requested_at_ms) AND ((mint_started_at_ms IS NULL) OR (mint_started_at_ms >= mint_claimed_at_ms)) AND ((indeterminate_at_ms IS NULL) OR (indeterminate_at_ms >= mint_started_at_ms)) AND ((ready_at_ms IS NULL) OR (ready_at_ms >= mint_started_at_ms)) AND ((revoke_pending_at_ms IS NULL) OR (revoke_pending_at_ms >= mint_started_at_ms)) AND ((rejected_at_ms IS NULL) OR (rejected_at_ms >= mint_started_at_ms)) AND ((quarantine_at_ms IS NULL) OR (quarantine_at_ms >= mint_started_at_ms)) AND ((revoked_at_ms IS NULL) OR (revoked_at_ms >= requested_at_ms)))),
    CONSTRAINT github_runtime_authority_terminal_reason CHECK (((terminal_reason IS NULL) OR (terminal_reason = ANY (ARRAY['superseded_before_mint'::text, 'request_expired_before_mint'::text, 'provider_mint_rejected'::text, 'provider_mint_retry_expired'::text, 'provider_revocation_confirmed'::text, 'provider_authority_expired'::text, 'conservative_authority_expired'::text, 'indeterminate_authority_expired'::text, 'quarantined_authority_expired'::text]))))
);

CREATE FUNCTION automata_github_runtime_authority_has_selection_tails(authority github_runtime_authority_issuances) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM logical_workflow_concrete_jobs AS concrete
        JOIN logical_workflow_materialization_claims AS materialization
          ON materialization.instance_id = concrete.instance_id
         AND materialization.run_id = concrete.run_id
         AND materialization.invocation_id = concrete.invocation_id
         AND materialization.logical_job_id = concrete.logical_job_id
         AND materialization.descriptor_digest = concrete.descriptor_digest
         AND materialization.expected_job_id = concrete.job_id
         AND materialization.expected_attempt_id = concrete.initial_attempt_id
        JOIN logical_workflow_jobs AS logical_job
          ON logical_job.run_id = concrete.run_id
         AND logical_job.invocation_id = concrete.invocation_id
         AND logical_job.id = concrete.logical_job_id
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = logical_job.run_id
         AND publication.invocation_id = logical_job.invocation_id
         AND publication.logical_job_id = logical_job.id
         AND publication.activation_input_digest =
             logical_job.activation_input_digest
        JOIN logical_workflow_activation_preparations AS preparation
          ON preparation.run_id = publication.run_id
         AND preparation.invocation_id = publication.invocation_id
         AND preparation.logical_job_id = publication.logical_job_id
         AND preparation.activation_input_digest =
             publication.activation_input_digest
        JOIN logical_workflow_activation_preparation_claims AS preparation_claim
          ON preparation_claim.run_id = preparation.run_id
         AND preparation_claim.invocation_id = preparation.invocation_id
         AND preparation_claim.logical_job_id = preparation.logical_job_id
         AND preparation_claim.descriptor_digest = preparation.descriptor_digest
        JOIN logical_workflow_activation_work_selections AS preparation_selection
          ON preparation_selection.selection_id =
             authority.preparation_selection_id
         AND preparation_selection.outcome = 'claimed'
         AND preparation_selection.tenant_id = authority.tenant_id
         AND preparation_selection.run_id = authority.run_id
         AND preparation_selection.invocation_id = concrete.invocation_id
         AND preparation_selection.logical_job_id = concrete.logical_job_id
         AND preparation_selection.authority_kind = 'preparation'
         AND preparation_selection.owner_id =
             authority.preparation_selection_owner_id
         AND preparation_selection.authority_digest =
             authority.preparation_selection_descriptor_digest
        JOIN logical_workflow_activation_work_selections AS activation_selection
          ON activation_selection.selection_id = authority.activation_selection_id
         AND activation_selection.outcome = 'claimed'
         AND activation_selection.tenant_id = authority.tenant_id
         AND activation_selection.run_id = authority.run_id
         AND activation_selection.invocation_id = concrete.invocation_id
         AND activation_selection.logical_job_id = concrete.logical_job_id
         AND activation_selection.authority_kind = 'activation'
         AND activation_selection.owner_id = authority.activation_selection_owner_id
         AND activation_selection.authority_digest =
             authority.activation_selection_input_digest
        JOIN logical_workflow_materialization_work_selections AS materialization_selection
          ON materialization_selection.selection_id =
             authority.materialization_selection_id
         AND materialization_selection.outcome = 'claimed'
         AND materialization_selection.tenant_id = authority.tenant_id
         AND materialization_selection.run_id = authority.run_id
         AND materialization_selection.invocation_id = concrete.invocation_id
         AND materialization_selection.logical_job_id = concrete.logical_job_id
         AND materialization_selection.instance_id = concrete.instance_id
         AND materialization_selection.owner_id =
             authority.materialization_selection_owner_id
         AND materialization_selection.authority_digest =
             authority.materialization_selection_descriptor_digest
        WHERE concrete.job_id = authority.job_id
          AND concrete.run_id = authority.run_id
          AND preparation_claim.origin_selection_id =
              authority.preparation_selection_id
          AND preparation_claim.owner_id =
              authority.preparation_selection_owner_id
          AND preparation_claim.generation =
              authority.preparation_selection_generation
          AND preparation_claim.descriptor_digest =
              authority.preparation_selection_descriptor_digest
          AND preparation_claim.claimed_at_ms =
              authority.preparation_selection_claimed_at_ms
          AND preparation_claim.expires_at_ms =
              authority.preparation_selection_expires_at_ms
          AND logical_job.activation_origin_selection_id =
              authority.activation_selection_id
          AND logical_job.activation_fence = authority.activation_selection_generation
          AND logical_job.activation_input_digest =
              authority.activation_selection_input_digest
          AND publication.activation_owner_id =
              authority.activation_selection_owner_id
          AND publication.activation_generation =
              authority.activation_selection_generation
          AND publication.activation_input_digest =
              authority.activation_selection_input_digest
          AND publication.activation_claimed_at_ms =
              authority.activation_selection_claimed_at_ms
          AND publication.activation_expires_at_ms =
              authority.activation_selection_expires_at_ms
          AND materialization.origin_selection_id =
              authority.materialization_selection_id
          AND materialization.owner_id = authority.materialization_selection_owner_id
          AND materialization.generation = authority.materialization_selection_generation
          AND materialization.descriptor_digest =
              authority.materialization_selection_descriptor_digest
          AND materialization.claimed_at_ms =
              authority.materialization_selection_claimed_at_ms
          AND materialization.expires_at_ms =
              authority.materialization_selection_expires_at_ms
          AND (
              (
                  preparation_selection.generation =
                      authority.preparation_selection_generation
                  AND preparation_selection.claimed_at_ms =
                      authority.preparation_selection_claimed_at_ms
                  AND preparation_selection.expires_at_ms =
                      authority.preparation_selection_expires_at_ms
              ) OR EXISTS (
                  SELECT 1
                  FROM logical_workflow_activation_renewal_receipts AS renewal
                  WHERE renewal.selection_id = authority.preparation_selection_id
                    AND renewal.logical_job_id = concrete.logical_job_id
                    AND renewal.authority_kind = 'preparation'
                    AND renewal.owner_id = authority.preparation_selection_owner_id
                    AND renewal.authority_digest =
                        authority.preparation_selection_descriptor_digest
                    AND renewal.runtime_policy_revision =
                        preparation_claim.runtime_policy_revision
                    AND renewal.runtime_policy_digest =
                        preparation_claim.runtime_policy_digest
                    AND renewal.successor_generation =
                        authority.preparation_selection_generation
                    AND renewal.successor_claimed_at_ms =
                        authority.preparation_selection_claimed_at_ms
                    AND renewal.successor_expires_at_ms =
                        authority.preparation_selection_expires_at_ms
              )
          )
          AND (
              (
                  activation_selection.generation =
                      authority.activation_selection_generation
                  AND activation_selection.claimed_at_ms =
                      authority.activation_selection_claimed_at_ms
                  AND activation_selection.expires_at_ms =
                      authority.activation_selection_expires_at_ms
              ) OR EXISTS (
                  SELECT 1
                  FROM logical_workflow_activation_renewal_receipts AS renewal
                  WHERE renewal.selection_id = authority.activation_selection_id
                    AND renewal.logical_job_id = concrete.logical_job_id
                    AND renewal.authority_kind = 'activation'
                    AND renewal.owner_id = authority.activation_selection_owner_id
                    AND renewal.authority_digest =
                        authority.activation_selection_input_digest
                    AND renewal.runtime_policy_revision =
                        logical_job.runtime_policy_revision
                    AND renewal.runtime_policy_digest =
                        logical_job.runtime_policy_digest
                    AND renewal.successor_generation =
                        authority.activation_selection_generation
                    AND renewal.successor_claimed_at_ms =
                        authority.activation_selection_claimed_at_ms
                    AND renewal.successor_expires_at_ms =
                        authority.activation_selection_expires_at_ms
              )
          )
          AND (
              (
                  materialization_selection.generation =
                      authority.materialization_selection_generation
                  AND materialization_selection.claimed_at_ms =
                      authority.materialization_selection_claimed_at_ms
                  AND materialization_selection.expires_at_ms =
                      authority.materialization_selection_expires_at_ms
              ) OR EXISTS (
                  SELECT 1
                  FROM logical_workflow_materialization_renewal_receipts AS renewal
                  WHERE renewal.selection_id = authority.materialization_selection_id
                    AND renewal.instance_id = concrete.instance_id
                    AND renewal.owner_id =
                        authority.materialization_selection_owner_id
                    AND renewal.authority_digest =
                        authority.materialization_selection_descriptor_digest
                    AND renewal.runtime_policy_revision =
                        materialization.runtime_policy_revision
                    AND renewal.runtime_policy_digest =
                        materialization.runtime_policy_digest
                    AND renewal.expected_job_id = concrete.job_id
                    AND renewal.expected_attempt_id = concrete.initial_attempt_id
                    AND renewal.successor_generation =
                        authority.materialization_selection_generation
                    AND renewal.successor_claimed_at_ms =
                        authority.materialization_selection_claimed_at_ms
                    AND renewal.successor_expires_at_ms =
                        authority.materialization_selection_expires_at_ms
              )
          )
    )
$$;

CREATE FUNCTION automata_github_runtime_authority_has_provenance(authority github_runtime_authority_issuances) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT automata_github_runtime_authority_has_selection_tails(authority)
       AND EXISTS (
        SELECT 1
        FROM github_workflow_run_manifest_origins AS origin
        JOIN github_provider_manifest_revisions AS manifest
          ON manifest.tenant_id = origin.tenant_id
         AND manifest.repository_id = origin.repository_id
         AND manifest.provider_connection_id = origin.provider_connection_id
         AND manifest.manifest_revision = origin.provider_manifest_revision
         AND manifest.manifest_digest = origin.provider_manifest_digest
        JOIN github_server_service_authorities AS checks
          ON checks.tenant_id = origin.tenant_id
         AND checks.id = origin.checks_authority_id
         AND checks.repository_id = origin.repository_id
         AND checks.provider_connection_id = origin.provider_connection_id
         AND checks.provider_installation_id = origin.provider_installation_id
         AND checks.github_repository_id = origin.github_repository_id
         AND checks.github_repository_name = origin.github_repository_name
         AND checks.service_scope = 'checks_write'
         AND checks.identity_digest = origin.checks_authority_identity_digest
         AND checks.app_configuration_revision =
             origin.checks_authority_app_configuration_revision
         AND checks.policy_revision = origin.checks_authority_policy_revision
        LEFT JOIN github_server_service_authorities AS private_authority
          ON private_authority.tenant_id = origin.tenant_id
         AND private_authority.id = origin.private_source_authority_id
         AND private_authority.repository_id = origin.repository_id
         AND private_authority.provider_connection_id =
             origin.provider_connection_id
         AND private_authority.provider_installation_id =
             origin.provider_installation_id
         AND private_authority.github_repository_id = origin.github_repository_id
         AND private_authority.github_repository_name =
             origin.github_repository_name
         AND private_authority.service_scope = 'private_repository_source_read'
         AND private_authority.identity_digest =
             origin.private_source_authority_identity_digest
         AND private_authority.app_configuration_revision =
             origin.private_source_authority_app_configuration_revision
         AND private_authority.policy_revision =
             origin.private_source_authority_policy_revision
        JOIN workflow_admission_receipts AS admission
          ON admission.tenant_id = origin.tenant_id
         AND admission.idempotency_kind = origin.admission_idempotency_kind
         AND admission.idempotency_key = origin.admission_idempotency_key
         AND admission.request_digest = origin.logical_admission_digest
         AND admission.repository_id = origin.repository_id
         AND admission.run_id = origin.run_id
         AND admission.committed_at_ms = origin.admitted_at_ms
         AND admission.github_subject_evidence_required
        JOIN logical_workflow_runtime_policy_pins AS pin
          ON pin.run_id = origin.run_id
         AND pin.tenant_id = origin.tenant_id
         AND pin.repository_id = origin.repository_id
        JOIN workflow_runtime_policy_revisions AS policy
          ON policy.tenant_id = pin.tenant_id
         AND policy.repository_id = pin.repository_id
         AND policy.policy_revision = pin.policy_revision
         AND policy.policy_digest = pin.policy_digest
         AND policy.state = 'sealed'
        JOIN logical_workflow_concrete_jobs AS concrete
          ON concrete.job_id = authority.job_id
         AND concrete.run_id = authority.run_id
        JOIN logical_workflow_materialization_claims AS materialization
          ON materialization.instance_id = concrete.instance_id
         AND materialization.run_id = concrete.run_id
         AND materialization.invocation_id = concrete.invocation_id
         AND materialization.logical_job_id = concrete.logical_job_id
         AND materialization.descriptor_digest = concrete.descriptor_digest
         AND materialization.expected_job_id = concrete.job_id
         AND materialization.expected_attempt_id = concrete.initial_attempt_id
         AND materialization.owner_id = concrete.claim_owner_id
         AND materialization.generation = concrete.claim_generation
         AND materialization.claimed_at_ms = concrete.claim_started_at_ms
         AND materialization.expires_at_ms = concrete.claim_expires_at_ms
         AND materialization.updated_at_ms = concrete.committed_at_ms
        JOIN logical_workflow_instances AS instance
          ON instance.id = concrete.instance_id
         AND instance.run_id = concrete.run_id
         AND instance.invocation_id = concrete.invocation_id
         AND instance.logical_job_id = concrete.logical_job_id
        JOIN logical_workflow_activation_publications AS activation_publication
          ON activation_publication.run_id = instance.run_id
         AND activation_publication.invocation_id = instance.invocation_id
         AND activation_publication.logical_job_id = instance.logical_job_id
        JOIN logical_workflow_activation_preparations AS preparation
          ON preparation.run_id = activation_publication.run_id
         AND preparation.invocation_id = activation_publication.invocation_id
         AND preparation.logical_job_id = activation_publication.logical_job_id
         AND preparation.activation_input_digest =
             activation_publication.activation_input_digest
        JOIN logical_workflow_activation_preparation_claims AS preparation_claim
          ON preparation_claim.run_id = preparation.run_id
         AND preparation_claim.invocation_id = preparation.invocation_id
         AND preparation_claim.logical_job_id = preparation.logical_job_id
         AND preparation_claim.descriptor_digest = preparation.descriptor_digest
        JOIN logical_workflow_jobs AS logical_job
          ON logical_job.run_id = concrete.run_id
         AND logical_job.invocation_id = concrete.invocation_id
         AND logical_job.id = concrete.logical_job_id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = concrete.run_id
         AND invocation.id = concrete.invocation_id
        JOIN logical_workflow_runs AS marker
          ON marker.run_id = concrete.run_id
        WHERE origin.tenant_id = authority.tenant_id
          AND origin.repository_id = authority.repository_id
          AND origin.run_id = authority.run_id
          AND origin.origin_kind IN (
              'provider_delivery', 'scheduled_fire', 'workflow_rerun'
          )
          AND (
              origin.repository_visibility = 'public'
              AND origin.private_source_authority_id IS NULL
              AND private_authority.id IS NULL
              OR origin.repository_visibility = 'private'
              AND private_authority.id IS NOT NULL
              AND private_authority.github_app_id = manifest.github_app_id
              AND private_authority.github_app_client_id =
                  manifest.github_app_client_id
              AND private_authority.github_app_jwt_issuer_kind =
                  manifest.github_app_jwt_issuer_kind
              AND private_authority.app_key_spki_sha256 =
                  manifest.app_key_spki_sha256
              AND private_authority.app_configuration_revision =
                  manifest.app_configuration_revision
              AND private_authority.policy_revision = manifest.policy_revision
          )
          AND origin.provider_connection_id = authority.provider_connection_id
          AND origin.provider_installation_id =
              authority.provider_installation_id
          AND origin.github_repository_id = authority.github_repository_id
          AND origin.github_repository_name = authority.github_repository_name
          AND manifest.github_app_id = authority.github_app_id
          AND manifest.github_app_client_id = authority.github_app_client_id
          AND manifest.github_app_jwt_issuer_kind =
              authority.github_app_jwt_issuer_kind
          AND authority.github_app_jwt_issuer_value =
              CASE manifest.github_app_jwt_issuer_kind
                  WHEN 'app_client_id' THEN manifest.github_app_client_id
                  WHEN 'app_id' THEN manifest.github_app_id::TEXT
              END
          AND manifest.app_key_spki_sha256 = authority.issuer_fingerprint
          AND manifest.github_app_id = checks.github_app_id
          AND manifest.github_app_client_id = checks.github_app_client_id
          AND manifest.github_app_jwt_issuer_kind =
              checks.github_app_jwt_issuer_kind
          AND manifest.app_key_spki_sha256 = checks.app_key_spki_sha256
          AND manifest.app_configuration_revision =
              checks.app_configuration_revision
          AND manifest.policy_revision = checks.policy_revision
          AND checks.configuration_fingerprint =
              authority.configuration_fingerprint
          AND marker.root_invocation_id = origin.root_invocation_id
          AND marker.admission_digest = origin.logical_admission_digest
          AND marker.admitted_at_ms = origin.admitted_at_ms
          AND automata_logical_workflow_invocation_published(
              concrete.run_id, concrete.invocation_id
          )
          AND invocation.plan_schema = 1
          AND manifest.runtime_policy_revision = pin.policy_revision
          AND manifest.runtime_policy_digest = pin.policy_digest
          AND manifest.runner_policy_digest =
              pg_catalog.sha256(policy.canonical_policy)
          AND manifest.runner_policy_object_key = 'github/runner-policy/v1/'
              || pg_catalog.encode(manifest.runner_policy_digest, 'hex') || '.json'
          AND manifest.runner_policy_size_bytes =
              pg_catalog.octet_length(policy.canonical_policy)
          AND manifest.runner_policy_media_type =
              'application/vnd.automata.github-runner-policy+json'
          AND logical_job.runtime_policy_revision = pin.policy_revision
          AND logical_job.runtime_policy_digest = pin.policy_digest
          AND preparation_claim.runtime_policy_revision = pin.policy_revision
          AND preparation_claim.runtime_policy_digest = pin.policy_digest
          AND preparation_claim.runner_policy_digest =
              manifest.runner_policy_digest
          AND preparation_claim.runner_policy_object_key =
              manifest.runner_policy_object_key
          AND preparation_claim.runner_policy_size_bytes =
              manifest.runner_policy_size_bytes
          AND preparation_claim.runner_policy_media_type =
              manifest.runner_policy_media_type
          AND preparation.runtime_policy_revision = pin.policy_revision
          AND preparation.runtime_policy_digest = pin.policy_digest
          AND activation_publication.runtime_policy_revision = pin.policy_revision
          AND activation_publication.runtime_policy_digest = pin.policy_digest
          AND instance.runtime_policy_revision = pin.policy_revision
          AND instance.runtime_policy_digest = pin.policy_digest
          AND materialization.runtime_policy_revision = pin.policy_revision
          AND materialization.runtime_policy_digest = pin.policy_digest
          AND concrete.runtime_policy_revision = pin.policy_revision
          AND concrete.runtime_policy_digest = pin.policy_digest
          AND logical_job.authority_profile = 'standard'
          AND preparation_claim.authority_profile = 'standard'
          AND preparation.authority_profile = 'standard'
          AND activation_publication.authority_profile = 'standard'
          AND materialization.authority_profile = 'standard'
          AND concrete.authority_profile = 'standard'
    )
$$;

CREATE FUNCTION automata_github_runtime_authority_hash_bytes(value bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT pg_catalog.int8send(pg_catalog.octet_length(value)::BIGINT) || value
$$;

CREATE FUNCTION automata_github_runtime_authority_is_current(authority github_runtime_authority_issuances, observed_at bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT automata_github_runtime_authority_base_is_current(authority, observed_at)
       AND automata_github_runtime_authority_has_provenance(authority)
$$;

CREATE FUNCTION automata_github_runtime_authority_lease_final_exact(checked_attempt_id uuid, checked_fencing_token bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM runners AS runner
        JOIN runner_sessions AS session
          ON session.runner_id = runner.id
        JOIN job_attempts AS attempt
          ON attempt.runner_id = runner.id
         AND attempt.runner_session_id = session.id
        JOIN github_runtime_authority_issuances AS authority
          ON attempt.id = authority.attempt_id
         AND attempt.job_id = authority.job_id
        JOIN github_runtime_authority_lease_renewal_receipts AS tail
          ON tail.attempt_id = authority.attempt_id
         AND tail.fencing_token = authority.fencing_token
         AND tail.lease_id = authority.lease_id
         AND tail.runner_id = authority.runner_id
         AND tail.runner_session_id = authority.runner_session_id
         AND tail.runner_session_epoch = authority.runner_session_epoch
         AND tail.runner_generation = authority.runner_generation
         AND tail.renewed_lease_expires_at_ms = attempt.lease_expires_at_ms
         AND tail.authorized_at_ms = attempt.changed_at_ms
        WHERE authority.attempt_id = checked_attempt_id
          AND authority.fencing_token = checked_fencing_token
          AND authority.state = 'ready'
          AND attempt.fencing_token = authority.fencing_token
          AND attempt.lease_id = authority.lease_id
          AND attempt.lease_issued_at_ms = authority.lease_issued_at_ms
          AND attempt.runner_id = authority.runner_id
          AND attempt.runner_session_id = authority.runner_session_id
          AND attempt.runner_session_epoch = authority.runner_session_epoch
          AND attempt.runner_generation = authority.runner_generation
          AND attempt.lifecycle IN ('leased', 'preparing', 'running', 'cancelling')
          AND attempt.changed_at_ms < attempt.lease_expires_at_ms
          AND runner.id = authority.runner_id
          AND runner.tenant_id = authority.tenant_id
          AND runner.generation = authority.runner_generation
          AND runner.session_epoch = authority.runner_session_epoch
          AND runner.status = 'online'
          AND runner.desired_state IN ('active', 'draining')
          AND session.id = authority.runner_session_id
          AND session.session_epoch = authority.runner_session_epoch
          AND session.runner_generation = authority.runner_generation
          AND session.disconnected_at_ms IS NULL
          AND session.job_ir_schema = 1
          AND NOT EXISTS (
              SELECT 1
              FROM github_runtime_authority_lease_renewal_receipts AS successor
              WHERE successor.attempt_id = tail.attempt_id
                AND successor.fencing_token = tail.fencing_token
                AND successor.previous_lease_expires_at_ms =
                    tail.renewed_lease_expires_at_ms
          )
    )
$$;

CREATE FUNCTION automata_github_runtime_authority_lease_horizon_is_tail(authority github_runtime_authority_issuances, horizon bigint, observed_at bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT (
        horizon = authority.lease_expires_at_ms
        AND NOT EXISTS (
            SELECT 1
            FROM github_runtime_authority_lease_renewal_receipts AS any_renewal
            WHERE any_renewal.attempt_id = authority.attempt_id
              AND any_renewal.fencing_token = authority.fencing_token
        )
    ) OR EXISTS (
        SELECT 1
        FROM github_runtime_authority_lease_renewal_receipts AS tail
        WHERE tail.attempt_id = authority.attempt_id
          AND tail.fencing_token = authority.fencing_token
          AND tail.lease_id = authority.lease_id
          AND tail.runner_id = authority.runner_id
          AND tail.runner_session_id = authority.runner_session_id
          AND tail.runner_session_epoch = authority.runner_session_epoch
          AND tail.runner_generation = authority.runner_generation
          AND tail.renewed_lease_expires_at_ms = horizon
          AND tail.authorized_at_ms <= observed_at
          AND NOT EXISTS (
              SELECT 1
              FROM github_runtime_authority_lease_renewal_receipts AS successor
              WHERE successor.attempt_id = tail.attempt_id
                AND successor.fencing_token = tail.fencing_token
                AND successor.previous_lease_expires_at_ms =
                    tail.renewed_lease_expires_at_ms
          )
    )
$$;

CREATE FUNCTION automata_github_runtime_authority_operation_digest(request_kind text, attempt_id uuid, fencing_token bigint, claim_fence bigint, claim_owner_id uuid, claim_claimed_at_ms bigint, claim_expires_at_ms bigint, observed_at_ms bigint, retry_at_ms bigint, failure_kind text, commit_disposition text, provider_expires_at_ms bigint, safe_erase_after_ms bigint, plaintext_schema integer, plaintext_size_bytes bigint, plaintext_digest bytea, aad_digest bytea, envelope_digest bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE
        WHEN request_kind = 'mint_commit' THEN pg_catalog.sha256(
            pg_catalog.convert_to(
                'automata.store.github-runtime-authority-operation.mint-commit.v4',
                'UTF8'
            ) || pg_catalog.decode('00', 'hex')
            || pg_catalog.uuid_send(attempt_id)
            || pg_catalog.int8send(fencing_token)
            || pg_catalog.uuid_send(claim_owner_id)
            || pg_catalog.int8send(claim_fence)
            || pg_catalog.int8send(claim_claimed_at_ms)
            || pg_catalog.int8send(claim_expires_at_ms)
            || automata_github_runtime_authority_hash_bytes(
                pg_catalog.convert_to(commit_disposition, 'UTF8')
            )
            || pg_catalog.int8send(observed_at_ms)
            || CASE WHEN provider_expires_at_ms IS NULL
                THEN pg_catalog.decode('00', 'hex')
                ELSE pg_catalog.decode('01', 'hex')
                    || pg_catalog.int8send(provider_expires_at_ms)
            END
            || pg_catalog.int8send(safe_erase_after_ms)
            || pg_catalog.int2send(plaintext_schema::SMALLINT)
            || pg_catalog.int8send(plaintext_size_bytes)
            || plaintext_digest || aad_digest || envelope_digest
        )
        WHEN request_kind = 'quarantine' THEN pg_catalog.sha256(
            pg_catalog.convert_to(
                'automata.store.github-runtime-authority-operation.quarantine.v4',
                'UTF8'
            ) || pg_catalog.decode('00', 'hex')
            || pg_catalog.uuid_send(attempt_id)
            || pg_catalog.int8send(fencing_token)
            || aad_digest
            || automata_github_runtime_authority_hash_bytes(
                pg_catalog.convert_to(failure_kind, 'UTF8')
            )
            || pg_catalog.int8send(observed_at_ms)
        )
        WHEN request_kind IN (
            'revocation_retry', 'revocation_defer', 'revocation_confirm'
        ) THEN pg_catalog.sha256(
            pg_catalog.convert_to(
                'automata.store.github-runtime-authority-operation.revocation-outcome.v4',
                'UTF8'
            ) || pg_catalog.decode('00', 'hex')
            || automata_github_runtime_authority_hash_bytes(
                pg_catalog.convert_to(
                    CASE request_kind
                        WHEN 'revocation_retry' THEN 'retry'
                        WHEN 'revocation_defer' THEN 'defer'
                        ELSE 'confirm'
                    END,
                    'UTF8'
                )
            )
            || pg_catalog.uuid_send(attempt_id)
            || pg_catalog.int8send(fencing_token)
            || pg_catalog.uuid_send(claim_owner_id)
            || pg_catalog.int8send(claim_fence)
            || pg_catalog.int8send(claim_claimed_at_ms)
            || pg_catalog.int8send(claim_expires_at_ms)
            || CASE WHEN request_kind = 'revocation_confirm' THEN ''::BYTEA
                    ELSE automata_github_runtime_authority_hash_bytes(
                        pg_catalog.convert_to(failure_kind, 'UTF8')
                    )
               END
            || pg_catalog.int8send(observed_at_ms)
            || CASE WHEN request_kind = 'revocation_retry'
                    THEN pg_catalog.int8send(retry_at_ms)
                    ELSE ''::BYTEA
               END
        )
    END
$$;

CREATE FUNCTION automata_github_runtime_authority_same_non_operation_state(prior github_runtime_authority_issuances, candidate github_runtime_authority_issuances) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT (
        to_jsonb(candidate) - ARRAY[
            'operation_request_kind', 'operation_request_claim_fence',
            'operation_request_claim_owner_id',
            'operation_request_observed_at_ms',
            'operation_request_retry_at_ms',
            'operation_request_failure_kind',
            'operation_request_commit_disposition',
            'operation_request_provider_expires_at_ms',
            'operation_request_safe_erase_after_ms',
            'operation_request_plaintext_schema',
            'operation_request_plaintext_size_bytes',
            'operation_request_plaintext_digest',
            'operation_request_aad_digest',
            'operation_request_envelope_digest'
        ]
    ) IS NOT DISTINCT FROM (
        to_jsonb(prior) - ARRAY[
            'operation_request_kind', 'operation_request_claim_fence',
            'operation_request_claim_owner_id',
            'operation_request_observed_at_ms',
            'operation_request_retry_at_ms',
            'operation_request_failure_kind',
            'operation_request_commit_disposition',
            'operation_request_provider_expires_at_ms',
            'operation_request_safe_erase_after_ms',
            'operation_request_plaintext_schema',
            'operation_request_plaintext_size_bytes',
            'operation_request_plaintext_digest',
            'operation_request_aad_digest',
            'operation_request_envelope_digest'
        ]
    )
$$;

CREATE FUNCTION automata_github_runtime_authority_same_operation_request(prior github_runtime_authority_issuances, candidate github_runtime_authority_issuances) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT ROW(
        candidate.operation_request_kind,
        candidate.operation_request_claim_fence,
        candidate.operation_request_claim_owner_id,
        candidate.operation_request_observed_at_ms,
        candidate.operation_request_retry_at_ms,
        candidate.operation_request_failure_kind,
        candidate.operation_request_commit_disposition,
        candidate.operation_request_provider_expires_at_ms,
        candidate.operation_request_safe_erase_after_ms,
        candidate.operation_request_plaintext_schema,
        candidate.operation_request_plaintext_size_bytes,
        candidate.operation_request_plaintext_digest,
        candidate.operation_request_aad_digest,
        candidate.operation_request_envelope_digest
    ) IS NOT DISTINCT FROM ROW(
        prior.operation_request_kind,
        prior.operation_request_claim_fence,
        prior.operation_request_claim_owner_id,
        prior.operation_request_observed_at_ms,
        prior.operation_request_retry_at_ms,
        prior.operation_request_failure_kind,
        prior.operation_request_commit_disposition,
        prior.operation_request_provider_expires_at_ms,
        prior.operation_request_safe_erase_after_ms,
        prior.operation_request_plaintext_schema,
        prior.operation_request_plaintext_size_bytes,
        prior.operation_request_plaintext_digest,
        prior.operation_request_aad_digest,
        prior.operation_request_envelope_digest
    )
$$;

CREATE FUNCTION automata_github_runtime_authority_base_is_current(authority github_runtime_authority_issuances, observed_at bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM job_attempts AS attempt
        JOIN jobs AS job
          ON job.id = attempt.job_id
         AND job.id = authority.job_id
         AND job.run_id = authority.run_id
        JOIN workflow_runs AS run
          ON run.id = job.run_id
         AND run.id = authority.run_id
         AND run.repository_id = authority.repository_id
        JOIN repositories AS repository
          ON repository.id = run.repository_id
         AND repository.id = authority.repository_id
         AND repository.tenant_id = authority.tenant_id
        JOIN workflow_definitions AS workflow
          ON workflow.id = run.workflow_id
         AND workflow.repository_id = run.repository_id
        JOIN workflow_snapshots AS snapshot
          ON snapshot.id = run.snapshot_id
         AND snapshot.workflow_id = run.workflow_id
        JOIN logical_workflow_runs AS marker
          ON marker.run_id = run.id
        JOIN logical_workflow_concrete_jobs AS concrete
          ON concrete.run_id = run.id
         AND concrete.job_id = job.id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = run.id
         AND invocation.id = concrete.invocation_id
        JOIN logical_workflow_jobs AS logical_job
          ON logical_job.run_id = run.id
         AND logical_job.invocation_id = invocation.id
         AND logical_job.id = concrete.logical_job_id
        JOIN logical_workflow_activation_preparation_claims AS preparation_claim
          ON preparation_claim.run_id = logical_job.run_id
         AND preparation_claim.invocation_id = logical_job.invocation_id
         AND preparation_claim.logical_job_id = logical_job.id
        JOIN logical_workflow_activation_preparations AS preparation
          ON preparation.run_id = preparation_claim.run_id
         AND preparation.invocation_id = preparation_claim.invocation_id
         AND preparation.logical_job_id = preparation_claim.logical_job_id
         AND preparation.descriptor_digest = preparation_claim.descriptor_digest
        JOIN logical_workflow_activation_publications AS activation_publication
          ON activation_publication.run_id = logical_job.run_id
         AND activation_publication.invocation_id = logical_job.invocation_id
         AND activation_publication.logical_job_id = logical_job.id
         AND activation_publication.activation_input_digest =
             preparation.activation_input_digest
        JOIN logical_workflow_instances AS instance
          ON instance.run_id = activation_publication.run_id
         AND instance.invocation_id = activation_publication.invocation_id
         AND instance.logical_job_id = activation_publication.logical_job_id
         AND instance.id = concrete.instance_id
        JOIN logical_workflow_materialization_claims AS materialization
          ON materialization.instance_id = instance.id
         AND materialization.run_id = instance.run_id
         AND materialization.invocation_id = instance.invocation_id
         AND materialization.logical_job_id = instance.logical_job_id
        JOIN github_workflow_run_manifest_origins AS origin
          ON origin.tenant_id = repository.tenant_id
         AND origin.repository_id = repository.id
         AND origin.workflow_id = run.workflow_id
         AND origin.snapshot_id = run.snapshot_id
         AND origin.run_id = run.id
         AND origin.root_invocation_id = marker.root_invocation_id
        JOIN workflow_admission_receipts AS admission_receipt
          ON admission_receipt.tenant_id = origin.tenant_id
         AND admission_receipt.idempotency_kind =
             origin.admission_idempotency_kind
         AND admission_receipt.idempotency_key =
             origin.admission_idempotency_key
         AND admission_receipt.request_digest = origin.logical_admission_digest
         AND admission_receipt.repository_id = origin.repository_id
         AND admission_receipt.run_id = origin.run_id
         AND admission_receipt.committed_at_ms = origin.admitted_at_ms
         AND admission_receipt.github_subject_evidence_required
        JOIN github_provider_manifest_revisions AS manifest
          ON manifest.tenant_id = origin.tenant_id
         AND manifest.repository_id = origin.repository_id
         AND manifest.provider_connection_id = origin.provider_connection_id
         AND manifest.manifest_revision = origin.provider_manifest_revision
         AND manifest.manifest_digest = origin.provider_manifest_digest
        JOIN github_server_service_authorities AS checks_authority
          ON checks_authority.tenant_id = origin.tenant_id
         AND checks_authority.id = origin.checks_authority_id
         AND checks_authority.repository_id = origin.repository_id
         AND checks_authority.provider_connection_id =
             origin.provider_connection_id
         AND checks_authority.provider_installation_id =
             origin.provider_installation_id
         AND checks_authority.github_repository_id = origin.github_repository_id
         AND checks_authority.github_repository_name =
             origin.github_repository_name
         AND checks_authority.service_scope = 'checks_write'
         AND checks_authority.identity_digest =
             origin.checks_authority_identity_digest
         AND checks_authority.app_configuration_revision =
             origin.checks_authority_app_configuration_revision
         AND checks_authority.policy_revision =
             origin.checks_authority_policy_revision
        LEFT JOIN github_server_service_authorities AS private_authority
          ON private_authority.tenant_id = origin.tenant_id
         AND private_authority.id = origin.private_source_authority_id
         AND private_authority.repository_id = origin.repository_id
         AND private_authority.provider_connection_id =
             origin.provider_connection_id
         AND private_authority.provider_installation_id =
             origin.provider_installation_id
         AND private_authority.github_repository_id = origin.github_repository_id
         AND private_authority.github_repository_name =
             origin.github_repository_name
         AND private_authority.service_scope = 'private_repository_source_read'
         AND private_authority.identity_digest =
             origin.private_source_authority_identity_digest
         AND private_authority.app_configuration_revision =
             origin.private_source_authority_app_configuration_revision
         AND private_authority.policy_revision =
             origin.private_source_authority_policy_revision
        JOIN runners AS runner
          ON runner.id = attempt.runner_id
         AND runner.id = authority.runner_id
         AND runner.tenant_id = authority.tenant_id
         AND runner.generation = authority.runner_generation
         AND runner.session_epoch = authority.runner_session_epoch
        JOIN runner_sessions AS session
          ON session.id = attempt.runner_session_id
         AND session.id = authority.runner_session_id
         AND session.runner_id = authority.runner_id
         AND session.session_epoch = authority.runner_session_epoch
         AND session.runner_generation = authority.runner_generation
        WHERE attempt.id = authority.attempt_id
          AND attempt.job_id = authority.job_id
          AND attempt.fencing_token = authority.fencing_token
          AND attempt.lease_id = authority.lease_id
          AND attempt.lease_issued_at_ms = authority.lease_issued_at_ms
          AND automata_github_runtime_authority_lease_horizon_is_tail(
              authority,
              attempt.lease_expires_at_ms,
              observed_at
          )
          AND attempt.lease_expires_at_ms > observed_at
          AND attempt.runner_id = authority.runner_id
          AND attempt.runner_session_id = authority.runner_session_id
          AND attempt.runner_session_epoch = authority.runner_session_epoch
          AND attempt.runner_generation = authority.runner_generation
          AND attempt.runner_slot = authority.runner_slot
          AND attempt.lifecycle IN ('leased', 'preparing', 'running')
          AND attempt.changed_at_ms <= observed_at
          AND job.admission_epoch = 1
          AND job.job_ir_schema = 1
          AND job.job_ir_schema = authority.job_ir_schema
          AND job.job_ir_size_bytes = authority.job_ir_size_bytes
          AND job.job_ir_digest = authority.job_ir_digest
          AND job.job_ir_digest = authority.policy_digest
          AND concrete.requirements = job.requirements
          AND concrete.instance_id = materialization.instance_id
          AND concrete.run_id = materialization.run_id
          AND concrete.invocation_id = materialization.invocation_id
          AND concrete.logical_job_id = materialization.logical_job_id
          AND concrete.descriptor_digest = materialization.descriptor_digest
          AND concrete.job_id = materialization.expected_job_id
          AND concrete.initial_attempt_id = materialization.expected_attempt_id
          AND concrete.claim_owner_id = materialization.owner_id
          AND concrete.claim_generation = materialization.generation
          AND concrete.claim_started_at_ms = materialization.claimed_at_ms
          AND concrete.claim_expires_at_ms = materialization.expires_at_ms
          AND concrete.committed_at_ms = materialization.updated_at_ms
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
          AND (
              invocation.id <> marker.root_invocation_id
              OR run.plan_digest = invocation.plan_digest
          )
          AND run.plan_digest = origin.plan_digest
          AND run.event_digest = origin.event_digest
          AND run.head_sha = origin.github_check_head_sha
          AND run.event_name = origin.event_name
          AND run.git_ref = origin.git_ref
          AND run.status IN ('queued', 'in_progress')
          AND workflow.path = origin.workflow_path
          AND snapshot.source_digest = origin.source_digest
          AND marker.orchestration_schema = 1
          AND marker.admission_digest = origin.logical_admission_digest
          AND marker.admitted_at_ms = origin.admitted_at_ms
          AND marker.state IN ('pending', 'active')
          AND automata_logical_workflow_invocation_published(
              run.id, invocation.id
          )
          AND invocation.plan_schema = 1
          AND (
              invocation.id <> marker.root_invocation_id
              OR invocation.plan_digest = origin.plan_digest
          )
          AND invocation.state IN ('pending', 'active')
          AND logical_job.execution_kind = 'steps'
          AND logical_job.state = 'activated'
          AND logical_job.activation_input_digest =
              preparation.activation_input_digest
          AND preparation_claim.state = 'prepared'
          AND activation_publication.condition_matched
          AND activation_publication.job_ir_version = 1
          AND activation_publication.runtime_context_schema = 1
          AND instance.job_ir_version = 1
          AND instance.job_ir_digest = job.job_ir_digest
          AND instance.job_ir_size_bytes = job.job_ir_size_bytes
          AND instance.job_ir_object_key = job.job_ir_object_key
          AND instance.job_ir_media_type =
              'application/vnd.automata.job-ir.protobuf'
          AND materialization.state = 'materialized'
          AND concrete.runtime_context_schema = 1
          AND manifest.authority_profile = 'standard'
          AND logical_job.authority_profile = 'standard'
          AND preparation_claim.authority_profile = 'standard'
          AND preparation.authority_profile = 'standard'
          AND activation_publication.authority_profile = 'standard'
          AND materialization.authority_profile = 'standard'
          AND concrete.authority_profile = 'standard'
          AND repository.scm_provider = 'github'
          AND repository.provider_repository_id =
              origin.github_repository_id::TEXT
          AND repository.owner || '/' || repository.name =
              origin.github_repository_name
          AND authority.provider_connection_id = origin.provider_connection_id
          AND authority.provider_connection_id = manifest.provider_connection_id
          AND authority.provider_installation_id =
              origin.provider_installation_id
          AND authority.provider_installation_id =
              manifest.provider_installation_id
          AND authority.github_repository_id = origin.github_repository_id
          AND authority.github_repository_id = manifest.github_repository_id
          AND authority.github_repository_name = origin.github_repository_name
          AND authority.github_repository_name = manifest.github_repository_name
          AND authority.authority_namespace = 'github.repository'
          AND authority.issuer_fingerprint = manifest.app_key_spki_sha256
          AND authority.configuration_fingerprint =
              checks_authority.configuration_fingerprint
          AND authority.requested_at_ms = attempt.lease_issued_at_ms
          AND authority.request_deadline_at_ms = LEAST(
              authority.lease_expires_at_ms,
              authority.lease_issued_at_ms + 120000
          )
          AND manifest.webhook_verifier_fingerprint_sha256 =
              origin.authenticated_webhook_verifier_fingerprint_sha256
          AND manifest.webhook_verifier_revision =
              origin.authenticated_webhook_verifier_revision
          AND manifest.repository_visibility = origin.repository_visibility
          AND manifest.github_web_origin = 'https://github.com/'
          AND manifest.github_api_origin = 'https://api.github.com/'
          AND manifest.github_rest_api_version = '2026-03-10'
          AND manifest.github_app_id = checks_authority.github_app_id
          AND manifest.github_app_client_id = checks_authority.github_app_client_id
          AND manifest.github_app_jwt_issuer_kind =
              checks_authority.github_app_jwt_issuer_kind
          AND manifest.app_key_spki_sha256 = checks_authority.app_key_spki_sha256
          AND manifest.app_configuration_revision =
              checks_authority.app_configuration_revision
          AND manifest.policy_revision = checks_authority.policy_revision
          AND manifest.registered_at_ms <= observed_at
          AND checks_authority.state = 'active'
          AND checks_authority.created_at_ms <= observed_at
          AND checks_authority.state_updated_at_ms <= observed_at
          AND origin.origin_kind IN (
              'provider_delivery', 'scheduled_fire', 'workflow_rerun'
          )
          AND (
              origin.repository_visibility = 'public'
              AND origin.private_source_authority_id IS NULL
              AND private_authority.id IS NULL
              OR origin.repository_visibility = 'private'
              AND private_authority.id IS NOT NULL
              AND private_authority.github_app_id = manifest.github_app_id
              AND private_authority.github_app_client_id =
                  manifest.github_app_client_id
              AND private_authority.github_app_jwt_issuer_kind =
                  manifest.github_app_jwt_issuer_kind
              AND private_authority.app_key_spki_sha256 =
                  manifest.app_key_spki_sha256
              AND private_authority.app_configuration_revision =
                  manifest.app_configuration_revision
              AND private_authority.policy_revision = manifest.policy_revision
              AND private_authority.state = 'active'
              AND private_authority.created_at_ms <= observed_at
              AND private_authority.state_updated_at_ms <= observed_at
          )
          AND origin.admitted_at_ms <= observed_at
          AND runner.status = 'online'
          AND runner.desired_state IN ('active', 'draining')
          AND session.job_ir_schema = 1
          AND session.disconnected_at_ms IS NULL
    )
$$;

CREATE FUNCTION automata_github_schedule_check_evidence_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact BOOLEAN;
    now_ms BIGINT;
BEGIN
    now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT TRUE INTO exact
    FROM github_schedule_fires AS fire
    JOIN github_schedule_registry_revisions AS registry
      ON registry.tenant_id = fire.tenant_id
     AND registry.repository_id = fire.repository_id
     AND registry.provider_connection_id = fire.provider_connection_id
     AND registry.registry_id = fire.registry_id
    JOIN github_schedule_registry_entries AS entry
      ON entry.registry_id = fire.registry_id
     AND entry.ordinal = fire.entry_ordinal
    JOIN github_schedule_registry_seals AS seal
      ON seal.registry_id = registry.registry_id
     AND seal.inventory_digest = registry.inventory_digest
     AND seal.schedule_count = registry.schedule_count
    JOIN github_schedule_registry_current AS current
      ON current.tenant_id = registry.tenant_id
     AND current.repository_id = registry.repository_id
     AND current.provider_connection_id = registry.provider_connection_id
     AND current.registry_id = registry.registry_id
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = registry.tenant_id
     AND manifest.repository_id = registry.repository_id
     AND manifest.provider_connection_id = registry.provider_connection_id
     AND manifest.manifest_revision = registry.manifest_revision
     AND manifest.manifest_digest = registry.manifest_digest
    JOIN github_provider_manifest_current AS manifest_current
      ON manifest_current.tenant_id = manifest.tenant_id
     AND manifest_current.repository_id = manifest.repository_id
     AND manifest_current.provider_connection_id = manifest.provider_connection_id
     AND manifest_current.manifest_revision = manifest.manifest_revision
     AND manifest_current.manifest_digest = manifest.manifest_digest
    JOIN github_server_service_authorities AS authority
      ON authority.tenant_id = registry.tenant_id
     AND authority.id = NEW.checks_authority_id
    JOIN github_check_subjects AS subject
      ON subject.tenant_id = fire.tenant_id
     AND subject.repository_id = fire.repository_id
     AND subject.provider_connection_id = fire.provider_connection_id
     AND subject.schedule_fire_id = fire.fire_id
     AND subject.id = NEW.github_check_subject_id
    WHERE fire.fire_id = NEW.schedule_fire_id
      AND fire.tenant_id = NEW.tenant_id
      AND fire.repository_id = NEW.repository_id
      AND fire.provider_connection_id = NEW.provider_connection_id
      AND fire.registry_id = NEW.registry_id
      AND fire.entry_ordinal = NEW.entry_ordinal
      AND fire.scheduled_at_ms = NEW.scheduled_at_ms
      AND fire.state = 'claimed'
      AND fire.claimed_at_ms <= now_ms
      AND fire.claim_expires_at_ms > now_ms
      AND NEW.recorded_at_ms >= fire.claimed_at_ms
      AND NEW.recorded_at_ms < fire.claim_expires_at_ms
      AND registry.manifest_revision = NEW.provider_manifest_revision
      AND registry.manifest_digest = NEW.provider_manifest_digest
      AND registry.default_branch_ref = NEW.default_branch_ref
      AND registry.source_revision = NEW.source_revision
      AND registry.github_repository_owner_id = NEW.github_repository_owner_id
      AND registry.default_branch_ref = manifest.git_ref
      AND NEW.github_check_head_sha = decode(registry.source_revision, 'hex')
      AND subject.origin_kind = 'scheduled_fire'
      AND subject.provider_delivery_id IS NULL
      AND subject.subject_key = entry.workflow_path
      AND subject.provider_installation_id = manifest.provider_installation_id
      AND subject.github_repository_id = manifest.github_repository_id
      AND subject.github_repository_name = manifest.github_repository_name
      AND subject.github_app_id = manifest.github_app_id
      AND subject.head_sha = NEW.github_check_head_sha
      AND subject.check_name = manifest.check_name
      AND subject.created_at_ms = NEW.recorded_at_ms
      AND authority.repository_id = registry.repository_id
      AND authority.provider_connection_id = registry.provider_connection_id
      AND authority.provider_installation_id = manifest.provider_installation_id
      AND authority.github_app_id = manifest.github_app_id
      AND authority.github_repository_id = manifest.github_repository_id
      AND authority.github_repository_name = manifest.github_repository_name
      AND authority.service_scope = 'checks_write'
      AND authority.github_app_client_id = manifest.github_app_client_id
      AND authority.github_app_jwt_issuer_kind = manifest.github_app_jwt_issuer_kind
      AND authority.app_key_spki_sha256 = manifest.app_key_spki_sha256
      AND authority.app_configuration_revision =
          NEW.checks_authority_app_configuration_revision
      AND authority.app_configuration_revision = manifest.app_configuration_revision
      AND authority.policy_revision = NEW.checks_authority_policy_revision
      AND authority.policy_revision = manifest.policy_revision
      AND authority.identity_digest = NEW.checks_authority_identity_digest
      AND authority.state = 'active'
      AND authority.created_at_ms <= NEW.recorded_at_ms
    FOR SHARE OF fire, registry, entry, seal, current, manifest, manifest_current,
                 authority, subject;
    IF exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'GitHub schedule Check evidence is not exact and live'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_check_evidence_authority_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_schedule_check_requires_atomic_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    evidence github_schedule_check_evidence%ROWTYPE;
    outbox github_check_projection_outbox%ROWTYPE;
BEGIN
    IF NEW.origin_kind <> 'scheduled_fire' THEN
        RETURN NULL;
    END IF;
    SELECT * INTO evidence
    FROM github_schedule_check_evidence
    WHERE schedule_fire_id = NEW.schedule_fire_id
      AND tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND provider_connection_id = NEW.provider_connection_id
      AND github_check_subject_id = NEW.id;
    SELECT * INTO outbox
    FROM github_check_projection_outbox
    WHERE subject_id = NEW.id;
    IF evidence.schedule_fire_id IS NULL
        OR evidence.github_check_head_sha <> NEW.head_sha
        OR evidence.recorded_at_ms <> NEW.created_at_ms
        OR outbox.subject_id IS NULL
        OR outbox.state <> 'pending'
        OR outbox.attempted_revision IS NOT NULL
        OR outbox.attempt_count <> 0
        OR outbox.claim_fence <> 0
        OR outbox.projected_revision <> 0
        OR outbox.state_updated_at_ms <> NEW.created_at_ms
    THEN
        RAISE EXCEPTION 'GitHub scheduled Check requires atomic sealed evidence and outbox'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_check_atomic_evidence_required';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_github_schedule_run_evidence_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact BOOLEAN;
    now_ms BIGINT;
BEGIN
    now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT TRUE INTO exact
    FROM github_schedule_fires AS fire
    JOIN github_schedule_registry_revisions AS registry
      ON registry.tenant_id = fire.tenant_id
     AND registry.repository_id = fire.repository_id
     AND registry.provider_connection_id = fire.provider_connection_id
     AND registry.registry_id = fire.registry_id
    JOIN github_schedule_registry_entries AS entry
     ON entry.registry_id = fire.registry_id
     AND entry.ordinal = fire.entry_ordinal
    JOIN github_provider_manifest_current AS manifest_current
      ON manifest_current.tenant_id = registry.tenant_id
     AND manifest_current.repository_id = registry.repository_id
     AND manifest_current.provider_connection_id = registry.provider_connection_id
     AND manifest_current.manifest_revision = registry.manifest_revision
     AND manifest_current.manifest_digest = registry.manifest_digest
    JOIN github_schedule_check_evidence AS schedule_check
      ON schedule_check.schedule_fire_id = fire.fire_id
     AND schedule_check.tenant_id = fire.tenant_id
     AND schedule_check.repository_id = fire.repository_id
     AND schedule_check.provider_connection_id = fire.provider_connection_id
     AND schedule_check.registry_id = fire.registry_id
     AND schedule_check.entry_ordinal = fire.entry_ordinal
    JOIN github_check_subjects AS check_subject
      ON check_subject.id = schedule_check.github_check_subject_id
     AND check_subject.tenant_id = schedule_check.tenant_id
    JOIN workflow_runs AS run
      ON run.repository_id = fire.repository_id
     AND run.id = NEW.run_id
    JOIN workflow_definitions AS workflow
      ON workflow.repository_id = run.repository_id
     AND workflow.id = run.workflow_id
    JOIN workflow_snapshots AS snapshot
      ON snapshot.id = run.snapshot_id
     AND snapshot.workflow_id = run.workflow_id
    JOIN logical_workflow_runs AS marker
      ON marker.run_id = run.id
    JOIN workflow_admission_receipts AS admission
      ON admission.tenant_id = fire.tenant_id
     AND admission.idempotency_kind = 'operation'
     AND admission.idempotency_key = fire.fire_id::TEXT
     AND admission.repository_id = fire.repository_id
     AND admission.run_id = run.id
    WHERE fire.fire_id = NEW.schedule_fire_id
      AND fire.tenant_id = NEW.tenant_id
      AND fire.repository_id = NEW.repository_id
      AND fire.state = 'claimed'
      AND fire.claim_owner_id = NEW.admission_claim_owner_id
      AND fire.attempt_count = NEW.admission_claim_attempt
      AND fire.claim_fence = NEW.admission_claim_fence
      AND fire.claimed_at_ms = NEW.admission_claimed_at_ms
      AND fire.claim_expires_at_ms = NEW.admission_claim_expires_at_ms
      AND fire.claimed_at_ms <= now_ms
      AND fire.claim_expires_at_ms > now_ms
      AND registry.default_branch_ref = schedule_check.default_branch_ref
      AND registry.source_revision = schedule_check.source_revision
      AND registry.github_repository_owner_id = NEW.github_repository_owner_id
      AND schedule_check.github_repository_owner_id = NEW.github_repository_owner_id
      AND entry.workflow_path = NEW.workflow_path
      AND entry.workflow_source_digest = NEW.source_digest
      AND check_subject.origin_kind = 'scheduled_fire'
      AND check_subject.schedule_fire_id = fire.fire_id
      AND check_subject.provider_delivery_id IS NULL
      AND check_subject.workflow_run_id = run.id
      AND check_subject.linked_at_ms = NEW.admitted_at_ms
      AND check_subject.desired_state = 'in_progress'
      AND check_subject.head_sha = NEW.github_check_head_sha
      AND schedule_check.github_check_subject_id = NEW.github_check_subject_id
      AND schedule_check.github_check_head_sha = NEW.github_check_head_sha
      AND run.workflow_id = NEW.workflow_id
      AND run.snapshot_id = NEW.snapshot_id
      AND run.head_sha = NEW.github_check_head_sha
      AND run.git_ref = registry.default_branch_ref
      AND run.git_ref = NEW.git_ref
      AND run.event_name = 'schedule'
      AND run.event_name = NEW.event_name
      AND run.event_digest = NEW.event_digest
      AND run.plan_schema = NEW.workflow_plan_schema
      AND run.plan_digest = NEW.plan_digest
      AND run.created_at_ms = NEW.admitted_at_ms
      AND workflow.path = NEW.workflow_path
      AND snapshot.source_digest = NEW.source_digest
      AND marker.root_invocation_id = NEW.root_invocation_id
      AND marker.admission_digest = NEW.logical_admission_digest
      AND marker.admitted_at_ms = NEW.admitted_at_ms
      AND admission.request_digest = NEW.logical_admission_digest
      AND admission.committed_at_ms = NEW.admitted_at_ms
      AND admission.github_subject_evidence_required
    FOR SHARE OF fire, registry, entry, manifest_current, schedule_check, check_subject,
                 run, workflow, snapshot, marker, admission;
    IF exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'GitHub scheduled run evidence is not exact and live'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_run_evidence_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_schedule_run_subject_evidence_digest(schedule_fire_id uuid, tenant_id text, repository_id uuid, workflow_id uuid, snapshot_id uuid, run_id uuid, root_invocation_id uuid, github_repository_owner_id bigint, admission_claim_owner_id uuid, admission_claim_attempt smallint, admission_claim_fence bigint, admission_claimed_at_ms bigint, admission_claim_expires_at_ms bigint, github_check_subject_id uuid, github_check_head_sha bytea, workflow_path text, source_digest bytea, event_name text, event_digest bytea, git_ref text, workflow_plan_schema smallint, plan_digest bytea, logical_admission_digest bytea, admitted_at_ms bigint) RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to(
        'automata.store.github-schedule-run-subject-evidence.v1', 'UTF8'
    )
    || pg_catalog.decode('00', 'hex')
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(schedule_fire_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.convert_to(tenant_id, 'UTF8'))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(repository_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(workflow_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(snapshot_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(run_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(root_invocation_id))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(github_repository_owner_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(admission_claim_owner_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admission_claim_attempt::BIGINT)
    )
    || automata_github_provider_manifest_digest_part(pg_catalog.int8send(admission_claim_fence))
    || automata_github_provider_manifest_digest_part(pg_catalog.int8send(admission_claimed_at_ms))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admission_claim_expires_at_ms)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(github_check_subject_id)
    )
    || automata_github_provider_manifest_digest_part(github_check_head_sha)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(workflow_path, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(source_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(event_name, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(event_digest)
    || automata_github_provider_manifest_digest_part(pg_catalog.convert_to(git_ref, 'UTF8'))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(workflow_plan_schema::BIGINT)
    )
    || automata_github_provider_manifest_digest_part(plan_digest)
    || automata_github_provider_manifest_digest_part(logical_admission_digest)
    || automata_github_provider_manifest_digest_part(pg_catalog.int8send(admitted_at_ms))
)
$$;

CREATE FUNCTION automata_github_server_service_aad_digest(bytea, bigint, bigint, bigint, bigint, bigint, smallint, bigint, bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to('automata.store.github-server-service.aad.v1', 'UTF8')
    || pg_catalog.decode('00', 'hex')
    || automata_github_server_service_digest_part($1)
    || automata_github_server_service_digest_part(pg_catalog.int8send($2))
    || automata_github_server_service_digest_part(pg_catalog.int8send($3))
    || automata_github_server_service_digest_part(pg_catalog.int8send($4))
    || automata_github_server_service_digest_part(
        CASE WHEN $5 IS NULL
            THEN pg_catalog.decode('00', 'hex')
            ELSE pg_catalog.decode('01', 'hex')
        END
    )
    || CASE WHEN $5 IS NULL THEN ''::BYTEA
        ELSE automata_github_server_service_digest_part(pg_catalog.int8send($5))
    END
    || automata_github_server_service_digest_part(pg_catalog.int8send($6))
    || automata_github_server_service_digest_part(pg_catalog.int2send($7))
    || automata_github_server_service_digest_part(pg_catalog.int8send($8))
    || automata_github_server_service_digest_part($9)
)
$_$;

CREATE FUNCTION automata_github_server_service_authority_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    repository repositories%ROWTYPE;
BEGIN
    SELECT * INTO repository
    FROM repositories
    WHERE tenant_id = NEW.tenant_id
      AND id = NEW.repository_id
    FOR SHARE;
    IF repository.id IS NULL
        OR repository.scm_provider <> 'github'
        OR repository.provider_repository_id <> NEW.github_repository_id::TEXT
        OR repository.owner || '/' || repository.name <> NEW.github_repository_name
        OR NEW.state <> 'active'
        OR NEW.current_issuance_generation IS NOT NULL
        OR NEW.refresh_issuance_generation IS NOT NULL
        OR NEW.next_issuance_generation <> 1
        OR NEW.consecutive_generation_failures <> 0
        OR NEW.next_mint_not_before_ms IS NOT NULL
        OR NEW.mint_gate_generation IS NOT NULL
        OR NEW.failure_budget_rearm_at_ms IS NOT NULL
        OR NEW.state_updated_at_ms <> NEW.created_at_ms
        OR NEW.retired_at_ms IS NOT NULL
    THEN
        RAISE EXCEPTION 'GitHub server-service authority descriptor is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_initial_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_server_service_authority_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_state TEXT;
    refresh_state TEXT;
    refresh_updated_at_ms BIGINT;
    transition_state TEXT;
    transition_safe_erase_after_ms BIGINT;
    transition_updated_at_ms BIGINT;
    previous_current_state TEXT;
    previous_current_updated_at_ms BIGINT;
    gate_state TEXT;
    gate_terminal_reason TEXT;
    gate_generation_failure_gate_at_ms BIGINT;
    expected_gate_generation BIGINT;
    expected_gate_at_ms BIGINT;
    failure_gate_advanced BOOLEAN := FALSE;
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
        OR NEW.provider_connection_id IS DISTINCT FROM OLD.provider_connection_id
        OR NEW.provider_installation_id IS DISTINCT FROM OLD.provider_installation_id
        OR NEW.github_app_id IS DISTINCT FROM OLD.github_app_id
        OR NEW.github_app_client_id IS DISTINCT FROM OLD.github_app_client_id
        OR NEW.github_app_jwt_issuer_kind IS DISTINCT FROM OLD.github_app_jwt_issuer_kind
        OR NEW.github_repository_id IS DISTINCT FROM OLD.github_repository_id
        OR NEW.github_repository_name IS DISTINCT FROM OLD.github_repository_name
        OR NEW.service_scope IS DISTINCT FROM OLD.service_scope
        OR NEW.permission_policy IS DISTINCT FROM OLD.permission_policy
        OR NEW.policy_digest IS DISTINCT FROM OLD.policy_digest
        OR NEW.policy_revision IS DISTINCT FROM OLD.policy_revision
        OR NEW.app_key_spki_sha256 IS DISTINCT FROM OLD.app_key_spki_sha256
        OR NEW.app_configuration_revision IS DISTINCT FROM OLD.app_configuration_revision
        OR NEW.configuration_fingerprint IS DISTINCT FROM OLD.configuration_fingerprint
        OR NEW.identity_digest IS DISTINCT FROM OLD.identity_digest
        OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms
        OR NEW.state_updated_at_ms < OLD.state_updated_at_ms
        OR NEW.next_issuance_generation < OLD.next_issuance_generation
    THEN
        RAISE EXCEPTION 'GitHub server-service authority identity is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_identity_immutable';
    END IF;
    IF NEW.state = 'active' AND OLD.state = 'active' THEN
        IF OLD.refresh_issuance_generation IS NOT NULL
            AND NEW.refresh_issuance_generation IS NULL
        THEN
            SELECT state, safe_erase_after_ms, state_updated_at_ms
            INTO transition_state, transition_safe_erase_after_ms,
                 transition_updated_at_ms
            FROM github_server_service_authority_issuances
            WHERE authority_id = NEW.id
              AND generation = OLD.refresh_issuance_generation;
            IF NEW.state_updated_at_ms IS DISTINCT FROM transition_updated_at_ms THEN
                RAISE EXCEPTION 'GitHub server-service refresh pointer time is not exact'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_authorities_pointer_time_exact';
            END IF;
            IF NEW.current_issuance_generation
                IS NOT DISTINCT FROM OLD.refresh_issuance_generation
            THEN
                IF OLD.current_issuance_generation IS NOT NULL THEN
                    SELECT state, state_updated_at_ms
                    INTO previous_current_state, previous_current_updated_at_ms
                    FROM github_server_service_authority_issuances
                    WHERE authority_id = NEW.id
                      AND generation = OLD.current_issuance_generation;
                END IF;
                IF transition_state IS DISTINCT FROM 'ready'
                    OR NEW.consecutive_generation_failures <> 0
                    OR NEW.next_mint_not_before_ms IS NOT NULL
                    OR NEW.mint_gate_generation IS NOT NULL
                    OR NEW.failure_budget_rearm_at_ms IS NOT NULL
                    OR OLD.current_issuance_generation IS NOT NULL
                        AND (
                            previous_current_state IS DISTINCT FROM 'revoke_pending'
                            OR previous_current_updated_at_ms
                                IS DISTINCT FROM transition_updated_at_ms
                        )
                THEN
                    RAISE EXCEPTION 'GitHub server-service ready generation did not reset its failure budget'
                        USING ERRCODE = 'integrity_constraint_violation',
                              CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
                END IF;
            ELSIF NEW.current_issuance_generation
                IS NOT DISTINCT FROM OLD.current_issuance_generation
            THEN
                IF transition_state IS NULL
                    OR NEW.consecutive_generation_failures <> LEAST(
                        OLD.consecutive_generation_failures + 1, 32
                    )
                    OR NEW.failure_budget_rearm_at_ms::NUMERIC
                        IS DISTINCT FROM (CASE
                            WHEN OLD.consecutive_generation_failures = 31
                                THEN transition_updated_at_ms::NUMERIC + 86400000
                            ELSE OLD.failure_budget_rearm_at_ms::NUMERIC
                        END)
                    OR (
                        transition_state = 'rejected'
                        AND NEW.next_mint_not_before_ms
                            IS DISTINCT FROM GREATEST(
                                COALESCE(
                                    OLD.next_mint_not_before_ms,
                                    transition_updated_at_ms + 60000
                                ),
                                transition_updated_at_ms + 60000
                            )
                    )
                    OR (
                        transition_state = 'rejected'
                        AND NEW.mint_gate_generation IS DISTINCT FROM (CASE
                            WHEN OLD.next_mint_not_before_ms IS NULL
                                OR transition_updated_at_ms + 60000
                                    > OLD.next_mint_not_before_ms
                                THEN OLD.refresh_issuance_generation
                            ELSE OLD.mint_gate_generation
                        END)
                    )
                    OR (
                        transition_state IN ('indeterminate', 'revoke_pending')
                        AND NEW.next_mint_not_before_ms
                            IS DISTINCT FROM GREATEST(
                                COALESCE(
                                    OLD.next_mint_not_before_ms,
                                    transition_safe_erase_after_ms
                                ),
                                transition_safe_erase_after_ms
                            )
                    )
                    OR (
                        transition_state IN ('indeterminate', 'revoke_pending')
                        AND NEW.mint_gate_generation IS DISTINCT FROM (CASE
                            WHEN OLD.next_mint_not_before_ms IS NULL
                                OR transition_safe_erase_after_ms
                                    > OLD.next_mint_not_before_ms
                                THEN OLD.refresh_issuance_generation
                            ELSE OLD.mint_gate_generation
                        END)
                    )
                    OR transition_state NOT IN (
                        'rejected', 'indeterminate', 'revoke_pending'
                    )
                THEN
                    RAISE EXCEPTION 'GitHub server-service failed generation did not advance its failure budget'
                        USING ERRCODE = 'integrity_constraint_violation',
                              CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
                END IF;
            ELSE
                RAISE EXCEPTION 'GitHub server-service refresh result changed an unrelated current generation'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
            END IF;
        ELSIF OLD.current_issuance_generation IS NOT NULL
            AND NEW.current_issuance_generation IS NULL
            AND NEW.refresh_issuance_generation
                IS NOT DISTINCT FROM OLD.refresh_issuance_generation
        THEN
            SELECT state, safe_erase_after_ms, state_updated_at_ms
            INTO transition_state, transition_safe_erase_after_ms,
                 transition_updated_at_ms
            FROM github_server_service_authority_issuances
            WHERE authority_id = NEW.id
              AND generation = OLD.current_issuance_generation;
            IF transition_state IS NULL
                OR NEW.state_updated_at_ms IS DISTINCT FROM transition_updated_at_ms
            THEN
                RAISE EXCEPTION 'GitHub server-service current reduction lacks its issuance'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
            ELSIF transition_state = 'quarantined' THEN
                IF NEW.consecutive_generation_failures <> LEAST(
                        OLD.consecutive_generation_failures + 1, 32
                    )
                    OR NEW.failure_budget_rearm_at_ms::NUMERIC
                        IS DISTINCT FROM (CASE
                            WHEN OLD.consecutive_generation_failures = 31
                                THEN transition_updated_at_ms::NUMERIC + 86400000
                            ELSE OLD.failure_budget_rearm_at_ms::NUMERIC
                        END)
                    OR NEW.next_mint_not_before_ms
                        IS DISTINCT FROM GREATEST(
                            COALESCE(
                                OLD.next_mint_not_before_ms,
                                transition_safe_erase_after_ms
                            ),
                            transition_safe_erase_after_ms
                        )
                    OR NEW.mint_gate_generation IS DISTINCT FROM (CASE
                        WHEN OLD.next_mint_not_before_ms IS NULL
                            OR transition_safe_erase_after_ms
                                > OLD.next_mint_not_before_ms
                            THEN OLD.current_issuance_generation
                        ELSE OLD.mint_gate_generation
                    END)
                THEN
                    RAISE EXCEPTION 'GitHub server-service quarantined current did not advance its failure budget'
                        USING ERRCODE = 'integrity_constraint_violation',
                              CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
                END IF;
            ELSIF NEW.consecutive_generation_failures
                    IS DISTINCT FROM OLD.consecutive_generation_failures
                OR NEW.next_mint_not_before_ms
                    IS DISTINCT FROM OLD.next_mint_not_before_ms
                OR NEW.mint_gate_generation
                    IS DISTINCT FROM OLD.mint_gate_generation
                OR NEW.failure_budget_rearm_at_ms
                    IS DISTINCT FROM OLD.failure_budget_rearm_at_ms
            THEN
                RAISE EXCEPTION 'GitHub server-service current reduction rewrote its failure budget'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
            END IF;
        ELSIF NEW.consecutive_generation_failures
                IS DISTINCT FROM OLD.consecutive_generation_failures
            OR NEW.next_mint_not_before_ms
                IS DISTINCT FROM OLD.next_mint_not_before_ms
            OR NEW.mint_gate_generation
                IS DISTINCT FROM OLD.mint_gate_generation
            OR NEW.failure_budget_rearm_at_ms
                IS DISTINCT FROM OLD.failure_budget_rearm_at_ms
        THEN
            IF OLD.consecutive_generation_failures = 32
                AND OLD.refresh_issuance_generation IS NULL
                AND NEW.consecutive_generation_failures = 31
                AND NEW.next_mint_not_before_ms
                    IS NOT DISTINCT FROM OLD.next_mint_not_before_ms
                AND NEW.mint_gate_generation
                    IS NOT DISTINCT FROM OLD.mint_gate_generation
                AND NEW.failure_budget_rearm_at_ms IS NULL
                AND OLD.next_mint_not_before_ms <= NEW.state_updated_at_ms
                AND OLD.failure_budget_rearm_at_ms <= NEW.state_updated_at_ms
                AND NEW.current_issuance_generation
                    IS NOT DISTINCT FROM OLD.current_issuance_generation
                AND NEW.refresh_issuance_generation
                    IS NOT DISTINCT FROM OLD.refresh_issuance_generation
                AND NEW.next_issuance_generation
                    IS NOT DISTINCT FROM OLD.next_issuance_generation
            THEN
                failure_gate_advanced := TRUE;
            ELSE
                SELECT state, terminal_reason, state_updated_at_ms,
                       generation_failure_gate_at_ms
                INTO gate_state, gate_terminal_reason, transition_updated_at_ms,
                     gate_generation_failure_gate_at_ms
                FROM github_server_service_authority_issuances
                WHERE authority_id = NEW.id
                  AND generation = OLD.mint_gate_generation;
                IF gate_state = 'revoked'
                    AND gate_terminal_reason = 'provider_revoked'
                THEN
                    NULL;
                ELSIF gate_state = 'revoke_pending'
                    AND gate_generation_failure_gate_at_ms IS NOT NULL
                    AND gate_generation_failure_gate_at_ms
                        < OLD.next_mint_not_before_ms
                THEN
                    NULL;
                ELSE
                    RAISE EXCEPTION 'GitHub server-service failure gate lacks exact reduction evidence'
                        USING ERRCODE = 'integrity_constraint_violation',
                              CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
                END IF;
                SELECT generation, effective_gate_at_ms
                INTO expected_gate_generation, expected_gate_at_ms
                FROM (
                    SELECT generation,
                           CASE
                               WHEN state = 'revoked'
                                    AND terminal_reason = 'provider_revoked'
                                   THEN LEAST(
                                       generation_failure_gate_at_ms::NUMERIC,
                                       state_updated_at_ms::NUMERIC + 60000
                                   )::BIGINT
                               ELSE generation_failure_gate_at_ms
                           END AS effective_gate_at_ms
                    FROM github_server_service_authority_issuances
                    WHERE authority_id = NEW.id
                      AND generation_failure_gate_at_ms IS NOT NULL
                ) AS failure_gate
                ORDER BY effective_gate_at_ms DESC, generation DESC
                LIMIT 1;
                IF expected_gate_generation IS NULL
                    OR OLD.mint_gate_generation IS NULL
                    OR NEW.current_issuance_generation
                        IS DISTINCT FROM OLD.current_issuance_generation
                    OR NEW.refresh_issuance_generation
                        IS DISTINCT FROM OLD.refresh_issuance_generation
                    OR NEW.next_issuance_generation
                        IS DISTINCT FROM OLD.next_issuance_generation
                    OR NEW.consecutive_generation_failures
                        IS DISTINCT FROM OLD.consecutive_generation_failures
                    OR NEW.next_mint_not_before_ms
                        IS DISTINCT FROM expected_gate_at_ms
                    OR NEW.mint_gate_generation
                        IS DISTINCT FROM expected_gate_generation
                    OR NEW.failure_budget_rearm_at_ms
                        IS DISTINCT FROM OLD.failure_budget_rearm_at_ms
                    OR NEW.state_updated_at_ms
                        IS DISTINCT FROM transition_updated_at_ms
                THEN
                    RAISE EXCEPTION 'GitHub server-service lifecycle rewrote its failure budget'
                        USING ERRCODE = 'integrity_constraint_violation',
                              CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
                END IF;
                failure_gate_advanced := TRUE;
            END IF;
        END IF;
    ELSIF NEW.consecutive_generation_failures
            IS DISTINCT FROM OLD.consecutive_generation_failures
        OR NEW.next_mint_not_before_ms
            IS DISTINCT FROM OLD.next_mint_not_before_ms
        OR NEW.mint_gate_generation
            IS DISTINCT FROM OLD.mint_gate_generation
        OR NEW.failure_budget_rearm_at_ms
            IS DISTINCT FROM OLD.failure_budget_rearm_at_ms
    THEN
        RAISE EXCEPTION 'GitHub server-service non-active lifecycle rewrote its failure budget'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_generation_failure_exact';
    END IF;
    IF NEW.next_issuance_generation IS DISTINCT FROM OLD.next_issuance_generation THEN
        IF OLD.state <> 'active'
            OR OLD.refresh_issuance_generation IS NOT NULL
            OR NEW.next_issuance_generation <> OLD.next_issuance_generation + 1
            OR NEW.refresh_issuance_generation
                IS DISTINCT FROM OLD.next_issuance_generation
        THEN
            RAISE EXCEPTION 'GitHub server-service next generation was not reserved exactly'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_authorities_next_generation_exact';
        END IF;
    ELSIF OLD.refresh_issuance_generation IS NULL
        AND NEW.refresh_issuance_generation IS NOT NULL
    THEN
        RAISE EXCEPTION 'GitHub server-service refresh lacks generation reservation'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_next_generation_exact';
    END IF;
    IF NOT (
        NEW.state = OLD.state
        OR OLD.state = 'active' AND NEW.state = 'retiring'
        OR OLD.state = 'retiring' AND NEW.state = 'retired'
    ) THEN
        RAISE EXCEPTION 'GitHub server-service authority state transition is invalid'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_state_transition';
    END IF;
    IF NEW.state = OLD.state AND NOT failure_gate_advanced AND (
        OLD.state <> 'active'
        OR (
            NEW.current_issuance_generation
                IS NOT DISTINCT FROM OLD.current_issuance_generation
            AND NEW.refresh_issuance_generation
                IS NOT DISTINCT FROM OLD.refresh_issuance_generation
        )
    ) THEN
        RAISE EXCEPTION 'GitHub server-service authority replay rewrote lifecycle evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_same_state_exact';
    END IF;
    IF OLD.state = 'retiring' AND NEW.state = 'retired' AND EXISTS (
        SELECT 1
        FROM github_server_service_authority_issuances
        WHERE authority_id = NEW.id
          AND (
              state NOT IN ('rejected', 'revoked')
              OR envelope_schema IS NOT NULL
          )
    ) THEN
        RAISE EXCEPTION 'GitHub server-service authority retired with retained custody'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_authorities_retired_terminal_exact';
    END IF;
    IF NEW.current_issuance_generation IS NOT NULL THEN
        SELECT state INTO current_state
        FROM github_server_service_authority_issuances
        WHERE authority_id = NEW.id
          AND generation = NEW.current_issuance_generation;
        IF current_state IS DISTINCT FROM 'ready' THEN
            RAISE EXCEPTION 'GitHub server-service current generation is not ready'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_authorities_current_ready';
        END IF;
    END IF;
    IF NEW.refresh_issuance_generation IS NOT NULL THEN
        SELECT state, state_updated_at_ms
        INTO refresh_state, refresh_updated_at_ms
        FROM github_server_service_authority_issuances
        WHERE authority_id = NEW.id
          AND generation = NEW.refresh_issuance_generation;
        IF refresh_state NOT IN ('claimed', 'minting', 'mint_retry')
            OR (
                NEW.refresh_issuance_generation
                    IS DISTINCT FROM OLD.refresh_issuance_generation
                AND NEW.state_updated_at_ms IS DISTINCT FROM refresh_updated_at_ms
            )
        THEN
            RAISE EXCEPTION 'GitHub server-service refresh generation is not mintable'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_authorities_refresh_mintable';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_server_service_digest_part(bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
SELECT pg_catalog.int8send(pg_catalog.octet_length($1)::BIGINT) || $1
$_$;

CREATE FUNCTION automata_github_server_service_handoff_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    issuance github_server_service_authority_issuances%ROWTYPE;
    authority github_server_service_authorities%ROWTYPE;
    check_outbox github_check_projection_outbox%ROWTYPE;
    check_subject github_check_subjects%ROWTYPE;
    delivery provider_delivery_inbox%ROWTYPE;
    repository repositories%ROWTYPE;
    discovery_exact BOOLEAN;
    observed_at_ms BIGINT := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
BEGIN
    SELECT * INTO issuance
    FROM github_server_service_authority_issuances
    WHERE tenant_id = NEW.tenant_id
      AND authority_id = NEW.authority_id
      AND generation = NEW.generation
    FOR SHARE;
    SELECT * INTO authority
    FROM github_server_service_authorities
    WHERE tenant_id = NEW.tenant_id
      AND id = NEW.authority_id
    FOR SHARE;
    IF issuance.authority_id IS NULL
        OR authority.id IS NULL
        OR authority.state <> 'active'
        OR authority.current_issuance_generation IS DISTINCT FROM NEW.generation
        OR issuance.state <> 'ready'
        OR issuance.state_updated_at_ms > NEW.granted_at_ms
        OR authority.state_updated_at_ms > NEW.granted_at_ms
        OR NEW.required_through_ms
            > issuance.provider_expires_at_ms - 60000
    THEN
        RAISE EXCEPTION 'GitHub server-service handoff authority is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_handoffs_authority_exact';
    END IF;

    IF authority.service_scope = 'checks_write' THEN
        SELECT * INTO check_outbox
        FROM github_check_projection_outbox
        WHERE subject_id = NEW.consumer_id
        FOR SHARE;
        SELECT * INTO check_subject
        FROM github_check_subjects
        WHERE id = NEW.consumer_id
        FOR SHARE;
        IF check_outbox.subject_id IS NULL
            OR check_subject.id IS NULL
            OR check_outbox.state <> 'claimed'
            OR check_outbox.claim_owner_id <> NEW.consumer_owner_id
            OR check_outbox.claim_fence <> NEW.consumer_claim_fence
            OR check_outbox.claimed_desired_revision <> NEW.consumer_revision
            OR check_outbox.claimed_at_ms IS NULL
            OR check_outbox.claim_expires_at_ms IS NULL
            OR check_outbox.claimed_at_ms > NEW.granted_at_ms
            OR check_outbox.state_updated_at_ms > NEW.granted_at_ms
            OR check_outbox.claim_expires_at_ms <= NEW.granted_at_ms
            OR NEW.required_through_ms::NUMERIC
                > check_outbox.claim_expires_at_ms::NUMERIC
                    + (CASE NEW.consumer_action
                        WHEN 'publish_check_run' THEN 600000
                        ELSE 300000
                    END)
            OR (CASE NEW.consumer_action
                WHEN 'ensure_check_suite' THEN check_outbox.claim_action <> 'ensure_suite'
                WHEN 'create_check_run' THEN check_outbox.claim_action <> 'prepare_run_create'
                WHEN 'reconcile_check_run' THEN check_outbox.claim_action <> 'reconcile_run_create'
                WHEN 'publish_check_run' THEN check_outbox.claim_action <> 'publish'
                ELSE TRUE
            END)
            OR check_subject.tenant_id <> authority.tenant_id
            OR check_subject.repository_id <> authority.repository_id
            OR check_subject.provider_connection_id <> authority.provider_connection_id
            OR check_subject.provider_installation_id <> authority.provider_installation_id
            OR check_subject.github_app_id <> authority.github_app_id
            OR check_subject.github_repository_id <> authority.github_repository_id
            OR check_subject.github_repository_name <> authority.github_repository_name
        THEN
            RAISE EXCEPTION 'GitHub Checks handoff consumer claim is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_handoffs_checks_claim_exact';
        END IF;
    ELSIF authority.service_scope = 'private_repository_source_read' THEN
        IF NEW.consumer_action = 'discover_private_repository_schedules' THEN
            SELECT EXISTS (
                SELECT 1
                  FROM github_schedule_discovery_claims AS discovery
                  JOIN github_provider_manifest_current AS current
                    ON current.tenant_id = discovery.tenant_id
                   AND current.repository_id = discovery.repository_id
                   AND current.provider_connection_id = discovery.provider_connection_id
                   AND current.manifest_revision = discovery.manifest_revision
                   AND current.manifest_digest = discovery.manifest_digest
                  JOIN github_provider_manifest_revisions AS manifest
                    ON manifest.tenant_id = current.tenant_id
                   AND manifest.repository_id = current.repository_id
                   AND manifest.provider_connection_id = current.provider_connection_id
                   AND manifest.manifest_revision = current.manifest_revision
                   AND manifest.manifest_digest = current.manifest_digest
                  JOIN repositories AS schedule_repository
                    ON schedule_repository.id = discovery.repository_id
                   AND schedule_repository.tenant_id = discovery.tenant_id
                   AND schedule_repository.scm_provider = 'github'
                   AND schedule_repository.provider_repository_id =
                       manifest.github_repository_id::TEXT
                 WHERE discovery.discovery_id = NEW.consumer_id
                   AND discovery.state = 'claimed'
                   AND discovery.claim_owner_id = NEW.consumer_owner_id
                   AND discovery.claim_fence = NEW.consumer_claim_fence
                   AND NEW.consumer_revision = 1
                   AND discovery.claimed_at_ms <= NEW.granted_at_ms
                   AND discovery.updated_at_ms <= NEW.granted_at_ms
                   AND discovery.claim_expires_at_ms > NEW.granted_at_ms
                   AND discovery.claim_expires_at_ms > observed_at_ms
                   AND NEW.required_through_ms::NUMERIC <=
                       discovery.claim_expires_at_ms::NUMERIC + 300000
                   AND discovery.tenant_id = authority.tenant_id
                   AND discovery.repository_id = authority.repository_id
                   AND discovery.provider_connection_id = authority.provider_connection_id
                   AND discovery.source_authority_kind =
                       'private_repository_source_read'
                   AND discovery.private_source_authority_id = authority.id
                   AND discovery.private_source_authority_identity_digest =
                       authority.identity_digest
                   AND discovery.private_source_authority_app_configuration_revision =
                       authority.app_configuration_revision
                   AND discovery.private_source_authority_policy_revision =
                       authority.policy_revision
                   AND manifest.provider_installation_id =
                       authority.provider_installation_id
                   AND manifest.github_app_id = authority.github_app_id
                   AND manifest.github_repository_id = authority.github_repository_id
                   AND manifest.github_repository_name = authority.github_repository_name
                   AND manifest.github_repository_owner_id IS NOT NULL
                   AND manifest.github_repository_owner_id =
                       discovery.github_repository_owner_id
                 FOR SHARE OF discovery, current, manifest, schedule_repository
            ) INTO discovery_exact;
            IF discovery_exact IS DISTINCT FROM TRUE THEN
                RAISE EXCEPTION 'private GitHub schedule discovery handoff claim is not exact'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT =
                              'github_server_service_handoffs_schedule_discovery_claim_exact';
            END IF;
        ELSE
            SELECT * INTO delivery
            FROM provider_delivery_inbox
            WHERE id = NEW.consumer_id
            FOR SHARE;
            SELECT * INTO repository
            FROM repositories
            WHERE id = authority.repository_id
              AND tenant_id = authority.tenant_id
            FOR SHARE;
            IF delivery.id IS NULL
                OR repository.id IS NULL
                OR delivery.state IS DISTINCT FROM 'claimed'
                OR delivery.claim_owner_id IS DISTINCT FROM NEW.consumer_owner_id
                OR delivery.claim_fence IS DISTINCT FROM NEW.consumer_claim_fence
                OR delivery.attempt_count IS DISTINCT FROM NEW.consumer_revision
                OR delivery.claimed_at_ms IS NULL
                OR delivery.claim_expires_at_ms IS NULL
                OR delivery.claimed_at_ms > NEW.granted_at_ms
                OR delivery.state_updated_at_ms > NEW.granted_at_ms
                OR delivery.claim_expires_at_ms <= NEW.granted_at_ms
                OR NEW.required_through_ms::NUMERIC
                    > delivery.claim_expires_at_ms::NUMERIC + 300000
                OR NEW.consumer_action NOT IN (
                    'fetch_private_repository_revision',
                    'fetch_private_repository_changed_files'
                )
                OR delivery.tenant_id IS DISTINCT FROM authority.tenant_id
                OR delivery.provider IS DISTINCT FROM 'github'
                OR delivery.repository_visibility IS DISTINCT FROM 'private'
                OR delivery.connection_id IS DISTINCT FROM authority.provider_connection_id
                OR delivery.installation_id IS DISTINCT FROM authority.provider_installation_id
                OR delivery.provider_repository_id IS DISTINCT FROM authority.github_repository_id
                OR delivery.repository_identity IS DISTINCT FROM authority.github_repository_name
                OR repository.scm_provider IS DISTINCT FROM 'github'
                OR repository.provider_repository_id
                    IS DISTINCT FROM authority.github_repository_id::TEXT
                OR repository.owner || '/' || repository.name
                    IS DISTINCT FROM authority.github_repository_name
            THEN
                RAISE EXCEPTION 'private GitHub source handoff consumer claim is not exact'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_handoffs_source_claim_exact';
            END IF;
        END IF;
    ELSE
        RAISE EXCEPTION 'GitHub server-service handoff scope is unknown'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_handoffs_scope_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_server_service_handoff_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
        OR NEW.generation IS DISTINCT FROM OLD.generation
        OR NEW.consumer_id IS DISTINCT FROM OLD.consumer_id
        OR NEW.consumer_owner_id IS DISTINCT FROM OLD.consumer_owner_id
        OR NEW.consumer_claim_fence IS DISTINCT FROM OLD.consumer_claim_fence
        OR NEW.consumer_action IS DISTINCT FROM OLD.consumer_action
        OR NEW.consumer_revision IS DISTINCT FROM OLD.consumer_revision
        OR NEW.required_through_ms IS DISTINCT FROM OLD.required_through_ms
        OR NEW.granted_at_ms IS DISTINCT FROM OLD.granted_at_ms
        OR OLD.released_at_ms IS NOT NULL
            AND NEW.released_at_ms IS DISTINCT FROM OLD.released_at_ms
    THEN
        RAISE EXCEPTION 'GitHub server-service handoff evidence is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_handoffs_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TABLE github_server_service_authorities (
    id uuid NOT NULL,
    tenant_id text NOT NULL,
    repository_id uuid NOT NULL,
    provider_connection_id uuid CONSTRAINT github_server_service_authoriti_provider_connection_id_not_null NOT NULL,
    provider_installation_id bigint CONSTRAINT github_server_service_authori_provider_installation_id_not_null NOT NULL,
    github_app_id bigint NOT NULL,
    github_app_client_id text NOT NULL COLLATE pg_catalog."C",
    github_app_jwt_issuer_kind text CONSTRAINT github_server_service_autho_github_app_jwt_issuer_kind_not_null NOT NULL COLLATE pg_catalog."C",
    github_repository_id bigint NOT NULL,
    github_repository_name text CONSTRAINT github_server_service_authoriti_github_repository_name_not_null NOT NULL COLLATE pg_catalog."C",
    service_scope text NOT NULL COLLATE pg_catalog."C",
    permission_policy jsonb NOT NULL,
    policy_digest bytea NOT NULL,
    policy_revision bigint NOT NULL,
    app_key_spki_sha256 bytea NOT NULL,
    app_configuration_revision bigint CONSTRAINT github_server_service_autho_app_configuration_revision_not_null NOT NULL,
    configuration_fingerprint bytea CONSTRAINT github_server_service_author_configuration_fingerprint_not_null NOT NULL,
    identity_digest bytea NOT NULL,
    state text DEFAULT 'active'::text NOT NULL COLLATE pg_catalog."C",
    current_issuance_generation bigint,
    refresh_issuance_generation bigint,
    next_issuance_generation bigint DEFAULT 1 CONSTRAINT github_server_service_authori_next_issuance_generation_not_null NOT NULL,
    consecutive_generation_failures smallint DEFAULT 0 CONSTRAINT github_server_service_autho_consecutive_generation_fai_not_null NOT NULL,
    next_mint_not_before_ms bigint,
    mint_gate_generation bigint,
    failure_budget_rearm_at_ms bigint,
    created_at_ms bigint NOT NULL,
    state_updated_at_ms bigint NOT NULL,
    retired_at_ms bigint,
    CONSTRAINT github_server_service_authorities_app_client_shape CHECK ((((octet_length(github_app_client_id) >= 1) AND (octet_length(github_app_client_id) <= 128)) AND (github_app_client_id ~ '^[A-Za-z0-9](?:[A-Za-z0-9._-]*[A-Za-z0-9])?$'::text))),
    CONSTRAINT github_server_service_authorities_digest_shape CHECK (((octet_length(policy_digest) = 32) AND (octet_length(app_key_spki_sha256) = 32) AND (octet_length(configuration_fingerprint) = 32) AND (octet_length(identity_digest) = 32))),
    CONSTRAINT github_server_service_authorities_generation_failure_shape CHECK (((((consecutive_generation_failures >= 0) AND (consecutive_generation_failures <= 32)) AND (((consecutive_generation_failures = 0) AND (next_mint_not_before_ms IS NULL) AND (mint_gate_generation IS NULL) AND (failure_budget_rearm_at_ms IS NULL)) OR (((consecutive_generation_failures >= 1) AND (consecutive_generation_failures <= 31)) AND (next_mint_not_before_ms IS NOT NULL) AND (next_mint_not_before_ms >= created_at_ms) AND (mint_gate_generation IS NOT NULL) AND (mint_gate_generation > 0) AND (mint_gate_generation < next_issuance_generation) AND (failure_budget_rearm_at_ms IS NULL)) OR ((consecutive_generation_failures = 32) AND (next_mint_not_before_ms IS NOT NULL) AND (next_mint_not_before_ms >= created_at_ms) AND (mint_gate_generation IS NOT NULL) AND (mint_gate_generation > 0) AND (mint_gate_generation < next_issuance_generation) AND (failure_budget_rearm_at_ms IS NOT NULL) AND (failure_budget_rearm_at_ms >= created_at_ms)))) IS TRUE)),
    CONSTRAINT github_server_service_authorities_generation_shape CHECK (((next_issuance_generation > 0) AND ((current_issuance_generation IS NULL) OR ((current_issuance_generation > 0) AND (current_issuance_generation < next_issuance_generation))))),
    CONSTRAINT github_server_service_authorities_jwt_issuer_kind CHECK ((github_app_jwt_issuer_kind = ANY (ARRAY['app_client_id'::text, 'app_id'::text]))),
    CONSTRAINT github_server_service_authorities_non_nil CHECK (((id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provider_connection_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT github_server_service_authorities_numeric_positive CHECK (((provider_installation_id > 0) AND (github_app_id > 0) AND (github_repository_id > 0) AND (policy_revision > 0) AND (app_configuration_revision > 0))),
    CONSTRAINT github_server_service_authorities_permission_exact CHECK ((((service_scope = 'checks_write'::text) AND (permission_policy = '{"checks": "write"}'::jsonb) AND (policy_digest = decode('6acf4ef0f49f5935d65a42dacb8ffcd49718dfd847d802d96038d81cea869a9c'::text, 'hex'::text))) OR ((service_scope = 'private_repository_source_read'::text) AND (permission_policy = '{"contents": "read"}'::jsonb) AND (policy_digest = decode('3c2516eac095f5bda3e7d20265497325e91030d1abe5907d4fb7fefcd0aa7f57'::text, 'hex'::text))))),
    CONSTRAINT github_server_service_authorities_refresh_shape CHECK (((refresh_issuance_generation IS NULL) OR ((refresh_issuance_generation > 0) AND (refresh_issuance_generation < next_issuance_generation) AND (refresh_issuance_generation IS DISTINCT FROM current_issuance_generation)))),
    CONSTRAINT github_server_service_authorities_repository_name_shape CHECK ((((octet_length(github_repository_name) >= 3) AND (octet_length(github_repository_name) <= 140)) AND (github_repository_name ~ '^[^/]+/[^/]+$'::text) AND ((octet_length(split_part(github_repository_name, '/'::text, 1)) >= 1) AND (octet_length(split_part(github_repository_name, '/'::text, 1)) <= 39)) AND ((octet_length(split_part(github_repository_name, '/'::text, 2)) >= 1) AND (octet_length(split_part(github_repository_name, '/'::text, 2)) <= 100)) AND ((split_part(github_repository_name, '/'::text, 1) ~ '^[A-Za-z0-9]$'::text) OR (split_part(github_repository_name, '/'::text, 1) ~ '^[A-Za-z0-9][A-Za-z0-9-]*[A-Za-z0-9]$'::text)) AND (split_part(github_repository_name, '/'::text, 1) !~ '--'::text) AND (split_part(github_repository_name, '/'::text, 2) ~ '^[A-Za-z0-9._-]+$'::text) AND (split_part(github_repository_name, '/'::text, 2) <> ALL (ARRAY['.'::text, '..'::text])) AND (split_part(github_repository_name, '/'::text, 2) !~* '[.]git$'::text))),
    CONSTRAINT github_server_service_authorities_service_scope CHECK ((service_scope = ANY (ARRAY['checks_write'::text, 'private_repository_source_read'::text]))),
    CONSTRAINT github_server_service_authorities_state CHECK ((state = ANY (ARRAY['active'::text, 'retiring'::text, 'retired'::text]))),
    CONSTRAINT github_server_service_authorities_time_shape CHECK (((created_at_ms >= 0) AND (state_updated_at_ms >= created_at_ms) AND (((state = 'active'::text) AND (retired_at_ms IS NULL)) OR ((state = 'retiring'::text) AND (retired_at_ms IS NULL) AND (current_issuance_generation IS NULL) AND (refresh_issuance_generation IS NULL)) OR ((state = 'retired'::text) AND (current_issuance_generation IS NULL) AND (refresh_issuance_generation IS NULL) AND (retired_at_ms IS NOT NULL) AND (retired_at_ms = state_updated_at_ms)))))
);

CREATE FUNCTION automata_github_server_service_identity_digest(github_server_service_authorities) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to(
        'automata.store.github-server-service.identity.v1', 'UTF8'
    ) || pg_catalog.decode('00', 'hex')
    || automata_github_server_service_digest_part(
        pg_catalog.convert_to(($1).tenant_id, 'UTF8')
    )
    || automata_github_server_service_digest_part(
        pg_catalog.uuid_send(($1).id)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.uuid_send(($1).repository_id)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.uuid_send(($1).provider_connection_id)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.int8send(($1).provider_installation_id)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.int8send(($1).github_app_id)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.int8send(($1).github_repository_id)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.convert_to(($1).github_repository_name, 'UTF8')
    )
    || automata_github_server_service_digest_part(
        pg_catalog.convert_to(($1).service_scope, 'UTF8')
    )
    || automata_github_server_service_digest_part(
        pg_catalog.convert_to(($1).github_app_client_id, 'UTF8')
    )
    || automata_github_server_service_digest_part(
        pg_catalog.convert_to(($1).github_app_jwt_issuer_kind, 'UTF8')
    )
    || automata_github_server_service_digest_part(($1).app_key_spki_sha256)
    || automata_github_server_service_digest_part(
        pg_catalog.int8send(($1).app_configuration_revision)
    )
    || automata_github_server_service_digest_part(
        pg_catalog.int8send(($1).policy_revision)
    )
    || automata_github_server_service_digest_part(($1).configuration_fingerprint)
)
$_$;

CREATE FUNCTION automata_github_server_service_issuance_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    authority github_server_service_authorities%ROWTYPE;
    expected_generation BIGINT;
    current_state TEXT;
    current_provider_expires_at_ms BIGINT;
BEGIN
    SELECT * INTO authority
    FROM github_server_service_authorities
    WHERE tenant_id = NEW.tenant_id
      AND id = NEW.authority_id
    FOR UPDATE;
    expected_generation := authority.next_issuance_generation;
    IF authority.current_issuance_generation IS NOT NULL THEN
        SELECT state, provider_expires_at_ms
        INTO current_state, current_provider_expires_at_ms
        FROM github_server_service_authority_issuances
        WHERE authority_id = authority.id
          AND generation = authority.current_issuance_generation
        FOR UPDATE;
    END IF;
    IF authority.id IS NULL
        OR authority.state <> 'active'
        OR authority.refresh_issuance_generation IS NOT NULL
        OR authority.consecutive_generation_failures >= 32
        OR authority.next_mint_not_before_ms IS NOT NULL
            AND authority.next_mint_not_before_ms > NEW.requested_at_ms
        OR authority.current_issuance_generation IS NOT NULL
            AND (
                current_state IS DISTINCT FROM 'ready'
                OR current_provider_expires_at_ms IS NULL
                OR current_provider_expires_at_ms::NUMERIC - 60000
                    > NEW.requested_at_ms::NUMERIC + 1620000
            )
        OR NEW.generation <> expected_generation
        OR NEW.state <> 'claimed'
        OR NEW.mint_attempt_count <> 1
        OR NEW.mint_claim_fence <> 1
        OR NEW.state_updated_at_ms <> NEW.requested_at_ms
    THEN
        RAISE EXCEPTION 'GitHub server-service issuance initial claim is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_initial_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_server_service_issuance_pointer_exact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    authority github_server_service_authorities%ROWTYPE;
    current_state TEXT;
    refresh_state TEXT;
    target_authority_id UUID;
BEGIN
    target_authority_id := (
        to_jsonb(NEW) ->> CASE
            WHEN TG_TABLE_NAME = 'github_server_service_authorities' THEN 'id'
            ELSE 'authority_id'
        END
    )::UUID;
    SELECT * INTO authority
    FROM github_server_service_authorities
    WHERE id = target_authority_id;
    IF authority.id IS NULL THEN
        RAISE EXCEPTION 'GitHub server-service issuance lost its descriptor'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_authority_pointer_exact';
    END IF;
    IF authority.current_issuance_generation IS NOT NULL THEN
        SELECT state INTO current_state
        FROM github_server_service_authority_issuances
        WHERE authority_id = authority.id
          AND generation = authority.current_issuance_generation;
    END IF;
    IF authority.refresh_issuance_generation IS NOT NULL THEN
        SELECT state INTO refresh_state
        FROM github_server_service_authority_issuances
        WHERE authority_id = authority.id
          AND generation = authority.refresh_issuance_generation;
    END IF;
    IF (authority.current_issuance_generation IS NOT NULL
            AND current_state IS DISTINCT FROM 'ready')
        OR (authority.refresh_issuance_generation IS NOT NULL
            AND (
                refresh_state IS NULL
                OR refresh_state NOT IN ('claimed', 'minting', 'mint_retry')
            ))
        OR EXISTS (
            SELECT 1
            FROM github_server_service_authority_issuances AS issuance
            WHERE issuance.authority_id = authority.id
              AND (
                  issuance.state = 'ready'
                      AND authority.current_issuance_generation
                          IS DISTINCT FROM issuance.generation
                  OR issuance.state IN ('claimed', 'minting', 'mint_retry')
                      AND authority.refresh_issuance_generation
                          IS DISTINCT FROM issuance.generation
              )
        )
        OR authority.next_issuance_generation::NUMERIC IS DISTINCT FROM (
            SELECT COALESCE(MAX(issuance.generation), 0)::NUMERIC + 1
            FROM github_server_service_authority_issuances AS issuance
            WHERE issuance.authority_id = authority.id
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service issuance is outside its exact descriptor slot'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_authority_pointer_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_github_server_service_issuance_update_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    live_handoff BOOLEAN;
    authority_state TEXT;
    authority_identity_digest BYTEA;
BEGIN
    SELECT state, identity_digest
    INTO authority_state, authority_identity_digest
    FROM github_server_service_authorities
    WHERE id = NEW.authority_id;
    IF authority_identity_digest IS NULL THEN
        RAISE EXCEPTION 'GitHub server-service issuance lacks its authority identity'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_authority_identity_exact';
    END IF;
    IF NEW.aad_digest IS NOT NULL
        AND NEW.aad_digest IS DISTINCT FROM
            automata_github_server_service_aad_digest(
                authority_identity_digest,
                NEW.generation,
                NEW.requested_at_ms,
                NEW.request_deadline_at_ms,
                NEW.provider_expires_at_ms,
                NEW.safe_erase_after_ms,
                NEW.plaintext_schema,
                NEW.plaintext_size_bytes,
                NEW.plaintext_digest
            )
        AND NOT (
            NEW.state = 'quarantined'
            AND NEW.revoke_failure_kind = 'protected_custody_corrupt'
            AND NEW.aad_digest IS NOT DISTINCT FROM OLD.aad_digest
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service protected AAD digest is non-canonical'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_aad_digest_canonical';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
        OR NEW.generation IS DISTINCT FROM OLD.generation
        OR NEW.requested_at_ms IS DISTINCT FROM OLD.requested_at_ms
        OR NEW.request_deadline_at_ms IS DISTINCT FROM OLD.request_deadline_at_ms
        OR NEW.conservative_expiry_at_ms IS DISTINCT FROM OLD.conservative_expiry_at_ms
        OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms
        OR NEW.state_updated_at_ms < OLD.state_updated_at_ms
        OR NEW.mint_attempt_count < OLD.mint_attempt_count
        OR NEW.mint_claim_fence < OLD.mint_claim_fence
        OR NEW.revoke_attempt_count < OLD.revoke_attempt_count
        OR NEW.revoke_claim_fence < OLD.revoke_claim_fence
    THEN
        RAISE EXCEPTION 'GitHub server-service issuance evidence regressed'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_monotonic';
    END IF;
    IF NOT (
        OLD.state = 'claimed' AND NEW.state IN ('minting', 'rejected')
        OR OLD.state = 'minting' AND NEW.state IN (
            'ready', 'revoke_pending', 'mint_retry', 'indeterminate', 'rejected'
        )
        OR OLD.state = 'mint_retry' AND NEW.state IN ('claimed', 'rejected')
        OR OLD.state = 'ready' AND NEW.state IN ('revoke_pending', 'quarantined', 'revoked')
        OR OLD.state = 'revoke_pending'
            AND NEW.state IN ('revoke_claimed', 'quarantined', 'revoked')
        OR OLD.state = 'revoke_claimed' AND NEW.state IN ('revoke_claimed', 'revoke_retry', 'quarantined', 'revoked')
        OR OLD.state = 'revoke_retry'
            AND NEW.state IN ('revoke_claimed', 'quarantined', 'revoked')
        OR OLD.state = 'indeterminate' AND NEW.state IN ('revoke_pending', 'revoked')
        OR OLD.state = 'quarantined' AND NEW.state = 'revoked'
    ) THEN
        RAISE EXCEPTION 'GitHub server-service issuance transition is invalid'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_state_transition';
    END IF;
    IF OLD.state = 'mint_retry' AND NEW.state = 'claimed' THEN
        IF NEW.mint_claim_fence <> OLD.mint_claim_fence + 1
            OR NEW.mint_attempt_count <> OLD.mint_attempt_count + 1
            OR OLD.next_mint_at_ms IS NULL
            OR OLD.next_mint_at_ms > NEW.mint_claimed_at_ms
            OR NEW.mint_started_at_ms IS NOT NULL
            OR NEW.mint_started_owner_id IS NOT NULL
            OR NEW.mint_started_claim_fence IS NOT NULL
            OR NEW.mint_started_claimed_at_ms IS NOT NULL
            OR NEW.mint_started_claim_expires_at_ms IS NOT NULL
            OR NEW.next_mint_at_ms IS NOT NULL
            OR NEW.mint_failure_kind IS NOT NULL
        THEN
            RAISE EXCEPTION 'GitHub server-service mint retry claim is not next and exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_issuances_mint_retry_claim_exact';
        END IF;
    ELSIF NEW.mint_claim_fence IS DISTINCT FROM OLD.mint_claim_fence
        OR NEW.mint_attempt_count IS DISTINCT FROM OLD.mint_attempt_count
    THEN
        RAISE EXCEPTION 'GitHub server-service mint fence changed outside proven retry'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_mint_fence_exact';
    END IF;
    IF OLD.state = 'claimed' AND NEW.state = 'minting' AND (
        NEW.mint_claim_owner_id IS DISTINCT FROM OLD.mint_claim_owner_id
        OR NEW.mint_claimed_at_ms IS DISTINCT FROM OLD.mint_claimed_at_ms
        OR NEW.mint_claim_expires_at_ms IS DISTINCT FROM OLD.mint_claim_expires_at_ms
        OR NEW.mint_started_owner_id IS DISTINCT FROM OLD.mint_claim_owner_id
        OR NEW.mint_started_claim_fence IS DISTINCT FROM OLD.mint_claim_fence
        OR NEW.mint_started_claimed_at_ms IS DISTINCT FROM OLD.mint_claimed_at_ms
        OR NEW.mint_started_claim_expires_at_ms IS DISTINCT FROM OLD.mint_claim_expires_at_ms
    ) THEN
        RAISE EXCEPTION 'GitHub server-service mint start rewrote claim evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_mint_start_exact';
    END IF;
    IF (
        NEW.mint_started_at_ms IS DISTINCT FROM OLD.mint_started_at_ms
        OR NEW.mint_started_owner_id IS DISTINCT FROM OLD.mint_started_owner_id
        OR NEW.mint_started_claim_fence IS DISTINCT FROM OLD.mint_started_claim_fence
        OR NEW.mint_started_claimed_at_ms IS DISTINCT FROM OLD.mint_started_claimed_at_ms
        OR NEW.mint_started_claim_expires_at_ms IS DISTINCT FROM OLD.mint_started_claim_expires_at_ms
    ) AND NOT (
        OLD.state = 'claimed' AND NEW.state = 'minting'
        OR OLD.state = 'mint_retry' AND NEW.state = 'claimed'
    ) THEN
        RAISE EXCEPTION 'GitHub server-service begun mint provenance changed'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_mint_started_immutable';
    END IF;
    IF NEW.ready_at_ms IS DISTINCT FROM OLD.ready_at_ms
        AND NOT (
            OLD.state = 'minting'
            AND NEW.state = 'ready'
            AND OLD.ready_at_ms IS NULL
            AND NEW.ready_at_ms = NEW.state_updated_at_ms
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service Ready evidence changed outside exact promotion'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_ready_evidence_exact';
    END IF;
    IF NEW.generation_failure_gate_at_ms
        IS DISTINCT FROM OLD.generation_failure_gate_at_ms
        AND NOT (
            (
                OLD.generation_failure_gate_at_ms IS NULL
                AND (
                    NEW.state = 'rejected'
                        AND NEW.generation_failure_gate_at_ms
                            = NEW.state_updated_at_ms + 60000
                    OR NEW.state = 'indeterminate'
                        AND NEW.generation_failure_gate_at_ms = NEW.safe_erase_after_ms
                    OR NEW.state = 'revoke_pending'
                        AND OLD.state = 'minting'
                        AND NEW.generation_failure_gate_at_ms = NEW.safe_erase_after_ms
                    OR NEW.state = 'quarantined'
                        AND OLD.state = 'ready'
                        AND NEW.generation_failure_gate_at_ms = NEW.safe_erase_after_ms
                )
            ) OR (
                OLD.state = 'indeterminate'
                AND NEW.state = 'revoke_pending'
                AND OLD.generation_failure_gate_at_ms IS NOT NULL
                AND NEW.generation_failure_gate_at_ms = NEW.safe_erase_after_ms
                AND NEW.generation_failure_gate_at_ms
                    <= OLD.generation_failure_gate_at_ms
            )
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service generation failure gate changed outside exact failure evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_generation_failure_gate_exact';
    END IF;
    IF OLD.state = 'mint_retry' AND NEW.state = 'rejected'
        AND NEW.mint_failure_kind IS DISTINCT FROM OLD.mint_failure_kind
    THEN
        RAISE EXCEPTION 'GitHub server-service terminal retry rewrote provider evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_mint_retry_failure_exact';
    END IF;
    IF NEW.state = 'rejected' THEN
        IF NEW.terminal_reason = 'request_expired' THEN
            IF NOT (
                OLD.state = 'claimed'
                    AND NEW.mint_started_at_ms IS NULL
                    AND NEW.state_updated_at_ms >= LEAST(
                        OLD.mint_claim_expires_at_ms,
                        OLD.request_deadline_at_ms
                    )
                OR OLD.state = 'mint_retry'
                    AND NEW.state_updated_at_ms >= OLD.request_deadline_at_ms
                OR OLD.state = 'minting'
                    AND NEW.state_updated_at_ms + 1 >= OLD.request_deadline_at_ms
            ) THEN
                RAISE EXCEPTION 'GitHub server-service request-expired terminal reason lacks exact timing evidence'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_issuances_rejected_reason_exact';
            END IF;
        ELSIF NEW.terminal_reason = 'provider_rejected' THEN
            IF OLD.state <> 'minting' THEN
                RAISE EXCEPTION 'GitHub server-service provider rejection lacks a begun mint'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_issuances_rejected_reason_exact';
            END IF;
        ELSIF NEW.terminal_reason = 'retry_exhausted' THEN
            IF OLD.state <> 'minting' OR OLD.mint_attempt_count <> 32 THEN
                RAISE EXCEPTION 'GitHub server-service retry exhaustion lacks the exact attempt bound'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_issuances_rejected_reason_exact';
            END IF;
        ELSIF NEW.terminal_reason = 'authority_retired_before_mint' THEN
            IF authority_state NOT IN ('retiring', 'retired')
                OR OLD.state NOT IN ('claimed', 'mint_retry')
            THEN
                RAISE EXCEPTION 'GitHub server-service retirement rejection lacks retiring authority evidence'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_server_service_issuances_rejected_reason_exact';
            END IF;
        ELSE
            RAISE EXCEPTION 'GitHub server-service rejection reason is unknown'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_issuances_rejected_reason_exact';
        END IF;
    END IF;
    IF OLD.state = 'minting'
        AND NEW.state IN ('ready', 'mint_retry', 'rejected')
        AND (
            NEW.state_updated_at_ms < OLD.mint_started_at_ms
            OR NEW.state_updated_at_ms >= OLD.mint_claim_expires_at_ms
            OR NEW.state_updated_at_ms >= OLD.request_deadline_at_ms
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service mint result lacks a live claim'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_mint_result_claim_exact';
    END IF;
    IF NEW.state = 'ready'
        AND NEW.provider_expires_at_ms::NUMERIC - 60000
            < NEW.state_updated_at_ms::NUMERIC + 1500000
    THEN
        RAISE EXCEPTION 'GitHub server-service credential lacks its fixed usable horizon'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_ready_expiry_exact';
    END IF;
    IF OLD.state IN ('revoke_pending', 'revoke_retry', 'revoke_claimed')
        AND NEW.state = 'revoke_claimed'
    THEN
        IF NEW.revoke_claim_fence <> OLD.revoke_claim_fence + 1
            OR NEW.revoke_attempt_count <> OLD.revoke_attempt_count + 1
            OR OLD.state = 'revoke_retry'
                AND (OLD.next_revoke_at_ms IS NULL
                    OR OLD.next_revoke_at_ms > NEW.revoke_claimed_at_ms)
            OR OLD.state = 'revoke_claimed'
                AND (OLD.revoke_claim_expires_at_ms IS NULL
                    OR OLD.revoke_claim_expires_at_ms > NEW.revoke_claimed_at_ms)
        THEN
            RAISE EXCEPTION 'GitHub server-service revoke claim is not next and exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_issuances_revoke_claim_exact';
        END IF;
        SELECT EXISTS (
            SELECT 1 FROM github_server_service_authority_handoffs
            WHERE authority_id = NEW.authority_id
              AND generation = NEW.generation
              AND released_at_ms IS NULL
              AND required_through_ms > NEW.revoke_claimed_at_ms
        ) INTO live_handoff;
        IF live_handoff THEN
            RAISE EXCEPTION 'GitHub server-service credential still has a live handoff'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_server_service_issuances_handoff_live';
        END IF;
    ELSIF NEW.revoke_claim_fence IS DISTINCT FROM OLD.revoke_claim_fence
        OR NEW.revoke_attempt_count IS DISTINCT FROM OLD.revoke_attempt_count
    THEN
        RAISE EXCEPTION 'GitHub server-service revoke fence changed outside claim'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_revoke_fence_exact';
    END IF;
    IF OLD.state = 'revoke_claimed'
        AND (
            NEW.state IN ('revoke_retry', 'quarantined')
            OR NEW.state = 'revoked'
                AND NEW.terminal_reason = 'provider_revoked'
        )
        AND (
            NEW.state_updated_at_ms < OLD.revoke_claimed_at_ms
            OR NEW.state_updated_at_ms >= OLD.revoke_claim_expires_at_ms
        )
        AND NOT (
            NEW.state = 'quarantined'
            AND NEW.revoke_failure_kind = 'protected_custody_corrupt'
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service revocation result lacks a live claim'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_revoke_result_claim_exact';
    END IF;
    IF (
        NEW.revoke_result_owner_id IS DISTINCT FROM OLD.revoke_result_owner_id
        OR NEW.revoke_result_claim_fence IS DISTINCT FROM OLD.revoke_result_claim_fence
        OR NEW.revoke_result_claimed_at_ms IS DISTINCT FROM OLD.revoke_result_claimed_at_ms
        OR NEW.revoke_result_claim_expires_at_ms
            IS DISTINCT FROM OLD.revoke_result_claim_expires_at_ms
    ) AND NOT (
        OLD.state = 'revoke_claimed'
        AND NEW.state IN ('revoke_retry', 'quarantined', 'revoked')
        AND NEW.revoke_result_owner_id IS NOT DISTINCT FROM OLD.revoke_claim_owner_id
        AND NEW.revoke_result_claim_fence IS NOT DISTINCT FROM OLD.revoke_claim_fence
        AND NEW.revoke_result_claimed_at_ms IS NOT DISTINCT FROM OLD.revoke_claimed_at_ms
        AND NEW.revoke_result_claim_expires_at_ms
            IS NOT DISTINCT FROM OLD.revoke_claim_expires_at_ms
        OR OLD.state = 'revoke_retry'
        AND NEW.state = 'revoke_claimed'
        AND NEW.revoke_result_owner_id IS NULL
        AND NEW.revoke_result_claim_fence IS NULL
        AND NEW.revoke_result_claimed_at_ms IS NULL
        AND NEW.revoke_result_claim_expires_at_ms IS NULL
    ) THEN
        RAISE EXCEPTION 'GitHub server-service revocation result provenance changed'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_revoke_result_provenance_exact';
    END IF;
    IF NEW.state = 'revoked'
        AND NEW.terminal_reason = 'provider_revoked'
        AND OLD.state <> 'revoke_claimed'
    THEN
        RAISE EXCEPTION 'GitHub server-service provider revocation lacks claim evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_provider_revocation_exact';
    END IF;
    IF (
        NEW.provider_expires_at_ms IS DISTINCT FROM OLD.provider_expires_at_ms
        OR NEW.safe_erase_after_ms IS DISTINCT FROM OLD.safe_erase_after_ms
    ) AND NOT (
        OLD.state IN ('minting', 'indeterminate')
        AND NEW.state IN ('ready', 'revoke_pending')
        AND OLD.provider_expires_at_ms IS NULL
        AND NEW.provider_expires_at_ms IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'GitHub server-service provider expiry evidence changed'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_provider_expiry_immutable';
    END IF;
    IF (
        NEW.plaintext_schema IS DISTINCT FROM OLD.plaintext_schema
        OR NEW.plaintext_size_bytes IS DISTINCT FROM OLD.plaintext_size_bytes
        OR NEW.plaintext_digest IS DISTINCT FROM OLD.plaintext_digest
        OR NEW.aad_digest IS DISTINCT FROM OLD.aad_digest
        OR NEW.envelope_schema IS DISTINCT FROM OLD.envelope_schema
        OR NEW.wrapping_key_id IS DISTINCT FROM OLD.wrapping_key_id
        OR NEW.wrapped_data_key IS DISTINCT FROM OLD.wrapped_data_key
        OR NEW.nonce IS DISTINCT FROM OLD.nonce
        OR NEW.ciphertext IS DISTINCT FROM OLD.ciphertext
    ) AND NOT (
        OLD.state IN ('minting', 'indeterminate')
            AND NEW.state IN ('ready', 'revoke_pending')
            AND OLD.envelope_schema IS NULL
            AND NEW.envelope_schema IS NOT NULL
        OR NEW.state = 'revoked'
            AND OLD.envelope_schema IS NOT NULL
            AND NEW.envelope_schema IS NULL
    ) THEN
        RAISE EXCEPTION 'GitHub server-service protected credential changed outside commit/erasure'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_protected_immutable';
    END IF;
    IF OLD.envelope_schema IS NOT NULL
        AND NEW.envelope_schema IS NOT NULL
        AND (
            NEW.plaintext_schema IS DISTINCT FROM OLD.plaintext_schema
            OR NEW.plaintext_size_bytes IS DISTINCT FROM OLD.plaintext_size_bytes
            OR NEW.plaintext_digest IS DISTINCT FROM OLD.plaintext_digest
            OR NEW.aad_digest IS DISTINCT FROM OLD.aad_digest
            OR NEW.envelope_schema IS DISTINCT FROM OLD.envelope_schema
            OR NEW.wrapping_key_id IS DISTINCT FROM OLD.wrapping_key_id
            OR NEW.wrapped_data_key IS DISTINCT FROM OLD.wrapped_data_key
            OR NEW.nonce IS DISTINCT FROM OLD.nonce
            OR NEW.ciphertext IS DISTINCT FROM OLD.ciphertext
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service protected credential is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_protected_immutable';
    END IF;
    IF OLD.state IN ('minting', 'indeterminate')
        AND NEW.state = 'revoke_pending'
        AND (
            NEW.state_updated_at_ms < OLD.mint_started_at_ms
            OR NEW.state_updated_at_ms >= NEW.safe_erase_after_ms
        )
    THEN
        RAISE EXCEPTION 'GitHub server-service revoke-only commit lacks begun mint evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_revoke_only_exact';
    END IF;
    IF NEW.state = 'revoked'
        AND NEW.terminal_reason IS DISTINCT FROM 'provider_revoked'
        AND NEW.state_updated_at_ms < OLD.safe_erase_after_ms
    THEN
        RAISE EXCEPTION 'GitHub server-service custody erased before safe horizon'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_server_service_issuances_safe_erase_horizon';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_github_server_service_reject_removal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'GitHub server-service authority evidence cannot be removed'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'github_server_service_authority_removal_forbidden';
END;
$$;

CREATE FUNCTION automata_github_workflow_rerun_subject_evidence_digest(operation_id uuid, tenant_id text, repository_id uuid, workflow_id uuid, snapshot_id uuid, run_id uuid, source_run_id uuid, root_invocation_id uuid, github_repository_owner_id bigint, github_check_subject_id uuid, github_check_head_sha bytea, workflow_path text, source_digest bytea, event_name text, event_digest bytea, git_ref text, workflow_plan_schema smallint, plan_digest bytea, logical_admission_digest bytea, admitted_at_ms bigint) RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to(
        'automata.store.github-workflow-rerun-subject-evidence.v1', 'UTF8'
    )
    || pg_catalog.decode('00', 'hex')
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(operation_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(tenant_id, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(repository_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(workflow_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(snapshot_id)
    )
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(run_id))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(source_run_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(root_invocation_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(github_repository_owner_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(github_check_subject_id)
    )
    || automata_github_provider_manifest_digest_part(github_check_head_sha)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(workflow_path, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(source_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(event_name, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(event_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(git_ref, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(workflow_plan_schema::BIGINT)
    )
    || automata_github_provider_manifest_digest_part(plan_digest)
    || automata_github_provider_manifest_digest_part(logical_admission_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admitted_at_ms)
    )
)
$$;

CREATE FUNCTION automata_github_workflow_run_subject_evidence_digest(tenant_id text, repository_id uuid, workflow_id uuid, snapshot_id uuid, run_id uuid, root_invocation_id uuid, provider_delivery_id uuid, provider_delivery_idempotency_key text, admission_claim_owner_id uuid, admission_claim_attempt smallint, admission_claim_fence bigint, admission_claimed_at_ms bigint, admission_claim_expires_at_ms bigint, github_check_subject_id uuid, github_check_head_sha bytea, provider_connection_id uuid, provider_installation_id bigint, github_repository_id bigint, github_repository_owner_id bigint, github_repository_name text, repository_visibility text, provider_manifest_revision bigint, provider_manifest_digest bytea, authenticated_webhook_verifier_fingerprint_sha256 bytea, authenticated_webhook_verifier_revision bigint, checks_authority_id uuid, checks_authority_identity_digest bytea, checks_authority_app_configuration_revision bigint, checks_authority_policy_revision bigint, private_source_authority_id uuid, private_source_authority_identity_digest bytea, private_source_authority_app_configuration_revision bigint, private_source_authority_policy_revision bigint, request_digest bytea, raw_event_digest bytea, accepted_at_ms bigint, workflow_path text, source_digest bytea, event_name text, event_digest bytea, git_ref text, workflow_plan_schema smallint, plan_digest bytea, logical_admission_digest bytea, admitted_at_ms bigint) RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to(
        'automata.store.github-workflow-run-subject-evidence.v1', 'UTF8'
    )
    || pg_catalog.decode('00', 'hex')
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(tenant_id, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(repository_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(workflow_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(snapshot_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(run_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(root_invocation_id))
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(provider_delivery_id))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(provider_delivery_idempotency_key, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.uuid_send(admission_claim_owner_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admission_claim_attempt::BIGINT)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admission_claim_fence)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admission_claimed_at_ms)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(admission_claim_expires_at_ms)
    )
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(github_check_subject_id))
    || automata_github_provider_manifest_digest_part(github_check_head_sha)
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(provider_connection_id))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(provider_installation_id)
    )
    || automata_github_provider_manifest_digest_part(pg_catalog.int8send(github_repository_id))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(github_repository_owner_id)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(github_repository_name, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(repository_visibility, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(provider_manifest_revision)
    )
    || automata_github_provider_manifest_digest_part(provider_manifest_digest)
    || automata_github_provider_manifest_digest_part(
        authenticated_webhook_verifier_fingerprint_sha256
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(authenticated_webhook_verifier_revision)
    )
    || automata_github_provider_manifest_digest_part(pg_catalog.uuid_send(checks_authority_id))
    || automata_github_provider_manifest_digest_part(checks_authority_identity_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(checks_authority_app_configuration_revision)
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(checks_authority_policy_revision)
    )
    || automata_github_provider_manifest_digest_part(
        CASE WHEN private_source_authority_id IS NULL
            THEN pg_catalog.decode('00', 'hex')
            ELSE pg_catalog.decode('01', 'hex')
        END
    )
    || CASE WHEN private_source_authority_id IS NULL THEN ''::BYTEA ELSE
        automata_github_provider_manifest_digest_part(
            pg_catalog.uuid_send(private_source_authority_id)
        )
        || automata_github_provider_manifest_digest_part(
            private_source_authority_identity_digest
        )
        || automata_github_provider_manifest_digest_part(
            pg_catalog.int8send(private_source_authority_app_configuration_revision)
        )
        || automata_github_provider_manifest_digest_part(
            pg_catalog.int8send(private_source_authority_policy_revision)
        )
       END
    || automata_github_provider_manifest_digest_part(request_digest)
    || automata_github_provider_manifest_digest_part(raw_event_digest)
    || automata_github_provider_manifest_digest_part(pg_catalog.int8send(accepted_at_ms))
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(workflow_path, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(source_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(event_name, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(event_digest)
    || automata_github_provider_manifest_digest_part(
        pg_catalog.convert_to(git_ref, 'UTF8')
    )
    || automata_github_provider_manifest_digest_part(
        pg_catalog.int8send(workflow_plan_schema::BIGINT)
    )
    || automata_github_provider_manifest_digest_part(plan_digest)
    || automata_github_provider_manifest_digest_part(logical_admission_digest)
    || automata_github_provider_manifest_digest_part(pg_catalog.int8send(admitted_at_ms))
)
$$;

CREATE FUNCTION automata_github_workflow_run_subject_evidence_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'GitHub workflow-run subject evidence is immutable'
        USING ERRCODE = 'check_violation',
              CONSTRAINT = 'github_workflow_run_subject_evidence_immutable';
END;
$$;

CREATE FUNCTION automata_github_workflow_run_subject_evidence_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_evidence RECORD;
    source_evidence_found BOOLEAN;
    run_evidence RECORD;
    run_evidence_found BOOLEAN;
    expected_digest BYTEA;
BEGIN
    SELECT evidence_source.*,
           inbox_source.request_digest,
           inbox_source.raw_event_digest,
           inbox_source.accepted_at_ms,
           inbox_source.state AS inbox_state,
           inbox_source.attempt_count AS inbox_attempt_count,
           inbox_source.claim_fence AS inbox_claim_fence,
           inbox_source.claim_owner_id AS inbox_claim_owner_id,
           inbox_source.claimed_at_ms AS inbox_claimed_at_ms,
           inbox_source.claim_expires_at_ms AS inbox_claim_expires_at_ms,
           manifest_source.workflow_path AS manifest_workflow_path,
           manifest_source.workflow_selection_kind AS manifest_workflow_selection_kind,
           manifest_source.event_name AS manifest_event_name,
           manifest_source.git_ref AS manifest_git_ref,
           subject_source.id AS subject_id,
           subject_source.provider_delivery_id AS subject_delivery_id,
           subject_source.repository_id AS subject_repository_id,
           subject_source.head_sha AS subject_head_sha,
           subject_source.subject_key AS subject_key,
           subject_source.workflow_run_id AS subject_run_id,
           subject_source.linked_at_ms AS subject_linked_at_ms,
           subject_source.desired_state AS subject_desired_state,
           subject_source.desired_conclusion AS subject_desired_conclusion,
           subject_source.terminal_cause AS subject_terminal_cause,
           subject_source.desired_revision AS subject_desired_revision,
           subject_source.desired_updated_at_ms AS subject_desired_updated_at_ms,
           repository_source.scm_provider AS repository_scm_provider,
           repository_source.provider_repository_id AS repository_provider_id,
           repository_source.owner AS repository_owner,
           repository_source.name AS repository_name
      INTO source_evidence
    FROM github_provider_delivery_evidence AS evidence_source
    JOIN provider_delivery_inbox AS inbox_source
      ON inbox_source.id = evidence_source.provider_delivery_id
     AND inbox_source.tenant_id = evidence_source.tenant_id
    JOIN github_provider_manifest_revisions AS manifest_source
      ON manifest_source.tenant_id = evidence_source.tenant_id
     AND manifest_source.repository_id = evidence_source.repository_id
     AND manifest_source.provider_connection_id = evidence_source.provider_connection_id
     AND manifest_source.manifest_revision = evidence_source.provider_manifest_revision
     AND manifest_source.manifest_digest = evidence_source.provider_manifest_digest
     AND manifest_source.webhook_verifier_fingerprint_sha256 =
         evidence_source.authenticated_webhook_verifier_fingerprint_sha256
     AND manifest_source.webhook_verifier_revision =
         evidence_source.authenticated_webhook_verifier_revision
    JOIN repositories AS repository_source
      ON repository_source.tenant_id = evidence_source.tenant_id
     AND repository_source.id = evidence_source.repository_id
    JOIN github_check_subjects AS subject_source
      ON subject_source.id = NEW.github_check_subject_id
     AND subject_source.tenant_id = evidence_source.tenant_id
     AND subject_source.provider_delivery_id = evidence_source.provider_delivery_id
     AND subject_source.repository_id = evidence_source.repository_id
    WHERE evidence_source.provider_delivery_id = NEW.provider_delivery_id
      AND evidence_source.tenant_id = NEW.tenant_id
      AND evidence_source.repository_id = NEW.repository_id
    FOR SHARE OF evidence_source, inbox_source, manifest_source, subject_source,
                 repository_source;
    source_evidence_found = FOUND;

    SELECT run_source.repository_id,
           run_source.workflow_id,
           run_source.snapshot_id,
           run_source.head_sha,
           run_source.event_name,
           run_source.event_digest,
           run_source.git_ref,
           run_source.plan_schema,
           run_source.plan_digest,
           run_source.admission_epoch,
           run_source.created_at_ms,
           workflow_source.path AS workflow_path,
           snapshot_source.source_digest,
           marker_source.root_invocation_id,
           marker_source.admission_digest,
           marker_source.admitted_at_ms AS marker_admitted_at_ms,
           invocation_source.plan_schema AS invocation_plan_schema,
           invocation_source.plan_digest AS invocation_plan_digest,
           admission_receipt_source.repository_id AS receipt_repository_id,
           admission_receipt_source.run_id AS receipt_run_id,
           admission_receipt_source.committed_at_ms AS receipt_committed_at_ms,
           admission_receipt_source.github_subject_evidence_required AS
               receipt_github_evidence_required
      INTO run_evidence
    FROM workflow_runs AS run_source
    JOIN workflow_definitions AS workflow_source
      ON workflow_source.id = run_source.workflow_id
     AND workflow_source.repository_id = run_source.repository_id
    JOIN workflow_snapshots AS snapshot_source
      ON snapshot_source.id = run_source.snapshot_id
     AND snapshot_source.workflow_id = run_source.workflow_id
    JOIN logical_workflow_runs AS marker_source
      ON marker_source.run_id = run_source.id
    JOIN logical_workflow_invocations AS invocation_source
      ON invocation_source.run_id = run_source.id
     AND invocation_source.id = marker_source.root_invocation_id
    JOIN github_provider_delivery_evidence AS admission_evidence_source
      ON admission_evidence_source.tenant_id = NEW.tenant_id
     AND admission_evidence_source.repository_id = NEW.repository_id
     AND admission_evidence_source.provider_delivery_id = NEW.provider_delivery_id
    JOIN provider_delivery_inbox AS admission_inbox_source
      ON admission_inbox_source.id = admission_evidence_source.provider_delivery_id
     AND admission_inbox_source.tenant_id = admission_evidence_source.tenant_id
    JOIN workflow_admission_receipts AS admission_receipt_source
     ON admission_receipt_source.tenant_id = admission_evidence_source.tenant_id
     AND admission_receipt_source.idempotency_kind = 'provider_delivery'
     AND admission_receipt_source.idempotency_key =
         NEW.provider_delivery_idempotency_key
     AND admission_receipt_source.request_digest = marker_source.admission_digest
    WHERE run_source.repository_id = NEW.repository_id
      AND run_source.id = NEW.run_id
    FOR SHARE OF run_source, workflow_source, snapshot_source,
                 marker_source, invocation_source, admission_evidence_source,
                 admission_inbox_source, admission_receipt_source;
    run_evidence_found = FOUND;

    IF NOT source_evidence_found
        OR NOT run_evidence_found
        OR NEW.workflow_id <> run_evidence.workflow_id
        OR NEW.snapshot_id <> run_evidence.snapshot_id
        OR NEW.root_invocation_id <> run_evidence.root_invocation_id
        OR NEW.github_check_subject_id <> source_evidence.subject_id
        OR NEW.github_check_head_sha <> source_evidence.github_check_head_sha
        OR NEW.github_check_head_sha <> source_evidence.subject_head_sha
        OR NEW.github_check_head_sha <> run_evidence.head_sha
        OR source_evidence.repository_scm_provider <> 'github'
        OR source_evidence.repository_provider_id <>
            source_evidence.github_repository_id::TEXT
        OR source_evidence.repository_owner <>
            split_part(source_evidence.github_repository_name, '/', 1)
        OR source_evidence.repository_name <>
            split_part(source_evidence.github_repository_name, '/', 2)
        OR run_evidence.receipt_repository_id IS DISTINCT FROM NEW.repository_id
        OR run_evidence.receipt_run_id IS DISTINCT FROM NEW.run_id
        OR run_evidence.receipt_committed_at_ms IS DISTINCT FROM NEW.admitted_at_ms
        OR run_evidence.receipt_github_evidence_required IS DISTINCT FROM TRUE
        OR source_evidence.inbox_state <> 'claimed'
        OR source_evidence.inbox_attempt_count <> NEW.admission_claim_attempt
        OR source_evidence.inbox_claim_fence <> NEW.admission_claim_fence
        OR source_evidence.inbox_claim_owner_id <> NEW.admission_claim_owner_id
        OR source_evidence.inbox_claimed_at_ms <> NEW.admission_claimed_at_ms
        OR source_evidence.inbox_claim_expires_at_ms <>
            NEW.admission_claim_expires_at_ms
        OR NEW.admitted_at_ms < NEW.admission_claimed_at_ms
        OR NEW.admitted_at_ms >= NEW.admission_claim_expires_at_ms
        OR source_evidence.subject_delivery_id <> NEW.provider_delivery_id
        OR source_evidence.subject_repository_id <> NEW.repository_id
        OR source_evidence.subject_run_id <> NEW.run_id
        OR source_evidence.subject_linked_at_ms <> NEW.admitted_at_ms
        OR source_evidence.subject_desired_state <> 'in_progress'
        OR source_evidence.subject_desired_conclusion IS NOT NULL
        OR source_evidence.subject_terminal_cause IS NOT NULL
        OR source_evidence.subject_desired_revision <> 2
        OR source_evidence.subject_desired_updated_at_ms <> NEW.admitted_at_ms
        OR source_evidence.subject_key <> NEW.workflow_path
        OR NOT (
            source_evidence.manifest_workflow_selection_kind = 'all_direct'
            AND EXISTS (
                SELECT 1
                FROM provider_delivery_workflow_inventories AS inventory
                JOIN provider_delivery_workflow_inventory_entries AS entry
                  ON entry.inbox_id = inventory.inbox_id
                 AND entry.tenant_id = inventory.tenant_id
                WHERE inventory.inbox_id = NEW.provider_delivery_id
                  AND inventory.tenant_id = NEW.tenant_id
                  AND inventory.manifest_digest =
                      source_evidence.provider_manifest_digest
                  AND entry.workflow_path = NEW.workflow_path
                  AND entry.source_state = 'ready'
                  AND entry.source_digest = NEW.source_digest
            )
        )
        OR NEW.workflow_path <> run_evidence.workflow_path
        OR NEW.source_digest <> run_evidence.source_digest
        OR NEW.event_name <> COALESCE(source_evidence.authenticated_event_name, source_evidence.manifest_event_name)
        OR NEW.event_name <> run_evidence.event_name
        OR NEW.event_digest <> run_evidence.event_digest
        OR NEW.event_digest <> source_evidence.raw_event_digest
        OR NEW.git_ref <> COALESCE(source_evidence.authenticated_event_git_ref, source_evidence.manifest_git_ref)
        OR NEW.git_ref <> run_evidence.git_ref
        OR NEW.workflow_plan_schema <> run_evidence.plan_schema
        OR NEW.workflow_plan_schema <> run_evidence.invocation_plan_schema
        OR NEW.plan_digest <> run_evidence.plan_digest
        OR NEW.plan_digest <> run_evidence.invocation_plan_digest
        OR NEW.logical_admission_digest <> run_evidence.admission_digest
        OR run_evidence.admission_epoch <> 1
        OR NEW.admitted_at_ms <> run_evidence.created_at_ms
        OR NEW.admitted_at_ms <> run_evidence.marker_admitted_at_ms
        OR NEW.admitted_at_ms < source_evidence.accepted_at_ms
    THEN
        RAISE EXCEPTION 'GitHub workflow-run subject evidence authority is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_workflow_run_subject_evidence_authority_exact';
    END IF;

    expected_digest = automata_github_workflow_run_subject_evidence_digest(
        NEW.tenant_id,
        NEW.repository_id,
        NEW.workflow_id,
        NEW.snapshot_id,
        NEW.run_id,
        NEW.root_invocation_id,
        NEW.provider_delivery_id,
        NEW.provider_delivery_idempotency_key,
        NEW.admission_claim_owner_id,
        NEW.admission_claim_attempt,
        NEW.admission_claim_fence,
        NEW.admission_claimed_at_ms,
        NEW.admission_claim_expires_at_ms,
        NEW.github_check_subject_id,
        NEW.github_check_head_sha,
        source_evidence.provider_connection_id,
        source_evidence.provider_installation_id,
        source_evidence.github_repository_id,
        source_evidence.github_repository_owner_id,
        source_evidence.github_repository_name,
        source_evidence.repository_visibility,
        source_evidence.provider_manifest_revision,
        source_evidence.provider_manifest_digest,
        source_evidence.authenticated_webhook_verifier_fingerprint_sha256,
        source_evidence.authenticated_webhook_verifier_revision,
        source_evidence.checks_authority_id,
        source_evidence.checks_authority_identity_digest,
        source_evidence.checks_authority_app_configuration_revision,
        source_evidence.checks_authority_policy_revision,
        source_evidence.private_source_authority_id,
        source_evidence.private_source_authority_identity_digest,
        source_evidence.private_source_authority_app_configuration_revision,
        source_evidence.private_source_authority_policy_revision,
        source_evidence.request_digest,
        source_evidence.raw_event_digest,
        source_evidence.accepted_at_ms,
        NEW.workflow_path,
        NEW.source_digest,
        NEW.event_name,
        NEW.event_digest,
        NEW.git_ref,
        NEW.workflow_plan_schema,
        NEW.plan_digest,
        NEW.logical_admission_digest,
        NEW.admitted_at_ms
    );

    IF NEW.subject_evidence_sha256 IS DISTINCT FROM expected_digest THEN
        RAISE EXCEPTION 'GitHub workflow-run subject evidence digest is not canonical'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_workflow_run_subject_evidence_canonical';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_runtime_authority_mint_begin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' OR pg_trigger_depth() <> 2 THEN
        RAISE EXCEPTION 'GitHub runtime-authority mint begins are trigger-owned and immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_mint_begin_immutable';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM github_runtime_authority_issuances AS authority
        JOIN github_runtime_authority_mint_claims AS claim
          ON claim.attempt_id = authority.attempt_id
         AND claim.fencing_token = authority.fencing_token
         AND claim.claim_fence = authority.mint_claim_fence
         AND claim.tenant_id = authority.tenant_id
         AND claim.claim_owner_id = authority.mint_claim_owner_id
         AND claim.claimed_at_ms = NEW.claimed_at_ms
         AND claim.expires_at_ms = NEW.expires_at_ms
        WHERE authority.attempt_id = NEW.attempt_id
          AND authority.fencing_token = NEW.fencing_token
          AND authority.tenant_id = NEW.tenant_id
          AND authority.state = 'minting'
          AND authority.mint_claim_fence = NEW.claim_fence
          AND authority.mint_claim_owner_id = NEW.claim_owner_id
          AND authority.mint_claimed_at_ms = NEW.claimed_at_ms
          AND authority.mint_started_at_ms = NEW.started_at_ms
          AND authority.mint_provider_request_millis =
              NEW.provider_request_millis
          AND NEW.started_at_ms::NUMERIC +
              NEW.provider_request_millis::NUMERIC
              <= authority.request_deadline_at_ms::NUMERIC
        FOR KEY SHARE OF authority, claim
    ) THEN
        RAISE EXCEPTION 'GitHub runtime-authority mint begin is not exact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_mint_begin_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_runtime_authority_mint_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'GitHub runtime-authority mint claims are immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_mint_claim_immutable';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM github_runtime_authority_issuances AS authority
        WHERE authority.attempt_id = NEW.attempt_id
          AND authority.fencing_token = NEW.fencing_token
          AND authority.tenant_id = NEW.tenant_id
          AND authority.state = 'claimed'
          AND authority.mint_claim_fence = NEW.claim_fence
          AND authority.mint_claim_owner_id = NEW.claim_owner_id
          AND authority.mint_claimed_at_ms = NEW.claimed_at_ms
          AND authority.mint_claim_expires_at_ms = NEW.expires_at_ms
        FOR KEY SHARE
    ) THEN
        RAISE EXCEPTION 'GitHub runtime-authority mint claim is not exact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_mint_claim_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_runtime_authority_operation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'GitHub runtime-authority operation evidence is immutable'
        USING ERRCODE = 'check_violation',
              CONSTRAINT = 'github_runtime_authority_operation_receipt_immutable';
END;
$$;

CREATE FUNCTION automata_guard_github_runtime_authority_operation_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' OR pg_trigger_depth() <> 2 THEN
        RAISE EXCEPTION 'GitHub runtime-authority operation transitions are immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_operation_transition_immutable';
    END IF;
    NEW.operation_digest := automata_github_runtime_authority_operation_digest(
        NEW.request_kind, NEW.attempt_id, NEW.fencing_token,
        NEW.claim_fence, NEW.claim_owner_id, NEW.claim_claimed_at_ms,
        NEW.claim_expires_at_ms, NEW.request_observed_at_ms,
        NEW.request_retry_at_ms, NEW.request_failure_kind,
        NEW.request_commit_disposition, NEW.request_provider_expires_at_ms,
        NEW.request_safe_erase_after_ms, NEW.request_plaintext_schema,
        NEW.request_plaintext_size_bytes, NEW.request_plaintext_digest,
        NEW.request_aad_digest, NEW.request_envelope_digest
    );
    IF NEW.operation_digest IS NULL THEN
        RAISE EXCEPTION 'GitHub runtime-authority operation digest is not canonical'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_operation_digest_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_runtime_authority_revocation_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'GitHub runtime-authority revocation claims are immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_revocation_claim_immutable';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM github_runtime_authority_issuances AS authority
        WHERE authority.attempt_id = NEW.attempt_id
          AND authority.fencing_token = NEW.fencing_token
          AND authority.tenant_id = NEW.tenant_id
          AND authority.state = 'revoke_pending'
          AND authority.revoke_claim_fence = NEW.claim_fence
          AND authority.revoke_claim_owner_id = NEW.claim_owner_id
          AND authority.revoke_claimed_at_ms = NEW.claimed_at_ms
          AND authority.revoke_claim_expires_at_ms = NEW.expires_at_ms
          AND authority.aad_digest = NEW.aad_digest
          AND authority.safe_erase_after_ms = NEW.safe_erase_after_ms
        FOR KEY SHARE
    ) THEN
        RAISE EXCEPTION 'GitHub runtime-authority revocation claim is not exact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_revocation_claim_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_runtime_authority_database_time() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
BEGIN
    IF NEW.state_updated_at_ms > database_now THEN
        RAISE EXCEPTION 'GitHub runtime-authority state time is ahead of PostgreSQL time'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_database_time';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'claimed'
            OR NEW.mint_claimed_at_ms > database_now
            OR NEW.mint_claim_expires_at_ms <= database_now
            OR NEW.state_updated_at_ms <> NEW.mint_claimed_at_ms
            OR NOT automata_github_runtime_authority_is_current(NEW, database_now)
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority claim is not current at PostgreSQL time'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_insert_database_time';
        END IF;
        RETURN NEW;
    END IF;

    -- A terminal receipt observation does not advance lifecycle time.  Its
    -- exact database-time eligibility is re-proved by the trigger-owned
    -- operation transition after the lifecycle guard proves it is otherwise
    -- a byte-for-byte self transition.
    IF OLD.state = NEW.state
        AND NEW.operation_request_kind IS NOT NULL
        AND automata_github_runtime_authority_same_non_operation_state(
            OLD, NEW
        )
    THEN
        RETURN NEW;
    END IF;

    IF NEW.state = 'claimed' AND OLD.state IN ('claimed', 'mint_retry_pending') THEN
        IF NEW.mint_claimed_at_ms > database_now
            OR NEW.mint_claim_expires_at_ms <= database_now
            OR (
                OLD.state = 'claimed'
                AND OLD.mint_claim_expires_at_ms > database_now
            )
            OR (
                OLD.state = 'mint_retry_pending'
                AND OLD.next_mint_at_ms > database_now
            )
            OR NOT automata_github_runtime_authority_is_current(NEW, database_now)
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority mint claim is not due and live'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_mint_claim_database_time';
        END IF;
    ELSIF OLD.state = 'claimed' AND NEW.state = 'minting' THEN
        IF OLD.mint_claimed_at_ms > database_now
            OR OLD.mint_claim_expires_at_ms <= database_now
            OR NEW.mint_started_at_ms > database_now
            OR NEW.mint_provider_request_millis NOT BETWEEN 1 AND 120000
            OR database_now::NUMERIC + NEW.mint_provider_request_millis::NUMERIC
                > OLD.mint_claim_expires_at_ms::NUMERIC
            OR database_now::NUMERIC + NEW.mint_provider_request_millis::NUMERIC
                > NEW.request_deadline_at_ms::NUMERIC
            OR NOT automata_github_runtime_authority_is_current(NEW, database_now)
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority mint begin lacks a live database claim'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_mint_begin_database_time';
        END IF;
    ELSIF OLD.state = 'minting' AND NEW.state = 'mint_retry_pending' THEN
        IF NEW.next_mint_at_ms <= database_now
            OR NEW.request_deadline_at_ms <= NEW.next_mint_at_ms
            OR NOT automata_github_runtime_authority_is_current(NEW, database_now)
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority retry is not current at PostgreSQL time'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_mint_retry_database_time';
        END IF;
    ELSIF OLD.state = 'minting' AND NEW.state = 'indeterminate' THEN
        IF NEW.indeterminate_at_ms > database_now
            OR NEW.conservative_expiry_at_ms <= database_now
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority indeterminate boundary is expired'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_indeterminate_database_time';
        END IF;
    ELSIF OLD.state IN ('minting', 'indeterminate')
          AND NEW.state IN ('ready', 'revoke_pending') THEN
        IF NEW.safe_erase_after_ms <= database_now
            OR (
                NEW.state = 'ready'
                AND (
                    OLD.state <> 'minting'
                    OR NEW.ready_at_ms > database_now
                    OR NEW.provider_expires_at_ms::NUMERIC
                        <= database_now::NUMERIC + 60000
                    OR NOT automata_github_runtime_authority_is_current(NEW, database_now)
                )
            )
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority finalization is stale at PostgreSQL time'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_finalize_database_time';
        END IF;
    ELSIF OLD.state = 'ready' AND NEW.state = 'revoke_pending' THEN
        IF NEW.safe_erase_after_ms <= database_now
            OR automata_github_runtime_authority_is_current(OLD, database_now)
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority revocation transition is not due'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_revoke_pending_database_time';
        END IF;
    ELSIF OLD.state IN ('ready', 'revoke_pending') AND NEW.state = 'quarantined' THEN
        IF NEW.quarantine_at_ms > database_now
            OR NEW.safe_erase_after_ms <= database_now
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority quarantine is past safe custody'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_quarantine_database_time';
        END IF;
    ELSIF OLD.state = 'revoke_pending' AND NEW.state = 'revoke_pending' THEN
        IF OLD.revoke_claim_owner_id IS NULL AND NEW.revoke_claim_owner_id IS NOT NULL THEN
            IF OLD.next_revoke_at_ms > database_now
                OR NEW.revoke_claimed_at_ms > database_now
                OR NEW.revoke_claim_expires_at_ms <= database_now
                OR NEW.revoke_claim_expires_at_ms >= NEW.safe_erase_after_ms
            THEN
                RAISE EXCEPTION 'GitHub runtime-authority revoke claim is not due and live'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'github_runtime_authority_revoke_claim_database_time';
            END IF;
        ELSIF OLD.revoke_claim_owner_id IS NOT NULL
              AND NEW.revoke_claim_owner_id IS NOT NULL THEN
            IF OLD.revoke_claim_expires_at_ms > database_now
                OR NEW.revoke_claimed_at_ms > database_now
                OR NEW.revoke_claim_expires_at_ms <= database_now
                OR NEW.revoke_claim_expires_at_ms >= NEW.safe_erase_after_ms
            THEN
                RAISE EXCEPTION 'GitHub runtime-authority revoke takeover is not due and live'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'github_runtime_authority_revoke_takeover_database_time';
            END IF;
        ELSIF OLD.revoke_claim_owner_id IS NOT NULL
              AND NEW.revoke_claim_owner_id IS NULL THEN
            IF NEW.last_revoke_failure_kind = 'claim_budget_exhausted' THEN
                IF OLD.revoke_claim_expires_at_ms > database_now
                    OR NOT (
                        OLD.revoke_attempt_count = 64
                        OR OLD.revoke_claim_fence = 9223372036854775807
                    )
                THEN
                    RAISE EXCEPTION 'GitHub runtime-authority revoke budget is not exhausted'
                        USING ERRCODE = 'check_violation',
                              CONSTRAINT =
                                  'github_runtime_authority_revoke_budget_database_time';
                END IF;
            ELSIF OLD.revoke_claimed_at_ms > database_now
                OR OLD.revoke_claim_expires_at_ms <= database_now
            THEN
                RAISE EXCEPTION 'GitHub runtime-authority revoke outcome lacks a live claim'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'github_runtime_authority_revoke_outcome_database_time';
            END IF;
        END IF;
    ELSIF NEW.state = 'revoked' THEN
        IF NEW.terminal_reason = 'provider_revocation_confirmed' AND (
                OLD.revoke_claimed_at_ms > database_now
                OR OLD.revoke_claim_expires_at_ms <= database_now
            )
            OR NEW.terminal_reason IN (
                'provider_authority_expired', 'conservative_authority_expired',
                'quarantined_authority_expired'
            ) AND OLD.safe_erase_after_ms > database_now
            OR NEW.terminal_reason = 'indeterminate_authority_expired'
                AND OLD.conservative_expiry_at_ms > database_now
            OR NEW.terminal_reason = 'superseded_before_mint'
                AND automata_github_runtime_authority_is_current(OLD, database_now)
            OR NEW.terminal_reason = 'request_expired_before_mint'
                AND OLD.request_deadline_at_ms > database_now
        THEN
            RAISE EXCEPTION 'GitHub runtime-authority terminal transition is not due'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'github_runtime_authority_terminal_database_time';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_schedule_discovery_claim_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    manifest github_provider_manifest_revisions%ROWTYPE;
    authority github_server_service_authorities%ROWTYPE;
    observed_at_ms BIGINT := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
BEGIN
    SELECT revision.* INTO manifest
      FROM github_provider_manifest_revisions AS revision
      JOIN github_provider_manifest_current AS current
        ON current.tenant_id = revision.tenant_id
       AND current.repository_id = revision.repository_id
       AND current.provider_connection_id = revision.provider_connection_id
       AND current.manifest_revision = revision.manifest_revision
       AND current.manifest_digest = revision.manifest_digest
     WHERE revision.tenant_id = NEW.tenant_id
       AND revision.repository_id = NEW.repository_id
       AND revision.provider_connection_id = NEW.provider_connection_id
       AND revision.manifest_revision = NEW.manifest_revision
       AND revision.manifest_digest = NEW.manifest_digest
     FOR SHARE OF revision, current;
    IF NEW.source_authority_kind = 'private_repository_source_read' THEN
        SELECT * INTO authority
          FROM github_server_service_authorities
         WHERE tenant_id = NEW.tenant_id
           AND id = NEW.private_source_authority_id
         FOR SHARE;
    END IF;
    IF manifest.provider_connection_id IS NULL
        OR manifest.github_repository_owner_id IS NULL
        OR manifest.github_repository_owner_id <> NEW.github_repository_owner_id
        OR NEW.claimed_at_ms > observed_at_ms
        OR observed_at_ms - NEW.claimed_at_ms > 60000
        OR NEW.claim_expires_at_ms <= observed_at_ms
        OR (
            NEW.source_authority_kind = 'public_anonymous'
            AND manifest.repository_visibility <> 'public'
        )
        OR (
            NEW.source_authority_kind = 'private_repository_source_read'
            AND (
                manifest.repository_visibility <> 'private'
                OR authority.id IS NULL
                OR authority.repository_id <> NEW.repository_id
                OR authority.provider_connection_id <> NEW.provider_connection_id
                OR authority.provider_installation_id <> manifest.provider_installation_id
                OR authority.github_app_id <> manifest.github_app_id
                OR authority.github_repository_id <> manifest.github_repository_id
                OR authority.github_repository_name <> manifest.github_repository_name
                OR authority.service_scope <> 'private_repository_source_read'
                OR authority.github_app_client_id <> manifest.github_app_client_id
                OR authority.github_app_jwt_issuer_kind <>
                    manifest.github_app_jwt_issuer_kind
                OR authority.app_key_spki_sha256 <> manifest.app_key_spki_sha256
                OR authority.app_configuration_revision <>
                    NEW.private_source_authority_app_configuration_revision
                OR authority.app_configuration_revision <> manifest.app_configuration_revision
                OR authority.policy_revision <> NEW.private_source_authority_policy_revision
                OR authority.policy_revision <> manifest.policy_revision
                OR authority.identity_digest <> NEW.private_source_authority_identity_digest
                OR authority.state <> 'active'
                OR authority.created_at_ms > NEW.claimed_at_ms
            )
        )
    THEN
        RAISE EXCEPTION 'GitHub schedule discovery authority is not exact and live'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_discovery_authority_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_schedule_discovery_claim_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    observed_at_ms BIGINT := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
BEGIN
    IF TG_OP = 'DELETE'
        OR OLD.state <> 'claimed'
        OR NEW.discovery_id IS DISTINCT FROM OLD.discovery_id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
        OR NEW.provider_connection_id IS DISTINCT FROM OLD.provider_connection_id
        OR NEW.manifest_revision IS DISTINCT FROM OLD.manifest_revision
        OR NEW.manifest_digest IS DISTINCT FROM OLD.manifest_digest
        OR NEW.github_repository_owner_id IS DISTINCT FROM OLD.github_repository_owner_id
        OR NEW.source_authority_kind IS DISTINCT FROM OLD.source_authority_kind
        OR NEW.private_source_authority_id IS DISTINCT FROM OLD.private_source_authority_id
        OR NEW.private_source_authority_identity_digest IS DISTINCT FROM
            OLD.private_source_authority_identity_digest
        OR NEW.private_source_authority_app_configuration_revision IS DISTINCT FROM
            OLD.private_source_authority_app_configuration_revision
        OR NEW.private_source_authority_policy_revision IS DISTINCT FROM
            OLD.private_source_authority_policy_revision
        OR NEW.claim_owner_id IS DISTINCT FROM OLD.claim_owner_id
        OR NEW.claim_fence IS DISTINCT FROM OLD.claim_fence
        OR NEW.claimed_at_ms IS DISTINCT FROM OLD.claimed_at_ms
        OR NEW.claim_expires_at_ms IS DISTINCT FROM OLD.claim_expires_at_ms
        OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms
        OR NEW.updated_at_ms < OLD.updated_at_ms
        OR NEW.state NOT IN ('completed', 'expired')
        OR NEW.state = 'completed' AND (
            NEW.updated_at_ms >= OLD.claim_expires_at_ms
            OR observed_at_ms >= OLD.claim_expires_at_ms
        )
        OR NEW.state = 'expired' AND (
            NEW.updated_at_ms < OLD.claim_expires_at_ms
            OR observed_at_ms < OLD.claim_expires_at_ms
        )
    THEN
        RAISE EXCEPTION 'GitHub schedule discovery transition is invalid'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_discovery_transition_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_schedule_fire_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'GitHub schedule fire evidence cannot be deleted'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_fire_transition_exact';
    END IF;
    IF OLD.state IN ('admitted', 'skipped', 'failed')
        OR NEW.fire_id IS DISTINCT FROM OLD.fire_id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
        OR NEW.provider_connection_id IS DISTINCT FROM OLD.provider_connection_id
        OR NEW.registry_id IS DISTINCT FROM OLD.registry_id
        OR NEW.entry_ordinal IS DISTINCT FROM OLD.entry_ordinal
        OR NEW.scheduled_at_ms IS DISTINCT FROM OLD.scheduled_at_ms
        OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms
        OR NEW.updated_at_ms < OLD.updated_at_ms
    THEN
        RAISE EXCEPTION 'GitHub schedule fire identity or terminal evidence is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_fire_transition_exact';
    END IF;

    IF OLD.state = 'pending' THEN
        IF NEW.state = 'claimed' THEN
            IF NEW.attempt_count <> OLD.attempt_count + 1
                OR NEW.claim_fence <> OLD.claim_fence + 1
                OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
                OR NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id
                OR NEW.failure_kind IS DISTINCT FROM OLD.failure_kind
                OR NEW.claimed_at_ms IS DISTINCT FROM NEW.updated_at_ms
                OR NEW.claimed_at_ms < OLD.next_attempt_at_ms
                OR NEW.claim_expires_at_ms - NEW.updated_at_ms > 300000
            THEN
                RAISE EXCEPTION 'pending GitHub schedule fire claim transition is invalid'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_schedule_fire_transition_exact';
            END IF;
        ELSIF NEW.state = 'failed' THEN
            IF NEW.attempt_count IS DISTINCT FROM OLD.attempt_count
                OR NEW.claim_fence IS DISTINCT FROM OLD.claim_fence
                OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
                OR NEW.workflow_run_id IS NOT NULL
                OR NEW.failure_kind IS DISTINCT FROM 'registry_superseded'
            THEN
                RAISE EXCEPTION 'pending GitHub schedule fire terminal transition is invalid'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_schedule_fire_transition_exact';
            END IF;
        ELSE
            RAISE EXCEPTION 'pending GitHub schedule fire state transition is invalid'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_schedule_fire_transition_exact';
        END IF;
    ELSIF OLD.state = 'claimed' THEN
        IF NEW.attempt_count IS DISTINCT FROM OLD.attempt_count
            OR NEW.claim_fence IS DISTINCT FROM OLD.claim_fence
        THEN
            RAISE EXCEPTION 'claimed GitHub schedule fire fence is immutable'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_schedule_fire_transition_exact';
        END IF;
        IF NEW.state = 'claimed' THEN
            IF NEW.claim_owner_id IS DISTINCT FROM OLD.claim_owner_id
                OR NEW.claimed_at_ms IS DISTINCT FROM OLD.claimed_at_ms
                OR NEW.claim_expires_at_ms <= OLD.claim_expires_at_ms
                OR NEW.claim_expires_at_ms - NEW.updated_at_ms > 300000
                OR NEW.updated_at_ms >= OLD.claim_expires_at_ms
                OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
                OR NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id
                OR NEW.failure_kind IS DISTINCT FROM OLD.failure_kind
            THEN
                RAISE EXCEPTION 'GitHub schedule fire renewal is invalid'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_schedule_fire_transition_exact';
            END IF;
        ELSIF NEW.state = 'pending' THEN
            IF NEW.claim_owner_id IS NOT NULL
                OR NEW.claimed_at_ms IS NOT NULL
                OR NEW.claim_expires_at_ms IS NOT NULL
                OR NEW.next_attempt_at_ms < NEW.updated_at_ms
                OR NEW.workflow_run_id IS NOT NULL
                OR NEW.failure_kind IS NOT NULL
            THEN
                RAISE EXCEPTION 'GitHub schedule fire retry transition is invalid'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_schedule_fire_transition_exact';
            END IF;
        ELSIF NEW.state IN ('admitted', 'skipped', 'failed') THEN
            IF NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
                OR (
                    NEW.failure_kind IS DISTINCT FROM 'registry_superseded'
                    AND NEW.failure_kind IS DISTINCT FROM
                        'github.schedule.attempts_exhausted'
                    AND NEW.updated_at_ms >= OLD.claim_expires_at_ms
                )
                OR NEW.failure_kind = 'github.schedule.attempts_exhausted'
                   AND OLD.attempt_count <> 20
            THEN
                RAISE EXCEPTION 'GitHub schedule fire completion transition is invalid'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'github_schedule_fire_transition_exact';
            END IF;
        ELSE
            RAISE EXCEPTION 'claimed GitHub schedule fire state transition is invalid'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_schedule_fire_transition_exact';
        END IF;
    ELSE
        RAISE EXCEPTION 'GitHub schedule fire state is unsupported'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_fire_transition_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_schedule_registry_entry_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
      FROM github_schedule_registry_revisions
     WHERE registry_id = NEW.registry_id
     FOR KEY SHARE;
    IF EXISTS (
        SELECT 1 FROM github_schedule_registry_seals
        WHERE registry_id = NEW.registry_id
    ) THEN
        RAISE EXCEPTION 'sealed GitHub schedule registry cannot accept entries'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_registry_entry_after_seal';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_github_schedule_registry_revision_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    manifest github_provider_manifest_revisions%ROWTYPE;
    authority github_server_service_authorities%ROWTYPE;
    discovery github_schedule_discovery_claims%ROWTYPE;
    observed_at_ms BIGINT := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
BEGIN
    SELECT * INTO discovery
      FROM github_schedule_discovery_claims
     WHERE discovery_id = NEW.discovery_id
     FOR UPDATE;
    IF discovery.discovery_id IS NULL
        OR discovery.state <> 'claimed'
        OR discovery.claimed_at_ms > NEW.discovered_at_ms
        OR NEW.discovered_at_ms >= discovery.claim_expires_at_ms
        OR observed_at_ms >= discovery.claim_expires_at_ms
        OR discovery.tenant_id <> NEW.tenant_id
        OR discovery.repository_id <> NEW.repository_id
        OR discovery.provider_connection_id <> NEW.provider_connection_id
        OR discovery.manifest_revision <> NEW.manifest_revision
        OR discovery.manifest_digest <> NEW.manifest_digest
        OR discovery.github_repository_owner_id <> NEW.github_repository_owner_id
        OR discovery.source_authority_kind <> NEW.source_authority_kind
        OR discovery.private_source_authority_id IS DISTINCT FROM
            NEW.private_source_authority_id
        OR discovery.private_source_authority_identity_digest IS DISTINCT FROM
            NEW.private_source_authority_identity_digest
        OR discovery.private_source_authority_app_configuration_revision IS DISTINCT FROM
            NEW.private_source_authority_app_configuration_revision
        OR discovery.private_source_authority_policy_revision IS DISTINCT FROM
            NEW.private_source_authority_policy_revision
    THEN
        RAISE EXCEPTION 'GitHub schedule registry lacks an exact live discovery claim'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_registry_discovery_claim_exact';
    END IF;
    SELECT revision.* INTO manifest
      FROM github_provider_manifest_revisions AS revision
      JOIN github_provider_manifest_current AS current
        ON current.tenant_id = revision.tenant_id
       AND current.repository_id = revision.repository_id
       AND current.provider_connection_id = revision.provider_connection_id
       AND current.manifest_revision = revision.manifest_revision
       AND current.manifest_digest = revision.manifest_digest
     WHERE revision.tenant_id = NEW.tenant_id
       AND revision.repository_id = NEW.repository_id
       AND revision.provider_connection_id = NEW.provider_connection_id
       AND revision.manifest_revision = NEW.manifest_revision
       AND revision.manifest_digest = NEW.manifest_digest
     FOR SHARE OF revision, current;
    IF manifest.provider_connection_id IS NULL
        OR manifest.github_repository_owner_id IS NULL
        OR manifest.github_repository_owner_id <> NEW.github_repository_owner_id
        OR manifest.git_ref <> NEW.default_branch_ref
    THEN
        RAISE EXCEPTION 'GitHub schedule registry lacks its exact current manifest'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_registry_source_authority_exact';
    END IF;

    IF NEW.source_authority_kind = 'private_repository_source_read' THEN
        SELECT * INTO authority
          FROM github_server_service_authorities
         WHERE tenant_id = NEW.tenant_id
           AND id = NEW.private_source_authority_id
         FOR SHARE;
    END IF;
    IF (
        NEW.source_authority_kind = 'public_anonymous'
        AND manifest.repository_visibility <> 'public'
    ) OR (
        NEW.source_authority_kind = 'private_repository_source_read'
        AND (
            manifest.repository_visibility <> 'private'
            OR authority.id IS NULL
            OR authority.repository_id <> NEW.repository_id
            OR authority.provider_connection_id <> NEW.provider_connection_id
            OR authority.provider_installation_id <> manifest.provider_installation_id
            OR authority.github_app_id <> manifest.github_app_id
            OR authority.github_repository_id <> manifest.github_repository_id
            OR authority.github_repository_name <> manifest.github_repository_name
            OR authority.service_scope <> 'private_repository_source_read'
            OR authority.github_app_client_id <> manifest.github_app_client_id
            OR authority.github_app_jwt_issuer_kind <>
                manifest.github_app_jwt_issuer_kind
            OR authority.app_key_spki_sha256 <> manifest.app_key_spki_sha256
            OR authority.app_configuration_revision <>
                NEW.private_source_authority_app_configuration_revision
            OR authority.app_configuration_revision <> manifest.app_configuration_revision
            OR authority.policy_revision <> NEW.private_source_authority_policy_revision
            OR authority.policy_revision <> manifest.policy_revision
            OR authority.identity_digest <> NEW.private_source_authority_identity_digest
            OR authority.state <> 'active'
            OR authority.created_at_ms > NEW.discovered_at_ms
        )
    ) THEN
        RAISE EXCEPTION 'GitHub schedule registry source authority is not exact and live'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_registry_source_authority_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_provider_delivery_workflow_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    inbox provider_delivery_inbox%ROWTYPE;
    manifest_digest BYTEA;
BEGIN
    SELECT * INTO inbox
    FROM provider_delivery_inbox
    WHERE id = NEW.inbox_id AND tenant_id = NEW.tenant_id
    FOR SHARE;
    SELECT evidence.provider_manifest_digest INTO manifest_digest
    FROM github_provider_delivery_evidence AS evidence
    WHERE evidence.provider_delivery_id = NEW.inbox_id
      AND evidence.tenant_id = NEW.tenant_id
    FOR SHARE;
    IF inbox.id IS NULL
        OR manifest_digest IS NULL
        OR inbox.state <> 'claimed'
        OR NEW.registered_at_ms < inbox.claimed_at_ms
        OR NEW.registered_at_ms >= inbox.claim_expires_at_ms
        OR NEW.manifest_digest <> manifest_digest
    THEN
        RAISE EXCEPTION 'provider delivery workflow inventory lacks live authority'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'provider_delivery_workflow_inventory_live_authority';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_provider_delivery_workflow_inventory_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    inbox_state TEXT;
BEGIN
    SELECT inbox.state INTO inbox_state
    FROM provider_delivery_inbox AS inbox
    JOIN provider_delivery_workflow_inventories AS inventory
      ON inventory.inbox_id = inbox.id
     AND inventory.tenant_id = inbox.tenant_id
    WHERE inventory.inbox_id = NEW.inbox_id
      AND inventory.tenant_id = NEW.tenant_id
    FOR SHARE OF inbox, inventory;
    IF inbox_state IS DISTINCT FROM 'claimed' THEN
        RAISE EXCEPTION 'provider delivery workflow inventory entry lacks live authority'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'provider_delivery_workflow_inventory_entry_live_authority';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_provider_delivery_workflow_progress() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    inbox_row provider_delivery_inbox%ROWTYPE;
BEGIN
    SELECT inbox_source.* INTO inbox_row
    FROM provider_delivery_inbox AS inbox_source
    JOIN provider_delivery_workflow_inventories AS inventory
      ON inventory.inbox_id = inbox_source.id
     AND inventory.tenant_id = inbox_source.tenant_id
     AND inventory.inventory_digest = NEW.inventory_digest
    WHERE inventory.inbox_id = NEW.inbox_id
      AND inventory.tenant_id = NEW.tenant_id
    FOR SHARE OF inbox_source, inventory;
    IF inbox_row.id IS NULL
        OR inbox_row.state <> 'claimed'
        OR NEW.recorded_at_ms < inbox_row.claimed_at_ms
        OR NEW.recorded_at_ms >= inbox_row.claim_expires_at_ms
    THEN
        RAISE EXCEPTION 'provider delivery workflow progress lacks live authority'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'provider_delivery_workflow_progress_live_authority';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_runner_command_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    session_acknowledged BIGINT;
    session_disconnected_at BIGINT;
    session_generation BIGINT;
    session_epoch_value BIGINT;
    current_generation BIGINT;
    current_epoch BIGINT;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.payload_tombstone_reason IS NOT NULL
            OR NEW.payload_tombstoned_at_ms IS NOT NULL
            OR NEW.envelope_schema IS NULL
            OR NEW.wrapping_key_id IS NULL
            OR NEW.wrapped_data_key IS NULL
            OR NEW.nonce IS NULL
            OR NEW.ciphertext IS NULL
        THEN
            RAISE EXCEPTION 'runner command payloads must be inserted live'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_command_outbox_payload_insert_live';
        END IF;
        RETURN NEW;
    END IF;

    IF ROW(
        NEW.runner_session_id, NEW.command_sequence, NEW.operation_id,
        NEW.runner_id, NEW.runner_session_epoch, NEW.runner_generation,
        NEW.command_kind, NEW.command_schema, NEW.command_digest,
        NEW.created_at_ms, NEW.tenant_id, NEW.command_plaintext_size_bytes
    ) IS DISTINCT FROM ROW(
        OLD.runner_session_id, OLD.command_sequence, OLD.operation_id,
        OLD.runner_id, OLD.runner_session_epoch, OLD.runner_generation,
        OLD.command_kind, OLD.command_schema, OLD.command_digest,
        OLD.created_at_ms, OLD.tenant_id, OLD.command_plaintext_size_bytes
    ) THEN
        RAISE EXCEPTION 'runner command authenticated metadata is immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'runner_command_outbox_metadata_immutable';
    END IF;

    IF OLD.payload_tombstone_reason IS NOT NULL THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'runner command payload tombstones are immutable'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_command_outbox_tombstone_immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.payload_tombstone_reason IS NULL THEN
        IF ROW(
            NEW.envelope_schema, NEW.wrapping_key_id, NEW.wrapped_data_key,
            NEW.nonce, NEW.ciphertext, NEW.payload_tombstoned_at_ms
        ) IS DISTINCT FROM ROW(
            OLD.envelope_schema, OLD.wrapping_key_id, OLD.wrapped_data_key,
            OLD.nonce, OLD.ciphertext, OLD.payload_tombstoned_at_ms
        ) THEN
            RAISE EXCEPTION 'live runner command envelopes are immutable'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_command_outbox_envelope_immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.payload_tombstoned_at_ms IS NULL
        OR NEW.envelope_schema IS NOT NULL
        OR NEW.wrapping_key_id IS NOT NULL
        OR NEW.wrapped_data_key IS NOT NULL
        OR NEW.nonce IS NOT NULL
        OR NEW.ciphertext IS NOT NULL
    THEN
        RAISE EXCEPTION 'runner command tombstone must erase the complete envelope'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'runner_command_outbox_payload_lifecycle';
    END IF;

    SELECT session.acknowledged_command_sequence,
           session.disconnected_at_ms,
           session.runner_generation,
           session.session_epoch,
           runner.generation,
           runner.session_epoch
    INTO session_acknowledged, session_disconnected_at,
         session_generation, session_epoch_value,
         current_generation, current_epoch
    FROM runner_sessions AS session
    JOIN runners AS runner ON runner.id = session.runner_id
    WHERE session.id = OLD.runner_session_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'runner command session authority is missing'
            USING ERRCODE = 'foreign_key_violation',
                  CONSTRAINT = 'runner_command_outbox_session_fence';
    END IF;

    CASE NEW.payload_tombstone_reason
        WHEN 'acknowledged' THEN
            IF session_disconnected_at IS NOT NULL
                OR (
                    OLD.command_sequence > session_acknowledged
                    AND NOT EXISTS (
                        SELECT 1
                        FROM attempt_cancellation_intents AS cancellation
                        WHERE cancellation.delivery_session_id = OLD.runner_session_id
                          AND cancellation.delivery_command_sequence = OLD.command_sequence
                          AND cancellation.acknowledged_at_ms IS NOT NULL
                          AND cancellation.acknowledged_at_ms <= NEW.payload_tombstoned_at_ms
                    )
                )
            THEN
                RAISE EXCEPTION 'runner command is not acknowledged by a live session'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'runner_command_outbox_ack_tombstone_authority';
            END IF;
        WHEN 'session_closed' THEN
            IF session_disconnected_at IS NULL
                OR NEW.payload_tombstoned_at_ms < session_disconnected_at
                OR session_generation <> current_generation
                OR session_epoch_value <> current_epoch
            THEN
                RAISE EXCEPTION 'runner command session-close tombstone lacks current authority'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'runner_command_outbox_close_tombstone_authority';
            END IF;
        WHEN 'session_superseded' THEN
            IF session_disconnected_at IS NULL
                OR NEW.payload_tombstoned_at_ms < session_disconnected_at
                OR current_generation < session_generation
                OR (
                    current_generation = session_generation
                    AND current_epoch <= session_epoch_value
                )
            THEN
                RAISE EXCEPTION 'runner command supersession tombstone lacks newer authority'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'runner_command_outbox_superseded_tombstone_authority';
            END IF;
        ELSE
            RAISE EXCEPTION 'unknown runner command payload tombstone reason'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_command_outbox_payload_lifecycle';
    END CASE;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_runner_rpc_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    session_disconnected_at BIGINT;
    session_generation BIGINT;
    session_epoch_value BIGINT;
    current_generation BIGINT;
    current_epoch BIGINT;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.payload_tombstone_reason IS NOT NULL
            OR NEW.payload_tombstoned_at_ms IS NOT NULL
            OR NEW.envelope_schema IS NULL
            OR NEW.wrapping_key_id IS NULL
            OR NEW.wrapped_data_key IS NULL
            OR NEW.nonce IS NULL
            OR NEW.ciphertext IS NULL
        THEN
            RAISE EXCEPTION 'runner RPC payloads must be inserted live'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_rpc_receipts_payload_insert_live';
        END IF;
        RETURN NEW;
    END IF;

    IF ROW(
        NEW.runner_session_id, NEW.operation_id, NEW.runner_id,
        NEW.runner_session_epoch, NEW.runner_generation, NEW.operation_kind,
        NEW.request_digest, NEW.response_schema, NEW.response_digest,
        NEW.committed_at_ms, NEW.tenant_id,
        NEW.response_plaintext_size_bytes
    ) IS DISTINCT FROM ROW(
        OLD.runner_session_id, OLD.operation_id, OLD.runner_id,
        OLD.runner_session_epoch, OLD.runner_generation, OLD.operation_kind,
        OLD.request_digest, OLD.response_schema, OLD.response_digest,
        OLD.committed_at_ms, OLD.tenant_id,
        OLD.response_plaintext_size_bytes
    ) THEN
        RAISE EXCEPTION 'runner RPC authenticated metadata is immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'runner_rpc_receipts_metadata_immutable';
    END IF;

    IF OLD.payload_tombstone_reason IS NOT NULL THEN
        IF NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'runner RPC payload tombstones are immutable'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_rpc_receipts_tombstone_immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.payload_tombstone_reason IS NULL THEN
        IF ROW(
            NEW.envelope_schema, NEW.wrapping_key_id, NEW.wrapped_data_key,
            NEW.nonce, NEW.ciphertext, NEW.payload_tombstoned_at_ms
        ) IS DISTINCT FROM ROW(
            OLD.envelope_schema, OLD.wrapping_key_id, OLD.wrapped_data_key,
            OLD.nonce, OLD.ciphertext, OLD.payload_tombstoned_at_ms
        ) THEN
            RAISE EXCEPTION 'live runner RPC envelopes are immutable'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_rpc_receipts_envelope_immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.payload_tombstoned_at_ms IS NULL
        OR NEW.envelope_schema IS NOT NULL
        OR NEW.wrapping_key_id IS NOT NULL
        OR NEW.wrapped_data_key IS NOT NULL
        OR NEW.nonce IS NOT NULL
        OR NEW.ciphertext IS NOT NULL
    THEN
        RAISE EXCEPTION 'runner RPC tombstone must erase the complete envelope'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'runner_rpc_receipts_payload_lifecycle';
    END IF;

    SELECT session.disconnected_at_ms,
           session.runner_generation,
           session.session_epoch,
           runner.generation,
           runner.session_epoch
    INTO session_disconnected_at, session_generation, session_epoch_value,
         current_generation, current_epoch
    FROM runner_sessions AS session
    JOIN runners AS runner ON runner.id = session.runner_id
    WHERE session.id = OLD.runner_session_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'runner RPC session authority is missing'
            USING ERRCODE = 'foreign_key_violation',
                  CONSTRAINT = 'runner_rpc_receipts_session_fence';
    END IF;

    CASE NEW.payload_tombstone_reason
        WHEN 'session_closed' THEN
            IF session_disconnected_at IS NULL
                OR NEW.payload_tombstoned_at_ms < session_disconnected_at
                OR session_generation <> current_generation
                OR session_epoch_value <> current_epoch
            THEN
                RAISE EXCEPTION 'runner RPC session-close tombstone lacks current authority'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'runner_rpc_receipts_close_tombstone_authority';
            END IF;
        WHEN 'session_superseded' THEN
            IF session_disconnected_at IS NULL
                OR NEW.payload_tombstoned_at_ms < session_disconnected_at
                OR current_generation < session_generation
                OR (
                    current_generation = session_generation
                    AND current_epoch <= session_epoch_value
                )
            THEN
                RAISE EXCEPTION 'runner RPC supersession tombstone lacks newer authority'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'runner_rpc_receipts_superseded_tombstone_authority';
            END IF;
        ELSE
            RAISE EXCEPTION 'unknown runner RPC payload tombstone reason'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'runner_rpc_receipts_payload_lifecycle';
    END CASE;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_logical_workflow_invocation_run_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.invocation_kind = 'reusable'
       AND OLD.state = 'active'
       AND NEW.state IN ('completed', 'cancelled', 'failed')
       AND NEW.revision = OLD.revision + 1
       AND NEW.updated_at_ms >= OLD.updated_at_ms
       AND EXISTS (
           SELECT 1
           FROM logical_workflow_reusable_call_results AS call_result
           JOIN logical_workflow_reusable_call_publications AS publication
             ON publication.run_id = call_result.run_id
            AND publication.parent_invocation_id =
                call_result.parent_invocation_id
            AND publication.caller_logical_job_id =
                call_result.caller_logical_job_id
           WHERE call_result.run_id = NEW.run_id
             AND call_result.child_invocation_id = NEW.id
             AND call_result.sealed_at_ms IS NOT NULL
             AND publication.condition_matched
             AND call_result.completed_at_ms = NEW.updated_at_ms
             AND NEW.state = CASE call_result.effective_conclusion
                 WHEN 'success' THEN 'completed'
                 WHEN 'skipped' THEN 'completed'
                 WHEN 'cancelled' THEN 'cancelled'
                 ELSE 'failed'
             END
       )
    THEN
        RETURN NEW;
    END IF;

    IF NEW.state IS DISTINCT FROM OLD.state
       AND NEW.state = 'cancelled'
       AND OLD.state IN ('pending', 'active')
       AND NEW.revision = OLD.revision + 1
       AND NEW.updated_at_ms >= OLD.updated_at_ms
       AND EXISTS (
           SELECT 1
           FROM logical_workflow_concurrency_cancellations AS cancellation
           WHERE cancellation.run_id = NEW.run_id
             AND cancellation.root_invocation_id = NEW.id
             AND cancellation.prior_invocation_state = OLD.state
             AND cancellation.prior_invocation_revision = OLD.revision
             AND cancellation.prior_invocation_updated_at_ms = OLD.updated_at_ms
             AND cancellation.cancelled_at_ms = NEW.updated_at_ms
       )
    THEN
        RETURN NEW;
    END IF;
    IF NEW.state IS DISTINCT FROM OLD.state
       AND NEW.state IN ('completed', 'cancelled', 'failed') THEN
        IF OLD.state NOT IN ('pending', 'active')
           OR NEW.revision <> OLD.revision + 1
           OR NEW.updated_at_ms < OLD.updated_at_ms
           OR NOT EXISTS (
               SELECT 1
               FROM logical_workflow_run_results AS run_result
               JOIN logical_workflow_run_result_claims AS claim
                 ON claim.run_id = run_result.run_id
               WHERE run_result.run_id = NEW.run_id
                 AND run_result.root_invocation_id = NEW.id
                 AND claim.state = 'aggregating'
                 AND run_result.invocation_state = OLD.state
                 AND run_result.invocation_revision = OLD.revision
                 AND run_result.invocation_updated_at_ms = OLD.updated_at_ms
                 AND run_result.finalized_at_ms = NEW.updated_at_ms
                 AND NEW.state = CASE run_result.effective_conclusion
                     WHEN 'success' THEN 'completed'
                     WHEN 'skipped' THEN 'completed'
                     WHEN 'cancelled' THEN 'cancelled'
                     ELSE 'failed'
                 END
           )
        THEN
            RAISE EXCEPTION 'logical workflow invocation terminal transition lacks result evidence'
                USING ERRCODE = '23514';
        END IF;
    ELSIF OLD.state IN ('completed', 'cancelled', 'failed')
          AND (NEW.state IS DISTINCT FROM OLD.state
               OR NEW.revision IS DISTINCT FROM OLD.revision
               OR NEW.updated_at_ms IS DISTINCT FROM OLD.updated_at_ms) THEN
        RAISE EXCEPTION 'logical workflow terminal invocation is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_logical_workflow_marker_run_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state IS DISTINCT FROM OLD.state
       AND NEW.state = 'cancelled'
       AND OLD.state IN ('pending', 'active')
       AND NEW.revision = OLD.revision + 1
       AND NEW.updated_at_ms >= OLD.updated_at_ms
       AND EXISTS (
           SELECT 1
           FROM logical_workflow_concurrency_cancellations AS cancellation
           WHERE cancellation.run_id = NEW.run_id
             AND cancellation.root_invocation_id = NEW.root_invocation_id
             AND cancellation.prior_marker_state = OLD.state
             AND cancellation.prior_marker_revision = OLD.revision
             AND cancellation.prior_marker_updated_at_ms = OLD.updated_at_ms
             AND cancellation.cancelled_at_ms = NEW.updated_at_ms
       )
    THEN
        RETURN NEW;
    END IF;
    IF NEW.state IS DISTINCT FROM OLD.state
       AND NEW.state IN ('completed', 'cancelled', 'failed') THEN
        IF OLD.state NOT IN ('pending', 'active')
           OR NEW.revision <> OLD.revision + 1
           OR NEW.updated_at_ms < OLD.updated_at_ms
           OR NOT EXISTS (
               SELECT 1
               FROM logical_workflow_run_results AS result
               JOIN logical_workflow_run_result_claims AS claim
                 ON claim.run_id = result.run_id
               WHERE result.run_id = NEW.run_id
                 AND claim.state = 'aggregating'
                 AND result.marker_state = OLD.state
                 AND result.marker_revision = OLD.revision
                 AND result.marker_updated_at_ms = OLD.updated_at_ms
                 AND result.finalized_at_ms = NEW.updated_at_ms
                 AND NEW.state = CASE result.effective_conclusion
                     WHEN 'success' THEN 'completed'
                     WHEN 'skipped' THEN 'completed'
                     WHEN 'cancelled' THEN 'cancelled'
                     ELSE 'failed'
                 END
           )
        THEN
            RAISE EXCEPTION 'logical workflow marker terminal transition lacks run result'
                USING ERRCODE = '23514';
        END IF;
    ELSIF OLD.state IN ('completed', 'cancelled', 'failed')
          AND (NEW.state IS DISTINCT FROM OLD.state
               OR NEW.revision IS DISTINCT FROM OLD.revision
               OR NEW.updated_at_ms IS DISTINCT FROM OLD.updated_at_ms) THEN
        RAISE EXCEPTION 'logical workflow terminal marker is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_guard_workflow_run_plan_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('queued', 'in_progress')
       AND NEW.status = 'cancelled'
       AND EXISTS (
           SELECT 1 FROM logical_workflow_runs AS marker
           WHERE marker.run_id = OLD.id
       )
    THEN
        IF NOT EXISTS (
            SELECT 1
            FROM logical_workflow_concurrency_cancellations AS cancellation
            WHERE cancellation.run_id = OLD.id
              AND cancellation.prior_workflow_status = OLD.status
              AND cancellation.prior_workflow_updated_at_ms = OLD.updated_at_ms
              AND cancellation.cancelled_at_ms = NEW.updated_at_ms
        ) THEN
            RAISE EXCEPTION 'logical workflow cancellation lacks concurrency evidence'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.status IS DISTINCT FROM OLD.status
        OR (OLD.status = 'cancelled'
            AND NEW.updated_at_ms IS DISTINCT FROM OLD.updated_at_ms))
       AND EXISTS (
           SELECT 1 FROM logical_workflow_runs AS marker
           WHERE marker.run_id = OLD.id
       )
       AND (
           NEW.status = 'completed'
           OR (OLD.status = 'cancelled'
              AND NEW.status = 'cancelled'
              AND NEW.updated_at_ms IS DISTINCT FROM OLD.updated_at_ms)
           OR EXISTS (
               SELECT 1
               FROM logical_workflow_run_result_claims AS claim
               WHERE claim.run_id = OLD.id AND claim.state = 'aggregating'
           )
       )
    THEN
        IF OLD.status NOT IN ('queued', 'in_progress', 'cancelled')
           OR NEW.updated_at_ms < OLD.updated_at_ms
           OR NOT EXISTS (
               SELECT 1
               FROM logical_workflow_run_results AS result
               JOIN logical_workflow_run_result_claims AS claim
                 ON claim.run_id = result.run_id
               WHERE result.run_id = OLD.id
                 AND claim.state = 'aggregating'
                 AND result.workflow_status = OLD.status
                 AND result.workflow_updated_at_ms = OLD.updated_at_ms
                 AND result.finalized_at_ms = NEW.updated_at_ms
                 AND NEW.status = CASE result.effective_conclusion
                     WHEN 'cancelled' THEN 'cancelled'
                     ELSE 'completed'
                 END
           )
        THEN
            RAISE EXCEPTION 'logical workflow workflow status transition lacks run result'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_is_canonical_logical_activation_workspace(workspace text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
DECLARE
    component TEXT;
    components TEXT[];
BEGIN
    IF octet_length(workspace) NOT BETWEEN 2 AND 1024
        OR workspace ~ '[[:cntrl:]]'
        OR btrim(workspace) <> workspace
    THEN
        RETURN FALSE;
    END IF;

    IF left(workspace, 1) = '/' THEN
        IF workspace = '/' OR position('//' IN workspace) > 0 THEN
            RETURN FALSE;
        END IF;
        components := string_to_array(substring(workspace FROM 2), '/');
    ELSIF workspace ~ E'^[A-Za-z]:\\\\' THEN
        IF position('/' IN workspace) > 0
            OR position(E'\\\\\\\\' IN workspace) > 0
        THEN
            RETURN FALSE;
        END IF;
        components := string_to_array(substring(workspace FROM 4), E'\\');
    ELSE
        RETURN FALSE;
    END IF;

    FOREACH component IN ARRAY components LOOP
        IF component = '' OR component = '.' OR component = '..' THEN
            RETURN FALSE;
        END IF;
    END LOOP;
    RETURN TRUE;
END;
$$;

CREATE FUNCTION automata_job_attempt_output_safety_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.secret_exposure_class IS DISTINCT FROM OLD.secret_exposure_class
       OR NEW.raw_log_disposition IS DISTINCT FROM OLD.raw_log_disposition
       OR NEW.requested_log_visibility IS DISTINCT FROM OLD.requested_log_visibility
       OR NEW.effective_log_visibility IS DISTINCT FROM OLD.effective_log_visibility
       OR NEW.output_safety_reason IS DISTINCT FROM OLD.output_safety_reason
       OR NEW.output_safety_schema IS DISTINCT FROM OLD.output_safety_schema
       OR NEW.classified_at_ms IS DISTINCT FROM OLD.classified_at_ms THEN
        RAISE EXCEPTION 'job attempt output safety snapshots are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_attempts_output_safety_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_job_attempt_started_at_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.lease_issued_at_ms IS NOT NULL THEN
            IF NEW.started_at_ms IS NULL THEN
                NEW.started_at_ms := NEW.lease_issued_at_ms;
            ELSIF NEW.started_at_ms <> NEW.lease_issued_at_ms THEN
                RAISE EXCEPTION 'job attempt start must equal its first lease issuance'
                    USING ERRCODE = '23514',
                          CONSTRAINT = 'job_attempts_started_at_immutable';
            END IF;
        ELSIF NEW.started_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'job attempt start requires an issued lease'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'job_attempts_started_at_immutable';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.started_at_ms IS NOT NULL THEN
        IF NEW.started_at_ms IS DISTINCT FROM OLD.started_at_ms THEN
            RAISE EXCEPTION 'job attempt start is immutable'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'job_attempts_started_at_immutable';
        END IF;
    ELSIF NEW.lease_issued_at_ms IS NOT NULL THEN
        IF NEW.started_at_ms IS NULL THEN
            NEW.started_at_ms := NEW.lease_issued_at_ms;
        ELSIF NEW.started_at_ms <> NEW.lease_issued_at_ms THEN
            RAISE EXCEPTION 'job attempt start must equal its first lease issuance'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'job_attempts_started_at_immutable';
        END IF;
    ELSIF NEW.started_at_ms IS NOT NULL THEN
        RAISE EXCEPTION 'job attempt start requires an issued lease'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'job_attempts_started_at_immutable';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_job_attempt_terminal_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.lifecycle IN (
        'succeeded', 'failed', 'cancelled', 'timed_out', 'skipped', 'lost'
    ) AND NEW.lifecycle IS DISTINCT FROM OLD.lifecycle THEN
        RAISE EXCEPTION 'terminal job attempts are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_attempts_terminal_monotonic';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_job_binding_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'job credential bindings are append-only'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'job_credential_bindings_append_only';
END;
$$;

CREATE FUNCTION automata_job_credential_resolution_digest(target_attempt_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    AS $_$
SELECT pg_catalog.sha256(
    convert_to('automata.store.job-credential-resolution.v2', 'UTF8')
    || decode('00', 'hex')
    || uuid_send($1)
    || convert_to(jsonb_build_object(
        'secrets', COALESCE((
            SELECT jsonb_agg(jsonb_build_array(canonical_name, encode(binding_digest, 'hex'))
                             ORDER BY canonical_name)
            FROM job_secret_selections WHERE attempt_id = $1
        ), '[]'::JSONB),
        'missing_secrets', COALESCE((
            SELECT jsonb_agg(canonical_name ORDER BY canonical_name)
            FROM job_missing_secret_bindings WHERE attempt_id = $1
        ), '[]'::JSONB),
        'variables', COALESCE((
            SELECT jsonb_agg(jsonb_build_array(canonical_name, encode(binding_digest, 'hex'))
                             ORDER BY canonical_name)
            FROM job_variable_bindings WHERE attempt_id = $1
        ), '[]'::JSONB),
        'missing_variables', COALESCE((
            SELECT jsonb_agg(canonical_name ORDER BY canonical_name)
            FROM job_missing_variable_bindings WHERE attempt_id = $1
        ), '[]'::JSONB)
    )::TEXT, 'UTF8')
);
$_$;

CREATE FUNCTION automata_job_environment_gate_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    environment repository_environments%ROWTYPE;
    approval protected_environment_approval_requests%ROWTYPE;
    database_now_ms BIGINT;
BEGIN
    database_now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.run_id IS DISTINCT FROM OLD.run_id
       OR NEW.invocation_id IS DISTINCT FROM OLD.invocation_id
       OR NEW.logical_job_id IS DISTINCT FROM OLD.logical_job_id
       OR NEW.instance_id IS DISTINCT FROM OLD.instance_id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
       OR NEW.environment_requirement_kind IS DISTINCT FROM OLD.environment_requirement_kind
       OR NEW.environment_template_digest IS DISTINCT FROM OLD.environment_template_digest
       OR NEW.invocation_kind IS DISTINCT FROM OLD.invocation_kind
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms THEN
        RAISE EXCEPTION 'job environment gate identity is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_environment_gates_identity_immutable';
    END IF;
    IF NOT (
        (OLD.state = 'unclassified' AND NEW.state = 'unclassified')
        OR (OLD.state = 'selection_pending'
            AND NEW.state IN ('selection_pending', 'waiting', 'resolving', 'cancelled'))
        OR (OLD.state = 'waiting'
            AND NEW.state IN ('waiting', 'resolving', 'rejected', 'expired', 'cancelled'))
        OR (OLD.state = 'resolving'
            AND NEW.state IN ('resolving', 'ready', 'expired', 'cancelled'))
        OR (OLD.state IN ('ready', 'rejected', 'expired', 'cancelled')
            AND NEW.state = OLD.state)
    ) THEN
        RAISE EXCEPTION 'job environment gate transition is invalid'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_environment_gates_state_transition';
    END IF;
    IF OLD.state <> 'selection_pending' AND (
        NEW.environment_id IS DISTINCT FROM OLD.environment_id
        OR NEW.environment_revision IS DISTINCT FROM OLD.environment_revision
        OR NEW.approval_request_id IS DISTINCT FROM OLD.approval_request_id
        OR NEW.event_trust IS DISTINCT FROM OLD.event_trust
        OR NEW.source_kind IS DISTINCT FROM OLD.source_kind
        OR NEW.reusable_secret_permission IS DISTINCT FROM OLD.reusable_secret_permission
    ) THEN
        RAISE EXCEPTION 'job environment selection evidence is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_environment_gates_selection_immutable';
    END IF;
    IF NEW.state IN ('waiting', 'resolving', 'ready')
       AND NEW.environment_id IS NOT NULL THEN
        SELECT * INTO STRICT environment
        FROM repository_environments
        WHERE tenant_id = NEW.tenant_id
          AND repository_id = NEW.repository_id
          AND id = NEW.environment_id
        FOR SHARE;
        IF environment.status <> 'active'
           OR environment.revision <> NEW.environment_revision THEN
            RAISE EXCEPTION 'job environment selection is stale'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'job_environment_gates_environment_current';
        END IF;
        IF NEW.state = 'waiting' THEN
            IF environment.protection_mode <> 'required_approvals'
               OR NEW.approval_request_id IS NULL THEN
                RAISE EXCEPTION 'waiting gate requires a protected environment request'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'job_environment_gates_waiting_approval';
            END IF;
            SELECT * INTO STRICT approval
            FROM protected_environment_approval_requests
            WHERE tenant_id = NEW.tenant_id AND id = NEW.approval_request_id
            FOR SHARE;
            IF approval.status <> 'pending'
               OR approval.environment_revision <> environment.revision
               OR approval.required_approvals <> environment.required_approvals
               OR approval.prevent_self_review <> environment.prevent_self_review
               OR database_now_ms >= approval.expires_at_ms THEN
                RAISE EXCEPTION 'waiting gate approval request is stale'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'job_environment_gates_waiting_approval';
            END IF;
        ELSIF environment.protection_mode = 'required_approvals' THEN
            SELECT * INTO STRICT approval
            FROM protected_environment_approval_requests
            WHERE tenant_id = NEW.tenant_id AND id = NEW.approval_request_id
            FOR SHARE;
            IF approval.status <> 'approved'
               OR approval.environment_revision <> environment.revision
               OR approval.required_approvals <> environment.required_approvals
               OR approval.prevent_self_review <> environment.prevent_self_review
               OR approval.resolved_at_ms IS NULL
               OR approval.resolved_at_ms >= approval.expires_at_ms
               OR database_now_ms >= approval.expires_at_ms
               OR NOT automata_protected_environment_approval_is_current(
                   NEW.tenant_id, NEW.approval_request_id, database_now_ms
               ) THEN
                RAISE EXCEPTION 'protected environment gate lacks current approval'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'job_environment_gates_approved_current';
            END IF;
        ELSIF NEW.approval_request_id IS NOT NULL THEN
            RAISE EXCEPTION 'unprotected environment cannot retain approval evidence'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'job_environment_gates_approved_current';
        END IF;
    END IF;
    IF OLD.state IN ('ready', 'rejected', 'expired', 'cancelled')
       AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal job environment gate is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_environment_gates_terminal_monotonic';
    END IF;
    IF NEW IS DISTINCT FROM OLD AND NEW.revision <> OLD.revision + 1 THEN
        RAISE EXCEPTION 'job environment gate transition requires one revision increment'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'job_environment_gates_revision_guard';
    END IF;
    IF NEW.state = 'ready' THEN
        IF NEW.resolution_digest IS DISTINCT FROM
               automata_job_credential_resolution_digest(NEW.attempt_id)
           OR NEW.resolved_secret_count <> (
               SELECT count(*) FROM job_secret_selections WHERE attempt_id = NEW.attempt_id
           )
           OR NEW.missing_secret_count <> (
               SELECT count(*) FROM job_missing_secret_bindings WHERE attempt_id = NEW.attempt_id
           )
           OR NEW.resolved_variable_count <> (
               SELECT count(*) FROM job_variable_bindings WHERE attempt_id = NEW.attempt_id
           )
           OR NEW.missing_variable_count <> (
               SELECT count(*) FROM job_missing_variable_bindings WHERE attempt_id = NEW.attempt_id
           ) THEN
            RAISE EXCEPTION 'job credential resolution digest is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'job_environment_gates_resolution_exact';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_job_environment_gate_ready_authority_is_current(target_attempt_id uuid, target_now_ms bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
SELECT EXISTS (
    SELECT 1
    FROM job_environment_gates AS gate
    JOIN logical_workflow_jobs AS logical_job
      ON logical_job.run_id = gate.run_id
     AND logical_job.invocation_id = gate.invocation_id
     AND logical_job.id = gate.logical_job_id
    WHERE gate.attempt_id = $1
      AND gate.state = 'ready'
      AND gate.environment_requirement_kind =
          logical_job.environment_requirement_kind
      AND gate.environment_template_digest IS NOT DISTINCT FROM
          logical_job.environment_template_digest
      AND gate.resolution_digest IS NOT DISTINCT FROM
          automata_job_credential_resolution_digest(gate.attempt_id)
      AND NOT (
          gate.event_trust = 'unknown'
          AND cardinality(logical_job.secret_reference_names) > 0
      )
      AND NOT (
          gate.source_kind = 'unknown'
          AND cardinality(logical_job.secret_reference_names) > 0
      )
      AND NOT (
          gate.invocation_kind = 'reusable'
          AND cardinality(logical_job.secret_reference_names) > 0
          AND gate.reusable_secret_permission <> 'explicit'
      )
      AND (
          (gate.environment_id IS NULL
           AND gate.environment_revision IS NULL
           AND gate.approval_request_id IS NULL)
          OR EXISTS (
              SELECT 1
              FROM repository_environments AS environment
              WHERE environment.tenant_id = gate.tenant_id
                AND environment.repository_id = gate.repository_id
                AND environment.id = gate.environment_id
                AND environment.status = 'active'
                AND environment.revision = gate.environment_revision
                AND (
                    (environment.protection_mode = 'unprotected'
                     AND gate.approval_request_id IS NULL)
                    OR (
                        environment.protection_mode = 'required_approvals'
                        AND gate.approval_request_id IS NOT NULL
                        AND automata_protected_environment_approval_is_current(
                            gate.tenant_id,
                            gate.approval_request_id,
                            $2
                        )
                    )
                )
          )
      )
      AND gate.resolved_secret_count = (
          SELECT count(*)
          FROM job_secret_selections AS selection
          JOIN secrets AS secret
            ON secret.tenant_id = selection.tenant_id
           AND secret.id = selection.secret_id
           AND secret.current_version_id = selection.secret_version_id
           AND secret.current_version_number = selection.secret_version_number
           AND secret.canonical_name = selection.canonical_name
           AND secret.scope_kind = selection.scope_kind
           AND secret.environment_id IS NOT DISTINCT FROM selection.environment_id
          JOIN secret_policies AS policy
            ON policy.tenant_id = secret.tenant_id
           AND policy.secret_id = secret.id
          WHERE selection.attempt_id = gate.attempt_id
            AND selection.tenant_id = gate.tenant_id
            AND selection.binding_digest IS NOT DISTINCT FROM
                automata_job_secret_selection_digest(
                    selection.attempt_id,
                    selection.canonical_name,
                    selection.tenant_id,
                    selection.secret_id,
                    selection.secret_version_id,
                    selection.secret_version_number,
                    selection.scope_kind,
                    selection.environment_id
                )
            AND automata_secret_is_available_to_gate(secret, policy, gate)
            AND NOT (
                selection.scope_kind = 'repository'
                AND EXISTS (
                    SELECT 1
                    FROM secrets AS higher
                    JOIN secret_policies AS higher_policy
                      ON higher_policy.tenant_id = higher.tenant_id
                     AND higher_policy.secret_id = higher.id
                    WHERE higher.tenant_id = gate.tenant_id
                      AND higher.repository_id = gate.repository_id
                      AND higher.environment_id = gate.environment_id
                      AND higher.scope_kind = 'environment'
                      AND higher.canonical_name = selection.canonical_name
                      AND automata_secret_is_available_to_gate(
                          higher,
                          higher_policy,
                          gate
                      )
                )
            )
            AND NOT (
                selection.scope_kind = 'tenant'
                AND EXISTS (
                    SELECT 1
                    FROM secrets AS higher
                    JOIN secret_policies AS higher_policy
                      ON higher_policy.tenant_id = higher.tenant_id
                     AND higher_policy.secret_id = higher.id
                    WHERE higher.tenant_id = gate.tenant_id
                      AND higher.repository_id = gate.repository_id
                      AND higher.canonical_name = selection.canonical_name
                      AND higher.scope_kind IN ('repository', 'environment')
                      AND (
                          higher.scope_kind = 'repository'
                          OR higher.environment_id = gate.environment_id
                      )
                      AND automata_secret_is_available_to_gate(
                          higher,
                          higher_policy,
                          gate
                      )
                )
            )
      )
      AND gate.resolved_variable_count = (
          SELECT count(*)
          FROM job_variable_bindings AS binding
          JOIN workflow_variables AS variable
            ON variable.tenant_id = binding.tenant_id
           AND variable.id = binding.variable_id
           AND variable.repository_id = gate.repository_id
           AND variable.canonical_name = binding.canonical_name
           AND variable.scope_kind = binding.scope_kind
           AND variable.environment_id IS NOT DISTINCT FROM binding.environment_id
           AND variable.current_version_id = binding.variable_version_id
           AND variable.current_version_number = binding.variable_version_number
           AND variable.status = 'active'
          WHERE binding.attempt_id = gate.attempt_id
            AND binding.tenant_id = gate.tenant_id
            AND binding.binding_digest IS NOT DISTINCT FROM
                automata_job_variable_binding_digest(
                    binding.attempt_id,
                    binding.canonical_name,
                    binding.tenant_id,
                    binding.variable_id,
                    binding.variable_version_id,
                    binding.variable_version_number,
                    binding.scope_kind,
                    binding.environment_id
                )
            AND (
                binding.scope_kind = 'repository'
                OR binding.environment_id = gate.environment_id
            )
            AND NOT EXISTS (
                SELECT 1
                FROM workflow_variables AS higher
                WHERE higher.tenant_id = gate.tenant_id
                  AND higher.repository_id = gate.repository_id
                  AND higher.environment_id = gate.environment_id
                  AND higher.scope_kind = 'environment'
                  AND higher.canonical_name = binding.canonical_name
                  AND higher.status = 'active'
                  AND binding.scope_kind = 'repository'
            )
      )
      AND gate.missing_secret_count = (
          SELECT count(*)
          FROM job_missing_secret_bindings
          WHERE attempt_id = gate.attempt_id
      )
      AND gate.missing_variable_count = (
          SELECT count(*)
          FROM job_missing_variable_bindings
          WHERE attempt_id = gate.attempt_id
      )
      AND gate.resolved_secret_count + gate.missing_secret_count =
          cardinality(logical_job.secret_reference_names)
      AND gate.resolved_variable_count + gate.missing_variable_count =
          cardinality(logical_job.variable_reference_names)
);
$_$;

CREATE FUNCTION automata_job_secret_binding_digest(target_attempt_id uuid, target_name text, target_tenant_id text, target_grant_id uuid, target_lease_id uuid, target_fencing_token bigint) RETURNS bytea
    LANGUAGE sql STABLE
    AS $_$
SELECT pg_catalog.sha256(
    convert_to('automata.store.job-secret-binding.v1', 'UTF8')
    || decode('00', 'hex') || uuid_send($1)
    || int4send(octet_length(convert_to($2, 'UTF8'))) || convert_to($2, 'UTF8')
    || int4send(octet_length(convert_to($3, 'UTF8'))) || convert_to($3, 'UTF8')
    || uuid_send($4) || uuid_send($5) || int8send($6)
    || workload_grant.authority_digest
    || int8send(workload_grant.expires_at_ms)
)
FROM secret_workload_grants AS workload_grant
WHERE workload_grant.tenant_id = $3 AND workload_grant.id = $4;
$_$;

CREATE FUNCTION automata_job_secret_selection_digest(target_attempt_id uuid, target_name text, target_tenant_id text, target_secret_id uuid, target_version_id uuid, target_version_number bigint, target_scope_kind text, target_environment_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    AS $_$
SELECT pg_catalog.sha256(
    convert_to('automata.store.job-secret-selection.v1', 'UTF8')
    || decode('00', 'hex') || uuid_send($1)
    || int4send(octet_length(convert_to($2, 'UTF8'))) || convert_to($2, 'UTF8')
    || int4send(octet_length(convert_to($3, 'UTF8'))) || convert_to($3, 'UTF8')
    || uuid_send($4) || uuid_send($5) || int8send($6)
    || int4send(octet_length(convert_to($7, 'UTF8'))) || convert_to($7, 'UTF8')
    || CASE WHEN $8 IS NULL THEN decode('00', 'hex')
            ELSE decode('01', 'hex') || uuid_send($8) END
    || int8send(policy.revision)
    || int8send(secret.revision)
    || int4send(octet_length(convert_to(gate.event_trust, 'UTF8')))
    || convert_to(gate.event_trust, 'UTF8')
    || int4send(octet_length(convert_to(gate.source_kind, 'UTF8')))
    || convert_to(gate.source_kind, 'UTF8')
    || int4send(octet_length(convert_to(gate.invocation_kind, 'UTF8')))
    || convert_to(gate.invocation_kind, 'UTF8')
)
FROM secrets AS secret
JOIN secret_policies AS policy
  ON policy.tenant_id = secret.tenant_id AND policy.secret_id = secret.id
JOIN job_environment_gates AS gate ON gate.attempt_id = $1
WHERE secret.tenant_id = $3 AND secret.id = $4
  AND secret.current_version_id = $5 AND secret.current_version_number = $6;
$_$;

CREATE FUNCTION automata_job_variable_binding_digest(target_attempt_id uuid, target_name text, target_tenant_id text, target_variable_id uuid, target_version_id uuid, target_version_number bigint, target_scope_kind text, target_environment_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    AS $_$
SELECT pg_catalog.sha256(
    convert_to('automata.store.job-variable-binding.v1', 'UTF8')
    || decode('00', 'hex') || uuid_send($1)
    || int4send(octet_length(convert_to($2, 'UTF8'))) || convert_to($2, 'UTF8')
    || int4send(octet_length(convert_to($3, 'UTF8'))) || convert_to($3, 'UTF8')
    || uuid_send($4) || uuid_send($5) || int8send($6)
    || int4send(octet_length(convert_to($7, 'UTF8'))) || convert_to($7, 'UTF8')
    || CASE WHEN $8 IS NULL THEN decode('00', 'hex')
            ELSE decode('01', 'hex') || uuid_send($8) END
    || version.value_ciphertext_sha256
    || int8send(version.value_size_bytes)
    || int2send(version.envelope_schema)
)
FROM workflow_variable_versions AS version
WHERE version.tenant_id = $3 AND version.id = $5
  AND version.variable_id = $4 AND version.version_number = $6;
$_$;

CREATE FUNCTION automata_lock_github_oidc_authority_dependencies(authority github_oidc_authorities) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    origin_visibility TEXT;
    private_authority_id UUID;
BEGIN
    SELECT origin.repository_visibility,
           origin.private_source_authority_id
      INTO origin_visibility, private_authority_id
    FROM job_attempts AS attempt
    JOIN jobs AS job
      ON job.id = attempt.job_id
     AND job.id = authority.job_id
     AND job.run_id = authority.run_id
    JOIN workflow_runs AS run
      ON run.id = job.run_id
     AND run.id = authority.run_id
     AND run.repository_id = authority.repository_id
    JOIN repositories AS repository
      ON repository.id = run.repository_id
     AND repository.tenant_id = authority.tenant_id
    JOIN workflow_definitions AS workflow
      ON workflow.id = run.workflow_id
     AND workflow.repository_id = run.repository_id
    JOIN workflow_snapshots AS snapshot
      ON snapshot.id = run.snapshot_id
     AND snapshot.workflow_id = run.workflow_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = run.id
    JOIN logical_workflow_invocations AS invocation
      ON invocation.run_id = run.id
     AND invocation.id = authority.invocation_id
    JOIN logical_workflow_jobs AS logical_job
      ON logical_job.run_id = run.id
     AND logical_job.invocation_id = invocation.id
     AND logical_job.id = authority.logical_job_id
    JOIN logical_workflow_activation_preparation_claims AS preparation_claim
      ON preparation_claim.run_id = logical_job.run_id
     AND preparation_claim.invocation_id = logical_job.invocation_id
     AND preparation_claim.logical_job_id = logical_job.id
    JOIN logical_workflow_activation_preparations AS preparation
      ON preparation.run_id = preparation_claim.run_id
     AND preparation.invocation_id = preparation_claim.invocation_id
     AND preparation.logical_job_id = preparation_claim.logical_job_id
     AND preparation.descriptor_digest = preparation_claim.descriptor_digest
    JOIN logical_workflow_activation_publications AS activation_publication
      ON activation_publication.run_id = logical_job.run_id
     AND activation_publication.invocation_id = logical_job.invocation_id
     AND activation_publication.logical_job_id = logical_job.id
     AND activation_publication.activation_input_digest =
         preparation.activation_input_digest
    JOIN logical_workflow_instances AS instance
      ON instance.run_id = run.id
     AND instance.invocation_id = invocation.id
     AND instance.logical_job_id = logical_job.id
     AND instance.id = authority.instance_id
    JOIN logical_workflow_concrete_jobs AS concrete
      ON concrete.instance_id = instance.id
     AND concrete.run_id = run.id
     AND concrete.invocation_id = invocation.id
     AND concrete.logical_job_id = logical_job.id
     AND concrete.job_id = job.id
    JOIN logical_workflow_materialization_claims AS materialization
      ON materialization.instance_id = concrete.instance_id
     AND materialization.run_id = concrete.run_id
     AND materialization.invocation_id = concrete.invocation_id
     AND materialization.logical_job_id = concrete.logical_job_id
     AND materialization.descriptor_digest = concrete.descriptor_digest
     AND materialization.expected_job_id = concrete.job_id
     AND materialization.expected_attempt_id = concrete.initial_attempt_id
     AND materialization.owner_id = concrete.claim_owner_id
     AND materialization.generation = concrete.claim_generation
     AND materialization.claimed_at_ms = concrete.claim_started_at_ms
     AND materialization.expires_at_ms = concrete.claim_expires_at_ms
     AND materialization.updated_at_ms = concrete.committed_at_ms
    JOIN runners AS runner
      ON runner.id = attempt.runner_id
     AND runner.id = authority.runner_id
     AND runner.tenant_id = authority.tenant_id
    JOIN runner_sessions AS session
      ON session.id = attempt.runner_session_id
     AND session.id = authority.runner_session_id
     AND session.runner_id = authority.runner_id
    JOIN github_workflow_run_manifest_origins AS origin
      ON origin.tenant_id = authority.tenant_id
     AND origin.repository_id = authority.repository_id
     AND origin.workflow_id = authority.workflow_id
     AND origin.run_id = authority.run_id
     AND origin.root_invocation_id = marker.root_invocation_id
     AND origin.subject_evidence_sha256 =
         authority.github_run_subject_evidence_sha256
    JOIN workflow_admission_receipts AS admission_receipt
      ON admission_receipt.tenant_id = origin.tenant_id
     AND admission_receipt.idempotency_kind =
         origin.admission_idempotency_kind
     AND admission_receipt.idempotency_key =
         origin.admission_idempotency_key
     AND admission_receipt.request_digest = origin.logical_admission_digest
     AND admission_receipt.repository_id = origin.repository_id
     AND admission_receipt.run_id = origin.run_id
     AND admission_receipt.committed_at_ms = origin.admitted_at_ms
     AND admission_receipt.github_subject_evidence_required
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = origin.tenant_id
     AND manifest.repository_id = origin.repository_id
     AND manifest.provider_connection_id = origin.provider_connection_id
     AND manifest.manifest_revision = origin.provider_manifest_revision
     AND manifest.manifest_digest = origin.provider_manifest_digest
    JOIN github_server_service_authorities AS checks_authority
      ON checks_authority.tenant_id = origin.tenant_id
     AND checks_authority.id = origin.checks_authority_id
     AND checks_authority.repository_id = origin.repository_id
     AND checks_authority.provider_connection_id = origin.provider_connection_id
     AND checks_authority.provider_installation_id =
         origin.provider_installation_id
     AND checks_authority.github_repository_id = origin.github_repository_id
     AND checks_authority.github_repository_name =
         origin.github_repository_name
     AND checks_authority.service_scope = 'checks_write'
     AND checks_authority.identity_digest =
         origin.checks_authority_identity_digest
     AND checks_authority.app_configuration_revision =
         origin.checks_authority_app_configuration_revision
     AND checks_authority.policy_revision =
         origin.checks_authority_policy_revision
    WHERE attempt.id = authority.attempt_id
      AND materialization.state = 'materialized'
      AND (
          origin.origin_kind = 'provider_delivery'
          AND origin.admission_idempotency_kind = 'provider_delivery'
          OR origin.origin_kind IN ('scheduled_fire', 'workflow_rerun')
          AND origin.admission_idempotency_kind = 'operation'
      )
      AND logical_job.activation_input_digest = preparation.activation_input_digest
      AND preparation_claim.state = 'prepared'
      AND activation_publication.condition_matched
      AND automata_logical_workflow_invocation_published(
          run.id, invocation.id
      )
      AND automata_reusable_workflow_oidc_permission_authorized(
          run.id, invocation.id
      )
      AND manifest.authority_profile = 'standard'
      AND logical_job.authority_profile = 'standard'
      AND preparation_claim.authority_profile = 'standard'
      AND preparation.authority_profile = 'standard'
      AND activation_publication.authority_profile = 'standard'
      AND materialization.authority_profile = 'standard'
      AND concrete.authority_profile = 'standard'
      AND checks_authority.state = 'active'
    FOR SHARE OF attempt, job, run, repository, workflow, snapshot, marker,
                 invocation, logical_job, preparation_claim, preparation,
                 activation_publication, instance, concrete, materialization,
                 runner, session,
                 admission_receipt, manifest, checks_authority;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF origin_visibility = 'public' THEN
        RETURN private_authority_id IS NULL;
    END IF;
    IF origin_visibility <> 'private' OR private_authority_id IS NULL THEN
        RETURN FALSE;
    END IF;

    PERFORM 1
    FROM github_workflow_run_manifest_origins AS origin
    JOIN github_server_service_authorities AS private_authority
      ON private_authority.tenant_id = origin.tenant_id
     AND private_authority.id = origin.private_source_authority_id
     AND private_authority.repository_id = origin.repository_id
     AND private_authority.provider_connection_id =
         origin.provider_connection_id
     AND private_authority.provider_installation_id =
         origin.provider_installation_id
     AND private_authority.github_repository_id =
         origin.github_repository_id
     AND private_authority.github_repository_name =
         origin.github_repository_name
     AND private_authority.service_scope = 'private_repository_source_read'
     AND private_authority.identity_digest =
         origin.private_source_authority_identity_digest
     AND private_authority.app_configuration_revision =
         origin.private_source_authority_app_configuration_revision
     AND private_authority.policy_revision =
         origin.private_source_authority_policy_revision
    WHERE origin.tenant_id = authority.tenant_id
      AND origin.repository_id = authority.repository_id
      AND origin.workflow_id = authority.workflow_id
      AND origin.run_id = authority.run_id
      AND origin.subject_evidence_sha256 =
          authority.github_run_subject_evidence_sha256
      AND origin.private_source_authority_id = private_authority_id
      AND private_authority.state = 'active'
    FOR SHARE OF private_authority;
    RETURN FOUND;
END;
$$;

CREATE FUNCTION automata_lock_reusable_call_output_contract() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM logical_workflow_runs AS marker
    JOIN workflow_runs AS run ON run.id = marker.run_id
    JOIN logical_workflow_reusable_invocation_expansions AS expansion
      ON expansion.run_id = marker.run_id
     AND expansion.invocation_id = NEW.child_invocation_id
    WHERE marker.run_id = NEW.run_id
      AND marker.admission_graph_sealed_at_ms IS NOT NULL
      AND marker.state IN ('pending', 'active')
      AND run.status IN ('queued', 'in_progress')
      AND expansion.depth > 0
      AND NOT EXISTS (
          SELECT 1 FROM logical_workflow_run_result_claims AS claim
          WHERE claim.run_id = marker.run_id
      )
    FOR UPDATE OF marker, run;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'reusable call output contract lacks a live planned call'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_output_contract_window';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_lock_reusable_call_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM logical_workflow_runs AS marker
    JOIN workflow_runs AS run ON run.id = marker.run_id
    JOIN repositories AS repository ON repository.id = run.repository_id
    JOIN logical_workflow_invocations AS parent
      ON parent.run_id = marker.run_id
     AND parent.id = NEW.parent_invocation_id
    JOIN logical_workflow_jobs AS caller
      ON caller.run_id = parent.run_id
     AND caller.invocation_id = parent.id
     AND caller.id = NEW.caller_logical_job_id
    JOIN logical_workflow_runtime_policy_pins AS pin
      ON pin.run_id = marker.run_id
    JOIN logical_workflow_reusable_invocation_expansions AS planned
      ON planned.run_id = caller.run_id
     AND planned.parent_invocation_id = caller.invocation_id
     AND planned.caller_logical_job_id = caller.id
     AND planned.invocation_id = NEW.child_invocation_id
    JOIN logical_workflow_reusable_permission_snapshots AS permissions
      ON permissions.run_id = planned.run_id
     AND permissions.invocation_id = planned.invocation_id
    JOIN logical_workflow_reusable_call_output_contracts AS output_contract
      ON output_contract.run_id = planned.run_id
     AND output_contract.child_invocation_id = planned.invocation_id
    WHERE marker.run_id = NEW.run_id
      AND repository.tenant_id = NEW.tenant_id
      AND repository.id = NEW.repository_id
      AND marker.admission_graph_sealed_at_ms IS NOT NULL
      AND marker.state IN ('pending', 'active')
      AND run.status IN ('queued', 'in_progress')
      AND parent.state IN ('pending', 'active')
      AND caller.execution_kind = 'reusable_workflow'
      AND caller.state = 'pending'
      AND caller.activation_fence = 0
      AND caller.activation_owner_id IS NULL
      AND caller.activation_claimed_at_ms IS NULL
      AND caller.activation_expires_at_ms IS NULL
      AND caller.activation_input_digest IS NULL
      AND caller.activation_origin_selection_id IS NULL
      AND planned.depth > 0
      AND permissions.permission_digest = NEW.permission_digest
      AND output_contract.mapping_count = NEW.output_mapping_count
      AND output_contract.mapping_digest = NEW.output_mapping_digest
      AND pin.policy_revision = NEW.runtime_policy_revision
      AND pin.policy_digest = NEW.runtime_policy_digest
      AND NOT EXISTS (
          SELECT 1
          FROM logical_workflow_dependencies AS dependency
          LEFT JOIN logical_workflow_job_results AS result
            ON result.run_id = dependency.run_id
           AND result.invocation_id = dependency.invocation_id
           AND result.logical_job_id = dependency.prerequisite_job_id
          LEFT JOIN logical_workflow_job_result_claims AS claim
            ON claim.logical_job_id = result.logical_job_id
           AND claim.state = 'finalized'
          WHERE dependency.run_id = caller.run_id
            AND dependency.invocation_id = caller.invocation_id
            AND dependency.logical_job_id = caller.id
            AND (result.logical_job_id IS NULL OR claim.logical_job_id IS NULL)
      )
      AND NOT EXISTS (
          SELECT 1 FROM logical_workflow_run_result_claims AS claim
          WHERE claim.run_id = marker.run_id
      )
    FOR UPDATE OF marker, run, parent, caller;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'reusable call publication lacks a ready live parent instance'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_publication_window';
    END IF;
    IF NEW.child_graph_sealed_at_ms IS NOT NULL THEN
        RAISE EXCEPTION 'reusable child graph must begin unsealed'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_publication_unsealed';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_lock_reusable_call_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matched BOOLEAN;
    expected_conclusion TEXT;
BEGIN
    SELECT publication.condition_matched
      INTO matched
    FROM logical_workflow_reusable_call_publications AS publication
    JOIN logical_workflow_runs AS marker ON marker.run_id = publication.run_id
    JOIN workflow_runs AS run ON run.id = marker.run_id
    JOIN repositories AS repository ON repository.id = run.repository_id
    JOIN logical_workflow_jobs AS caller
      ON caller.run_id = publication.run_id
     AND caller.invocation_id = publication.parent_invocation_id
     AND caller.id = publication.caller_logical_job_id
    WHERE publication.run_id = NEW.run_id
      AND publication.parent_invocation_id = NEW.parent_invocation_id
      AND publication.caller_logical_job_id = NEW.caller_logical_job_id
      AND publication.caller_instance_id = NEW.caller_instance_id
      AND publication.child_invocation_id = NEW.child_invocation_id
      AND publication.operation_id = NEW.publication_operation_id
      AND publication.child_graph_sealed_at_ms IS NOT NULL
      AND repository.tenant_id = NEW.tenant_id
      AND repository.id = NEW.repository_id
      AND marker.state IN ('pending', 'active')
      AND run.status IN ('queued', 'in_progress')
      AND caller.state = CASE WHEN publication.condition_matched
          THEN 'activated' ELSE 'skipped' END
      AND caller.activation_fence = publication.activation_generation
      AND caller.activation_input_digest = publication.activation_input_digest
      AND caller.updated_at_ms = publication.published_at_ms
      AND NEW.completed_at_ms >= publication.published_at_ms
      AND NOT EXISTS (
          SELECT 1 FROM logical_workflow_run_result_claims AS claim
          WHERE claim.run_id = marker.run_id
      )
    FOR UPDATE OF marker, run, caller;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'reusable call result lacks an exact live publication'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_result_window';
    END IF;

    IF NEW.sealed_at_ms IS NOT NULL THEN
        RAISE EXCEPTION 'reusable call result must begin unsealed'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_result_unsealed';
    END IF;

    IF NOT matched THEN
        IF NEW.child_job_count <> 0
            OR NEW.output_count <> 0
            OR NEW.effective_conclusion <> 'skipped'
        THEN
            RAISE EXCEPTION 'skipped reusable call result is not empty'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'logical_workflow_reusable_call_result_skipped';
        END IF;
        RETURN NEW;
    END IF;

    PERFORM 1
    FROM logical_workflow_invocations AS child
    JOIN logical_workflow_reusable_workflow_catalog AS catalog
      ON catalog.run_id = child.run_id
     AND catalog.plan_digest = child.plan_digest
    WHERE child.run_id = NEW.run_id
      AND child.id = NEW.child_invocation_id
      AND child.invocation_kind = 'reusable'
      AND child.state = 'active'
      AND child.plan_digest = NEW.callee_plan_digest
      AND NEW.completed_at_ms >= child.updated_at_ms
    FOR UPDATE OF child;
    IF NOT FOUND OR EXISTS (
        SELECT 1
        FROM logical_workflow_jobs AS child_job
        LEFT JOIN logical_workflow_job_results AS child_result
          ON child_result.run_id = child_job.run_id
         AND child_result.invocation_id = child_job.invocation_id
         AND child_result.logical_job_id = child_job.id
        LEFT JOIN logical_workflow_job_result_claims AS child_claim
          ON child_claim.logical_job_id = child_result.logical_job_id
         AND child_claim.state = 'finalized'
        WHERE child_job.run_id = NEW.run_id
          AND child_job.invocation_id = NEW.child_invocation_id
          AND (child_result.logical_job_id IS NULL
               OR child_claim.logical_job_id IS NULL
               OR child_result.finalized_at_ms > NEW.completed_at_ms)
    ) THEN
        RAISE EXCEPTION 'reusable child invocation is not exactly complete'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_child_results_complete';
    END IF;

    SELECT CASE
        WHEN bool_or(child_result.effective_conclusion = 'failure') THEN 'failure'
        WHEN bool_or(child_result.effective_conclusion = 'timed_out') THEN 'timed_out'
        WHEN bool_or(child_result.effective_conclusion = 'cancelled') THEN 'cancelled'
        WHEN bool_or(child_result.effective_conclusion = 'success') THEN 'success'
        ELSE 'skipped'
    END
      INTO expected_conclusion
    FROM logical_workflow_jobs AS child_job
    JOIN logical_workflow_job_results AS child_result
      ON child_result.run_id = child_job.run_id
     AND child_result.invocation_id = child_job.invocation_id
     AND child_result.logical_job_id = child_job.id
    WHERE child_job.run_id = NEW.run_id
      AND child_job.invocation_id = NEW.child_invocation_id;

    IF NEW.child_job_count <> (
            SELECT count(*) FROM logical_workflow_jobs AS child_job
            WHERE child_job.run_id = NEW.run_id
              AND child_job.invocation_id = NEW.child_invocation_id
        )
        OR NEW.output_count <> (
            SELECT output_count
            FROM logical_workflow_reusable_invocation_expansions AS expansion
            WHERE expansion.run_id = NEW.run_id
              AND expansion.invocation_id = NEW.child_invocation_id
        )
        OR NEW.effective_conclusion IS DISTINCT FROM expected_conclusion
    THEN
        RAISE EXCEPTION 'reusable call result aggregate is inexact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_result_aggregate';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_lock_reusable_workflow_expansion_window() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM logical_workflow_runs AS marker
    JOIN workflow_runs AS run ON run.id = marker.run_id
    JOIN logical_workflow_invocations AS root
      ON root.run_id = marker.run_id
     AND root.id = marker.root_invocation_id
    WHERE marker.run_id = NEW.run_id
      AND marker.root_invocation_id = NEW.root_invocation_id
      AND marker.state IN ('pending', 'active')
      AND marker.admission_graph_sealed_at_ms IS NOT NULL
      AND run.status IN ('queued', 'in_progress')
      AND root.invocation_kind = 'root'
      AND root.state IN ('pending', 'active')
      AND NOT EXISTS (
          SELECT 1
          FROM logical_workflow_run_result_claims AS claim
          WHERE claim.run_id = marker.run_id
      )
    FOR UPDATE OF marker, run, root;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'reusable workflow expansion requires a live unfinalized root'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_window';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_managed_secret_delivery_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'managed secret delivery evidence is append-only'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'managed_secret_delivery_operations_no_delete';
END;
$$;

CREATE FUNCTION automata_managed_secret_delivery_operation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.run_id IS DISTINCT FROM OLD.run_id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
       OR NEW.lease_id IS DISTINCT FROM OLD.lease_id
       OR NEW.fencing_token IS DISTINCT FROM OLD.fencing_token
       OR NEW.runner_id IS DISTINCT FROM OLD.runner_id
       OR NEW.runner_session_id IS DISTINCT FROM OLD.runner_session_id
       OR NEW.runner_session_epoch IS DISTINCT FROM OLD.runner_session_epoch
       OR NEW.runner_generation IS DISTINCT FROM OLD.runner_generation
       OR NEW.runner_slot IS DISTINCT FROM OLD.runner_slot
       OR NEW.runtime_context_digest IS DISTINCT FROM OLD.runtime_context_digest
       OR NEW.binding_set_digest IS DISTINCT FROM OLD.binding_set_digest
       OR NEW.authority_evidence_digest IS DISTINCT FROM OLD.authority_evidence_digest
       OR NEW.credential_key_id IS DISTINCT FROM OLD.credential_key_id
       OR NEW.credential_sha256 IS DISTINCT FROM OLD.credential_sha256
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms
       OR NEW.usable_until_ms IS DISTINCT FROM OLD.usable_until_ms THEN
        RAISE EXCEPTION 'managed secret delivery evidence is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'managed_secret_delivery_operations_evidence_immutable';
    END IF;
    IF OLD.state <> 'pending' AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal managed secret delivery operations are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'managed_secret_delivery_operations_terminal_monotonic';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_membership_status_authorization_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.authorization_revision < OLD.authorization_revision THEN
        RAISE EXCEPTION 'membership authorization revision cannot decrease';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        NEW.authorization_revision := GREATEST(
            NEW.authorization_revision,
            OLD.authorization_revision + 1
        );
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_pin_github_scheduled_workflow_runtime_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rows_inserted BIGINT;
BEGIN
    INSERT INTO logical_workflow_runtime_policy_pins (
        run_id, tenant_id, repository_id, policy_revision,
        policy_digest, pinned_at_ms
    )
    SELECT NEW.run_id, NEW.tenant_id, NEW.repository_id,
           manifest.runtime_policy_revision, manifest.runtime_policy_digest,
           NEW.admitted_at_ms
    FROM github_workflow_run_manifest_origins AS origin
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = origin.tenant_id
     AND manifest.repository_id = origin.repository_id
     AND manifest.provider_connection_id = origin.provider_connection_id
     AND manifest.manifest_revision = origin.provider_manifest_revision
     AND manifest.manifest_digest = origin.provider_manifest_digest
    JOIN workflow_runtime_policy_revisions AS policy
      ON policy.tenant_id = manifest.tenant_id
     AND policy.repository_id = manifest.repository_id
     AND policy.policy_revision = manifest.runtime_policy_revision
     AND policy.policy_digest = manifest.runtime_policy_digest
     AND policy.state = 'sealed'
    WHERE origin.origin_kind = 'scheduled_fire'
      AND origin.origin_id = NEW.schedule_fire_id
      AND origin.run_id = NEW.run_id
      AND origin.tenant_id = NEW.tenant_id
      AND origin.repository_id = NEW.repository_id;
    GET DIAGNOSTICS rows_inserted = ROW_COUNT;
    IF rows_inserted <> 1 THEN
        RAISE EXCEPTION 'scheduled GitHub logical workflow run lacks its historical manifest runtime policy'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_runtime_policy_pin_required';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_pin_github_workflow_runtime_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    rows_inserted BIGINT;
BEGIN
    INSERT INTO logical_workflow_runtime_policy_pins (
        run_id, tenant_id, repository_id, policy_revision,
        policy_digest, pinned_at_ms
    )
    SELECT NEW.run_id, NEW.tenant_id, NEW.repository_id,
           manifest.runtime_policy_revision, manifest.runtime_policy_digest,
           NEW.admitted_at_ms
    FROM github_provider_delivery_evidence AS delivery
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = delivery.tenant_id
     AND manifest.repository_id = delivery.repository_id
     AND manifest.provider_connection_id = delivery.provider_connection_id
     AND manifest.manifest_revision = delivery.provider_manifest_revision
     AND manifest.manifest_digest = delivery.provider_manifest_digest
    JOIN workflow_runtime_policy_revisions AS policy
      ON policy.tenant_id = manifest.tenant_id
     AND policy.repository_id = manifest.repository_id
     AND policy.policy_revision = manifest.runtime_policy_revision
     AND policy.policy_digest = manifest.runtime_policy_digest
     AND policy.state = 'sealed'
    WHERE delivery.provider_delivery_id = NEW.provider_delivery_id
      AND delivery.tenant_id = NEW.tenant_id
      AND delivery.repository_id = NEW.repository_id;
    GET DIAGNOSTICS rows_inserted = ROW_COUNT;
    IF rows_inserted <> 1 THEN
        RAISE EXCEPTION 'GitHub logical workflow run lacks its historical manifest runtime policy'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_runtime_policy_pin_required';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_principal_has_repository_permission(target_tenant_id text, target_principal_id uuid, target_repository_id uuid, target_permission_name text, target_now_ms bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
SELECT EXISTS (
    SELECT 1
    FROM tenant_human_memberships AS membership
    JOIN rbac_role_bindings AS binding
      ON binding.tenant_id = membership.tenant_id
     AND binding.principal_id = membership.principal_id
    JOIN rbac_role_permissions AS permission
      ON permission.tenant_id = binding.tenant_id
     AND permission.role_id = binding.role_id
    WHERE membership.tenant_id = $1
      AND membership.principal_id = $2
      AND membership.status = 'active'
      AND binding.status = 'active'
      AND (binding.valid_until_ms IS NULL OR binding.valid_until_ms > $5)
      AND permission.permission_name = $4
      AND (
          binding.scope_kind = 'tenant'
          OR (binding.scope_kind = 'repository'
              AND binding.repository_id = $3)
      )
);
$_$;

CREATE FUNCTION automata_protect_attempt_terminal_result_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF ROW(
        NEW.attempt_id, NEW.terminal_authority,
        NEW.runner_session_id, NEW.operation_id,
        NEW.runner_id, NEW.runner_session_epoch, NEW.runner_generation,
        NEW.runner_slot, NEW.lease_id, NEW.fencing_token, NEW.result_schema,
        NEW.result_size_bytes, NEW.result_digest, NEW.result_object_key,
        NEW.server_cancellation_operation_id, NEW.server_cancellation_digest,
        NEW.conclusion, NEW.completed_at_ms, NEW.committed_at_ms
    ) IS DISTINCT FROM ROW(
        OLD.attempt_id, OLD.terminal_authority,
        OLD.runner_session_id, OLD.operation_id,
        OLD.runner_id, OLD.runner_session_epoch, OLD.runner_generation,
        OLD.runner_slot, OLD.lease_id, OLD.fencing_token, OLD.result_schema,
        OLD.result_size_bytes, OLD.result_digest, OLD.result_object_key,
        OLD.server_cancellation_operation_id, OLD.server_cancellation_digest,
        OLD.conclusion, OLD.completed_at_ms, OLD.committed_at_ms
    ) THEN
        RAISE EXCEPTION 'attempt terminal result evidence is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_protect_server_cancellation_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM attempt_terminal_results AS terminal
        WHERE terminal.attempt_id = OLD.attempt_id
          AND terminal.terminal_authority = 'server_cancellation'
    ) AND ROW(
        NEW.attempt_id, NEW.operation_id, NEW.requested_by, NEW.reason,
        NEW.requested_at_ms, NEW.delivery_session_id,
        NEW.delivery_command_sequence, NEW.acknowledged_at_ms
    ) IS DISTINCT FROM ROW(
        OLD.attempt_id, OLD.operation_id, OLD.requested_by, OLD.reason,
        OLD.requested_at_ms, OLD.delivery_session_id,
        OLD.delivery_command_sequence, OLD.acknowledged_at_ms
    ) THEN
        RAISE EXCEPTION 'server cancellation intent authority is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_protect_logical_workflow_terminal_ordinal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.logical_workflow_logical_job_id IS DISTINCT FROM
           OLD.logical_workflow_logical_job_id
       OR NEW.logical_workflow_terminal_ordinal IS DISTINCT FROM
           OLD.logical_workflow_terminal_ordinal
    THEN
        IF OLD.logical_workflow_logical_job_id IS NULL
            AND OLD.logical_workflow_terminal_ordinal IS NULL
            AND NEW.logical_workflow_logical_job_id IS NOT NULL
            AND NEW.logical_workflow_terminal_ordinal > 0
            AND pg_trigger_depth() > 1
        THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION 'logical workflow terminal ordinal evidence is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_protected_environment_approval_is_current(target_tenant_id text, target_request_id uuid, target_now_ms bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $_$
SELECT EXISTS (
    SELECT 1
    FROM protected_environment_approval_requests AS request
    JOIN repository_environments AS environment
      ON environment.tenant_id = request.tenant_id
     AND environment.repository_id = request.repository_id
     AND environment.id = request.environment_id
    WHERE request.tenant_id = $1
      AND request.id = $2
      AND request.status = 'approved'
      AND request.resolution_reason = 'approval_threshold_met'
      AND request.resolved_at_ms IS NOT NULL
      AND request.resolved_at_ms < request.expires_at_ms
      AND $3 < request.expires_at_ms
      AND environment.status = 'active'
      AND environment.protection_mode = 'required_approvals'
      AND environment.revision = request.environment_revision
      AND environment.required_approvals = request.required_approvals
      AND environment.prevent_self_review = request.prevent_self_review
      AND (
          NOT request.prevent_self_review
          OR request.requested_by_principal_id IS NOT NULL
      )
      AND (
          SELECT count(*)
          FROM protected_environment_approval_decisions AS decision
          WHERE decision.tenant_id = request.tenant_id
            AND decision.request_id = request.id
            AND decision.decision = 'approve'
            AND (
                NOT request.prevent_self_review
                OR decision.principal_id <> request.requested_by_principal_id
            )
            AND automata_environment_reviewer_assignment_is_current(
                request.tenant_id, request.repository_id, request.environment_id,
                request.environment_revision, decision.principal_id, $3
            )
      ) >= request.required_approvals
      AND NOT EXISTS (
          SELECT 1
          FROM protected_environment_approval_decisions AS decision
          WHERE decision.tenant_id = request.tenant_id
            AND decision.request_id = request.id
            AND decision.decision = 'reject'
            AND automata_environment_reviewer_assignment_is_current(
                request.tenant_id, request.repository_id, request.environment_id,
                request.environment_revision, decision.principal_id, $3
            )
      )
);
$_$;

CREATE FUNCTION automata_protected_environment_approval_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    environment repository_environments%ROWTYPE;
    policy_is_current BOOLEAN;
    database_now_ms BIGINT;
BEGIN
    database_now_ms := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
    SELECT * INTO STRICT environment
    FROM repository_environments
    WHERE tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND id = NEW.environment_id
    FOR SHARE;

    IF TG_OP = 'INSERT' THEN
        IF NEW.environment_revision IS NULL THEN
            NEW.environment_revision := environment.revision;
        END IF;
        IF NEW.status <> 'pending'
           OR NEW.required_approvals <> environment.required_approvals
           OR NEW.prevent_self_review <> environment.prevent_self_review
           OR NEW.environment_revision <> environment.revision
           OR environment.protection_mode <> 'required_approvals'
           OR environment.status <> 'active' THEN
            RAISE EXCEPTION 'approval request does not snapshot the current environment'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'protected_environment_approval_snapshot';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.run_id IS DISTINCT FROM OLD.run_id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.required_approvals IS DISTINCT FROM OLD.required_approvals
       OR NEW.prevent_self_review IS DISTINCT FROM OLD.prevent_self_review
       OR NEW.requested_by_principal_id IS DISTINCT FROM OLD.requested_by_principal_id
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms
       OR NEW.expires_at_ms IS DISTINCT FROM OLD.expires_at_ms
       OR NEW.environment_revision IS DISTINCT FROM OLD.environment_revision THEN
        RAISE EXCEPTION 'approval request evidence is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'protected_environment_approval_evidence_immutable';
    END IF;
    IF OLD.status <> 'pending' AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal approval requests are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'protected_environment_approval_terminal_monotonic';
    END IF;
    IF OLD.status = 'pending' AND NEW.status <> 'pending'
       AND NEW.revision <> OLD.revision + 1 THEN
        RAISE EXCEPTION 'approval resolution requires one revision increment'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'protected_environment_approval_revision_guard';
    ELSIF OLD.status = 'pending' AND NEW.status = 'pending'
          AND NEW.revision <> OLD.revision THEN
        RAISE EXCEPTION 'pending approval revision is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'protected_environment_approval_revision_guard';
    END IF;

    IF OLD.status = 'pending' AND NEW.status <> 'pending' THEN
        policy_is_current :=
            OLD.environment_revision = environment.revision
            AND OLD.required_approvals = environment.required_approvals
            AND OLD.prevent_self_review = environment.prevent_self_review
            AND environment.protection_mode = 'required_approvals'
            AND environment.status = 'active';

        IF NEW.resolved_at_ms IS NULL
           OR NEW.resolved_at_ms > database_now_ms
           OR database_now_ms - NEW.resolved_at_ms > 60000 THEN
            RAISE EXCEPTION 'approval resolution time is not current database time'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'protected_environment_approval_resolution_time';
        END IF;

        IF NEW.status IN ('approved', 'rejected')
           AND (
               NOT policy_is_current
               OR NEW.resolved_at_ms IS NULL
               OR NEW.resolved_at_ms >= OLD.expires_at_ms
               OR database_now_ms >= OLD.expires_at_ms
           ) THEN
            RAISE EXCEPTION 'approval resolution no longer matches current environment policy'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'protected_environment_approval_resolution_current';
        END IF;

        IF NOT policy_is_current
           AND NOT (
               NEW.status = 'cancelled'
               AND NEW.resolution_reason = CASE
                   WHEN environment.status = 'disabled'
                       THEN 'environment_disabled'
                   ELSE 'policy_changed'
               END
           )
           AND NOT (
               NEW.status = 'expired'
               AND NEW.resolution_reason = 'approval_expired'
               AND NEW.resolved_at_ms >= OLD.expires_at_ms
           ) THEN
            RAISE EXCEPTION 'stale approval requires a typed cancellation or expiry'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'protected_environment_approval_stale_resolution';
        END IF;

        IF NEW.status = 'expired'
           AND (
               NEW.resolved_at_ms < OLD.expires_at_ms
               OR database_now_ms < OLD.expires_at_ms
           ) THEN
            RAISE EXCEPTION 'approval cannot expire before its deadline'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'protected_environment_approval_expiry_time';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_protected_environment_decision_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'protected environment decisions are append-only'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'protected_environment_approval_decisions_immutable';
END;
$$;

CREATE FUNCTION automata_prove_protected_environment_approval_resolution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    environment repository_environments%ROWTYPE;
    database_now_ms BIGINT;
    approved_count BIGINT;
    has_rejection BOOLEAN;
BEGIN
    IF OLD.status <> 'pending' OR NEW.status = 'pending' THEN
        RETURN NEW;
    END IF;
    database_now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT * INTO STRICT environment
    FROM repository_environments
    WHERE tenant_id = OLD.tenant_id
      AND repository_id = OLD.repository_id
      AND id = OLD.environment_id
    FOR SHARE;

    IF NEW.status = 'approved' THEN
        IF NEW.resolution_reason <> 'approval_threshold_met'
           OR environment.status <> 'active'
           OR environment.protection_mode <> 'required_approvals'
           OR environment.revision <> OLD.environment_revision
           OR environment.required_approvals <> OLD.required_approvals
           OR environment.prevent_self_review <> OLD.prevent_self_review
           OR NEW.resolved_at_ms IS NULL
           OR NEW.resolved_at_ms >= OLD.expires_at_ms
           OR database_now_ms >= OLD.expires_at_ms THEN
            RAISE EXCEPTION 'approval resolution is not current and threshold-backed'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'protected_environment_approval_resolution_proven';
        END IF;

        SELECT count(*) INTO approved_count
        FROM protected_environment_approval_decisions AS decision
        WHERE decision.tenant_id = OLD.tenant_id
          AND decision.request_id = OLD.id
          AND decision.decision = 'approve'
          AND (
              NOT OLD.prevent_self_review
              OR OLD.requested_by_principal_id IS NULL
              OR decision.principal_id <> OLD.requested_by_principal_id
          )
          AND automata_environment_reviewer_assignment_is_current(
              OLD.tenant_id, OLD.repository_id, OLD.environment_id,
              OLD.environment_revision, decision.principal_id, database_now_ms
          );
        SELECT EXISTS (
            SELECT 1
            FROM protected_environment_approval_decisions AS decision
            WHERE decision.tenant_id = OLD.tenant_id
              AND decision.request_id = OLD.id
              AND decision.decision = 'reject'
              AND automata_environment_reviewer_assignment_is_current(
                  OLD.tenant_id, OLD.repository_id, OLD.environment_id,
                  OLD.environment_revision, decision.principal_id, database_now_ms
              )
        ) INTO has_rejection;
        IF approved_count < OLD.required_approvals OR has_rejection THEN
            RAISE EXCEPTION 'approval threshold is not proven by current distinct reviewers'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'protected_environment_approval_threshold_proven';
        END IF;
    ELSIF NEW.status = 'rejected' THEN
        IF NEW.resolution_reason <> 'approval_rejected'
           OR NOT EXISTS (
               SELECT 1
               FROM protected_environment_approval_decisions AS decision
               WHERE decision.tenant_id = OLD.tenant_id
                 AND decision.request_id = OLD.id
                 AND decision.decision = 'reject'
                 AND automata_environment_reviewer_assignment_is_current(
                     OLD.tenant_id, OLD.repository_id, OLD.environment_id,
                     OLD.environment_revision, decision.principal_id, database_now_ms
                 )
           ) THEN
            RAISE EXCEPTION 'rejection lacks current authorized reviewer evidence'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'protected_environment_approval_rejection_proven';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_provider_delivery_workflow_inventory_digest(uuid) RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
    AS $_$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to(
        'automata.store.provider-delivery-workflow-inventory.v1', 'UTF8'
    )
    || pg_catalog.decode('00', 'hex')
    || inventory.manifest_digest
    || automata_provider_delivery_workflow_inventory_part(
        pg_catalog.convert_to(inventory.source_revision, 'UTF8')
    )
    || inventory.repository_source_digest
    || pg_catalog.int8send(inventory.workflow_count::BIGINT)
    || coalesce((
        SELECT string_agg(
            automata_provider_delivery_workflow_inventory_part(
                pg_catalog.convert_to(entry.workflow_path, 'UTF8')
            )
            || automata_provider_delivery_workflow_inventory_part(
                pg_catalog.convert_to(entry.source_state, 'UTF8')
            )
            || coalesce(entry.source_digest, ''::BYTEA),
            ''::BYTEA ORDER BY entry.ordinal
        )
        FROM provider_delivery_workflow_inventory_entries AS entry
        WHERE entry.inbox_id = inventory.inbox_id
    ), ''::BYTEA)
)
FROM provider_delivery_workflow_inventories AS inventory
WHERE inventory.inbox_id = $1
$_$;

CREATE FUNCTION automata_provider_delivery_workflow_inventory_part(bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
SELECT pg_catalog.int8send(pg_catalog.octet_length($1)::BIGINT) || $1
$_$;

CREATE FUNCTION automata_provider_token_scopes_are_canonical(candidate text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
    SELECT
        cardinality(candidate) <= 256
        AND array_position(candidate, NULL) IS NULL
        AND COALESCE((
            SELECT bool_and(
                octet_length(scope) BETWEEN 1 AND 255
                AND scope ~ '^[A-Za-z0-9][A-Za-z0-9:._/-]*$'
            )
            FROM unnest(candidate) AS scope
        ), TRUE)
        AND cardinality(candidate) = (
            SELECT count(DISTINCT scope) FROM unnest(candidate) AS scope
        )
        AND candidate = ARRAY(
            SELECT scope FROM unnest(candidate) AS scope ORDER BY scope COLLATE "C"
        );
$_$;

CREATE FUNCTION automata_refresh_logical_workflow_activation_due_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM automata_refresh_logical_workflow_job_result_due(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_attempt_lifecycle_due_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.lifecycle IS DISTINCT FROM OLD.lifecycle
       AND NEW.lifecycle IN (
           'succeeded', 'failed', 'cancelled', 'timed_out', 'skipped'
       )
    THEN
        PERFORM automata_refresh_logical_workflow_instance_result_due(NEW.id);
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_instance_claim_due_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM automata_refresh_logical_workflow_instance_result_due(NEW.attempt_id);
    PERFORM 1
    FROM logical_workflow_jobs AS job
    WHERE job.run_id = NEW.run_id
      AND job.invocation_id = NEW.invocation_id
      AND job.id = NEW.logical_job_id
    FOR UPDATE;
    PERFORM automata_refresh_logical_workflow_job_result_due(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_instance_result_due(target_attempt_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO logical_workflow_instance_result_due (
        attempt_id, tenant_id, run_id, invocation_id, logical_job_id,
        source_order, ready_at_ms, available_at_ms
    )
    SELECT terminal.attempt_id, repository.tenant_id,
           concrete.run_id, concrete.invocation_id, concrete.logical_job_id,
           logical_job.source_order, terminal.committed_at_ms,
           COALESCE(claim.expires_at_ms, terminal.committed_at_ms)
    FROM attempt_terminal_results AS terminal
    JOIN job_attempts AS attempt ON attempt.id = terminal.attempt_id
    JOIN jobs AS job ON job.id = attempt.job_id
    JOIN logical_workflow_concrete_jobs AS concrete
      ON concrete.job_id = job.id
     AND concrete.initial_attempt_id = attempt.id
    JOIN logical_workflow_materialization_claims AS materialization
      ON materialization.instance_id = concrete.instance_id
    JOIN logical_workflow_instances AS instance
      ON instance.id = concrete.instance_id
     AND instance.run_id = concrete.run_id
     AND instance.invocation_id = concrete.invocation_id
     AND instance.logical_job_id = concrete.logical_job_id
    JOIN logical_workflow_jobs AS logical_job
      ON logical_job.run_id = concrete.run_id
     AND logical_job.invocation_id = concrete.invocation_id
     AND logical_job.id = concrete.logical_job_id
    JOIN logical_workflow_invocations AS invocation
      ON invocation.run_id = logical_job.run_id
     AND invocation.id = logical_job.invocation_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = concrete.run_id
    JOIN workflow_runs AS run ON run.id = marker.run_id
    JOIN repositories AS repository ON repository.id = run.repository_id
    LEFT JOIN logical_workflow_instance_result_claims AS claim
      ON claim.attempt_id = terminal.attempt_id
    WHERE terminal.attempt_id = target_attempt_id
      AND materialization.state = 'materialized'
      AND job.run_id = concrete.run_id
      AND job.admission_epoch = 1
      AND job.job_ir_schema = 1
      AND job.job_ir_digest = instance.job_ir_digest
      AND job.job_ir_object_key = instance.job_ir_object_key
      AND job.job_ir_size_bytes = instance.job_ir_size_bytes
      AND instance.job_ir_version = 1
      AND instance.job_ir_media_type =
          'application/vnd.automata.job-ir.protobuf'
      AND (
          (terminal.terminal_authority = 'runner'
           AND terminal.result_schema = 1)
          OR terminal.terminal_authority = 'server_cancellation'
      )
      AND terminal.logical_workflow_logical_job_id = concrete.logical_job_id
      AND terminal.logical_workflow_terminal_ordinal > 0
      AND terminal.completed_at_ms >= 0
      AND terminal.committed_at_ms >= terminal.completed_at_ms
      AND (
          (terminal.conclusion = 'success' AND attempt.lifecycle = 'succeeded')
          OR (terminal.conclusion = 'failure' AND attempt.lifecycle = 'failed')
          OR (terminal.conclusion = 'cancelled' AND attempt.lifecycle = 'cancelled')
          OR (terminal.conclusion = 'timed_out' AND attempt.lifecycle = 'timed_out')
          OR (terminal.conclusion = 'skipped' AND attempt.lifecycle = 'skipped')
      )
      AND logical_job.execution_kind = 'steps'
      AND logical_job.state = 'activated'
      AND invocation.plan_schema = 1
      AND invocation.state IN ('pending', 'active')
      AND marker.orchestration_schema = 1
      AND marker.state IN ('pending', 'active')
      AND run.admission_epoch = 1
      AND run.plan_schema = 1
      AND (claim.attempt_id IS NULL OR claim.state = 'projecting')
    ON CONFLICT (attempt_id) DO UPDATE SET
        tenant_id = EXCLUDED.tenant_id,
        run_id = EXCLUDED.run_id,
        invocation_id = EXCLUDED.invocation_id,
        logical_job_id = EXCLUDED.logical_job_id,
        source_order = EXCLUDED.source_order,
        ready_at_ms = EXCLUDED.ready_at_ms,
        available_at_ms = EXCLUDED.available_at_ms;

    IF NOT FOUND THEN
        DELETE FROM logical_workflow_instance_result_due
        WHERE attempt_id = target_attempt_id;
    END IF;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_job_claim_due_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    dependent RECORD;
BEGIN
    PERFORM automata_refresh_logical_workflow_job_result_due(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id
    );
    IF NEW.state = 'finalized' THEN
        FOR dependent IN
            SELECT dependency.run_id, dependency.invocation_id,
                   dependency.logical_job_id
            FROM logical_workflow_dependencies AS dependency
            JOIN logical_workflow_jobs AS job
              ON job.run_id = dependency.run_id
             AND job.invocation_id = dependency.invocation_id
             AND job.id = dependency.logical_job_id
            WHERE dependency.run_id = NEW.run_id
              AND dependency.invocation_id = NEW.invocation_id
              AND dependency.prerequisite_job_id = NEW.logical_job_id
            ORDER BY job.source_order, dependency.logical_job_id
            FOR UPDATE OF job
        LOOP
            PERFORM automata_refresh_logical_workflow_job_result_due(
                dependent.run_id,
                dependent.invocation_id,
                dependent.logical_job_id
            );
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_job_result_due(target_run_id uuid, target_invocation_id uuid, target_logical_job_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO logical_workflow_job_result_due (
        logical_job_id, tenant_id, run_id, invocation_id, source_order,
        ready_at_ms, available_at_ms
    )
    SELECT job.id, repository.tenant_id, job.run_id, job.invocation_id,
           job.source_order, ready.ready_at_ms,
           GREATEST(ready.ready_at_ms,
                    COALESCE(claim.expires_at_ms, ready.ready_at_ms))
    FROM logical_workflow_jobs AS job
    JOIN logical_workflow_invocations AS invocation
      ON invocation.run_id = job.run_id AND invocation.id = job.invocation_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = job.run_id
    JOIN workflow_runs AS run ON run.id = marker.run_id
    JOIN repositories AS repository ON repository.id = run.repository_id
    JOIN logical_workflow_activation_publications AS publication
      ON publication.run_id = job.run_id
     AND publication.invocation_id = job.invocation_id
     AND publication.logical_job_id = job.id
    LEFT JOIN logical_workflow_job_result_claims AS claim
      ON claim.logical_job_id = job.id
    CROSS JOIN LATERAL (
        SELECT GREATEST(
            publication.published_at_ms,
            COALESCE((
                SELECT max(result.finalized_at_ms)
                FROM logical_workflow_instances AS instance
                JOIN logical_workflow_instance_results AS result
                  ON result.instance_id = instance.id
                WHERE instance.run_id = job.run_id
                  AND instance.invocation_id = job.invocation_id
                  AND instance.logical_job_id = job.id
            ), 0),
            COALESCE((
                SELECT max(result.finalized_at_ms)
                FROM logical_workflow_dependencies AS dependency
                JOIN logical_workflow_job_results AS result
                  ON result.logical_job_id = dependency.prerequisite_job_id
                WHERE dependency.run_id = job.run_id
                  AND dependency.invocation_id = job.invocation_id
                  AND dependency.logical_job_id = job.id
            ), 0)
        ) AS ready_at_ms
    ) AS ready
    WHERE job.run_id = target_run_id
      AND job.invocation_id = target_invocation_id
      AND job.id = target_logical_job_id
      AND job.execution_kind = 'steps'
      AND job.state IN ('activated', 'skipped')
      AND invocation.plan_schema = 1
      AND invocation.plan_media_type =
          'application/vnd.automata.workflow-plan+json'
      AND invocation.state IN ('pending', 'active')
      AND marker.orchestration_schema = 1
      AND marker.state IN ('pending', 'active')
      AND run.admission_epoch = 1
      AND run.plan_schema = 1
      AND (claim.logical_job_id IS NULL OR claim.state = 'aggregating')
      AND publication.instance_count = (
          SELECT count(*)
          FROM logical_workflow_instances AS instance
          WHERE instance.run_id = job.run_id
            AND instance.invocation_id = job.invocation_id
            AND instance.logical_job_id = job.id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM logical_workflow_instances AS instance
          LEFT JOIN logical_workflow_instance_results AS result
            ON result.instance_id = instance.id
           AND result.run_id = instance.run_id
           AND result.invocation_id = instance.invocation_id
           AND result.logical_job_id = instance.logical_job_id
          LEFT JOIN logical_workflow_instance_result_claims AS instance_claim
            ON instance_claim.instance_id = result.instance_id
          WHERE instance.run_id = job.run_id
            AND instance.invocation_id = job.invocation_id
            AND instance.logical_job_id = job.id
            AND (result.instance_id IS NULL
                 OR instance_claim.state IS DISTINCT FROM 'finalized')
      )
      AND NOT EXISTS (
          SELECT 1
          FROM logical_workflow_dependencies AS dependency
          LEFT JOIN logical_workflow_job_results AS prerequisite_result
            ON prerequisite_result.run_id = dependency.run_id
           AND prerequisite_result.invocation_id = dependency.invocation_id
           AND prerequisite_result.logical_job_id =
               dependency.prerequisite_job_id
          LEFT JOIN logical_workflow_job_result_claims AS prerequisite_claim
            ON prerequisite_claim.logical_job_id =
               prerequisite_result.logical_job_id
          WHERE dependency.run_id = job.run_id
            AND dependency.invocation_id = job.invocation_id
            AND dependency.logical_job_id = job.id
            AND (prerequisite_result.logical_job_id IS NULL
                 OR prerequisite_claim.state IS DISTINCT FROM 'finalized')
      )
    ON CONFLICT (logical_job_id) DO UPDATE SET
        tenant_id = EXCLUDED.tenant_id,
        run_id = EXCLUDED.run_id,
        invocation_id = EXCLUDED.invocation_id,
        source_order = EXCLUDED.source_order,
        ready_at_ms = EXCLUDED.ready_at_ms,
        available_at_ms = EXCLUDED.available_at_ms;

    IF NOT FOUND THEN
        DELETE FROM logical_workflow_job_result_due
        WHERE logical_job_id = target_logical_job_id
          AND run_id = target_run_id
          AND invocation_id = target_invocation_id;
    END IF;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_job_state_due_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state IS DISTINCT FROM OLD.state THEN
        PERFORM automata_refresh_logical_workflow_job_result_due(
            NEW.run_id, NEW.invocation_id, NEW.id
        );
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_refresh_logical_workflow_terminal_result_due_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM automata_refresh_logical_workflow_instance_result_due(NEW.attempt_id);
    RETURN NEW;
END;
$$;

