CREATE FUNCTION automata_require_final_materialization_work_selection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt logical_workflow_materialization_work_selections%ROWTYPE;
    authority RECORD;
    exact_evidence BOOLEAN := FALSE;
    database_now BIGINT;
BEGIN
    SELECT * INTO receipt
    FROM logical_workflow_materialization_work_selections
    WHERE selection_id = NEW.selection_id
    FOR UPDATE;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF receipt.selection_id IS NULL OR receipt.outcome = 'selecting'
        OR receipt.expires_at_ms IS NULL
    THEN
        RAISE EXCEPTION 'materialization selection may not commit without a live handoff budget'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_must_finalize_live';
    END IF;
    IF receipt.outcome = 'quarantined' THEN
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_materialization_work_quarantines AS quarantine
            WHERE quarantine.selection_id = receipt.selection_id
              AND quarantine.instance_id = receipt.instance_id
              AND quarantine.tenant_id = receipt.tenant_id
              AND quarantine.run_id = receipt.run_id
              AND quarantine.invocation_id = receipt.invocation_id
              AND quarantine.logical_job_id = receipt.logical_job_id
              AND quarantine.selection_owner_id = receipt.owner_id
              AND quarantine.selection_requested_at_ms = receipt.requested_at_ms
              AND quarantine.selection_duration_ms = receipt.duration_ms
              AND quarantine.selection_generation = receipt.generation
              AND quarantine.selection_claimed_at_ms = receipt.claimed_at_ms
              AND quarantine.selection_expires_at_ms = receipt.expires_at_ms
              AND quarantine.authority_digest = receipt.authority_digest
        ) INTO exact_evidence;
    ELSIF receipt.expires_at_ms - database_now < 1000 THEN
        RAISE EXCEPTION 'materialization selection may not commit without a live handoff budget'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_must_finalize_live';
    ELSIF receipt.outcome IN ('idle', 'contended') THEN
        RETURN NULL;
    ELSE
        SELECT claim.state, claim.origin_selection_id, claim.owner_id,
               claim.generation, claim.descriptor_digest AS authority_digest,
               claim.claimed_at_ms, claim.expires_at_ms,
               claim.runtime_policy_revision, claim.runtime_policy_digest,
               claim.expected_job_id, claim.expected_attempt_id
          INTO authority
        FROM logical_workflow_materialization_claims AS claim
        WHERE claim.instance_id = receipt.instance_id
        FOR UPDATE;
        exact_evidence := authority IS NOT NULL
            AND authority.state = 'materializing'
            AND authority.origin_selection_id = receipt.selection_id
            AND authority.owner_id = receipt.owner_id
            AND authority.authority_digest = receipt.authority_digest
            AND authority.expires_at_ms - database_now >= 1000
            AND (
                (authority.generation = receipt.generation
                 AND authority.claimed_at_ms = receipt.claimed_at_ms
                 AND authority.expires_at_ms = receipt.expires_at_ms)
                OR EXISTS (
                    SELECT 1
                    FROM logical_workflow_materialization_renewal_receipts AS renewal
                    WHERE renewal.selection_id = receipt.selection_id
                      AND renewal.instance_id = receipt.instance_id
                      AND renewal.successor_generation = authority.generation
                      AND renewal.successor_claimed_at_ms = authority.claimed_at_ms
                      AND renewal.successor_expires_at_ms = authority.expires_at_ms
                      AND renewal.owner_id = authority.owner_id
                      AND renewal.authority_digest = authority.authority_digest
                      AND renewal.runtime_policy_revision = authority.runtime_policy_revision
                      AND renewal.runtime_policy_digest = authority.runtime_policy_digest
                      AND renewal.expected_job_id = authority.expected_job_id
                      AND renewal.expected_attempt_id = authority.expected_attempt_id
                )
            );
    END IF;
    IF exact_evidence IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'final materialization selection lacks exact current durable evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_final_evidence_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_github_manifest_runtime_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    policy workflow_runtime_policy_revisions%ROWTYPE;
BEGIN
    SELECT revision.* INTO policy
    FROM workflow_runtime_policy_current AS current_policy
    JOIN workflow_runtime_policy_revisions AS revision
      ON revision.tenant_id = current_policy.tenant_id
     AND revision.repository_id = current_policy.repository_id
     AND revision.policy_revision = current_policy.policy_revision
     AND revision.policy_digest = current_policy.policy_digest
    WHERE current_policy.tenant_id = NEW.tenant_id
      AND current_policy.repository_id = NEW.repository_id
      AND current_policy.policy_revision = NEW.runtime_policy_revision
      AND current_policy.policy_digest = NEW.runtime_policy_digest
    FOR SHARE OF current_policy, revision;
    IF policy.state IS DISTINCT FROM 'sealed'
        OR pg_catalog.sha256(policy.canonical_policy) IS DISTINCT FROM
            NEW.runner_policy_digest
        OR pg_catalog.octet_length(policy.canonical_policy) IS DISTINCT FROM
            NEW.runner_policy_size_bytes
    THEN
        RAISE EXCEPTION 'GitHub manifest runtime policy is not exact sealed evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_provider_manifest_runtime_policy_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_github_runtime_authority_attempt_renewal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM github_runtime_authority_issuances AS authority
        WHERE authority.attempt_id = NEW.id
          AND authority.fencing_token = NEW.fencing_token
          AND authority.state = 'ready'
    ) AND NOT automata_github_runtime_authority_lease_final_exact(
        NEW.id,
        NEW.fencing_token
    ) THEN
        RAISE EXCEPTION 'ready GitHub runtime authority lease edit lacks evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_attempt_renewal_final_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_github_runtime_authority_lease_final_exact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT automata_github_runtime_authority_lease_final_exact(
        NEW.attempt_id,
        NEW.fencing_token
    ) THEN
        RAISE EXCEPTION 'GitHub runtime authority lease renewal is not reciprocal'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_lease_renewal_final_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_github_runtime_authority_operation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM github_runtime_authority_operation_receipts AS receipt
        WHERE receipt.attempt_id = NEW.attempt_id
          AND receipt.fencing_token = NEW.fencing_token
          AND receipt.tenant_id = NEW.tenant_id
          AND receipt.operation_kind = NEW.operation_kind
          AND receipt.claim_fence = NEW.claim_fence
          AND receipt.operation_digest = NEW.operation_digest
          AND receipt.disposition = NEW.disposition
          AND receipt.claim_owner_id IS NOT DISTINCT FROM NEW.claim_owner_id
          AND receipt.claim_claimed_at_ms
              IS NOT DISTINCT FROM NEW.claim_claimed_at_ms
          AND receipt.claim_expires_at_ms
              IS NOT DISTINCT FROM NEW.claim_expires_at_ms
          AND receipt.result_state = NEW.result_state
          AND receipt.result_updated_at_ms = NEW.result_updated_at_ms
          AND receipt.result_terminal_reason
              IS NOT DISTINCT FROM NEW.result_terminal_reason
        FOR KEY SHARE
    ) THEN
        RAISE EXCEPTION 'GitHub runtime-authority transition lacks its exact receipt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_operation_transition_receipt_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_github_schedule_fire_terminal_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact BOOLEAN;
BEGIN
    IF NEW.state NOT IN ('admitted', 'skipped', 'failed') THEN
        RETURN NULL;
    END IF;
    IF NEW.failure_kind = 'registry_superseded' THEN
        SELECT NOT EXISTS (
                   SELECT 1
                     FROM github_schedule_registry_current AS current
                    WHERE current.tenant_id = NEW.tenant_id
                      AND current.repository_id = NEW.repository_id
                      AND current.provider_connection_id = NEW.provider_connection_id
                      AND current.registry_id = NEW.registry_id
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM github_schedule_runtime AS runtime
                    WHERE runtime.tenant_id = NEW.tenant_id
                      AND runtime.repository_id = NEW.repository_id
                      AND runtime.provider_connection_id = NEW.provider_connection_id
                      AND runtime.registry_id = NEW.registry_id
                      AND runtime.entry_ordinal = NEW.entry_ordinal
               )
          INTO exact;
        IF exact IS DISTINCT FROM TRUE THEN
            RAISE EXCEPTION 'superseded GitHub schedule fire lacks an inactive registry'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_schedule_fire_terminal_evidence';
        END IF;
        IF NEW.attempt_count = 0 THEN
            RETURN NULL;
        END IF;
    END IF;

    SELECT EXISTS (
               SELECT 1
                 FROM github_schedule_fire_attempts AS attempt
                WHERE attempt.fire_id = NEW.fire_id
                  AND attempt.attempt = NEW.attempt_count
                  AND attempt.claim_fence = NEW.claim_fence
                  AND attempt.outcome = NEW.state
                  AND attempt.failure_kind IS NOT DISTINCT FROM NEW.failure_kind
           )
           AND CASE
               WHEN NEW.failure_kind IN (
                   'registry_superseded',
                   'github.schedule.registry_invalid'
               ) THEN
                   NOT EXISTS (
                       SELECT 1
                         FROM github_schedule_runtime AS runtime
                        WHERE runtime.tenant_id = NEW.tenant_id
                          AND runtime.repository_id = NEW.repository_id
                          AND runtime.provider_connection_id = NEW.provider_connection_id
                          AND runtime.registry_id = NEW.registry_id
                          AND runtime.entry_ordinal = NEW.entry_ordinal
                   )
               ELSE EXISTS (
                   SELECT 1
                     FROM github_schedule_runtime AS runtime
                    WHERE runtime.tenant_id = NEW.tenant_id
                      AND runtime.repository_id = NEW.repository_id
                      AND runtime.provider_connection_id = NEW.provider_connection_id
                      AND runtime.registry_id = NEW.registry_id
                      AND runtime.entry_ordinal = NEW.entry_ordinal
                      AND runtime.next_fire_at_ms > NEW.scheduled_at_ms
               )
           END
      INTO exact;
    IF exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'terminal GitHub schedule fire lacks exact attempt and advancement evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_fire_terminal_evidence';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_inserted_manifest_revision_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM github_provider_manifest_current AS current_manifest
        WHERE current_manifest.tenant_id = NEW.tenant_id
          AND current_manifest.repository_id = NEW.repository_id
          AND current_manifest.provider_connection_id = NEW.provider_connection_id
          AND current_manifest.manifest_revision = NEW.manifest_revision
          AND current_manifest.manifest_digest = NEW.manifest_digest
    ) THEN
        RAISE EXCEPTION 'inserted provider manifest revision must become current'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_provider_manifest_revision_must_be_current';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_job_environment_activation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM logical_workflow_instances AS instance
        WHERE instance.id = NEW.id
    ) AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_environment_evidence AS evidence
        WHERE evidence.instance_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'new activation instance requires environment evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_instances_environment_evidence_required';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_job_environment_gate_before_lease() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
    environment repository_environments%ROWTYPE;
    approval protected_environment_approval_requests%ROWTYPE;
    logical_job logical_workflow_jobs%ROWTYPE;
    database_now_ms BIGINT;
    secret_count BIGINT;
    missing_secret_count BIGINT;
    variable_count BIGINT;
    missing_variable_count BIGINT;
BEGIN
    IF OLD.lifecycle <> 'queued' OR NEW.lifecycle <> 'leased' THEN
        RETURN NEW;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM logical_workflow_concrete_jobs WHERE job_id = NEW.job_id
    ) THEN
        RETURN NEW;
    END IF;
    database_now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.id AND job_id = NEW.job_id FOR SHARE;
    SELECT * INTO STRICT logical_job FROM logical_workflow_jobs
    WHERE run_id = gate.run_id AND invocation_id = gate.invocation_id
      AND id = gate.logical_job_id FOR SHARE;
    IF gate.state <> 'ready'
       OR gate.environment_requirement_kind <> logical_job.environment_requirement_kind
       OR gate.environment_template_digest IS DISTINCT FROM logical_job.environment_template_digest
       OR gate.resolution_digest IS NULL
       OR gate.event_trust = 'unknown' AND cardinality(logical_job.secret_reference_names) > 0
       OR gate.source_kind = 'unknown' AND cardinality(logical_job.secret_reference_names) > 0
       OR gate.invocation_kind = 'reusable'
          AND cardinality(logical_job.secret_reference_names) > 0
          AND gate.reusable_secret_permission <> 'explicit' THEN
        RAISE EXCEPTION 'job environment and credential gate is not ready'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_attempts_environment_gate_ready';
    END IF;

    SELECT count(*) INTO secret_count FROM job_secret_selections WHERE attempt_id = NEW.id;
    SELECT count(*) INTO missing_secret_count FROM job_missing_secret_bindings WHERE attempt_id = NEW.id;
    SELECT count(*) INTO variable_count FROM job_variable_bindings WHERE attempt_id = NEW.id;
    SELECT count(*) INTO missing_variable_count FROM job_missing_variable_bindings WHERE attempt_id = NEW.id;
    IF secret_count <> gate.resolved_secret_count
       OR missing_secret_count <> gate.missing_secret_count
       OR variable_count <> gate.resolved_variable_count
       OR missing_variable_count <> gate.missing_variable_count
       OR secret_count + missing_secret_count <> cardinality(logical_job.secret_reference_names)
       OR variable_count + missing_variable_count <> cardinality(logical_job.variable_reference_names) THEN
        RAISE EXCEPTION 'job credential resolution is incomplete'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_attempts_credential_resolution_complete';
    END IF;
    IF EXISTS (
        SELECT 1 FROM job_secret_selections AS selection
        WHERE selection.attempt_id = NEW.id
          AND selection.binding_digest IS DISTINCT FROM automata_job_secret_selection_digest(
              selection.attempt_id, selection.canonical_name, selection.tenant_id,
              selection.secret_id, selection.secret_version_id,
              selection.secret_version_number, selection.scope_kind,
              selection.environment_id
          )
    ) OR EXISTS (
        SELECT 1 FROM job_variable_bindings AS binding
        WHERE binding.attempt_id = NEW.id
          AND binding.binding_digest IS DISTINCT FROM automata_job_variable_binding_digest(
              binding.attempt_id, binding.canonical_name, binding.tenant_id,
              binding.variable_id, binding.variable_version_id,
              binding.variable_version_number, binding.scope_kind,
              binding.environment_id
          )
    ) THEN
        RAISE EXCEPTION 'job credential selection is no longer current'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_attempts_credential_selection_current';
    END IF;

    IF gate.environment_id IS NOT NULL THEN
        SELECT * INTO STRICT environment FROM repository_environments
        WHERE tenant_id = gate.tenant_id AND repository_id = gate.repository_id
          AND id = gate.environment_id FOR SHARE;
        IF environment.status <> 'active'
           OR environment.revision <> gate.environment_revision THEN
            RAISE EXCEPTION 'job environment policy is stale'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'job_attempts_environment_gate_current';
        END IF;
        IF environment.protection_mode = 'required_approvals' THEN
            SELECT * INTO STRICT approval FROM protected_environment_approval_requests
            WHERE tenant_id = gate.tenant_id AND id = gate.approval_request_id FOR SHARE;
            IF approval.status <> 'approved'
               OR approval.environment_revision <> environment.revision
               OR approval.required_approvals <> environment.required_approvals
               OR approval.prevent_self_review <> environment.prevent_self_review
               OR approval.resolved_at_ms IS NULL
               OR approval.resolved_at_ms >= approval.expires_at_ms
               OR database_now_ms >= approval.expires_at_ms
               OR NOT automata_protected_environment_approval_is_current(
                   gate.tenant_id, gate.approval_request_id, database_now_ms
               ) THEN
                RAISE EXCEPTION 'protected environment approval is stale'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'job_attempts_environment_approval_current';
            END IF;
        ELSIF gate.approval_request_id IS NOT NULL THEN
            RAISE EXCEPTION 'unprotected environment has approval evidence'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'job_attempts_environment_approval_current';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_live_concrete_job_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_claim logical_workflow_materialization_claims%ROWTYPE;
    database_now BIGINT;
BEGIN
    PERFORM automata_require_active_unquarantined_workflow_phase(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id, NEW.instance_id
    );
    SELECT * INTO current_claim
    FROM logical_workflow_materialization_claims
    WHERE instance_id = NEW.instance_id
    FOR UPDATE;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF current_claim.instance_id IS NULL
        OR current_claim.state <> 'materializing'
        OR current_claim.run_id IS DISTINCT FROM NEW.run_id
        OR current_claim.invocation_id IS DISTINCT FROM NEW.invocation_id
        OR current_claim.logical_job_id IS DISTINCT FROM NEW.logical_job_id
        OR current_claim.descriptor_digest IS DISTINCT FROM NEW.descriptor_digest
        OR current_claim.expected_job_id IS DISTINCT FROM NEW.job_id
        OR current_claim.expected_attempt_id IS DISTINCT FROM
           NEW.initial_attempt_id
        OR current_claim.owner_id IS DISTINCT FROM NEW.claim_owner_id
        OR current_claim.generation IS DISTINCT FROM NEW.claim_generation
        OR current_claim.claimed_at_ms IS DISTINCT FROM NEW.claim_started_at_ms
        OR current_claim.expires_at_ms IS DISTINCT FROM NEW.claim_expires_at_ms
        OR current_claim.runtime_policy_revision IS DISTINCT FROM
           NEW.runtime_policy_revision
        OR current_claim.runtime_policy_digest IS DISTINCT FROM
           NEW.runtime_policy_digest
        OR database_now < current_claim.claimed_at_ms
        OR database_now >= current_claim.expires_at_ms
    THEN
        RAISE EXCEPTION 'concrete job insert lacks live exact materialization authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_concrete_job_live_authority_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_materialization_claim_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_claim logical_workflow_materialization_claims%ROWTYPE;
    current_state TEXT;
    event_exact BOOLEAN := FALSE;
    current_exact BOOLEAN := FALSE;
    database_now BIGINT;
BEGIN
    IF NEW.state = 'materializing' THEN
        SELECT (
            EXISTS (
                SELECT 1
                FROM logical_workflow_materialization_work_selections AS selection
                JOIN workflow_runs AS run ON run.id = NEW.run_id
                JOIN repositories AS repository ON repository.id = run.repository_id
                WHERE selection.selection_id = NEW.origin_selection_id
                  AND selection.outcome = 'claimed'
                  AND selection.tenant_id = repository.tenant_id
                  AND selection.run_id = NEW.run_id
                  AND selection.invocation_id = NEW.invocation_id
                  AND selection.logical_job_id = NEW.logical_job_id
                  AND selection.instance_id = NEW.instance_id
                  AND selection.owner_id = NEW.owner_id
                  AND selection.generation = NEW.generation
                  AND selection.claimed_at_ms = NEW.claimed_at_ms
                  AND selection.expires_at_ms = NEW.expires_at_ms
                  AND selection.authority_digest = NEW.descriptor_digest
            ) OR EXISTS (
                SELECT 1
                FROM logical_workflow_materialization_renewal_receipts AS renewal
                JOIN workflow_runs AS run ON run.id = NEW.run_id
                JOIN repositories AS repository ON repository.id = run.repository_id
                WHERE renewal.selection_id = NEW.origin_selection_id
                  AND renewal.tenant_id = repository.tenant_id
                  AND renewal.run_id = NEW.run_id
                  AND renewal.invocation_id = NEW.invocation_id
                  AND renewal.logical_job_id = NEW.logical_job_id
                  AND renewal.instance_id = NEW.instance_id
                  AND renewal.owner_id = NEW.owner_id
                  AND renewal.successor_generation = NEW.generation
                  AND renewal.successor_claimed_at_ms = NEW.claimed_at_ms
                  AND renewal.successor_expires_at_ms = NEW.expires_at_ms
                  AND renewal.authority_digest = NEW.descriptor_digest
                  AND renewal.runtime_policy_revision =
                      NEW.runtime_policy_revision
                  AND renewal.runtime_policy_digest = NEW.runtime_policy_digest
                  AND renewal.expected_job_id = NEW.expected_job_id
                  AND renewal.expected_attempt_id = NEW.expected_attempt_id
            )
        ) INTO event_exact;
        IF event_exact IS DISTINCT FROM TRUE THEN
            RAISE EXCEPTION 'materialization claim event lacks exact selection lineage'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_materialization_claim_lineage_exact';
        END IF;
    END IF;

    SELECT state INTO current_state
    FROM logical_workflow_materialization_claims
    WHERE instance_id = NEW.instance_id;
    IF current_state IS NULL THEN
        RAISE EXCEPTION 'materialization claim lineage target disappeared'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_claim_lineage_retained';
    END IF;
    IF current_state <> 'materializing' THEN
        RETURN NULL;
    END IF;

    PERFORM automata_require_active_unquarantined_workflow_phase(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id, NEW.instance_id
    );
    SELECT * INTO current_claim
    FROM logical_workflow_materialization_claims
    WHERE instance_id = NEW.instance_id
    FOR UPDATE;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT (
        EXISTS (
            SELECT 1
            FROM logical_workflow_materialization_work_selections AS selection
            JOIN workflow_runs AS run ON run.id = current_claim.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE selection.selection_id = current_claim.origin_selection_id
              AND selection.outcome = 'claimed'
              AND selection.tenant_id = repository.tenant_id
              AND selection.run_id = current_claim.run_id
              AND selection.invocation_id = current_claim.invocation_id
              AND selection.logical_job_id = current_claim.logical_job_id
              AND selection.instance_id = current_claim.instance_id
              AND selection.owner_id = current_claim.owner_id
              AND selection.generation = current_claim.generation
              AND selection.claimed_at_ms = current_claim.claimed_at_ms
              AND selection.expires_at_ms = current_claim.expires_at_ms
              AND selection.authority_digest = current_claim.descriptor_digest
        ) OR EXISTS (
            SELECT 1
            FROM logical_workflow_materialization_renewal_receipts AS renewal
            JOIN workflow_runs AS run ON run.id = current_claim.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE renewal.selection_id = current_claim.origin_selection_id
              AND renewal.tenant_id = repository.tenant_id
              AND renewal.run_id = current_claim.run_id
              AND renewal.invocation_id = current_claim.invocation_id
              AND renewal.logical_job_id = current_claim.logical_job_id
              AND renewal.instance_id = current_claim.instance_id
              AND renewal.owner_id = current_claim.owner_id
              AND renewal.successor_generation = current_claim.generation
              AND renewal.successor_claimed_at_ms = current_claim.claimed_at_ms
              AND renewal.successor_expires_at_ms = current_claim.expires_at_ms
              AND renewal.authority_digest = current_claim.descriptor_digest
              AND renewal.runtime_policy_revision =
                  current_claim.runtime_policy_revision
              AND renewal.runtime_policy_digest =
                  current_claim.runtime_policy_digest
              AND renewal.expected_job_id = current_claim.expected_job_id
              AND renewal.expected_attempt_id = current_claim.expected_attempt_id
        )
    ) INTO current_exact;
    IF current_exact IS DISTINCT FROM TRUE
        OR database_now < current_claim.claimed_at_ms
        OR current_claim.expires_at_ms - database_now < 1000
    THEN
        RAISE EXCEPTION 'active materialization claim lacks live exact lineage'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_claim_lineage_current';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_materialization_state_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_claim logical_workflow_materialization_claims%ROWTYPE;
    concrete logical_workflow_concrete_jobs%ROWTYPE;
    database_now BIGINT;
    closed BOOLEAN := FALSE;
BEGIN
    SELECT * INTO current_claim
    FROM logical_workflow_materialization_claims
    WHERE instance_id = NEW.instance_id;
    IF current_claim.instance_id IS NULL THEN
        RAISE EXCEPTION 'materialization closure lost its durable claim'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_claim_retained';
    END IF;
    PERFORM automata_require_active_unquarantined_workflow_phase(
        current_claim.run_id, current_claim.invocation_id,
        current_claim.logical_job_id, current_claim.instance_id
    );
    SELECT * INTO current_claim
    FROM logical_workflow_materialization_claims
    WHERE instance_id = NEW.instance_id
    FOR UPDATE;
    SELECT * INTO concrete
    FROM logical_workflow_concrete_jobs
    WHERE instance_id = NEW.instance_id
    FOR SHARE;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;

    IF current_claim.state = 'materializing' THEN
        closed := concrete.instance_id IS NULL;
    ELSE
        closed := current_claim.state = 'materialized'
            AND concrete.instance_id IS NOT NULL
            AND concrete.run_id = current_claim.run_id
            AND concrete.invocation_id = current_claim.invocation_id
            AND concrete.logical_job_id = current_claim.logical_job_id
            AND concrete.descriptor_digest = current_claim.descriptor_digest
            AND concrete.job_id = current_claim.expected_job_id
            AND concrete.initial_attempt_id = current_claim.expected_attempt_id
            AND concrete.claim_owner_id = current_claim.owner_id
            AND concrete.claim_generation = current_claim.generation
            AND concrete.claim_started_at_ms = current_claim.claimed_at_ms
            AND concrete.claim_expires_at_ms = current_claim.expires_at_ms
            AND concrete.committed_at_ms = current_claim.updated_at_ms
            AND concrete.runtime_policy_revision =
                current_claim.runtime_policy_revision
            AND concrete.runtime_policy_digest = current_claim.runtime_policy_digest
            AND database_now >= current_claim.claimed_at_ms
            AND database_now < current_claim.expires_at_ms;
    END IF;
    IF closed IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'materialization claim and concrete job are not closed'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_state_closure';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_open_workflow_admission_graph() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM logical_workflow_runs AS marker
    JOIN workflow_admission_receipts AS receipt ON receipt.run_id = marker.run_id
    JOIN github_workflow_run_manifest_origins AS origin
      ON origin.run_id = marker.run_id
     AND origin.root_invocation_id = marker.root_invocation_id
    JOIN logical_workflow_runtime_policy_pins AS pin ON pin.run_id = marker.run_id
    WHERE marker.run_id = NEW.run_id
      AND marker.root_invocation_id = NEW.invocation_id
      AND marker.admission_graph_sealed_at_ms IS NULL
      AND receipt.committed_at_ms IS NOT NULL
      AND receipt.idempotency_kind = origin.admission_idempotency_kind
      AND receipt.idempotency_key = origin.admission_idempotency_key
      AND receipt.request_digest = marker.admission_digest
      AND origin.logical_admission_digest = marker.admission_digest
      AND origin.admitted_at_ms = receipt.committed_at_ms
      AND pin.pinned_at_ms = origin.admitted_at_ms
    FOR KEY SHARE OF marker, receipt, pin;
    IF FOUND THEN
        RETURN NEW;
    END IF;

    PERFORM 1
    FROM logical_workflow_runs AS marker
    JOIN workflow_admission_receipts AS receipt ON receipt.run_id = marker.run_id
    JOIN logical_workflow_runtime_policy_pins AS pin ON pin.run_id = marker.run_id
    JOIN security_audit_events AS audit
      ON audit.tenant_id = pin.tenant_id
     AND audit.action = 'workflow.dispatch'
     AND audit.outcome = 'succeeded'
     AND audit.resource_kind = 'workflow_run'
     AND audit.resource_id = marker.run_id::TEXT
     AND audit.occurred_at_ms = pin.pinned_at_ms
     AND audit.actor_kind = 'human'
     AND audit.actor_principal_id IS NOT NULL
     AND audit.actor_session_id IS NOT NULL
     AND audit.authorization_revision IS NOT NULL
    WHERE marker.run_id = NEW.run_id
      AND marker.root_invocation_id = NEW.invocation_id
      AND marker.admission_graph_sealed_at_ms IS NULL
      AND receipt.committed_at_ms IS NOT NULL
      AND receipt.github_subject_evidence_required = FALSE
      AND receipt.request_digest = marker.admission_digest
      AND pin.pinned_at_ms = receipt.committed_at_ms
    FOR KEY SHARE OF marker, receipt, pin, audit;
    IF FOUND THEN
        RETURN NEW;
    END IF;

    PERFORM 1
    FROM logical_workflow_reusable_call_publications AS publication
    JOIN logical_workflow_runs AS marker ON marker.run_id = publication.run_id
    WHERE publication.run_id = NEW.run_id
      AND publication.child_invocation_id = NEW.invocation_id
      AND publication.child_graph_sealed_at_ms IS NULL
      AND marker.admission_graph_sealed_at_ms IS NOT NULL
      AND marker.state IN ('pending', 'active')
      AND NOT EXISTS (
          SELECT 1 FROM logical_workflow_run_result_claims AS claim
          WHERE claim.run_id = marker.run_id
      )
    FOR KEY SHARE OF publication, marker;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'workflow graph insertion is outside an authenticated publication window'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_admission_graph_construction_window';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_preparation_binding_state_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_claim logical_workflow_activation_preparation_claims%ROWTYPE;
    binding logical_workflow_activation_preparations%ROWTYPE;
    database_now BIGINT;
    closed BOOLEAN := FALSE;
BEGIN
    SELECT * INTO current_claim
    FROM logical_workflow_activation_preparation_claims
    WHERE logical_job_id = NEW.logical_job_id;
    IF current_claim.logical_job_id IS NULL THEN
        RAISE EXCEPTION 'preparation binding closure lost its durable claim'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_preparation_binding_claim_retained';
    END IF;
    PERFORM automata_require_active_unquarantined_workflow_phase(
        current_claim.run_id, current_claim.invocation_id,
        current_claim.logical_job_id, NULL
    );
    SELECT * INTO current_claim
    FROM logical_workflow_activation_preparation_claims
    WHERE logical_job_id = NEW.logical_job_id
    FOR UPDATE;
    SELECT * INTO binding
    FROM logical_workflow_activation_preparations
    WHERE logical_job_id = NEW.logical_job_id
    FOR SHARE;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;

    IF current_claim.state = 'preparing' THEN
        closed := binding.logical_job_id IS NULL;
    ELSE
        closed := current_claim.state = 'prepared'
            AND binding.logical_job_id IS NOT NULL
            AND binding.run_id = current_claim.run_id
            AND binding.invocation_id = current_claim.invocation_id
            AND binding.descriptor_digest = current_claim.descriptor_digest
            AND binding.claim_owner_id = current_claim.owner_id
            AND binding.claim_generation = current_claim.generation
            AND binding.claim_started_at_ms = current_claim.claimed_at_ms
            AND binding.claim_expires_at_ms = current_claim.expires_at_ms
            AND binding.claim_origin_selection_id =
                current_claim.origin_selection_id
            AND binding.bound_at_ms = current_claim.updated_at_ms
            AND binding.runtime_policy_revision =
                current_claim.runtime_policy_revision
            AND binding.runtime_policy_digest = current_claim.runtime_policy_digest
            AND database_now >= current_claim.claimed_at_ms
            AND database_now < current_claim.expires_at_ms;
    END IF;
    IF closed IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'preparation binding and claim state are not closed'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_preparation_binding_state_closure';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_preparation_claim_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_claim logical_workflow_activation_preparation_claims%ROWTYPE;
    current_state TEXT;
    event_exact BOOLEAN := FALSE;
    current_exact BOOLEAN := FALSE;
    database_now BIGINT;
BEGIN
    IF NEW.state = 'preparing' THEN
        SELECT (
            EXISTS (
                SELECT 1
                FROM logical_workflow_activation_work_selections AS selection
                JOIN workflow_runs AS run ON run.id = NEW.run_id
                JOIN repositories AS repository ON repository.id = run.repository_id
                WHERE selection.selection_id = NEW.origin_selection_id
                  AND selection.outcome = 'claimed'
                  AND selection.authority_kind = 'preparation'
                  AND selection.tenant_id = repository.tenant_id
                  AND selection.run_id = NEW.run_id
                  AND selection.invocation_id = NEW.invocation_id
                  AND selection.logical_job_id = NEW.logical_job_id
                  AND selection.owner_id = NEW.owner_id
                  AND selection.generation = NEW.generation
                  AND selection.claimed_at_ms = NEW.claimed_at_ms
                  AND selection.expires_at_ms = NEW.expires_at_ms
                  AND selection.authority_digest = NEW.descriptor_digest
            ) OR EXISTS (
                SELECT 1
                FROM logical_workflow_activation_renewal_receipts AS renewal
                JOIN workflow_runs AS run ON run.id = NEW.run_id
                JOIN repositories AS repository ON repository.id = run.repository_id
                WHERE renewal.selection_id = NEW.origin_selection_id
                  AND renewal.authority_kind = 'preparation'
                  AND renewal.tenant_id = repository.tenant_id
                  AND renewal.run_id = NEW.run_id
                  AND renewal.invocation_id = NEW.invocation_id
                  AND renewal.logical_job_id = NEW.logical_job_id
                  AND renewal.owner_id = NEW.owner_id
                  AND renewal.successor_generation = NEW.generation
                  AND renewal.successor_claimed_at_ms = NEW.claimed_at_ms
                  AND renewal.successor_expires_at_ms = NEW.expires_at_ms
                  AND renewal.authority_digest = NEW.descriptor_digest
                  AND renewal.runtime_policy_revision =
                      NEW.runtime_policy_revision
                  AND renewal.runtime_policy_digest = NEW.runtime_policy_digest
            )
        ) INTO event_exact;
        IF event_exact IS DISTINCT FROM TRUE THEN
            RAISE EXCEPTION 'preparation claim event lacks exact selection lineage'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_preparation_claim_lineage_exact';
        END IF;
    END IF;

    SELECT state INTO current_state
    FROM logical_workflow_activation_preparation_claims
    WHERE logical_job_id = NEW.logical_job_id;
    IF current_state IS NULL THEN
        RAISE EXCEPTION 'preparation claim lineage target disappeared'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_preparation_claim_lineage_retained';
    END IF;
    IF current_state <> 'preparing' THEN
        RETURN NULL;
    END IF;

    PERFORM automata_require_active_unquarantined_workflow_phase(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id, NULL
    );
    SELECT * INTO current_claim
    FROM logical_workflow_activation_preparation_claims
    WHERE logical_job_id = NEW.logical_job_id
    FOR UPDATE;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT (
        EXISTS (
            SELECT 1
            FROM logical_workflow_activation_work_selections AS selection
            JOIN workflow_runs AS run ON run.id = current_claim.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE selection.selection_id = current_claim.origin_selection_id
              AND selection.outcome = 'claimed'
              AND selection.authority_kind = 'preparation'
              AND selection.tenant_id = repository.tenant_id
              AND selection.run_id = current_claim.run_id
              AND selection.invocation_id = current_claim.invocation_id
              AND selection.logical_job_id = current_claim.logical_job_id
              AND selection.owner_id = current_claim.owner_id
              AND selection.generation = current_claim.generation
              AND selection.claimed_at_ms = current_claim.claimed_at_ms
              AND selection.expires_at_ms = current_claim.expires_at_ms
              AND selection.authority_digest = current_claim.descriptor_digest
        ) OR EXISTS (
            SELECT 1
            FROM logical_workflow_activation_renewal_receipts AS renewal
            JOIN workflow_runs AS run ON run.id = current_claim.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE renewal.selection_id = current_claim.origin_selection_id
              AND renewal.authority_kind = 'preparation'
              AND renewal.tenant_id = repository.tenant_id
              AND renewal.run_id = current_claim.run_id
              AND renewal.invocation_id = current_claim.invocation_id
              AND renewal.logical_job_id = current_claim.logical_job_id
              AND renewal.owner_id = current_claim.owner_id
              AND renewal.successor_generation = current_claim.generation
              AND renewal.successor_claimed_at_ms = current_claim.claimed_at_ms
              AND renewal.successor_expires_at_ms = current_claim.expires_at_ms
              AND renewal.authority_digest = current_claim.descriptor_digest
              AND renewal.runtime_policy_revision =
                  current_claim.runtime_policy_revision
              AND renewal.runtime_policy_digest =
                  current_claim.runtime_policy_digest
        )
    ) INTO current_exact;
    IF current_exact IS DISTINCT FROM TRUE
        OR database_now < current_claim.claimed_at_ms
        OR current_claim.expires_at_ms - database_now < 1000
    THEN
        RAISE EXCEPTION 'active preparation claim lacks live exact lineage'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_preparation_claim_lineage_current';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_preparation_runner_policy_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.runner_policy_digest IS DISTINCT FROM OLD.runner_policy_digest
            OR NEW.runner_policy_object_key IS DISTINCT FROM OLD.runner_policy_object_key
            OR NEW.runner_policy_size_bytes IS DISTINCT FROM OLD.runner_policy_size_bytes
            OR NEW.runner_policy_media_type IS DISTINCT FROM OLD.runner_policy_media_type
        THEN
            RAISE EXCEPTION 'logical preparation runner policy is immutable'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_preparation_runner_policy_immutable';
        END IF;
        RETURN NEW;
    END IF;

    PERFORM 1
    FROM logical_workflow_jobs AS job
    JOIN logical_workflow_runtime_policy_pins AS pin ON pin.run_id = job.run_id
    JOIN github_workflow_run_manifest_origins AS origin
      ON origin.run_id = job.run_id
     AND origin.tenant_id = pin.tenant_id
     AND origin.repository_id = pin.repository_id
    JOIN workflow_admission_receipts AS receipt
      ON receipt.tenant_id = origin.tenant_id
     AND receipt.idempotency_kind = origin.admission_idempotency_kind
     AND receipt.idempotency_key = origin.admission_idempotency_key
     AND receipt.repository_id = origin.repository_id
     AND receipt.run_id = origin.run_id
     AND receipt.request_digest = origin.logical_admission_digest
     AND receipt.committed_at_ms = origin.admitted_at_ms
     AND receipt.github_subject_evidence_required
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = origin.tenant_id
     AND manifest.repository_id = origin.repository_id
     AND manifest.provider_connection_id = origin.provider_connection_id
     AND manifest.manifest_revision = origin.provider_manifest_revision
     AND manifest.manifest_digest = origin.provider_manifest_digest
    JOIN workflow_runtime_policy_revisions AS policy
      ON policy.tenant_id = pin.tenant_id
     AND policy.repository_id = pin.repository_id
     AND policy.policy_revision = pin.policy_revision
     AND policy.policy_digest = pin.policy_digest
     AND policy.state = 'sealed'
    WHERE job.run_id = NEW.run_id
      AND job.invocation_id = NEW.invocation_id
      AND job.id = NEW.logical_job_id
      AND NEW.runtime_policy_revision = pin.policy_revision
      AND NEW.runtime_policy_digest = pin.policy_digest
      AND manifest.runtime_policy_revision = pin.policy_revision
      AND manifest.runtime_policy_digest = pin.policy_digest
      AND NEW.runner_policy_digest = manifest.runner_policy_digest
      AND NEW.runner_policy_object_key = manifest.runner_policy_object_key
      AND NEW.runner_policy_size_bytes = manifest.runner_policy_size_bytes
      AND NEW.runner_policy_media_type = manifest.runner_policy_media_type
      AND NEW.runner_policy_digest = pg_catalog.sha256(policy.canonical_policy)
      AND NEW.runner_policy_size_bytes = pg_catalog.octet_length(policy.canonical_policy)
    FOR KEY SHARE OF job, pin, receipt, manifest, policy;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'logical preparation runner policy lacks authenticated manifest provenance'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_preparation_runner_policy_provenance';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_pristine_logical_job_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.rerun_carried THEN
        IF NEW.state NOT IN ('completed', 'skipped', 'cancelled', 'failed')
            OR NEW.activation_owner_id IS NOT NULL
            OR NEW.activation_claimed_at_ms IS NOT NULL
            OR NEW.activation_expires_at_ms IS NOT NULL
        THEN
            RAISE EXCEPTION 'carried logical job admission is not exact terminal evidence'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_rerun_carried_job_terminal';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.state IS DISTINCT FROM 'pending'
        OR NEW.activation_fence IS DISTINCT FROM 0
        OR NEW.activation_owner_id IS NOT NULL
        OR NEW.activation_claimed_at_ms IS NOT NULL
        OR NEW.activation_expires_at_ms IS NOT NULL
        OR NEW.activation_input_digest IS NOT NULL
        OR NEW.authority_profile IS NOT NULL
        OR NEW.activation_origin_selection_id IS NOT NULL
    THEN
        RAISE EXCEPTION 'logical job admission must begin without activation authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_jobs_activation_admission_pristine';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_provider_delivery_workflow_progress_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    requires_inventory BOOLEAN;
    inventory_count INTEGER;
    entry_count INTEGER;
    progress_count INTEGER;
    outcome_count INTEGER;
BEGIN
    IF NEW.state <> 'completed' OR OLD.state = 'completed' THEN
        RETURN NEW;
    END IF;

    SELECT manifest.workflow_selection_kind = 'all_direct'
      INTO requires_inventory
    FROM github_provider_delivery_evidence AS evidence
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = evidence.tenant_id
     AND manifest.repository_id = evidence.repository_id
     AND manifest.provider_connection_id = evidence.provider_connection_id
     AND manifest.manifest_revision = evidence.provider_manifest_revision
     AND manifest.manifest_digest = evidence.provider_manifest_digest
    WHERE evidence.provider_delivery_id = NEW.id;

    IF requires_inventory IS DISTINCT FROM TRUE
       AND NOT EXISTS (
           SELECT 1 FROM provider_delivery_workflow_inventories
           WHERE inbox_id = NEW.id
       )
    THEN
        RETURN NEW;
    END IF;

    SELECT inventory.workflow_count,
           (SELECT count(*) FROM provider_delivery_workflow_inventory_entries AS entry
             WHERE entry.inbox_id = NEW.id),
           (SELECT count(*) FROM provider_delivery_workflow_progress AS progress
             WHERE progress.inbox_id = NEW.id),
           (SELECT count(*) FROM provider_delivery_workflow_outcomes AS outcome
             WHERE outcome.inbox_id = NEW.id)
      INTO inventory_count, entry_count, progress_count, outcome_count
    FROM provider_delivery_workflow_inventories AS inventory
    WHERE inventory.inbox_id = NEW.id;

    IF NOT FOUND
        OR inventory_count <> entry_count
        OR inventory_count <> progress_count
        OR inventory_count <> outcome_count
        OR EXISTS (
            SELECT 1
            FROM provider_delivery_workflow_progress AS progress
            FULL JOIN provider_delivery_workflow_outcomes AS outcome
              ON outcome.inbox_id = progress.inbox_id
             AND outcome.workflow_path = progress.workflow_path
            WHERE coalesce(progress.inbox_id, outcome.inbox_id) = NEW.id
              AND (
                  progress.workflow_path IS NULL OR outcome.workflow_path IS NULL
                  OR progress.outcome_kind <> outcome.outcome_kind
                  OR progress.run_id IS DISTINCT FROM outcome.run_id
                  OR progress.failure_kind IS DISTINCT FROM outcome.failure_kind
              )
        )
    THEN
        RAISE EXCEPTION 'provider delivery completion does not match durable workflow progress'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'provider_delivery_workflow_progress_completion_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_renewal_receipt_parent_deleted() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_exists BOOLEAN;
BEGIN
    IF TG_TABLE_NAME = 'logical_workflow_activation_renewal_receipts' THEN
        SELECT EXISTS (
            SELECT 1 FROM logical_workflow_activation_work_selections
            WHERE selection_id = OLD.selection_id
        ) INTO parent_exists;
    ELSE
        SELECT EXISTS (
            SELECT 1 FROM logical_workflow_materialization_work_selections
            WHERE selection_id = OLD.selection_id
        ) INTO parent_exists;
    END IF;
    IF parent_exists THEN
        RAISE EXCEPTION 'renewal evidence is retained with its selection receipt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_real_claim_renewal_receipt_retained';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_runner_requirements_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT (
        NEW.requirements @> '{"schema_version": 1}'::jsonb
        AND NEW.requirements ? 'resource_allocation'
    ) OR NOT EXISTS (
        SELECT 1
        FROM workflow_runs AS run
        WHERE run.id = NEW.run_id
          AND run.runner_requirements_schema = 1
    ) THEN
        RAISE EXCEPTION 'new executable rows require runner-requirements schema v1'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'runner_requirements_current_new_rows_only';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_runner_requirements_current_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM jobs AS job
        WHERE job.id = NEW.job_id
          AND job.requirements @> '{"schema_version": 1}'::jsonb
          AND job.requirements ? 'resource_allocation'
    ) THEN
        RAISE EXCEPTION 'new attempts require runner-requirements schema v1'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_attempts_runner_requirements_current_new_only';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_sealed_workflow_runtime_policy_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    durable_state TEXT;
    selected_current BOOLEAN := FALSE;
BEGIN
    SELECT state INTO durable_state
    FROM workflow_runtime_policy_revisions
    WHERE tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND policy_revision = NEW.policy_revision;
    SELECT EXISTS (
        SELECT 1
        FROM workflow_runtime_policy_current AS current_policy
        WHERE current_policy.tenant_id = NEW.tenant_id
          AND current_policy.repository_id = NEW.repository_id
          AND current_policy.policy_revision = NEW.policy_revision
          AND current_policy.policy_digest = NEW.policy_digest
    ) INTO selected_current;
    IF durable_state IS DISTINCT FROM 'sealed' OR selected_current IS NOT TRUE THEN
        RAISE EXCEPTION 'workflow runtime policy revision must seal and become current'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runtime_policy_revision_must_be_current';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_secret_bindings_before_preparing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    selected_count BIGINT;
    bound_count BIGINT;
    database_now_ms BIGINT;
BEGIN
    IF OLD.lifecycle <> 'leased' OR NEW.lifecycle <> 'preparing'
       OR NOT EXISTS (
           SELECT 1 FROM logical_workflow_concrete_jobs WHERE job_id = NEW.job_id
       ) THEN
        RETURN NEW;
    END IF;
    database_now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT count(*) INTO selected_count
    FROM job_secret_selections WHERE attempt_id = NEW.id;
    SELECT count(*) INTO bound_count
    FROM job_secret_bindings AS binding
    JOIN secret_workload_grants AS workload_grant
      ON workload_grant.tenant_id = binding.tenant_id
     AND workload_grant.id = binding.grant_id
    WHERE binding.attempt_id = NEW.id
      AND binding.lease_id = NEW.lease_id
      AND binding.fencing_token = NEW.fencing_token
      AND workload_grant.status = 'active'
      AND workload_grant.lease_id = NEW.lease_id
      AND workload_grant.fencing_token = NEW.fencing_token
      AND database_now_ms < workload_grant.expires_at_ms;
    IF bound_count <> selected_count THEN
        RAISE EXCEPTION 'job cannot prepare before every selected secret is lease-bound'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_attempts_secret_bindings_complete';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_staging_workflow_runtime_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_state TEXT;
    declared_count INTEGER;
    inserted_count INTEGER;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'workflow runtime policy catalog rows are immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runtime_policy_catalog_immutable';
    END IF;
    SELECT state INTO parent_state
    FROM workflow_runtime_policy_revisions
    WHERE tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND policy_revision = NEW.policy_revision
    FOR UPDATE;
    IF parent_state IS DISTINCT FROM 'staging' THEN
        RAISE EXCEPTION 'workflow runtime policy catalog is sealed'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runtime_policy_catalog_sealed';
    END IF;
    IF TG_TABLE_NAME = 'workflow_runtime_policy_mappings' THEN
        SELECT mapping_count INTO declared_count
        FROM workflow_runtime_policy_revisions
        WHERE tenant_id = NEW.tenant_id
          AND repository_id = NEW.repository_id
          AND policy_revision = NEW.policy_revision;
        SELECT count(*)::INTEGER INTO inserted_count
        FROM workflow_runtime_policy_mappings
        WHERE tenant_id = NEW.tenant_id
          AND repository_id = NEW.repository_id
          AND policy_revision = NEW.policy_revision;
        IF inserted_count >= declared_count OR inserted_count >= 64 THEN
            RAISE EXCEPTION 'workflow runtime policy mapping census exceeded'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_runtime_policy_mapping_insert_census';
        END IF;
    ELSE
        SELECT feature_count INTO declared_count
        FROM workflow_runtime_policy_mappings
        WHERE tenant_id = NEW.tenant_id
          AND repository_id = NEW.repository_id
          AND policy_revision = NEW.policy_revision
          AND selector = NEW.selector
        FOR UPDATE;
        SELECT count(*)::INTEGER INTO inserted_count
        FROM workflow_runtime_policy_features
        WHERE tenant_id = NEW.tenant_id
          AND repository_id = NEW.repository_id
          AND policy_revision = NEW.policy_revision
          AND selector = NEW.selector;
        IF declared_count IS NULL
            OR inserted_count >= declared_count
            OR inserted_count >= 64
        THEN
            RAISE EXCEPTION 'workflow runtime policy feature census exceeded'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_runtime_policy_feature_insert_census';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_standard_github_oidc_profile() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM github_workflow_run_manifest_origins AS origin
        JOIN logical_workflow_runs AS marker
          ON marker.run_id = origin.run_id
         AND marker.root_invocation_id = origin.root_invocation_id
        JOIN github_provider_manifest_revisions AS manifest
          ON manifest.tenant_id = origin.tenant_id
         AND manifest.repository_id = origin.repository_id
         AND manifest.provider_connection_id = origin.provider_connection_id
         AND manifest.manifest_revision = origin.provider_manifest_revision
         AND manifest.manifest_digest = origin.provider_manifest_digest
        JOIN logical_workflow_concrete_jobs AS concrete
          ON concrete.instance_id = NEW.instance_id
         AND concrete.run_id = NEW.run_id
         AND concrete.invocation_id = NEW.invocation_id
         AND concrete.logical_job_id = NEW.logical_job_id
         AND concrete.job_id = NEW.job_id
         AND concrete.initial_attempt_id = NEW.attempt_id
        WHERE origin.tenant_id = NEW.tenant_id
          AND origin.repository_id = NEW.repository_id
          AND origin.workflow_id = NEW.workflow_id
          AND origin.run_id = NEW.run_id
          AND origin.subject_evidence_sha256 =
              NEW.github_run_subject_evidence_sha256
          AND (
              origin.origin_kind = 'provider_delivery'
              AND origin.admission_idempotency_kind = 'provider_delivery'
              OR origin.origin_kind IN ('scheduled_fire', 'workflow_rerun')
              AND origin.admission_idempotency_kind = 'operation'
          )
          AND automata_logical_workflow_invocation_published(
              NEW.run_id, NEW.invocation_id
          )
          AND automata_reusable_workflow_oidc_permission_authorized(
              NEW.run_id, NEW.invocation_id
          )
          AND manifest.authority_profile = 'standard'
          AND concrete.authority_profile = 'standard'
    ) THEN
        RAISE EXCEPTION 'GitHub-compatible OIDC requires historical Standard authority'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'github_oidc_historical_standard_authority';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_logical_workflow_concrete_job_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM logical_workflow_runs WHERE run_id = NEW.run_id
    ) AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_concrete_jobs AS concrete
        JOIN logical_workflow_materialization_claims AS claim
          ON claim.instance_id = concrete.instance_id
        WHERE concrete.run_id = NEW.run_id
          AND concrete.job_id = NEW.id
          AND claim.state = 'materialized'
    ) THEN
        RAISE EXCEPTION 'logical workflow concrete job is not linked to materialized instance'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_logical_workflow_nonempty_root() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_run UUID;
BEGIN
    target_run := CASE WHEN TG_OP = 'DELETE' THEN OLD.run_id ELSE NEW.run_id END;
    IF EXISTS (
        SELECT 1
        FROM logical_workflow_runs AS marker
        WHERE marker.run_id = target_run
          AND NOT EXISTS (
              SELECT 1
              FROM logical_workflow_jobs AS job
              WHERE job.run_id = marker.run_id
                AND job.invocation_id = marker.root_invocation_id
          )
    ) THEN
        RAISE EXCEPTION 'current logical workflow admission requires at least one job'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_workflow_run_results_nonempty_current_run';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_logical_workflow_runner_requirements_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.runner_requirements_schema <> 1
       OR NOT EXISTS (
           SELECT 1
           FROM workflow_runs AS run
           WHERE run.id = NEW.run_id
             AND run.runner_requirements_schema = 1
       )
    THEN
        RAISE EXCEPTION 'new logical workflow runs require runner-requirements schema v1'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_runs_runner_requirements_current_new_only';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_workflow_rerun_audit_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_run_id UUID;
BEGIN
    candidate_run_id := NEW.run_id;
    IF EXISTS (
        SELECT 1
        FROM workflow_rerun_attempts AS attempt
        WHERE attempt.run_id = candidate_run_id
          AND attempt.source_run_id IS NOT NULL
    ) AND NOT EXISTS (
        SELECT 1
        FROM workflow_rerun_audit_evidence AS evidence
        WHERE evidence.run_id = candidate_run_id
    ) THEN
        RAISE EXCEPTION 'workflow rerun requires atomic audit evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_audit_evidence_required';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_workflow_run_runner_requirements_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.runner_requirements_schema <> 1 THEN
        RAISE EXCEPTION 'new workflow runs require the current runner-requirements schema'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runs_runner_requirements_current_new_only';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_require_workflow_runtime_policy_pin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_runtime_policy_pins AS pin
        WHERE pin.run_id = NEW.run_id
    ) OR EXISTS (
        SELECT 1 FROM logical_workflow_runs AS marker
        WHERE marker.run_id = NEW.run_id
          AND marker.admission_graph_sealed_at_ms IS NULL
    ) OR NOT EXISTS (
        SELECT 1 FROM logical_workflow_jobs AS job WHERE job.run_id = NEW.run_id
    ) OR EXISTS (
        SELECT 1
        FROM logical_workflow_jobs AS job
        JOIN logical_workflow_runtime_policy_pins AS pin ON pin.run_id = job.run_id
        WHERE job.run_id = NEW.run_id
          AND (job.runtime_policy_revision, job.runtime_policy_digest)
              IS DISTINCT FROM (pin.policy_revision, pin.policy_digest)
    ) THEN
        RAISE EXCEPTION 'logical workflow admission requires authenticated provider runtime policy'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_runtime_policy_pin_required';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_require_workflow_runtime_policy_pin_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM github_workflow_run_manifest_origins AS origin
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = origin.tenant_id
     AND manifest.repository_id = origin.repository_id
     AND manifest.provider_connection_id = origin.provider_connection_id
     AND manifest.manifest_revision = origin.provider_manifest_revision
     AND manifest.manifest_digest = origin.provider_manifest_digest
    JOIN workflow_runtime_policy_revisions AS policy
      ON policy.tenant_id = manifest.tenant_id
     AND policy.repository_id = manifest.repository_id
     AND policy.policy_revision = manifest.runtime_policy_revision
     AND policy.policy_digest = manifest.runtime_policy_digest
     AND policy.state = 'sealed'
    JOIN workflow_runs AS run
      ON run.id = origin.run_id
     AND run.repository_id = origin.repository_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = origin.run_id
    WHERE origin.run_id = NEW.run_id
      AND origin.tenant_id = NEW.tenant_id
      AND origin.repository_id = NEW.repository_id
      AND origin.admitted_at_ms = NEW.pinned_at_ms
      AND manifest.runtime_policy_revision = NEW.policy_revision
      AND manifest.runtime_policy_digest = NEW.policy_digest
    FOR SHARE OF manifest, policy, run, marker;
    IF FOUND THEN
        RETURN NEW;
    END IF;

    PERFORM 1
    FROM workflow_runs AS run
    JOIN logical_workflow_runs AS marker ON marker.run_id = run.id
    JOIN security_audit_events AS audit
      ON audit.tenant_id = NEW.tenant_id
     AND audit.action = 'workflow.dispatch'
     AND audit.outcome = 'succeeded'
     AND audit.resource_kind = 'workflow_run'
     AND audit.resource_id = NEW.run_id::TEXT
     AND audit.occurred_at_ms = NEW.pinned_at_ms
     AND audit.actor_kind = 'human'
     AND audit.actor_principal_id IS NOT NULL
     AND audit.actor_session_id IS NOT NULL
     AND audit.authorization_revision IS NOT NULL
    JOIN github_provider_manifest_current AS current_manifest
      ON current_manifest.tenant_id = NEW.tenant_id
     AND current_manifest.repository_id = NEW.repository_id
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = current_manifest.tenant_id
     AND manifest.repository_id = current_manifest.repository_id
     AND manifest.provider_connection_id = current_manifest.provider_connection_id
     AND manifest.manifest_revision = current_manifest.manifest_revision
     AND manifest.manifest_digest = current_manifest.manifest_digest
    JOIN workflow_runtime_policy_revisions AS policy
      ON policy.tenant_id = manifest.tenant_id
     AND policy.repository_id = manifest.repository_id
     AND policy.policy_revision = manifest.runtime_policy_revision
     AND policy.policy_digest = manifest.runtime_policy_digest
     AND policy.state = 'sealed'
    WHERE run.id = NEW.run_id
      AND run.repository_id = NEW.repository_id
      AND manifest.runtime_policy_revision = NEW.policy_revision
      AND manifest.runtime_policy_digest = NEW.policy_digest
    FOR SHARE OF run, marker, audit, current_manifest, manifest, policy;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'workflow runtime policy pin lacks authenticated manifest provenance'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_runtime_policy_pin_provenance';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_required_github_subject_evidence_committed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    receipt workflow_admission_receipts%ROWTYPE;
    evidence_count BIGINT;
BEGIN
    IF NOT NEW.github_subject_evidence_required THEN
        RETURN NULL;
    END IF;

    SELECT * INTO receipt
    FROM workflow_admission_receipts
    WHERE tenant_id = NEW.tenant_id
      AND idempotency_kind = NEW.idempotency_kind
      AND idempotency_key = NEW.idempotency_key;

    IF receipt.github_subject_evidence_required
        AND receipt.idempotency_kind = 'provider_delivery'
        AND receipt.repository_id IS NOT NULL
        AND receipt.run_id IS NOT NULL
        AND receipt.committed_at_ms IS NOT NULL
    THEN
        SELECT count(*) INTO evidence_count
        FROM github_workflow_run_subject_evidence AS evidence
        WHERE evidence.tenant_id = receipt.tenant_id
          AND evidence.repository_id = receipt.repository_id
          AND evidence.run_id = receipt.run_id
          AND evidence.provider_delivery_idempotency_key = receipt.idempotency_key
          AND evidence.logical_admission_digest = receipt.request_digest
          AND evidence.admitted_at_ms = receipt.committed_at_ms;
    ELSIF receipt.github_subject_evidence_required
        AND receipt.idempotency_kind = 'operation'
        AND receipt.idempotency_key LIKE 'workflow-rerun:%'
        AND receipt.repository_id IS NOT NULL
        AND receipt.run_id IS NOT NULL
        AND receipt.committed_at_ms IS NOT NULL
    THEN
        SELECT count(*) INTO evidence_count
        FROM github_workflow_rerun_subject_evidence AS evidence
        WHERE evidence.tenant_id = receipt.tenant_id
          AND evidence.repository_id = receipt.repository_id
          AND evidence.run_id = receipt.run_id
          AND 'workflow-rerun:' || evidence.operation_id::TEXT =
              receipt.idempotency_key
          AND evidence.logical_admission_digest = receipt.request_digest
          AND evidence.admitted_at_ms = receipt.committed_at_ms;
    ELSIF receipt.github_subject_evidence_required
        AND receipt.idempotency_kind = 'operation'
        AND receipt.repository_id IS NOT NULL
        AND receipt.run_id IS NOT NULL
        AND receipt.committed_at_ms IS NOT NULL
    THEN
        SELECT count(*) INTO evidence_count
        FROM github_schedule_workflow_run_subject_evidence AS evidence
        WHERE evidence.tenant_id = receipt.tenant_id
          AND evidence.repository_id = receipt.repository_id
          AND evidence.run_id = receipt.run_id
          AND evidence.schedule_fire_id::TEXT = receipt.idempotency_key
          AND evidence.logical_admission_digest = receipt.request_digest
          AND evidence.admitted_at_ms = receipt.committed_at_ms;
    END IF;

    IF evidence_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'authenticated GitHub admission requires exact subject evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_admission_required_github_evidence_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_retain_runner_payload_tombstone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.payload_tombstone_reason IS NOT NULL THEN
        RAISE EXCEPTION 'runner payload tombstone metadata must be retained'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = TG_TABLE_NAME || '_tombstone_retained';
    END IF;
    RETURN OLD;
END;
$$;

CREATE FUNCTION automata_reusable_secret_identity_chain_is_exact(target_run_id uuid, target_invocation_id uuid, target_canonical_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    current_invocation_id UUID := target_invocation_id;
    parent_invocation_id UUID;
    current_depth SMALLINT;
    expected_depth SMALLINT;
    matching_target_count BIGINT;
    same_name_source_count BIGINT;
    visited_invocations UUID[] := ARRAY[]::UUID[];
BEGIN
    IF target_canonical_name IS NULL
       OR target_canonical_name !~ '^[A-Z_][A-Z0-9_]*$'
       OR target_canonical_name ~ '^(GITHUB_|ACTIONS_|RUNNER_|AUTOMATA_)'
       OR octet_length(target_canonical_name) > 255 THEN
        RETURN FALSE;
    END IF;

    LOOP
        IF current_invocation_id = ANY(visited_invocations) THEN
            RETURN FALSE;
        END IF;
        visited_invocations := array_append(
            visited_invocations,
            current_invocation_id
        );

        SELECT expansion.parent_invocation_id, expansion.depth
          INTO parent_invocation_id, current_depth
        FROM logical_workflow_reusable_invocation_expansions AS expansion
        WHERE expansion.run_id = target_run_id
          AND expansion.invocation_id = current_invocation_id;
        IF NOT FOUND
           OR expected_depth IS NOT NULL AND current_depth <> expected_depth THEN
            RETURN FALSE;
        END IF;
        IF parent_invocation_id IS NULL THEN
            RETURN current_depth = 0;
        END IF;
        IF current_depth <= 0 THEN
            RETURN FALSE;
        END IF;

        SELECT count(*),
               count(*) FILTER (
                   WHERE upper(binding.source_name) = target_canonical_name
               )
          INTO matching_target_count, same_name_source_count
        FROM logical_workflow_reusable_secret_bindings AS binding
        WHERE binding.run_id = target_run_id
          AND binding.invocation_id = current_invocation_id
          AND upper(binding.target_name) = target_canonical_name;
        IF matching_target_count <> 1 OR same_name_source_count <> 1 THEN
            RETURN FALSE;
        END IF;

        expected_depth := current_depth - 1;
        current_invocation_id := parent_invocation_id;
    END LOOP;
END;
$_$;

CREATE FUNCTION automata_reusable_workflow_oidc_permission_authorized(target_run_id uuid, target_invocation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM logical_workflow_runs AS marker
        WHERE marker.run_id = target_run_id
          AND (
              marker.root_invocation_id = target_invocation_id
              OR (
                  automata_logical_workflow_invocation_published(
                      target_run_id, target_invocation_id
                  )
                  AND EXISTS (
                      SELECT 1
                      FROM logical_workflow_reusable_invocation_expansions AS planned
                      JOIN logical_workflow_reusable_call_publications AS publication
                        ON publication.run_id = planned.run_id
                       AND publication.child_invocation_id = planned.invocation_id
                       AND publication.parent_invocation_id = planned.parent_invocation_id
                       AND publication.caller_logical_job_id =
                           planned.caller_logical_job_id
                       AND publication.permission_digest = planned.permission_digest
                       AND publication.condition_matched
                       AND publication.child_graph_sealed_at_ms =
                           publication.published_at_ms
                      JOIN logical_workflow_reusable_permission_snapshots AS permission_snapshot
                        ON permission_snapshot.run_id = planned.run_id
                       AND permission_snapshot.invocation_id = planned.invocation_id
                       AND permission_snapshot.permission_digest = planned.permission_digest
                      LEFT JOIN logical_workflow_reusable_permission_grants AS id_token_grant
                        ON id_token_grant.run_id = permission_snapshot.run_id
                       AND id_token_grant.invocation_id =
                           permission_snapshot.invocation_id
                       AND id_token_grant.permission_name = 'id-token'
                      WHERE planned.run_id = target_run_id
                        AND planned.invocation_id = target_invocation_id
                        AND planned.depth > 0
                        AND COALESCE(
                            id_token_grant.permission_level,
                            permission_snapshot.default_level
                        ) = 'write'
                  )
              )
          )
    )
$$;

CREATE FUNCTION automata_role_binding_authorization_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'DELETE' THEN
        UPDATE tenant_human_memberships
        SET authorization_revision = authorization_revision + 1
        WHERE tenant_id = NEW.tenant_id AND principal_id = NEW.principal_id;
    END IF;
    IF TG_OP <> 'INSERT' AND (
        TG_OP = 'DELETE'
        OR OLD.tenant_id IS DISTINCT FROM NEW.tenant_id
        OR OLD.principal_id IS DISTINCT FROM NEW.principal_id
    ) THEN
        UPDATE tenant_human_memberships
        SET authorization_revision = authorization_revision + 1
        WHERE tenant_id = OLD.tenant_id AND principal_id = OLD.principal_id;
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_role_permission_authorization_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'DELETE' THEN
        UPDATE tenant_human_memberships AS membership
        SET authorization_revision = membership.authorization_revision + 1
        WHERE membership.tenant_id = NEW.tenant_id
          AND EXISTS (
              SELECT 1 FROM rbac_role_bindings AS binding
              WHERE binding.tenant_id = NEW.tenant_id
                AND binding.principal_id = membership.principal_id
                AND binding.role_id = NEW.role_id
                AND binding.status = 'active'
          );
    END IF;
    IF TG_OP <> 'INSERT' AND (
        TG_OP = 'DELETE'
        OR OLD.tenant_id IS DISTINCT FROM NEW.tenant_id
        OR OLD.role_id IS DISTINCT FROM NEW.role_id
    ) THEN
        UPDATE tenant_human_memberships AS membership
        SET authorization_revision = membership.authorization_revision + 1
        WHERE membership.tenant_id = OLD.tenant_id
          AND EXISTS (
              SELECT 1 FROM rbac_role_bindings AS binding
              WHERE binding.tenant_id = OLD.tenant_id
                AND binding.principal_id = membership.principal_id
                AND binding.role_id = OLD.role_id
                AND binding.status = 'active'
          );
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_runner_certificate_authority_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.leaf_sha256 IS DISTINCT FROM OLD.leaf_sha256
       OR NEW.runner_id IS DISTINCT FROM OLD.runner_id
       OR NEW.expires_at_seconds IS DISTINCT FROM OLD.expires_at_seconds THEN
        RAISE EXCEPTION 'runner machine certificate authority is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'runner_machine_certificates_authority_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_runner_certificate_revocation_write_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.revoked_at_seconds IS NOT NULL
       AND NEW.revoked_at_seconds IS DISTINCT FROM OLD.revoked_at_seconds THEN
        RAISE EXCEPTION 'runner machine certificate revocation is write-once'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'runner_machine_certificates_revocation_write_once';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_runner_enrollment_token_consume_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.runner_group_id IS DISTINCT FROM OLD.runner_group_id
       OR NEW.token_sha256 IS DISTINCT FROM OLD.token_sha256
       OR NEW.issued_by_principal_id IS DISTINCT FROM OLD.issued_by_principal_id
       OR NEW.issued_by_session_id IS DISTINCT FROM OLD.issued_by_session_id
       OR NEW.issued_authorization_revision IS DISTINCT FROM OLD.issued_authorization_revision
       OR NEW.issued_at_ms IS DISTINCT FROM OLD.issued_at_ms
       OR NEW.expires_at_ms IS DISTINCT FROM OLD.expires_at_ms
       OR (OLD.consumed_at_ms IS NOT NULL AND (
           NEW.consumed_at_ms IS DISTINCT FROM OLD.consumed_at_ms
           OR NEW.consumed_runner_id IS DISTINCT FROM OLD.consumed_runner_id
           OR NEW.redeem_operation_id IS DISTINCT FROM OLD.redeem_operation_id
           OR NEW.redeem_request_sha256 IS DISTINCT FROM OLD.redeem_request_sha256
           OR NEW.redeem_response IS DISTINCT FROM OLD.redeem_response
       )) THEN
        RAISE EXCEPTION 'runner enrollment token authority is immutable and consumption is write-once'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'runner_enrollment_tokens_consume_once';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seal_github_schedule_registry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    revision_count SMALLINT;
    revision_digest BYTEA;
    actual_count BIGINT;
    minimum_ordinal SMALLINT;
    maximum_ordinal SMALLINT;
BEGIN
    SELECT schedule_count, inventory_digest
      INTO revision_count, revision_digest
     FROM github_schedule_registry_revisions
     WHERE registry_id = NEW.registry_id
     FOR UPDATE;
    SELECT count(*), min(ordinal), max(ordinal)
      INTO actual_count, minimum_ordinal, maximum_ordinal
      FROM github_schedule_registry_entries
     WHERE registry_id = NEW.registry_id;
    IF revision_count IS NULL
        OR revision_count <> NEW.schedule_count
        OR revision_digest <> NEW.inventory_digest
        OR actual_count <> NEW.schedule_count
        OR (
            NEW.schedule_count > 0
            AND (minimum_ordinal <> 0 OR maximum_ordinal <> NEW.schedule_count - 1)
        )
    THEN
        RAISE EXCEPTION 'GitHub schedule registry seal does not match exact entries'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_schedule_registry_seal_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seal_reusable_call_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.run_id IS DISTINCT FROM OLD.run_id
        OR NEW.parent_invocation_id IS DISTINCT FROM OLD.parent_invocation_id
        OR NEW.caller_logical_job_id IS DISTINCT FROM OLD.caller_logical_job_id
        OR NEW.caller_instance_id IS DISTINCT FROM OLD.caller_instance_id
        OR NEW.child_invocation_id IS DISTINCT FROM OLD.child_invocation_id
        OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
        OR NEW.activation_generation IS DISTINCT FROM OLD.activation_generation
        OR NEW.activation_input_digest IS DISTINCT FROM OLD.activation_input_digest
        OR NEW.condition_matched IS DISTINCT FROM OLD.condition_matched
        OR NEW.matrix_digest IS DISTINCT FROM OLD.matrix_digest
        OR NEW.runtime_context_digest IS DISTINCT FROM OLD.runtime_context_digest
        OR NEW.runtime_context_object_key IS DISTINCT FROM OLD.runtime_context_object_key
        OR NEW.runtime_context_size_bytes IS DISTINCT FROM OLD.runtime_context_size_bytes
        OR NEW.runtime_context_media_type IS DISTINCT FROM OLD.runtime_context_media_type
        OR NEW.runtime_context_schema IS DISTINCT FROM OLD.runtime_context_schema
        OR NEW.permission_digest IS DISTINCT FROM OLD.permission_digest
        OR NEW.output_mapping_count IS DISTINCT FROM OLD.output_mapping_count
        OR NEW.output_mapping_digest IS DISTINCT FROM OLD.output_mapping_digest
        OR NEW.publication_digest IS DISTINCT FROM OLD.publication_digest
        OR NEW.runtime_policy_revision IS DISTINCT FROM OLD.runtime_policy_revision
        OR NEW.runtime_policy_digest IS DISTINCT FROM OLD.runtime_policy_digest
        OR NEW.authority_profile IS DISTINCT FROM OLD.authority_profile
        OR NEW.published_at_ms IS DISTINCT FROM OLD.published_at_ms
        OR OLD.child_graph_sealed_at_ms IS NOT NULL
        OR NEW.child_graph_sealed_at_ms IS DISTINCT FROM NEW.published_at_ms
    THEN
        RAISE EXCEPTION 'reusable call publication is immutable outside its seal transition'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_publication_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seal_reusable_call_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
        OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
        OR NEW.run_id IS DISTINCT FROM OLD.run_id
        OR NEW.parent_invocation_id IS DISTINCT FROM OLD.parent_invocation_id
        OR NEW.caller_logical_job_id IS DISTINCT FROM OLD.caller_logical_job_id
        OR NEW.caller_instance_id IS DISTINCT FROM OLD.caller_instance_id
        OR NEW.child_invocation_id IS DISTINCT FROM OLD.child_invocation_id
        OR NEW.publication_operation_id IS DISTINCT FROM OLD.publication_operation_id
        OR NEW.completion_operation_id IS DISTINCT FROM OLD.completion_operation_id
        OR NEW.callee_plan_digest IS DISTINCT FROM OLD.callee_plan_digest
        OR NEW.evaluator_schema IS DISTINCT FROM OLD.evaluator_schema
        OR NEW.child_job_count IS DISTINCT FROM OLD.child_job_count
        OR NEW.child_jobs_digest IS DISTINCT FROM OLD.child_jobs_digest
        OR NEW.workflow_output_evaluation_digest IS DISTINCT FROM
           OLD.workflow_output_evaluation_digest
        OR NEW.descriptor_digest IS DISTINCT FROM OLD.descriptor_digest
        OR NEW.effective_conclusion IS DISTINCT FROM OLD.effective_conclusion
        OR NEW.output_count IS DISTINCT FROM OLD.output_count
        OR NEW.outputs_digest IS DISTINCT FROM OLD.outputs_digest
        OR NEW.commit_digest IS DISTINCT FROM OLD.commit_digest
        OR NEW.parent_result_descriptor_digest IS DISTINCT FROM
           OLD.parent_result_descriptor_digest
        OR NEW.parent_instances_digest IS DISTINCT FROM OLD.parent_instances_digest
        OR NEW.parent_prerequisites_digest IS DISTINCT FROM
           OLD.parent_prerequisites_digest
        OR NEW.parent_outputs_digest IS DISTINCT FROM OLD.parent_outputs_digest
        OR NEW.parent_commit_digest IS DISTINCT FROM OLD.parent_commit_digest
        OR NEW.completed_at_ms IS DISTINCT FROM OLD.completed_at_ms
        OR OLD.sealed_at_ms IS NOT NULL
        OR NEW.sealed_at_ms IS DISTINCT FROM NEW.completed_at_ms
    THEN
        RAISE EXCEPTION 'reusable call result is immutable outside its seal transition'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_result_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_cleanup_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret cleanup receipts cannot be deleted'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_cleanup_delete_forbidden';
END;
$$;

CREATE FUNCTION automata_secret_cleanup_transition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.operation_id = '00000000-0000-0000-0000-000000000000'::UUID
           OR NEW.status <> 'pending'
           OR NEW.attempts <> 0
           OR NEW.claim_generation <> 0
           OR NEW.locked_by IS NOT NULL
           OR NEW.locked_at_ms IS NOT NULL
           OR NEW.last_failure_kind IS NOT NULL
           OR NEW.completed_at_ms IS NOT NULL
           OR NEW.next_attempt_at_ms < NEW.created_at_ms THEN
            RAISE EXCEPTION 'secret cleanup must begin as an unfenced pending task'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_cleanup_initial_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.sequence IS DISTINCT FROM OLD.sequence
       OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.cleanup_kind IS DISTINCT FROM OLD.cleanup_kind
       OR NEW.provider_lease_record_id IS DISTINCT FROM OLD.provider_lease_record_id
       OR NEW.secret_id IS DISTINCT FROM OLD.secret_id
       OR NEW.secret_version_id IS DISTINCT FROM OLD.secret_version_id
       OR NEW.version_number IS DISTINCT FROM OLD.version_number
       OR NEW.envelope_generation IS DISTINCT FROM OLD.envelope_generation
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms THEN
        RAISE EXCEPTION 'secret cleanup task identity is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_cleanup_identity_immutable';
    END IF;

    IF OLD.status = 'pending' AND NEW.status = 'in_progress' THEN
        IF NEW.attempts IS DISTINCT FROM OLD.attempts + 1
           OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation + 1
           OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
           OR NEW.last_failure_kind IS DISTINCT FROM OLD.last_failure_kind
           OR octet_length(NEW.locked_by) NOT BETWEEN 1 AND 255
           OR NEW.locked_by ~ '[[:cntrl:]]'
           OR NEW.locked_at_ms < OLD.next_attempt_at_ms
           OR NEW.completed_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'secret cleanup claim is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_cleanup_claim_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'in_progress' AND NEW.status = 'in_progress' THEN
        IF NEW.attempts IS DISTINCT FROM OLD.attempts
           OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation + 1
           OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
           OR NEW.last_failure_kind IS DISTINCT FROM OLD.last_failure_kind
           OR octet_length(NEW.locked_by) NOT BETWEEN 1 AND 255
           OR NEW.locked_by ~ '[[:cntrl:]]'
           OR NEW.locked_at_ms <= OLD.locked_at_ms
           OR NEW.completed_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'secret cleanup takeover is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_cleanup_takeover_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'in_progress' AND NEW.status IN ('pending', 'dead_letter') THEN
        IF NEW.attempts IS DISTINCT FROM OLD.attempts
           OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation
           OR NEW.next_attempt_at_ms <= OLD.locked_at_ms
           OR NEW.next_attempt_at_ms > OLD.locked_at_ms + 86400000
           OR NEW.locked_by IS NOT NULL
           OR NEW.locked_at_ms IS NOT NULL
           OR NEW.last_failure_kind IS NULL
           OR NEW.completed_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'secret cleanup retry is not fence-bound'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_cleanup_retry_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'in_progress' AND NEW.status = 'completed' THEN
        IF NEW.attempts IS DISTINCT FROM OLD.attempts
           OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation
           OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
           OR NEW.locked_by IS NOT NULL
           OR NEW.locked_at_ms IS NOT NULL
           OR NEW.last_failure_kind IS DISTINCT FROM OLD.last_failure_kind
           OR NEW.completed_at_ms < OLD.locked_at_ms THEN
            RAISE EXCEPTION 'secret cleanup completion is not fence-bound'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_cleanup_completion_exact';
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'invalid secret cleanup transition'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_cleanup_transition_exact';
END;
$$;

CREATE FUNCTION automata_secret_custody_canary_require_fresh_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- A concurrent exact first writer is resolved by the primary key. Do not
    -- reject that replay merely because a write composed after its winner has
    -- already begun using the now-attested identity.
    IF EXISTS (
        SELECT 1 FROM secret_custody_key_canaries
        WHERE wrapping_key_id = NEW.wrapping_key_id
    ) THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1 FROM secret_provider_configuration_envelopes
        WHERE wrapping_key_id = NEW.wrapping_key_id
    ) OR EXISTS (
        SELECT 1 FROM secret_provider_locator_envelopes
        WHERE wrapping_key_id = NEW.wrapping_key_id
    ) OR EXISTS (
        SELECT 1 FROM secret_provider_version_envelopes
        WHERE wrapping_key_id = NEW.wrapping_key_id
    ) OR EXISTS (
        SELECT 1 FROM secret_version_envelopes
        WHERE wrapping_key_id = NEW.wrapping_key_id
    ) OR EXISTS (
        SELECT 1 FROM secret_provider_lease_envelopes
        WHERE wrapping_key_id = NEW.wrapping_key_id
    ) OR EXISTS (
        SELECT 1 FROM secret_key_rotations
        WHERE from_wrapping_key_id = NEW.wrapping_key_id
           OR to_wrapping_key_id = NEW.wrapping_key_id
    ) THEN
        RAISE EXCEPTION 'referenced secret custody keys require a prior canary'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_custody_key_canaries_fresh_key';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_custody_key_canaries_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret custody key canaries are immutable'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_custody_key_canaries_immutable';
END;
$$;

CREATE FUNCTION automata_secret_descriptor_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.canonical_name IS DISTINCT FROM OLD.canonical_name
       OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.created_by_principal_id IS DISTINCT FROM OLD.created_by_principal_id
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms THEN
        RAISE EXCEPTION 'logical secret descriptors are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secrets_descriptor_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TABLE job_environment_gates (
    tenant_id text NOT NULL,
    repository_id uuid NOT NULL,
    run_id uuid NOT NULL,
    invocation_id uuid NOT NULL,
    logical_job_id uuid NOT NULL,
    instance_id uuid NOT NULL,
    job_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    environment_requirement_kind text NOT NULL,
    environment_template_digest bytea,
    environment_id uuid,
    environment_revision bigint,
    approval_request_id uuid,
    event_trust text DEFAULT 'unknown'::text NOT NULL,
    source_kind text DEFAULT 'unknown'::text NOT NULL,
    invocation_kind text NOT NULL,
    reusable_secret_permission text DEFAULT 'none'::text NOT NULL,
    state text NOT NULL,
    resolution_digest bytea,
    resolved_secret_count integer,
    missing_secret_count integer,
    resolved_variable_count integer,
    missing_variable_count integer,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT job_environment_gates_environment_shape CHECK (((((environment_requirement_kind = ANY (ARRAY['unclassified'::text, 'none'::text])) AND (environment_template_digest IS NULL) AND (environment_id IS NULL) AND (environment_revision IS NULL) AND (approval_request_id IS NULL)) OR ((environment_requirement_kind = 'environment'::text) AND (octet_length(environment_template_digest) = 32) AND (((state = 'selection_pending'::text) AND (environment_id IS NULL) AND (environment_revision IS NULL) AND (approval_request_id IS NULL)) OR ((state = 'cancelled'::text) AND (((environment_id IS NULL) AND (environment_revision IS NULL) AND (approval_request_id IS NULL)) OR ((environment_id IS NOT NULL) AND (environment_revision > 0)))) OR ((state <> ALL (ARRAY['selection_pending'::text, 'cancelled'::text])) AND (environment_id IS NOT NULL) AND (environment_revision > 0))))) IS TRUE)),
    CONSTRAINT job_environment_gates_event_trust CHECK ((event_trust = ANY (ARRAY['unknown'::text, 'trusted'::text, 'untrusted'::text]))),
    CONSTRAINT job_environment_gates_invocation_kind CHECK ((invocation_kind = ANY (ARRAY['direct'::text, 'reusable'::text]))),
    CONSTRAINT job_environment_gates_requirement CHECK ((environment_requirement_kind = ANY (ARRAY['unclassified'::text, 'none'::text, 'environment'::text]))),
    CONSTRAINT job_environment_gates_resolution_shape CHECK (((((state = 'ready'::text) AND (octet_length(resolution_digest) = 32) AND (resolved_secret_count >= 0) AND (missing_secret_count >= 0) AND (resolved_variable_count >= 0) AND (missing_variable_count >= 0)) OR ((state <> 'ready'::text) AND (resolution_digest IS NULL) AND (resolved_secret_count IS NULL) AND (missing_secret_count IS NULL) AND (resolved_variable_count IS NULL) AND (missing_variable_count IS NULL))) IS TRUE)),
    CONSTRAINT job_environment_gates_reusable_permission CHECK (((reusable_secret_permission = ANY (ARRAY['none'::text, 'explicit'::text])) AND ((invocation_kind = 'reusable'::text) OR (reusable_secret_permission = 'none'::text)))),
    CONSTRAINT job_environment_gates_revision_positive CHECK ((revision > 0)),
    CONSTRAINT job_environment_gates_source_kind CHECK ((source_kind = ANY (ARRAY['same_repository'::text, 'fork'::text, 'dependabot'::text, 'unknown'::text]))),
    CONSTRAINT job_environment_gates_state CHECK ((state = ANY (ARRAY['unclassified'::text, 'selection_pending'::text, 'waiting'::text, 'resolving'::text, 'ready'::text, 'rejected'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT job_environment_gates_time CHECK (((created_at_ms >= 0) AND (updated_at_ms >= created_at_ms)))
);

CREATE TABLE secret_policies (
    tenant_id text NOT NULL,
    secret_id uuid NOT NULL,
    secret_scope_kind text NOT NULL,
    tenant_repository_access_mode text DEFAULT 'selected_repositories'::text NOT NULL,
    minimum_event_trust text DEFAULT 'trusted'::text NOT NULL,
    allow_fork_pull_requests boolean DEFAULT false NOT NULL,
    allow_dependabot boolean DEFAULT false NOT NULL,
    reusable_workflow_mode text DEFAULT 'disabled'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    updated_by_principal_id uuid,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    CONSTRAINT secret_policies_event_trust CHECK ((minimum_event_trust = ANY (ARRAY['trusted'::text, 'untrusted'::text]))),
    CONSTRAINT secret_policies_repository_access_mode CHECK ((tenant_repository_access_mode = ANY (ARRAY['selected_repositories'::text, 'all_repositories'::text, 'scope_only'::text]))),
    CONSTRAINT secret_policies_reusable_workflow_mode CHECK ((reusable_workflow_mode = ANY (ARRAY['disabled'::text, 'explicit_only'::text]))),
    CONSTRAINT secret_policies_revision_positive CHECK ((revision > 0)),
    CONSTRAINT secret_policies_scope_access_shape CHECK ((((secret_scope_kind = 'tenant'::text) AND (tenant_repository_access_mode = ANY (ARRAY['selected_repositories'::text, 'all_repositories'::text]))) OR ((secret_scope_kind = ANY (ARRAY['repository'::text, 'environment'::text])) AND (tenant_repository_access_mode = 'scope_only'::text)))),
    CONSTRAINT secret_policies_time_monotonic CHECK ((updated_at_ms >= created_at_ms))
);

CREATE TABLE secrets (
    tenant_id text NOT NULL,
    id uuid NOT NULL,
    canonical_name text NOT NULL,
    scope_kind text NOT NULL,
    repository_id uuid,
    environment_id uuid,
    provider_id text NOT NULL,
    current_version_id uuid,
    current_version_number bigint,
    status text DEFAULT 'provisioning'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_by_principal_id uuid,
    updated_by_principal_id uuid,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    deleted_at_ms bigint,
    CONSTRAINT secrets_name_shape CHECK ((((octet_length(canonical_name) >= 1) AND (octet_length(canonical_name) <= 255)) AND (canonical_name ~ '^[A-Z_][A-Z0-9_]*$'::text) AND (canonical_name !~ '^(GITHUB_|ACTIONS_|RUNNER_|AUTOMATA_)'::text))),
    CONSTRAINT secrets_revision_positive CHECK ((revision > 0)),
    CONSTRAINT secrets_scope_kind CHECK ((scope_kind = ANY (ARRAY['tenant'::text, 'repository'::text, 'environment'::text]))),
    CONSTRAINT secrets_scope_shape CHECK (((((scope_kind = 'tenant'::text) AND (repository_id IS NULL) AND (environment_id IS NULL)) OR ((scope_kind = 'repository'::text) AND (repository_id IS NOT NULL) AND (environment_id IS NULL)) OR ((scope_kind = 'environment'::text) AND (repository_id IS NOT NULL) AND (environment_id IS NOT NULL))) IS TRUE)),
    CONSTRAINT secrets_status CHECK ((status = ANY (ARRAY['provisioning'::text, 'active'::text, 'disabled'::text, 'deleted'::text]))),
    CONSTRAINT secrets_status_shape CHECK (((((status = 'provisioning'::text) AND (current_version_id IS NULL) AND (current_version_number IS NULL) AND (deleted_at_ms IS NULL)) OR ((status = ANY (ARRAY['active'::text, 'disabled'::text])) AND (current_version_id IS NOT NULL) AND (current_version_number > 0) AND (deleted_at_ms IS NULL)) OR ((status = 'deleted'::text) AND (((current_version_id IS NULL) AND (current_version_number IS NULL)) OR ((current_version_id IS NOT NULL) AND (current_version_number > 0))) AND (deleted_at_ms >= created_at_ms))) IS TRUE)),
    CONSTRAINT secrets_time_monotonic CHECK ((updated_at_ms >= created_at_ms))
);

CREATE FUNCTION automata_secret_is_available_to_gate(target_secret secrets, target_policy secret_policies, target_gate job_environment_gates) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
SELECT (target_secret).status = 'active'
   AND (target_secret).current_version_id IS NOT NULL
   AND (target_policy).minimum_event_trust IN ('trusted', 'untrusted')
   AND ((target_policy).minimum_event_trust <> 'trusted'
        OR (target_gate).event_trust = 'trusted')
   AND ((target_gate).source_kind <> 'fork' OR (target_policy).allow_fork_pull_requests)
   AND ((target_gate).source_kind <> 'dependabot' OR (target_policy).allow_dependabot)
   AND (target_gate).source_kind <> 'unknown'
   AND (
       (target_gate).invocation_kind = 'direct'
       OR (
           (target_gate).reusable_secret_permission = 'explicit'
           AND (target_policy).reusable_workflow_mode = 'explicit_only'
           AND automata_reusable_secret_identity_chain_is_exact(
               (target_gate).run_id,
               (target_gate).invocation_id,
               (target_secret).canonical_name
           )
       )
   )
   AND (
       ((target_secret).scope_kind = 'environment'
        AND (target_secret).repository_id = (target_gate).repository_id
        AND (target_secret).environment_id = (target_gate).environment_id)
       OR ((target_secret).scope_kind = 'repository'
           AND (target_secret).repository_id = (target_gate).repository_id)
       OR ((target_secret).scope_kind = 'tenant'
           AND ((target_policy).tenant_repository_access_mode = 'all_repositories'
                OR EXISTS (
                    SELECT 1 FROM secret_repository_access AS access
                    WHERE access.tenant_id = (target_secret).tenant_id
                      AND access.secret_id = (target_secret).id
                      AND access.repository_id = (target_gate).repository_id
                )))
   );
$$;

CREATE FUNCTION automata_secret_mutation_recovery_deferred_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    mutation_row secret_version_mutations%ROWTYPE;
    recovery_row secret_mutation_recovery_outbox%ROWTYPE;
BEGIN
    SELECT * INTO mutation_row
    FROM secret_version_mutations
    WHERE tenant_id = NEW.tenant_id AND mutation_id = NEW.mutation_id;

    SELECT * INTO recovery_row
    FROM secret_mutation_recovery_outbox
    WHERE tenant_id = NEW.tenant_id AND mutation_id = NEW.mutation_id;

    IF mutation_row.mutation_id IS NULL
       OR recovery_row.mutation_id IS NULL
       OR recovery_row.created_at_ms <> mutation_row.reserved_at_ms
       OR recovery_row.next_attempt_at_ms <> mutation_row.confirmation_deadline_ms
       OR (
           mutation_row.state = 'reserved'
           AND recovery_row.status NOT IN ('pending', 'in_progress')
       )
       OR (
           mutation_row.state <> 'reserved'
           AND recovery_row.status <> 'completed'
       ) THEN
        RAISE EXCEPTION 'secret mutation recovery schedule is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_mutation_recovery_schedule_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_secret_mutation_recovery_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret mutation recovery receipts cannot be deleted'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_mutation_recovery_delete_forbidden';
END;
$$;

CREATE FUNCTION automata_secret_mutation_recovery_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    greatest_reserved_number BIGINT;
    session_revision BIGINT;
    session_principal UUID;
BEGIN
    SELECT authorization_revision, principal_id
    INTO session_revision, session_principal
    FROM human_sessions
    WHERE tenant_id = NEW.tenant_id
      AND id = NEW.reserved_by_session_id
    FOR SHARE;

    IF session_principal IS DISTINCT FROM NEW.reserved_by_principal_id
       OR session_revision IS DISTINCT FROM NEW.reserved_authorization_revision THEN
        RAISE EXCEPTION 'secret mutation reserver evidence is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_reserver_exact';
    END IF;

    SELECT max(reserved_version_number)
    INTO greatest_reserved_number
    FROM secret_version_mutations
    WHERE tenant_id = NEW.tenant_id AND secret_id = NEW.secret_id;

    IF (
        NEW.mutation_kind = 'create'
        AND (greatest_reserved_number IS NOT NULL OR NEW.reserved_version_number <> 1)
    ) OR (
        NEW.mutation_kind = 'replace'
        AND (
            greatest_reserved_number < NEW.expected_predecessor_version_number
            OR NEW.reserved_version_number IS DISTINCT FROM CASE
                WHEN greatest_reserved_number < 9223372036854775807
                    THEN greatest_reserved_number + 1
                ELSE NULL
            END
        )
    ) THEN
        RAISE EXCEPTION 'secret mutation version reservation is not the next attempt ordinal'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_reserved_version_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_mutation_recovery_operation_id(text, uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
WITH raw(bytes) AS (
    SELECT substring(
        sha256(
            convert_to('automata.store.secret-mutation-recovery.v1', 'UTF8')
            || decode('00', 'hex')
            || int8send(octet_length(convert_to($1, 'UTF8'))::BIGINT)
            || convert_to($1, 'UTF8')
            || uuid_send($2)
        )
        FROM 1 FOR 16
    )
), shaped(bytes) AS (
    SELECT set_byte(
        set_byte(bytes, 6, (get_byte(bytes, 6) & 15) | 128),
        8,
        (get_byte(bytes, 8) & 63) | 128
    )
    FROM raw
), encoded(hex) AS (
    SELECT encode(bytes, 'hex') FROM shaped
)
SELECT (
    substring(hex FROM 1 FOR 8) || '-' ||
    substring(hex FROM 9 FOR 4) || '-' ||
    substring(hex FROM 13 FOR 4) || '-' ||
    substring(hex FROM 17 FOR 4) || '-' ||
    substring(hex FROM 21 FOR 12)
)::UUID
FROM encoded
$_$;

CREATE FUNCTION automata_secret_mutation_recovery_transition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    mutation_state TEXT;
    mutation_completion TEXT;
    mutation_reason TEXT;
    mutation_completed_at BIGINT;
    expected_resolution TEXT;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'pending'
           OR NEW.attempts <> 0
           OR NEW.claim_generation <> 0
           OR NEW.locked_by IS NOT NULL
           OR NEW.locked_at_ms IS NOT NULL
           OR NEW.completed_by IS NOT NULL
           OR NEW.completed_claim_generation IS NOT NULL
           OR NEW.completed_locked_at_ms IS NOT NULL
           OR NEW.resolution IS NOT NULL
           OR NEW.completed_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'secret mutation recovery must begin pending'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_mutation_recovery_initial_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.sequence IS DISTINCT FROM OLD.sequence
       OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.mutation_id IS DISTINCT FROM OLD.mutation_id
       OR NEW.next_attempt_at_ms IS DISTINCT FROM OLD.next_attempt_at_ms
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms THEN
        RAISE EXCEPTION 'secret mutation recovery identity and timing are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_mutation_recovery_identity_immutable';
    END IF;

    IF OLD.status = 'pending' AND NEW.status = 'in_progress' THEN
        IF OLD.attempts <> 0
           OR OLD.claim_generation <> 0
           OR NEW.attempts <> 1
           OR NEW.claim_generation <> 1
           OR octet_length(NEW.locked_by) NOT BETWEEN 1 AND 255
           OR NEW.locked_by ~ '[[:cntrl:]]'
           OR NEW.locked_at_ms < OLD.next_attempt_at_ms
           OR NEW.completed_by IS NOT NULL
           OR NEW.completed_claim_generation IS NOT NULL
           OR NEW.completed_locked_at_ms IS NOT NULL
           OR NEW.resolution IS NOT NULL
           OR NEW.completed_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'secret mutation recovery initial claim is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_mutation_recovery_claim_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'in_progress' AND NEW.status = 'in_progress' THEN
        IF NEW.attempts IS DISTINCT FROM OLD.attempts
           OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation + 1
           OR octet_length(NEW.locked_by) NOT BETWEEN 1 AND 255
           OR NEW.locked_by ~ '[[:cntrl:]]'
           OR NEW.locked_at_ms <= OLD.locked_at_ms
           OR NEW.completed_by IS DISTINCT FROM OLD.completed_by
           OR NEW.completed_claim_generation IS DISTINCT FROM OLD.completed_claim_generation
           OR NEW.completed_locked_at_ms IS DISTINCT FROM OLD.completed_locked_at_ms
           OR NEW.resolution IS DISTINCT FROM OLD.resolution
           OR NEW.completed_at_ms IS DISTINCT FROM OLD.completed_at_ms THEN
            RAISE EXCEPTION 'secret mutation recovery takeover is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_mutation_recovery_takeover_exact';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status IN ('pending', 'in_progress') AND NEW.status = 'completed' THEN
        SELECT state, completion_kind, terminal_reason, confirmed_at_ms
        INTO mutation_state, mutation_completion, mutation_reason, mutation_completed_at
        FROM secret_version_mutations
        WHERE tenant_id = OLD.tenant_id AND mutation_id = OLD.mutation_id;

        IF mutation_state IS NULL OR mutation_state = 'reserved'
           OR NEW.attempts IS DISTINCT FROM OLD.attempts
           OR NEW.claim_generation IS DISTINCT FROM OLD.claim_generation
           OR NEW.locked_by IS NOT NULL
           OR NEW.locked_at_ms IS NOT NULL
           OR NEW.completed_at_ms IS DISTINCT FROM mutation_completed_at THEN
            RAISE EXCEPTION 'secret mutation recovery completion has no exact terminal receipt'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_mutation_recovery_completion_exact';
        END IF;

        IF mutation_completion = 'reservation_expired' THEN
            expected_resolution := CASE mutation_reason
                WHEN 'reservation_expired_no_stage' THEN 'expired_without_stage'
                WHEN 'reservation_expired_staged' THEN 'expired_with_cleanup'
                ELSE NULL
            END;
            IF OLD.status <> 'in_progress'
               OR expected_resolution IS NULL
               OR NEW.resolution IS DISTINCT FROM expected_resolution
               OR NEW.completed_by IS DISTINCT FROM OLD.locked_by
               OR NEW.completed_claim_generation IS DISTINCT FROM OLD.claim_generation
               OR NEW.completed_locked_at_ms IS DISTINCT FROM OLD.locked_at_ms THEN
                RAISE EXCEPTION 'secret mutation recovery expiry is not fence-bound'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_mutation_recovery_expiry_fence_exact';
            END IF;
        ELSIF NEW.resolution IS DISTINCT FROM 'human_terminal'
              OR NEW.completed_by IS NOT NULL
              OR NEW.completed_claim_generation IS NOT NULL
              OR NEW.completed_locked_at_ms IS NOT NULL THEN
            RAISE EXCEPTION 'human terminal recovery closure is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_mutation_recovery_human_terminal_exact';
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'invalid secret mutation recovery transition'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_mutation_recovery_transition_exact';
END;
$$;

CREATE FUNCTION automata_secret_mutation_terminal_deferred_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_row secrets%ROWTYPE;
    lifecycle_status TEXT;
BEGIN
    IF NEW.state <> 'cancelled' THEN
        RETURN NULL;
    END IF;

    SELECT * INTO secret_row
    FROM secrets
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id;

    IF NEW.completion_kind = 'system_cancelled' THEN
        IF secret_row.status IS DISTINCT FROM 'deleted' THEN
            RAISE EXCEPTION 'deletion cancellation committed without deleted descriptor'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_delete_terminal';
        END IF;
    ELSIF NEW.completion_kind = 'reservation_expired' THEN
        IF NEW.abandoned_version_id IS NOT NULL THEN
            SELECT status INTO lifecycle_status
            FROM secret_version_lifecycle
            WHERE tenant_id = NEW.tenant_id
              AND secret_version_id = NEW.abandoned_version_id;
            IF lifecycle_status NOT IN ('destroy_pending', 'destroyed') THEN
                RAISE EXCEPTION 'expired staged candidate was not handed to erasure'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_expiry_cleanup';
            END IF;
        END IF;

        IF NEW.mutation_kind = 'create' THEN
            IF secret_row.status IS DISTINCT FROM 'deleted'
               OR secret_row.current_version_id IS NOT NULL
               OR secret_row.current_version_number IS NOT NULL THEN
                RAISE EXCEPTION 'expired creation retained a live descriptor'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_expiry_descriptor';
            END IF;
        ELSIF secret_row.status NOT IN ('active', 'disabled')
              OR (
                  NEW.abandoned_version_id IS NOT NULL
                  AND secret_row.current_version_id = NEW.abandoned_version_id
              ) THEN
            RAISE EXCEPTION 'expired replacement changed the logical head'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_expiry_descriptor';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_secret_provider_configuration_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM secret_provider_configuration_envelope_heads
        WHERE tenant_id = OLD.tenant_id
          AND provider_id = OLD.provider_id
          AND envelope_generation = OLD.envelope_generation
    ) THEN
        RAISE EXCEPTION 'current provider configuration envelope cannot be removed'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_provider_configuration_envelopes_current';
    END IF;
    RETURN OLD;
END;
$$;

CREATE FUNCTION automata_secret_provider_configuration_envelopes_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret provider configuration envelopes are immutable'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_provider_configuration_envelopes_immutable';
END;
$$;

CREATE FUNCTION automata_secret_provider_lease_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    lease_status TEXT;
BEGIN
    SELECT status
    INTO STRICT lease_status
    FROM secret_provider_leases
    WHERE tenant_id = OLD.tenant_id
      AND id = OLD.provider_lease_record_id;

    IF lease_status NOT IN ('revoked', 'expired') THEN
        RAISE EXCEPTION 'provider lease handles may only be removed when terminal'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_provider_lease_envelopes_terminal_lease';
    END IF;
    RETURN OLD;
END;
$$;

CREATE FUNCTION automata_secret_provider_locator_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_status TEXT;
BEGIN
    SELECT status
    INTO STRICT secret_status
    FROM secrets
    WHERE tenant_id = OLD.tenant_id
      AND id = OLD.secret_id;

    IF secret_status <> 'deleted' THEN
        RAISE EXCEPTION 'provider locators may only be removed for deleted secrets'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_provider_locator_envelopes_deleted_secret';
    END IF;
    RETURN OLD;
END;
$$;

CREATE FUNCTION automata_secret_provider_reference_envelopes_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret provider reference envelopes are immutable'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_provider_reference_envelopes_immutable';
END;
$$;

CREATE FUNCTION automata_secret_version_deferred_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact_stage_count BIGINT;
BEGIN
    IF NEW.provider_id <> 'builtin'
       OR NEW.storage_kind <> 'built_in_ciphertext' THEN
        RAISE EXCEPTION 'secret versions require the composed built-in mutation path'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_versions_mutation_stage_exact';
    END IF;

    SELECT count(*) INTO exact_stage_count
    FROM secret_version_lifecycle AS lifecycle
    JOIN secret_version_mutations AS mutation
      ON mutation.tenant_id = lifecycle.tenant_id
     AND mutation.mutation_id = lifecycle.mutation_id
     AND mutation.secret_id = lifecycle.secret_id
     AND mutation.provider_id = lifecycle.provider_id
    WHERE lifecycle.tenant_id = NEW.tenant_id
      AND lifecycle.secret_version_id = NEW.id
      AND lifecycle.secret_id = NEW.secret_id
      AND lifecycle.version_number = NEW.version_number
      AND lifecycle.provider_id = NEW.provider_id
      AND mutation.provider_create_request_id = NEW.create_request_id;

    IF exact_stage_count <> 1 THEN
        RAISE EXCEPTION 'secret version has no exact mutation stage'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_versions_mutation_stage_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_secret_version_envelope_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    lifecycle_status TEXT;
BEGIN
    SELECT status
    INTO STRICT lifecycle_status
    FROM secret_version_lifecycle
    WHERE tenant_id = OLD.tenant_id
      AND secret_version_id = OLD.secret_version_id;

    IF lifecycle_status <> 'destroy_pending' THEN
        RAISE EXCEPTION 'secret version envelopes may only be cryptographically destroyed'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_envelopes_destroy_pending';
    END IF;
    RETURN OLD;
END;
$$;

CREATE FUNCTION automata_secret_version_envelopes_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret version envelopes are immutable'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_version_envelopes_immutable';
END;
$$;

CREATE FUNCTION automata_secret_version_lifecycle_deferred_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_row secrets%ROWTYPE;
    mutation_row secret_version_mutations%ROWTYPE;
    builtin_head_count BIGINT;
    external_reference_count BIGINT;
    expired_cleanup BOOLEAN;
BEGIN
    SELECT * INTO secret_row
    FROM secrets
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id;
    SELECT * INTO mutation_row
    FROM secret_version_mutations
    WHERE tenant_id = NEW.tenant_id AND mutation_id = NEW.mutation_id;

    SELECT count(*) INTO builtin_head_count
    FROM secret_version_envelope_heads AS head
    JOIN secret_version_envelopes AS envelope
      ON envelope.tenant_id = head.tenant_id
     AND envelope.secret_version_id = head.secret_version_id
     AND envelope.envelope_generation = head.envelope_generation
    WHERE head.tenant_id = NEW.tenant_id
      AND head.secret_version_id = NEW.secret_version_id;

    SELECT
        (SELECT count(*) FROM secret_provider_locator_envelopes
         WHERE tenant_id = NEW.tenant_id AND secret_id = NEW.secret_id)
      + (SELECT count(*) FROM secret_provider_locator_envelope_heads
         WHERE tenant_id = NEW.tenant_id AND secret_id = NEW.secret_id)
      + (SELECT count(*) FROM secret_provider_version_envelopes
         WHERE tenant_id = NEW.tenant_id
           AND secret_version_id = NEW.secret_version_id)
      + (SELECT count(*) FROM secret_provider_version_envelope_heads
         WHERE tenant_id = NEW.tenant_id
           AND secret_version_id = NEW.secret_version_id)
    INTO external_reference_count;

    IF secret_row.id IS NULL
       OR mutation_row.mutation_id IS NULL
       OR mutation_row.secret_id <> NEW.secret_id
       OR mutation_row.provider_id <> NEW.provider_id
       OR mutation_row.reserved_version_number <> NEW.version_number
       OR secret_row.scope_kind <> mutation_row.scope_kind
       OR secret_row.repository_id IS DISTINCT FROM mutation_row.repository_id
       OR secret_row.environment_id IS DISTINCT FROM mutation_row.environment_id
       OR secret_row.canonical_name <> mutation_row.canonical_name
       OR builtin_head_count <> (CASE WHEN NEW.status = 'destroyed' THEN 0 ELSE 1 END)
       OR external_reference_count <> 0 THEN
        RAISE EXCEPTION 'secret lifecycle lost its exact encrypted mutation join'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_deferred_exact';
    END IF;

    IF NEW.status = 'staged' THEN
        IF mutation_row.state <> 'reserved'
           OR secret_row.revision <> mutation_row.reserved_secret_revision
           OR secret_row.current_version_id IS DISTINCT FROM mutation_row.expected_predecessor_version_id
           OR secret_row.current_version_number IS DISTINCT FROM mutation_row.expected_predecessor_version_number THEN
            RAISE EXCEPTION 'staged lifecycle committed without its reservation'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_lifecycle_deferred_state';
        END IF;
    ELSIF NEW.status IN ('active', 'disabled') THEN
        IF mutation_row.state <> 'confirmed'
           OR mutation_row.committed_version_id IS DISTINCT FROM NEW.secret_version_id
           OR mutation_row.committed_version_number IS DISTINCT FROM NEW.version_number
           OR mutation_row.confirmed_secret_revision <> mutation_row.reserved_secret_revision + 1
           OR secret_row.status IS DISTINCT FROM NEW.status
           OR secret_row.current_version_id IS DISTINCT FROM NEW.secret_version_id
           OR secret_row.current_version_number IS DISTINCT FROM NEW.version_number THEN
            RAISE EXCEPTION 'active lifecycle committed without its exact receipt'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_lifecycle_deferred_state';
        END IF;
    ELSIF NEW.status = 'superseded' THEN
        IF mutation_row.state <> 'superseded'
           OR mutation_row.committed_version_id IS DISTINCT FROM NEW.secret_version_id
           OR mutation_row.committed_version_number IS DISTINCT FROM NEW.version_number
           OR mutation_row.terminal_reason NOT IN (
                'applied_then_superseded', 'applied_then_deleted'
           )
           OR (
               mutation_row.terminal_reason = 'applied_then_superseded'
               AND (
                   secret_row.status NOT IN ('active', 'disabled')
                   OR secret_row.current_version_number <= NEW.version_number
               )
           )
           OR (
               mutation_row.terminal_reason = 'applied_then_deleted'
               AND secret_row.status <> 'deleted'
           ) THEN
            RAISE EXCEPTION 'superseded lifecycle committed without its exact receipt'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_lifecycle_deferred_state';
        END IF;
    ELSIF NEW.status IN ('destroy_pending', 'destroyed') THEN
        expired_cleanup := (
            mutation_row.state = 'cancelled'
            AND mutation_row.completion_kind = 'reservation_expired'
            AND mutation_row.terminal_reason = 'reservation_expired_staged'
            AND mutation_row.abandoned_version_id = NEW.secret_version_id
            AND mutation_row.abandoned_version_number = NEW.version_number
            AND (
                (
                    mutation_row.mutation_kind = 'create'
                    AND secret_row.status = 'deleted'
                    AND secret_row.current_version_id IS NULL
                    AND secret_row.current_version_number IS NULL
                ) OR (
                    mutation_row.mutation_kind = 'replace'
                    AND secret_row.status IN ('active', 'disabled')
                    AND secret_row.current_version_id IS DISTINCT FROM NEW.secret_version_id
                )
            )
        );
        IF NOT (
            (
                secret_row.status = 'deleted'
                AND (
                    (
                        mutation_row.state = 'cancelled'
                        AND mutation_row.completion_kind = 'system_cancelled'
                        AND mutation_row.terminal_reason = 'secret_deleted'
                    ) OR (
                        mutation_row.state = 'superseded'
                        AND mutation_row.completion_kind = 'builtin_created'
                        AND mutation_row.terminal_reason IN (
                            'applied_then_superseded', 'applied_then_deleted'
                        )
                    )
                )
            ) OR expired_cleanup
        ) THEN
            RAISE EXCEPTION 'destroy lifecycle committed without exact terminalization'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_lifecycle_deferred_state';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_secret_version_lifecycle_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret version lifecycle rows are append-only'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_version_lifecycle_append_only';
END;
$$;

CREATE FUNCTION automata_secret_version_lifecycle_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_row secrets%ROWTYPE;
    mutation_row secret_version_mutations%ROWTYPE;
    version_row secret_versions%ROWTYPE;
    predecessor_status TEXT;
    predecessor_receipt_count BIGINT;
BEGIN
    IF NEW.mutation_id IS NULL OR NEW.status <> 'staged' THEN
        RAISE EXCEPTION 'new secret versions must begin as a staged mutation candidate'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_initial_staged';
    END IF;

    SELECT * INTO secret_row
    FROM secrets
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id
    FOR UPDATE;

    SELECT * INTO mutation_row
    FROM secret_version_mutations
    WHERE tenant_id = NEW.tenant_id AND mutation_id = NEW.mutation_id
    FOR SHARE;

    SELECT * INTO version_row
    FROM secret_versions
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_version_id
    FOR SHARE;

    IF secret_row.id IS NULL
       OR mutation_row.mutation_id IS NULL
       OR version_row.id IS NULL
       OR mutation_row.state <> 'reserved'
       OR mutation_row.secret_id <> NEW.secret_id
       OR mutation_row.provider_id <> NEW.provider_id
       OR mutation_row.reserved_version_number <> NEW.version_number
       OR mutation_row.provider_create_request_id <> version_row.create_request_id
       OR version_row.secret_id <> NEW.secret_id
       OR version_row.version_number <> NEW.version_number
       OR version_row.provider_id <> NEW.provider_id
       OR version_row.storage_kind <> 'built_in_ciphertext'
       OR secret_row.scope_kind <> mutation_row.scope_kind
       OR secret_row.repository_id IS DISTINCT FROM mutation_row.repository_id
       OR secret_row.environment_id IS DISTINCT FROM mutation_row.environment_id
       OR secret_row.canonical_name <> mutation_row.canonical_name
       OR secret_row.provider_id <> mutation_row.provider_id THEN
        RAISE EXCEPTION 'staged secret version is not joined to its exact intent'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_staged_intent_exact';
    END IF;

    IF mutation_row.mutation_kind = 'create' THEN
        IF NEW.version_number <> 1
           OR secret_row.status <> 'provisioning'
           OR secret_row.revision <> mutation_row.reserved_secret_revision
           OR secret_row.current_version_id IS NOT NULL
           OR secret_row.current_version_number IS NOT NULL THEN
            RAISE EXCEPTION 'staged creation candidate has a stale descriptor'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_lifecycle_staged_head';
        END IF;
    ELSE
        SELECT status INTO predecessor_status
        FROM secret_version_lifecycle
        WHERE tenant_id = NEW.tenant_id
          AND secret_version_id = mutation_row.expected_predecessor_version_id
        FOR SHARE;

        SELECT count(*) INTO predecessor_receipt_count
        FROM secret_version_mutations
        WHERE tenant_id = NEW.tenant_id
          AND secret_id = NEW.secret_id
          AND state = 'confirmed'
          AND completion_kind = 'builtin_created'
          AND committed_version_id = mutation_row.expected_predecessor_version_id
          AND committed_version_number = mutation_row.expected_predecessor_version_number;

        IF secret_row.status <> 'active'
           OR secret_row.revision <> mutation_row.reserved_secret_revision
           OR secret_row.current_version_id IS DISTINCT FROM mutation_row.expected_predecessor_version_id
           OR secret_row.current_version_number IS DISTINCT FROM mutation_row.expected_predecessor_version_number
           OR NEW.version_number <> mutation_row.reserved_version_number
           OR NEW.version_number <= mutation_row.expected_predecessor_version_number
           OR predecessor_status IS DISTINCT FROM 'active'
           OR predecessor_receipt_count <> 1 THEN
            RAISE EXCEPTION 'staged replacement candidate has a stale predecessor'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_lifecycle_staged_head';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_version_lifecycle_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_row secrets%ROWTYPE;
    mutation_row secret_version_mutations%ROWTYPE;
    cleanup_is_valid BOOLEAN;
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.secret_version_id IS DISTINCT FROM OLD.secret_version_id
       OR NEW.secret_id IS DISTINCT FROM OLD.secret_id
       OR NEW.version_number IS DISTINCT FROM OLD.version_number
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.mutation_id IS DISTINCT FROM OLD.mutation_id THEN
        RAISE EXCEPTION 'secret version lifecycle identity is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_identity_immutable';
    END IF;
    IF NEW.revision <> OLD.revision + 1
       OR NEW.changed_at_ms < OLD.changed_at_ms THEN
        RAISE EXCEPTION 'secret version lifecycle updates require monotonic CAS'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_cas';
    END IF;
    IF OLD.destroy_request_id IS NOT NULL
       AND NEW.destroy_request_id IS DISTINCT FROM OLD.destroy_request_id THEN
        RAISE EXCEPTION 'secret version destroy request identity is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_destroy_request_immutable';
    END IF;
    IF NOT (
        (OLD.status = 'staged' AND NEW.status IN ('active', 'destroy_pending'))
        OR (OLD.status = 'active' AND NEW.status IN ('superseded', 'disabled', 'destroy_pending'))
        OR (OLD.status = 'superseded' AND NEW.status IN ('disabled', 'destroy_pending'))
        OR (OLD.status = 'disabled' AND NEW.status IN ('active', 'destroy_pending'))
        OR (OLD.status = 'destroy_pending' AND NEW.status = 'destroyed')
    ) THEN
        RAISE EXCEPTION 'invalid secret version lifecycle transition'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_transition';
    END IF;

    IF OLD.status = 'staged' THEN
        SELECT * INTO secret_row
        FROM secrets
        WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id
        FOR UPDATE;
        SELECT * INTO mutation_row
        FROM secret_version_mutations
        WHERE tenant_id = NEW.tenant_id AND mutation_id = NEW.mutation_id
        FOR SHARE;

        IF NEW.status = 'active' THEN
            IF mutation_row.state <> 'reserved'
               OR NEW.version_number <> mutation_row.reserved_version_number
               OR secret_row.status <> (CASE mutation_row.mutation_kind
                   WHEN 'create' THEN 'provisioning' ELSE 'active' END)
               OR secret_row.revision <> mutation_row.reserved_secret_revision
               OR secret_row.current_version_id IS DISTINCT FROM mutation_row.expected_predecessor_version_id
               OR secret_row.current_version_number IS DISTINCT FROM mutation_row.expected_predecessor_version_number THEN
                RAISE EXCEPTION 'staged candidate promotion lost its reservation CAS'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_lifecycle_staged_promotion';
            END IF;
        ELSE
            cleanup_is_valid := (
                mutation_row.state = 'cancelled'
                AND (
                    (
                        mutation_row.completion_kind = 'system_cancelled'
                        AND mutation_row.terminal_reason = 'secret_deleted'
                        AND secret_row.status = 'deleted'
                    ) OR (
                        mutation_row.completion_kind = 'reservation_expired'
                        AND mutation_row.terminal_reason = 'reservation_expired_staged'
                        AND mutation_row.abandoned_version_id = NEW.secret_version_id
                        AND mutation_row.abandoned_version_number = NEW.version_number
                        AND (
                            (
                                mutation_row.mutation_kind = 'create'
                                AND secret_row.status = 'deleted'
                                AND secret_row.current_version_id IS NULL
                                AND secret_row.current_version_number IS NULL
                            ) OR (
                                mutation_row.mutation_kind = 'replace'
                                AND secret_row.status IN ('active', 'disabled')
                                AND secret_row.current_version_id IS DISTINCT FROM NEW.secret_version_id
                            )
                        )
                    )
                )
            );
            IF cleanup_is_valid IS NOT TRUE THEN
                RAISE EXCEPTION 'staged candidate cleanup requires exact cancellation'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_lifecycle_staged_cleanup';
            END IF;
        END IF;
    END IF;

    IF NEW.status = 'destroyed'
       AND (
           EXISTS (
               SELECT 1 FROM secret_version_envelopes
               WHERE tenant_id = NEW.tenant_id
                 AND secret_version_id = NEW.secret_version_id
           )
           OR EXISTS (
               SELECT 1 FROM secret_version_envelope_heads
               WHERE tenant_id = NEW.tenant_id
                 AND secret_version_id = NEW.secret_version_id
           )
           OR EXISTS (
               SELECT 1 FROM secret_provider_version_envelopes
               WHERE tenant_id = NEW.tenant_id
                 AND secret_version_id = NEW.secret_version_id
           )
           OR EXISTS (
               SELECT 1 FROM secret_provider_version_envelope_heads
               WHERE tenant_id = NEW.tenant_id
                 AND secret_version_id = NEW.secret_version_id
           )
       ) THEN
        RAISE EXCEPTION 'cryptographic material must be removed before destroy completes'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_lifecycle_crypto_destroyed';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_version_mutation_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret version mutation receipts are append-only'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_version_mutations_append_only';
END;
$$;

CREATE FUNCTION automata_secret_version_mutation_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_row secrets%ROWTYPE;
    predecessor_lifecycle TEXT;
    predecessor_receipt_count BIGINT;
BEGIN
    IF NEW.state <> 'reserved' OR NEW.revision <> 1 THEN
        RAISE EXCEPTION 'secret version mutations must begin reserved at revision one'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_initial_state';
    END IF;

    SELECT * INTO secret_row
    FROM secrets
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id
    FOR UPDATE;
    IF NOT FOUND
       OR secret_row.scope_kind <> NEW.scope_kind
       OR secret_row.repository_id IS DISTINCT FROM NEW.repository_id
       OR secret_row.environment_id IS DISTINCT FROM NEW.environment_id
       OR secret_row.canonical_name <> NEW.canonical_name
       OR secret_row.provider_id <> NEW.provider_id THEN
        RAISE EXCEPTION 'secret version mutation descriptor is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_descriptor_exact';
    END IF;

    IF NEW.mutation_kind = 'create' THEN
        IF secret_row.status <> 'provisioning'
           OR secret_row.revision <> 1
           OR secret_row.current_version_id IS NOT NULL
           OR secret_row.current_version_number IS NOT NULL THEN
            RAISE EXCEPTION 'secret creation mutation does not name a fresh descriptor'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_create_head';
        END IF;
    ELSE
        IF secret_row.status <> 'active'
           OR secret_row.revision <> NEW.expected_secret_revision
           OR secret_row.revision <> NEW.reserved_secret_revision
           OR secret_row.current_version_id IS DISTINCT FROM NEW.expected_predecessor_version_id
           OR secret_row.current_version_number IS DISTINCT FROM NEW.expected_predecessor_version_number THEN
            RAISE EXCEPTION 'secret replacement mutation predecessor is not current'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_replace_head';
        END IF;

        SELECT status INTO predecessor_lifecycle
        FROM secret_version_lifecycle
        WHERE tenant_id = NEW.tenant_id
          AND secret_version_id = NEW.expected_predecessor_version_id
          AND secret_id = NEW.secret_id
          AND version_number = NEW.expected_predecessor_version_number
          AND provider_id = NEW.provider_id
        FOR SHARE;

        SELECT count(*) INTO predecessor_receipt_count
        FROM secret_version_mutations
        WHERE tenant_id = NEW.tenant_id
          AND secret_id = NEW.secret_id
          AND provider_id = NEW.provider_id
          AND state = 'confirmed'
          AND completion_kind = 'builtin_created'
          AND committed_version_id = NEW.expected_predecessor_version_id
          AND committed_version_number = NEW.expected_predecessor_version_number
          AND confirmed_secret_revision = reserved_secret_revision + 1;

        IF predecessor_lifecycle IS DISTINCT FROM 'active'
           OR predecessor_receipt_count <> 1 THEN
            RAISE EXCEPTION 'secret replacement predecessor is not confirmed and active'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_predecessor_confirmed';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_version_mutation_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    secret_row secrets%ROWTYPE;
    winner_row secret_versions%ROWTYPE;
    winner_lifecycle secret_version_lifecycle%ROWTYPE;
    builtin_head_count BIGINT;
    external_reference_count BIGINT;
    confirmer_principal UUID;
    confirmer_revision BIGINT;
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.mutation_id IS DISTINCT FROM OLD.mutation_id
       OR NEW.secret_id IS DISTINCT FROM OLD.secret_id
       OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.canonical_name IS DISTINCT FROM OLD.canonical_name
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.requested_provider_id IS DISTINCT FROM OLD.requested_provider_id
       OR NEW.mutation_kind IS DISTINCT FROM OLD.mutation_kind
       OR NEW.expected_secret_revision IS DISTINCT FROM OLD.expected_secret_revision
       OR NEW.reserved_secret_revision IS DISTINCT FROM OLD.reserved_secret_revision
       OR NEW.reserved_version_number IS DISTINCT FROM OLD.reserved_version_number
       OR NEW.confirmation_deadline_ms IS DISTINCT FROM OLD.confirmation_deadline_ms
       OR NEW.expected_predecessor_version_id IS DISTINCT FROM OLD.expected_predecessor_version_id
       OR NEW.expected_predecessor_version_number IS DISTINCT FROM OLD.expected_predecessor_version_number
       OR NEW.provider_create_request_id IS DISTINCT FROM OLD.provider_create_request_id
       OR NEW.reserved_by_principal_id IS DISTINCT FROM OLD.reserved_by_principal_id
       OR NEW.reserved_by_session_id IS DISTINCT FROM OLD.reserved_by_session_id
       OR NEW.reserved_authorization_revision IS DISTINCT FROM OLD.reserved_authorization_revision
       OR NEW.reserved_at_ms IS DISTINCT FROM OLD.reserved_at_ms THEN
        RAISE EXCEPTION 'secret version mutation intent is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_intent_immutable';
    END IF;

    IF NEW.revision <> OLD.revision + 1 THEN
        RAISE EXCEPTION 'secret version mutation updates require exact CAS'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_revision_cas';
    END IF;

    IF NOT (
        (OLD.state = 'reserved' AND NEW.state IN ('confirmed', 'cancelled'))
        OR (OLD.state = 'confirmed' AND NEW.state = 'superseded')
    ) THEN
        RAISE EXCEPTION 'invalid secret version mutation transition'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_transition';
    END IF;

    IF OLD.state = 'confirmed' AND (
        NEW.completion_kind IS DISTINCT FROM OLD.completion_kind
        OR NEW.committed_version_id IS DISTINCT FROM OLD.committed_version_id
        OR NEW.committed_version_number IS DISTINCT FROM OLD.committed_version_number
        OR NEW.confirmed_secret_revision IS DISTINCT FROM OLD.confirmed_secret_revision
        OR NEW.confirmed_by_principal_id IS DISTINCT FROM OLD.confirmed_by_principal_id
        OR NEW.confirmed_by_session_id IS DISTINCT FROM OLD.confirmed_by_session_id
        OR NEW.confirmed_authorization_revision IS DISTINCT FROM OLD.confirmed_authorization_revision
        OR NEW.confirmed_at_ms IS DISTINCT FROM OLD.confirmed_at_ms
        OR NEW.terminal_actor_kind IS DISTINCT FROM OLD.terminal_actor_kind
        OR NEW.expiration_authority IS DISTINCT FROM OLD.expiration_authority
        OR NEW.abandoned_version_id IS DISTINCT FROM OLD.abandoned_version_id
        OR NEW.abandoned_version_number IS DISTINCT FROM OLD.abandoned_version_number
    ) THEN
        RAISE EXCEPTION 'confirmed secret version receipt is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_receipt_immutable';
    END IF;

    IF OLD.state = 'reserved' AND NEW.terminal_actor_kind = 'human' THEN
        SELECT principal_id, authorization_revision
        INTO confirmer_principal, confirmer_revision
        FROM human_sessions
        WHERE tenant_id = NEW.tenant_id
          AND id = NEW.confirmed_by_session_id
        FOR SHARE;
        IF confirmer_principal IS DISTINCT FROM NEW.confirmed_by_principal_id
           OR confirmer_revision IS DISTINCT FROM NEW.confirmed_authorization_revision THEN
            RAISE EXCEPTION 'secret mutation confirmer evidence is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_confirmer_exact';
        END IF;
    END IF;

    SELECT * INTO secret_row
    FROM secrets
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id
    FOR UPDATE;

    IF secret_row.id IS NULL
       OR secret_row.scope_kind <> NEW.scope_kind
       OR secret_row.repository_id IS DISTINCT FROM NEW.repository_id
       OR secret_row.environment_id IS DISTINCT FROM NEW.environment_id
       OR secret_row.canonical_name <> NEW.canonical_name
       OR secret_row.provider_id <> NEW.provider_id THEN
        RAISE EXCEPTION 'secret version mutation lost its exact descriptor'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_version_mutations_descriptor_exact';
    END IF;

    IF NEW.completion_kind = 'builtin_created' THEN
        IF NEW.provider_id <> 'builtin'
           OR NEW.committed_version_id IS NULL
           OR NEW.committed_version_id =
              '00000000-0000-0000-0000-000000000000'::UUID THEN
            RAISE EXCEPTION 'built-in mutation receipt has no exact winner'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_winner_exact';
        END IF;

        SELECT * INTO winner_row
        FROM secret_versions
        WHERE tenant_id = NEW.tenant_id
          AND provider_id = NEW.provider_id
          AND create_request_id = NEW.provider_create_request_id
        FOR SHARE;
        SELECT * INTO winner_lifecycle
        FROM secret_version_lifecycle
        WHERE tenant_id = NEW.tenant_id
          AND secret_version_id = NEW.committed_version_id
        FOR SHARE;

        SELECT count(*) INTO builtin_head_count
        FROM secret_version_envelope_heads AS head
        JOIN secret_version_envelopes AS envelope
          ON envelope.tenant_id = head.tenant_id
         AND envelope.secret_version_id = head.secret_version_id
         AND envelope.envelope_generation = head.envelope_generation
        WHERE head.tenant_id = NEW.tenant_id
          AND head.secret_version_id = NEW.committed_version_id;

        SELECT
            (SELECT count(*) FROM secret_provider_locator_envelopes
             WHERE tenant_id = NEW.tenant_id AND secret_id = NEW.secret_id)
          + (SELECT count(*) FROM secret_provider_locator_envelope_heads
             WHERE tenant_id = NEW.tenant_id AND secret_id = NEW.secret_id)
          + (SELECT count(*) FROM secret_provider_version_envelopes
             WHERE tenant_id = NEW.tenant_id
               AND secret_version_id = NEW.committed_version_id)
          + (SELECT count(*) FROM secret_provider_version_envelope_heads
             WHERE tenant_id = NEW.tenant_id
               AND secret_version_id = NEW.committed_version_id)
        INTO external_reference_count;

        IF winner_row.id IS NULL
           OR winner_row.id IS DISTINCT FROM NEW.committed_version_id
           OR winner_row.secret_id <> NEW.secret_id
           OR winner_row.version_number IS DISTINCT FROM NEW.reserved_version_number
           OR NEW.committed_version_number IS DISTINCT FROM NEW.reserved_version_number
           OR winner_row.storage_kind <> 'built_in_ciphertext'
           OR winner_lifecycle.secret_version_id IS NULL
           OR winner_lifecycle.mutation_id IS DISTINCT FROM NEW.mutation_id
           OR builtin_head_count <> 1
           OR external_reference_count <> 0 THEN
            RAISE EXCEPTION 'secret version mutation winner is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_winner_exact';
        END IF;

        IF NEW.mutation_kind = 'create' THEN
            IF winner_row.version_number <> 1 THEN
                RAISE EXCEPTION 'secret creation winner has a predecessor'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_winner_predecessor';
            END IF;
        ELSIF winner_row.version_number <= NEW.expected_predecessor_version_number THEN
            RAISE EXCEPTION 'secret replacement winner has the wrong predecessor'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_winner_predecessor';
        END IF;

        IF NEW.state = 'confirmed' THEN
            IF secret_row.status <> 'active'
               OR secret_row.current_version_id IS DISTINCT FROM winner_row.id
               OR secret_row.current_version_number IS DISTINCT FROM winner_row.version_number
               OR secret_row.revision <> NEW.reserved_secret_revision + 1
               OR NEW.confirmed_secret_revision <> NEW.reserved_secret_revision + 1
               OR winner_lifecycle.status <> 'active' THEN
                RAISE EXCEPTION 'confirmed mutation winner is not current'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_winner_head';
            END IF;
        ELSIF NEW.terminal_reason = 'applied_then_superseded' THEN
            IF secret_row.status NOT IN ('active', 'disabled')
               OR secret_row.current_version_number <= winner_row.version_number
               OR winner_lifecycle.status <> 'superseded' THEN
                RAISE EXCEPTION 'superseded mutation winner has the wrong head'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_winner_head';
            END IF;
        ELSIF NEW.terminal_reason = 'applied_then_deleted' THEN
            IF secret_row.status <> 'deleted'
               OR winner_lifecycle.status NOT IN (
                    'active', 'superseded', 'disabled',
                    'destroy_pending', 'destroyed'
               ) THEN
                RAISE EXCEPTION 'deleted mutation winner has the wrong lifecycle'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_winner_head';
            END IF;
        END IF;
    ELSIF NEW.completion_kind = 'cas_lost' THEN
        IF EXISTS (
            SELECT 1 FROM secret_versions
            WHERE tenant_id = NEW.tenant_id
              AND provider_id = NEW.provider_id
              AND create_request_id = NEW.provider_create_request_id
        ) OR secret_row.status = 'deleted' OR NOT (
            (NEW.mutation_kind = 'create' AND (
                secret_row.status <> 'provisioning'
                OR secret_row.revision <> NEW.reserved_secret_revision
                OR secret_row.current_version_id IS NOT NULL
                OR secret_row.current_version_number IS NOT NULL
            )) OR
            (NEW.mutation_kind = 'replace' AND (
                secret_row.status <> 'active'
                OR secret_row.revision <> NEW.reserved_secret_revision
                OR secret_row.current_version_id IS DISTINCT FROM NEW.expected_predecessor_version_id
                OR secret_row.current_version_number IS DISTINCT FROM NEW.expected_predecessor_version_number
            ))
        ) THEN
            RAISE EXCEPTION 'secret version mutation has not definitively lost CAS'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_cas_lost';
        END IF;
    ELSIF NEW.completion_kind = 'system_cancelled' THEN
        IF EXISTS (
            SELECT 1
            FROM secret_versions AS version
            LEFT JOIN secret_version_lifecycle AS lifecycle
              ON lifecycle.tenant_id = version.tenant_id
             AND lifecycle.secret_version_id = version.id
            WHERE version.tenant_id = NEW.tenant_id
              AND version.provider_id = NEW.provider_id
              AND version.create_request_id = NEW.provider_create_request_id
              AND (
                  lifecycle.mutation_id IS DISTINCT FROM NEW.mutation_id
                  OR lifecycle.status NOT IN ('staged', 'destroy_pending', 'destroyed')
              )
        ) THEN
            RAISE EXCEPTION 'applied mutation cannot be recorded as cancelled'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_cancelled_unapplied';
        END IF;
    ELSIF NEW.completion_kind = 'reservation_expired' THEN
        IF NEW.confirmed_at_ms < NEW.confirmation_deadline_ms THEN
            RAISE EXCEPTION 'secret mutation cannot expire before its hard deadline'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'secret_version_mutations_expiry_deadline';
        END IF;
        IF NEW.abandoned_version_id IS NULL THEN
            IF EXISTS (
                SELECT 1 FROM secret_versions
                WHERE tenant_id = NEW.tenant_id
                  AND provider_id = NEW.provider_id
                  AND create_request_id = NEW.provider_create_request_id
            ) THEN
                RAISE EXCEPTION 'expired mutation omitted its staged candidate'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_expiry_candidate';
            END IF;
        ELSE
            SELECT * INTO winner_row
            FROM secret_versions
            WHERE tenant_id = NEW.tenant_id
              AND provider_id = NEW.provider_id
              AND create_request_id = NEW.provider_create_request_id
            FOR SHARE;
            SELECT * INTO winner_lifecycle
            FROM secret_version_lifecycle
            WHERE tenant_id = NEW.tenant_id
              AND secret_version_id = NEW.abandoned_version_id
            FOR SHARE;
            IF winner_row.id IS NULL
               OR winner_row.id IS DISTINCT FROM NEW.abandoned_version_id
               OR winner_row.secret_id <> NEW.secret_id
               OR winner_row.version_number IS DISTINCT FROM NEW.reserved_version_number
               OR winner_lifecycle.mutation_id IS DISTINCT FROM NEW.mutation_id
               OR winner_lifecycle.status <> 'staged' THEN
                RAISE EXCEPTION 'expired mutation candidate is not exact and staged'
                    USING ERRCODE = 'integrity_constraint_violation',
                          CONSTRAINT = 'secret_version_mutations_expiry_candidate';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_versions_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'secret versions are immutable'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'secret_versions_immutable';
END;
$$;

CREATE FUNCTION automata_secret_workload_grant_environment_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    environment repository_environments%ROWTYPE;
    approval protected_environment_approval_requests%ROWTYPE;
    database_now_ms BIGINT;
BEGIN
    database_now_ms := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
    IF NEW.environment_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT * INTO STRICT environment
    FROM repository_environments
    WHERE tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND id = NEW.environment_id
    FOR SHARE;

    IF environment.status <> 'active' THEN
        RAISE EXCEPTION 'environment is not active'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_environment_current';
    END IF;

    IF environment.protection_mode = 'unprotected' THEN
        IF NEW.environment_approval_request_id IS NOT NULL THEN
            RAISE EXCEPTION 'unprotected environment cannot use approval evidence'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'secret_workload_grants_environment_current';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.environment_approval_request_id IS NULL THEN
        RAISE EXCEPTION 'protected environment approval is required'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_environment_current';
    END IF;

    SELECT * INTO STRICT approval
    FROM protected_environment_approval_requests
    WHERE tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND environment_id = NEW.environment_id
      AND run_id = NEW.run_id
      AND job_id = NEW.job_id
      AND attempt_id = NEW.attempt_id
      AND id = NEW.environment_approval_request_id
    FOR SHARE;

    IF approval.status <> 'approved'
       OR approval.environment_revision <> environment.revision
       OR approval.required_approvals <> environment.required_approvals
       OR approval.prevent_self_review <> environment.prevent_self_review
       OR approval.resolved_at_ms IS NULL
       OR approval.resolved_at_ms >= approval.expires_at_ms
       OR NEW.issued_at_ms < approval.resolved_at_ms
       OR NEW.issued_at_ms >= approval.expires_at_ms
       OR NEW.issued_at_ms > database_now_ms
       OR database_now_ms >= approval.expires_at_ms
       OR database_now_ms >= NEW.expires_at_ms THEN
        RAISE EXCEPTION 'protected environment approval is stale or expired'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_environment_current';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_workload_grant_identity_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.run_id IS DISTINCT FROM OLD.run_id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.fencing_token IS DISTINCT FROM OLD.fencing_token
       OR NEW.secret_id IS DISTINCT FROM OLD.secret_id
       OR NEW.secret_version_id IS DISTINCT FROM OLD.secret_version_id
       OR NEW.secret_version_number IS DISTINCT FROM OLD.secret_version_number
       OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.environment_approval_request_id IS DISTINCT FROM OLD.environment_approval_request_id
       OR NEW.grant_mode IS DISTINCT FROM OLD.grant_mode
       OR NEW.event_trust IS DISTINCT FROM OLD.event_trust
       OR NEW.source_kind IS DISTINCT FROM OLD.source_kind
       OR NEW.authority_digest IS DISTINCT FROM OLD.authority_digest
       OR NEW.authority_digest_key_id IS DISTINCT FROM OLD.authority_digest_key_id
       OR NEW.issued_at_ms IS DISTINCT FROM OLD.issued_at_ms
       OR NEW.expires_at_ms IS DISTINCT FROM OLD.expires_at_ms THEN
        RAISE EXCEPTION 'workload grant identity and authority are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_workload_grants_identity_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_workload_grant_invocation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.invocation_kind IS DISTINCT FROM OLD.invocation_kind
       OR NEW.reusable_secret_permission IS DISTINCT FROM OLD.reusable_secret_permission
       OR NEW.lease_id IS DISTINCT FROM OLD.lease_id THEN
        RAISE EXCEPTION 'secret grant invocation authority is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_workload_grants_invocation_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_secret_workload_grant_terminal_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'active' AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal secret workload grants are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'secret_workload_grants_terminal_monotonic';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_security_audit_events_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'Automata security audit events are append-only'
        USING ERRCODE = 'integrity_constraint_violation',
              CONSTRAINT = 'security_audit_events_append_only';
END;
$$;

CREATE FUNCTION automata_seed_builtin_secret_provider() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO secret_providers (
        tenant_id, provider_id, adapter_kind, display_name,
        supports_create_version, supports_destroy_version,
        supports_dynamic_leases, supports_renew_leases, supports_revoke_leases,
        is_default, status, health, revision, created_at_ms, updated_at_ms
    ) VALUES (
        NEW.id, 'builtin', 'builtin_postgres', 'Built-in encrypted PostgreSQL',
        TRUE, TRUE, FALSE, FALSE, FALSE,
        TRUE, 'unconfigured', 'unknown', 1, NEW.created_at_ms, NEW.updated_at_ms
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seed_initial_job_environment_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM automata_seed_job_environment_gate(
        NEW.instance_id, NEW.job_id, NEW.initial_attempt_id, NEW.committed_at_ms
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seed_job_environment_gate(target_instance_id uuid, target_job_id uuid, target_attempt_id uuid, target_created_at_ms bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    logical_job logical_workflow_jobs%ROWTYPE;
    concrete logical_workflow_concrete_jobs%ROWTYPE;
    tenant TEXT;
    repository UUID;
    root_invocation UUID;
    initial_state TEXT;
BEGIN
    SELECT * INTO STRICT concrete
    FROM logical_workflow_concrete_jobs
    WHERE instance_id = target_instance_id AND job_id = target_job_id;
    SELECT * INTO STRICT logical_job
    FROM logical_workflow_jobs
    WHERE run_id = concrete.run_id
      AND invocation_id = concrete.invocation_id
      AND id = concrete.logical_job_id;
    SELECT repository_row.tenant_id, run.repository_id, marker.root_invocation_id
    INTO STRICT tenant, repository, root_invocation
    FROM workflow_runs AS run
    JOIN repositories AS repository_row ON repository_row.id = run.repository_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = run.id
    WHERE run.id = concrete.run_id;

    IF logical_job.environment_requirement_kind = 'unclassified' THEN
        initial_state := 'unclassified';
    ELSIF logical_job.environment_requirement_kind = 'none'
          AND cardinality(logical_job.secret_reference_names) = 0
          AND cardinality(logical_job.variable_reference_names) = 0 THEN
        initial_state := 'resolving';
    ELSE
        -- Selection evidence is immutable once resolution begins.  Even a
        -- no-environment job therefore pauses here until its authenticated
        -- trust/source projection has been recorded.
        initial_state := 'selection_pending';
    END IF;

    INSERT INTO job_environment_gates (
        tenant_id, repository_id, run_id, invocation_id, logical_job_id,
        instance_id, job_id, attempt_id, environment_requirement_kind,
        environment_template_digest, invocation_kind, state,
        resolution_digest, resolved_secret_count, missing_secret_count,
        resolved_variable_count, missing_variable_count,
        created_at_ms, updated_at_ms
    ) VALUES (
        tenant, repository, concrete.run_id, concrete.invocation_id,
        concrete.logical_job_id, concrete.instance_id, target_job_id,
        target_attempt_id, logical_job.environment_requirement_kind,
        logical_job.environment_template_digest,
        CASE WHEN concrete.invocation_id = root_invocation
             THEN 'direct' ELSE 'reusable' END,
        initial_state, NULL, NULL, NULL, NULL, NULL,
        target_created_at_ms, target_created_at_ms
    ) ON CONFLICT (attempt_id) DO NOTHING;

    IF logical_job.environment_requirement_kind = 'none'
       AND cardinality(logical_job.secret_reference_names) = 0
       AND cardinality(logical_job.variable_reference_names) = 0 THEN
        UPDATE job_environment_gates
        SET state = 'ready',
            resolution_digest = automata_job_credential_resolution_digest(target_attempt_id),
            resolved_secret_count = 0,
            missing_secret_count = 0,
            resolved_variable_count = 0,
            missing_variable_count = 0,
            revision = revision + 1
        WHERE attempt_id = target_attempt_id AND state = 'resolving';
    END IF;
END;
$$;

CREATE FUNCTION automata_seed_repository_publication_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO repository_publication_policies (
        tenant_id, repository_id, dashboard_audience, log_audience,
        artifact_audience, revision, created_at_ms, updated_at_ms
    ) VALUES (
        NEW.tenant_id, NEW.id, 'private', 'private', 'private', 1,
        NEW.created_at_ms, NEW.updated_at_ms
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seed_retry_job_environment_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    concrete_instance UUID;
BEGIN
    SELECT instance_id INTO concrete_instance
    FROM logical_workflow_concrete_jobs
    WHERE job_id = NEW.job_id;
    IF concrete_instance IS NOT NULL THEN
        PERFORM automata_seed_job_environment_gate(
            concrete_instance, NEW.job_id, NEW.id, NEW.queued_at_ms
        );
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_seed_secret_policy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO secret_policies (
        tenant_id, secret_id, secret_scope_kind,
        tenant_repository_access_mode, minimum_event_trust,
        allow_fork_pull_requests, allow_dependabot, reusable_workflow_mode,
        revision, created_at_ms, updated_at_ms
    ) VALUES (
        NEW.tenant_id, NEW.id, NEW.scope_kind,
        CASE
            WHEN NEW.scope_kind = 'tenant' THEN 'selected_repositories'
            ELSE 'scope_only'
        END,
        'trusted', FALSE, FALSE, 'disabled',
        1, NEW.created_at_ms, NEW.updated_at_ms
    );
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_server_cancellation_terminal_digest(target_attempt_id uuid, target_operation_id uuid, requested_by text, reason text, requested_at_ms bigint) RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
SELECT pg_catalog.sha256(
    convert_to('automata.store.server-cancellation-terminal.v1', 'UTF8')
    || decode('00', 'hex')
    || uuid_send($1)
    || uuid_send($2)
    || int4send(octet_length(convert_to($3, 'UTF8')))
    || convert_to($3, 'UTF8')
    || CASE
        WHEN $4 IS NULL THEN int4send(-1)
        ELSE int4send(octet_length(convert_to($4, 'UTF8')))
             || convert_to($4, 'UTF8')
       END
    || int8send($5)
    || convert_to('cancelled', 'UTF8')
);
$_$;

CREATE FUNCTION automata_validate_activation_preparation_authority_profile() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM workflow_runs AS run
        JOIN repositories AS repository ON repository.id = run.repository_id
        JOIN github_workflow_run_manifest_origins AS origin
          ON origin.tenant_id = repository.tenant_id
         AND origin.repository_id = run.repository_id
         AND origin.run_id = run.id
        JOIN github_provider_manifest_revisions AS manifest
          ON manifest.tenant_id = origin.tenant_id
         AND manifest.repository_id = origin.repository_id
         AND manifest.provider_connection_id = origin.provider_connection_id
         AND manifest.manifest_revision = origin.provider_manifest_revision
         AND manifest.manifest_digest = origin.provider_manifest_digest
        WHERE run.id = NEW.run_id
          AND automata_logical_workflow_invocation_published(
              run.id, NEW.invocation_id
          )
          AND manifest.authority_profile = NEW.authority_profile
    ) THEN
        RAISE EXCEPTION 'logical activation preparation lacks exact historical authority profile'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_activation_preparation_historical_profile';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_activation_publication_authority_profile() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_jobs AS job
        JOIN logical_workflow_activation_preparations AS preparation
          ON preparation.logical_job_id = job.id
         AND preparation.run_id = job.run_id
         AND preparation.invocation_id = job.invocation_id
        WHERE job.id = NEW.logical_job_id
          AND job.run_id = NEW.run_id
          AND job.invocation_id = NEW.invocation_id
          AND job.authority_profile = NEW.authority_profile
          AND preparation.authority_profile = NEW.authority_profile
          AND preparation.activation_input_digest = NEW.activation_input_digest
    ) THEN
        RAISE EXCEPTION 'activation publication authority profile is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_workflow_activation_publications_profile_binding';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_activation_real_claim_quarantine() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT;
    receipt logical_workflow_activation_work_selections%ROWTYPE;
    existing_quarantine logical_workflow_activation_work_quarantines%ROWTYPE;
    authority RECORD;
    internal_poison BOOLEAN := FALSE;
BEGIN
    SELECT * INTO receipt
    FROM logical_workflow_activation_work_selections
    WHERE selection_id = NEW.selection_id
    FOR UPDATE;
    PERFORM 1
    FROM logical_workflow_work_selection_replay_horizons
    WHERE queue_name = 'activation'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'activation quarantine replay horizon is absent'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_quarantine_horizon_required';
    END IF;
    SELECT * INTO existing_quarantine
    FROM logical_workflow_activation_work_quarantines
    WHERE logical_job_id = NEW.logical_job_id
    FOR UPDATE;
    IF existing_quarantine.logical_job_id IS NOT NULL THEN
        RAISE EXCEPTION 'activation quarantine already has immutable evidence'
            USING ERRCODE = 'unique_violation',
                  CONSTRAINT = 'workflow_activation_quarantine_already_exists';
    END IF;

    PERFORM automata_require_active_unquarantined_workflow_phase(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id, NULL
    );

    IF NEW.authority_kind = 'preparation' THEN
        SELECT repository.tenant_id, job.run_id, job.invocation_id,
               claim.origin_selection_id, claim.owner_id, claim.generation,
               claim.descriptor_digest AS digest, claim.claimed_at_ms,
               claim.expires_at_ms, claim.state
          INTO authority
        FROM logical_workflow_activation_preparation_claims AS claim
        JOIN logical_workflow_jobs AS job ON job.id = claim.logical_job_id
        JOIN workflow_runs AS run ON run.id = job.run_id
        JOIN repositories AS repository ON repository.id = run.repository_id
        WHERE claim.logical_job_id = NEW.logical_job_id
        FOR UPDATE OF claim, job;
    ELSE
        SELECT repository.tenant_id, job.run_id, job.invocation_id,
               job.activation_origin_selection_id AS origin_selection_id,
               job.activation_owner_id AS owner_id,
               job.activation_fence AS generation,
               job.activation_input_digest AS digest,
               job.activation_claimed_at_ms AS claimed_at_ms,
               job.activation_expires_at_ms AS expires_at_ms,
               job.state
          INTO authority
        FROM logical_workflow_jobs AS job
        JOIN workflow_runs AS run ON run.id = job.run_id
        JOIN repositories AS repository ON repository.id = run.repository_id
        WHERE job.id = NEW.logical_job_id
        FOR UPDATE OF job;
    END IF;

    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    internal_poison := NEW.failure_kind = 'generation_exhausted'
        AND receipt.outcome = 'selecting';
    IF receipt.selection_id IS NULL
        OR receipt.owner_id IS DISTINCT FROM NEW.selection_owner_id
        OR receipt.requested_at_ms IS DISTINCT FROM NEW.selection_requested_at_ms
        OR receipt.duration_ms IS DISTINCT FROM NEW.selection_duration_ms
    THEN
        RAISE EXCEPTION 'activation quarantine lacks its exact selection request'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_quarantine_selection_request_exact';
    END IF;
    IF internal_poison THEN
        IF receipt.claimed_at_ms IS NOT NULL OR receipt.expires_at_ms IS NOT NULL
            OR receipt.tenant_id IS NOT NULL OR receipt.run_id IS NOT NULL
            OR receipt.invocation_id IS NOT NULL OR receipt.logical_job_id IS NOT NULL
            OR receipt.generation IS NOT NULL OR receipt.authority_kind IS NOT NULL
            OR receipt.authority_digest IS NOT NULL
            OR NEW.selection_generation <> NEW.authority_generation
            OR NEW.selection_claimed_at_ms > database_now
            OR database_now - NEW.selection_claimed_at_ms > 60000
            OR NEW.selection_expires_at_ms - database_now < 1000
            OR NEW.authority_generation <> 9223372036854775807
            OR NEW.authority_expires_at_ms > database_now
        THEN
            RAISE EXCEPTION 'activation generation poison is not an exact provisional capture'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_activation_quarantine_generation_poison_exact';
        END IF;
    ELSIF NEW.failure_kind = 'generation_exhausted'
        OR receipt.outcome <> 'claimed'
        OR receipt.claimed_at_ms IS DISTINCT FROM NEW.selection_claimed_at_ms
        OR receipt.expires_at_ms IS DISTINCT FROM NEW.selection_expires_at_ms
        OR receipt.tenant_id IS DISTINCT FROM NEW.tenant_id
        OR receipt.run_id IS DISTINCT FROM NEW.run_id
        OR receipt.invocation_id IS DISTINCT FROM NEW.invocation_id
        OR receipt.logical_job_id IS DISTINCT FROM NEW.logical_job_id
        OR receipt.generation IS DISTINCT FROM NEW.selection_generation
        OR receipt.authority_kind IS DISTINCT FROM NEW.authority_kind
        OR receipt.authority_digest IS DISTINCT FROM NEW.authority_digest
    THEN
        RAISE EXCEPTION 'activation quarantine lacks the exact claimed receipt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_quarantine_selection_exact';
    END IF;

    IF authority IS NULL
        OR (authority.tenant_id, authority.run_id, authority.invocation_id)
           IS DISTINCT FROM (NEW.tenant_id, NEW.run_id, NEW.invocation_id)
        OR authority.owner_id IS DISTINCT FROM NEW.authority_owner_id
        OR authority.generation IS DISTINCT FROM NEW.authority_generation
        OR authority.generation < NEW.selection_generation
        OR authority.digest IS DISTINCT FROM NEW.authority_digest
        OR authority.claimed_at_ms IS DISTINCT FROM NEW.authority_claimed_at_ms
        OR authority.expires_at_ms IS DISTINCT FROM NEW.authority_expires_at_ms
        OR authority.claimed_at_ms > database_now
        OR authority.state IS DISTINCT FROM (
            CASE WHEN NEW.authority_kind = 'preparation'
                 THEN 'preparing' ELSE 'activating' END
        )
        OR (NOT internal_poison AND (
            authority.origin_selection_id IS DISTINCT FROM NEW.selection_id
            OR authority.owner_id IS DISTINCT FROM NEW.selection_owner_id))
    THEN
        RAISE EXCEPTION 'activation quarantine lacks exact unsuperseded authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_quarantine_authority_exact';
    END IF;
    NEW.quarantined_at_ms := database_now;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_activation_real_claim_renewal_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    selection logical_workflow_activation_work_selections%ROWTYPE;
    authority RECORD;
    database_now BIGINT;
    receipt_count BIGINT;
    predecessor_exact BOOLEAN := FALSE;
BEGIN
    SELECT * INTO selection
    FROM logical_workflow_activation_work_selections
    WHERE selection_id = NEW.selection_id;
    SELECT count(*) INTO receipt_count
    FROM logical_workflow_activation_renewal_receipts
    WHERE selection_id = NEW.selection_id;
    IF NEW.authority_kind = 'preparation' THEN
        SELECT claim.state, claim.origin_selection_id, claim.owner_id,
               claim.generation, claim.claimed_at_ms, claim.expires_at_ms,
               claim.descriptor_digest AS authority_digest,
               claim.runtime_policy_revision, claim.runtime_policy_digest
          INTO authority
        FROM logical_workflow_activation_preparation_claims AS claim
        WHERE claim.logical_job_id = NEW.logical_job_id
        FOR UPDATE;
    ELSE
        SELECT job.state, job.activation_origin_selection_id AS origin_selection_id,
               job.activation_owner_id AS owner_id,
               job.activation_fence AS generation,
               job.activation_claimed_at_ms AS claimed_at_ms,
               job.activation_expires_at_ms AS expires_at_ms,
               job.activation_input_digest AS authority_digest,
               job.runtime_policy_revision, job.runtime_policy_digest
          INTO authority
        FROM logical_workflow_jobs AS job
        WHERE job.id = NEW.logical_job_id
        FOR UPDATE;
    END IF;
    IF selection.selection_id IS NULL OR selection.outcome <> 'claimed'
        OR selection.authority_kind IS DISTINCT FROM NEW.authority_kind
        OR (selection.tenant_id, selection.run_id, selection.invocation_id,
            selection.logical_job_id, selection.owner_id,
            selection.authority_digest)
           IS DISTINCT FROM
           (NEW.tenant_id, NEW.run_id, NEW.invocation_id,
            NEW.logical_job_id, NEW.owner_id, NEW.authority_digest)
    THEN
        RAISE EXCEPTION 'activation renewal lacks its exact selection origin'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_renewal_selection_exact';
    END IF;
    IF NEW.predecessor_generation = selection.generation THEN
        predecessor_exact :=
            (NEW.predecessor_claimed_at_ms, NEW.predecessor_expires_at_ms,
             NEW.owner_id, NEW.authority_digest)
            IS NOT DISTINCT FROM
            (selection.claimed_at_ms, selection.expires_at_ms,
             selection.owner_id, selection.authority_digest);
    ELSE
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_activation_renewal_receipts AS prior
            WHERE prior.selection_id = NEW.selection_id
              AND prior.logical_job_id = NEW.logical_job_id
              AND prior.authority_kind = NEW.authority_kind
              AND prior.successor_generation = NEW.predecessor_generation
              AND prior.successor_claimed_at_ms = NEW.predecessor_claimed_at_ms
              AND prior.successor_expires_at_ms = NEW.predecessor_expires_at_ms
              AND prior.owner_id = NEW.owner_id
              AND prior.runtime_policy_revision = NEW.runtime_policy_revision
              AND prior.runtime_policy_digest = NEW.runtime_policy_digest
              AND prior.authority_digest = NEW.authority_digest
        ) INTO predecessor_exact;
    END IF;
    IF predecessor_exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'activation renewal does not extend its exact predecessor chain'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_renewal_predecessor_exact';
    END IF;
    IF receipt_count >= 64 THEN
        RAISE EXCEPTION 'activation selection renewal history is full'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_renewal_history_bounded';
    END IF;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF authority IS NULL
        OR authority.state IS DISTINCT FROM (
            CASE WHEN NEW.authority_kind = 'preparation'
                 THEN 'preparing' ELSE 'activating' END
        )
        OR authority.origin_selection_id IS DISTINCT FROM NEW.selection_id
        OR authority.owner_id IS DISTINCT FROM NEW.owner_id
        OR authority.generation IS DISTINCT FROM NEW.successor_generation
        OR authority.claimed_at_ms IS DISTINCT FROM NEW.successor_claimed_at_ms
        OR authority.expires_at_ms IS DISTINCT FROM NEW.successor_expires_at_ms
        OR authority.authority_digest IS DISTINCT FROM NEW.authority_digest
        OR (authority.runtime_policy_revision, authority.runtime_policy_digest)
           IS DISTINCT FROM
           (NEW.runtime_policy_revision, NEW.runtime_policy_digest)
        OR NEW.successor_expires_at_ms - database_now < 1000
    THEN
        RAISE EXCEPTION 'activation renewal lacks the exact live successor authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_renewal_successor_exact';
    END IF;
    NEW.validated_at_ms := database_now;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_activation_work_selection_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT;
    replay_floor BIGINT;
    exact_evidence BOOLEAN := FALSE;
    ready_exists BOOLEAN := FALSE;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.outcome <> 'selecting' THEN
            RAISE EXCEPTION 'activation selection must begin as a provisional reservation'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_activation_selection_reservation_first';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.outcome <> 'selecting'
        OR NEW.selection_id IS DISTINCT FROM OLD.selection_id
        OR NEW.owner_id IS DISTINCT FROM OLD.owner_id
        OR NEW.requested_at_ms IS DISTINCT FROM OLD.requested_at_ms
        OR NEW.duration_ms IS DISTINCT FROM OLD.duration_ms
        OR NEW.outcome = 'selecting'
    THEN
        RAISE EXCEPTION 'activation selection transition is immutable or invalid'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_selection_transition';
    END IF;
    SELECT replay_floor_ms INTO replay_floor
    FROM logical_workflow_work_selection_replay_horizons
    WHERE queue_name = 'activation'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'activation selection replay authority is absent'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_selection_horizon_required';
    END IF;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF NEW.requested_at_ms <= replay_floor
        OR NEW.requested_at_ms < database_now - 60000
        OR NEW.requested_at_ms > database_now + 60000
    THEN
        RAISE EXCEPTION 'activation selection request is outside replay authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_selection_request_time';
    END IF;
    IF NEW.claimed_at_ms > database_now
        OR database_now - NEW.claimed_at_ms > 60000
        OR (NEW.outcome <> 'quarantined' AND (
            NEW.expires_at_ms <= database_now
            OR NEW.expires_at_ms - database_now < 1000
        ))
    THEN
        RAISE EXCEPTION 'activation selection issue time is not database-current'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_selection_database_time';
    END IF;

    IF NEW.outcome = 'claimed' AND NEW.authority_kind = 'preparation' THEN
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_activation_preparation_claims AS claim
            JOIN logical_workflow_jobs AS job ON job.id = claim.logical_job_id
            JOIN workflow_runs AS run ON run.id = job.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE claim.logical_job_id = NEW.logical_job_id
              AND repository.tenant_id = NEW.tenant_id
              AND job.run_id = NEW.run_id
              AND job.invocation_id = NEW.invocation_id
              AND claim.origin_selection_id = NEW.selection_id
              AND claim.owner_id = NEW.owner_id
              AND claim.generation = NEW.generation
              AND claim.descriptor_digest = NEW.authority_digest
              AND claim.claimed_at_ms = NEW.claimed_at_ms
              AND claim.expires_at_ms = NEW.expires_at_ms
              AND claim.state = 'preparing'
        ) INTO exact_evidence;
    ELSIF NEW.outcome = 'claimed' AND NEW.authority_kind = 'activation' THEN
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_jobs AS job
            JOIN workflow_runs AS run ON run.id = job.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE job.id = NEW.logical_job_id
              AND repository.tenant_id = NEW.tenant_id
              AND job.run_id = NEW.run_id
              AND job.invocation_id = NEW.invocation_id
              AND job.activation_origin_selection_id = NEW.selection_id
              AND job.activation_owner_id = NEW.owner_id
              AND job.activation_fence = NEW.generation
              AND job.activation_input_digest = NEW.authority_digest
              AND job.activation_claimed_at_ms = NEW.claimed_at_ms
              AND job.activation_expires_at_ms = NEW.expires_at_ms
              AND job.state = 'activating'
        ) INTO exact_evidence;
    ELSIF NEW.outcome = 'quarantined' THEN
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_activation_work_quarantines AS quarantine
            WHERE quarantine.logical_job_id = NEW.logical_job_id
              AND quarantine.tenant_id = NEW.tenant_id
              AND quarantine.run_id = NEW.run_id
              AND quarantine.invocation_id = NEW.invocation_id
              AND quarantine.selection_id = NEW.selection_id
              AND quarantine.selection_owner_id = NEW.owner_id
              AND quarantine.selection_requested_at_ms = NEW.requested_at_ms
              AND quarantine.selection_duration_ms = NEW.duration_ms
              AND quarantine.selection_generation = NEW.generation
              AND quarantine.selection_claimed_at_ms = NEW.claimed_at_ms
              AND quarantine.selection_expires_at_ms = NEW.expires_at_ms
              AND quarantine.authority_kind = NEW.authority_kind
              AND quarantine.authority_digest = NEW.authority_digest
        ) INTO exact_evidence;
    ELSIF NEW.outcome = 'contended' THEN
        exact_evidence := TRUE;
    ELSE
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_jobs AS job
            JOIN logical_workflow_invocations AS invocation
              ON invocation.run_id = job.run_id
             AND invocation.id = job.invocation_id
            JOIN logical_workflow_runs AS marker ON marker.run_id = job.run_id
            JOIN workflow_runs AS run ON run.id = marker.run_id
            LEFT JOIN logical_workflow_activation_preparation_claims AS preparation
              ON preparation.logical_job_id = job.id
            LEFT JOIN logical_workflow_activation_work_quarantines AS quarantine
              ON quarantine.logical_job_id = job.id
            WHERE job.execution_kind = 'steps'
              AND automata_logical_workflow_invocation_published(
                  marker.run_id, invocation.id
              )
              AND invocation.state IN ('pending', 'active')
              AND marker.state IN ('pending', 'active')
              AND run.status IN ('queued', 'in_progress')
              AND quarantine.logical_job_id IS NULL
              AND ((job.state = 'pending' AND (
                  preparation.logical_job_id IS NULL OR preparation.state = 'prepared'
                  OR (preparation.state = 'preparing'
                      AND preparation.expires_at_ms <= NEW.claimed_at_ms)
              )) OR (job.state = 'activating'
                     AND job.activation_expires_at_ms <= NEW.claimed_at_ms))
              AND NOT EXISTS (
                  SELECT 1
                  FROM logical_workflow_dependencies AS dependency
                  LEFT JOIN logical_workflow_job_result_claims AS result_claim
                    ON result_claim.logical_job_id = dependency.prerequisite_job_id
                   AND result_claim.state = 'finalized'
                  WHERE dependency.run_id = job.run_id
                    AND dependency.invocation_id = job.invocation_id
                    AND dependency.logical_job_id = job.id
                    AND result_claim.logical_job_id IS NULL
              )
        ) INTO ready_exists;
        exact_evidence := NOT ready_exists;
    END IF;
    IF exact_evidence IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'activation selection lacks exact durable evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_activation_selection_receipt_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_artifact_safety_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    attempt_exposure TEXT;
    run_artifact_visibility TEXT;
BEGIN
    SELECT secret_exposure_class
    INTO attempt_exposure
    FROM job_attempts
    WHERE id = NEW.attempt_id;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    SELECT requested_artifact_visibility
    INTO run_artifact_visibility
    FROM workflow_runs
    WHERE id = NEW.run_id;

    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF NEW.secret_exposure_class IS DISTINCT FROM attempt_exposure THEN
        RAISE EXCEPTION 'artifact exposure must equal the immutable attempt ceiling'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_artifacts_attempt_exposure_snapshot';
    END IF;
    IF NEW.requested_visibility IS DISTINCT FROM run_artifact_visibility THEN
        RAISE EXCEPTION 'artifact audience must equal the immutable run request'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_artifacts_run_visibility_snapshot';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_attempt_log_safety_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    attempt_exposure TEXT;
    attempt_raw_disposition TEXT;
    attempt_requested_visibility TEXT;
    attempt_effective_visibility TEXT;
    attempt_reason TEXT;
    attempt_schema INTEGER;
BEGIN
    SELECT
        secret_exposure_class,
        raw_log_disposition,
        requested_log_visibility,
        effective_log_visibility,
        output_safety_reason,
        output_safety_schema
    INTO
        attempt_exposure,
        attempt_raw_disposition,
        attempt_requested_visibility,
        attempt_effective_visibility,
        attempt_reason,
        attempt_schema
    FROM job_attempts
    WHERE id = NEW.attempt_id;

    -- Preserve the existing foreign-key error for a nonexistent attempt.
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF NEW.secret_exposure_class IS DISTINCT FROM attempt_exposure
       OR NEW.raw_log_disposition IS DISTINCT FROM attempt_raw_disposition
       OR NEW.requested_visibility IS DISTINCT FROM attempt_requested_visibility
       OR NEW.effective_visibility IS DISTINCT FROM attempt_effective_visibility
       OR NEW.output_safety_reason IS DISTINCT FROM attempt_reason
       OR NEW.output_safety_schema IS DISTINCT FROM attempt_schema THEN
        RAISE EXCEPTION 'attempt log safety must equal the immutable attempt snapshot'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'attempt_log_streams_attempt_safety_snapshot';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_concrete_job_authority_profile() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_materialization_claims AS claim
        WHERE claim.instance_id = NEW.instance_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.logical_job_id = NEW.logical_job_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.authority_profile = NEW.authority_profile
    ) THEN
        RAISE EXCEPTION 'concrete job authority profile is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_workflow_concrete_jobs_profile_binding';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_concurrency_pending_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM concurrency_groups AS concurrency
        WHERE concurrency.repository_id = NEW.repository_id
          AND concurrency.normalized_key = NEW.normalized_key
          AND concurrency.running_run_id = NEW.run_id
    ) THEN
        RAISE EXCEPTION 'Concurrency run cannot occupy running and pending positions'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_concurrency_running_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.running_run_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM concurrency_group_pending_runs AS pending
        WHERE pending.repository_id = NEW.repository_id
          AND pending.normalized_key = NEW.normalized_key
          AND pending.run_id = NEW.running_run_id
    ) THEN
        RAISE EXCEPTION 'Concurrency run cannot occupy running and pending positions'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_environment_approval_decision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    request protected_environment_approval_requests%ROWTYPE;
    environment repository_environments%ROWTYPE;
    database_now_ms BIGINT;
BEGIN
    database_now_ms := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
    SELECT * INTO STRICT request
    FROM protected_environment_approval_requests
    WHERE tenant_id = NEW.tenant_id
      AND id = NEW.request_id
    FOR SHARE;

    SELECT * INTO STRICT environment
    FROM repository_environments
    WHERE tenant_id = request.tenant_id
      AND repository_id = request.repository_id
      AND id = request.environment_id
    FOR SHARE;

    IF request.status <> 'pending' THEN
        RAISE EXCEPTION 'environment approval request is terminal'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'protected_environment_approval_decisions_pending';
    END IF;
    IF request.environment_revision <> environment.revision
       OR request.required_approvals <> environment.required_approvals
       OR request.prevent_self_review <> environment.prevent_self_review
       OR environment.protection_mode <> 'required_approvals'
       OR environment.status <> 'active' THEN
        RAISE EXCEPTION 'environment approval request policy is stale'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'protected_environment_approval_decisions_current_policy';
    END IF;
    IF NEW.decided_at_ms < request.created_at_ms
       OR NEW.decided_at_ms >= request.expires_at_ms
       OR NEW.decided_at_ms > database_now_ms
       OR database_now_ms - NEW.decided_at_ms > 60000
       OR database_now_ms >= request.expires_at_ms THEN
        RAISE EXCEPTION 'environment approval decision is outside the request lifetime'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'protected_environment_approval_decisions_lifetime';
    END IF;
    IF request.prevent_self_review
       AND request.requested_by_principal_id = NEW.principal_id THEN
        RAISE EXCEPTION 'environment requester cannot approve their own workload'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'protected_environment_approval_decisions_self_review';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_oidc_authority_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT automata_lock_github_oidc_authority_dependencies(NEW)
        OR NOT automata_github_oidc_authority_is_current(
            NEW, NEW.reserved_at_ms, NEW.reserved_at_ms + 1
        )
    THEN
        RAISE EXCEPTION 'GitHub-compatible OIDC authority is not current'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_oidc_authority_current_execution';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_oidc_issuance_slot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    authority github_oidc_authorities%ROWTYPE;
    slot_count BIGINT;
BEGIN
    IF NEW.issued_at_seconds > 9223372036854774 THEN
        RAISE EXCEPTION 'GitHub-compatible OIDC issuance time is out of range'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_oidc_issuance_current_authority';
    END IF;
    SELECT * INTO authority
    FROM github_oidc_authorities
    WHERE authority_id = NEW.authority_id
    FOR UPDATE;
    IF authority.authority_id IS NULL
        OR NOT automata_lock_github_oidc_authority_dependencies(authority)
        OR NEW.resolved_audience IS DISTINCT FROM coalesce(
            NEW.requested_audience, authority.default_audience
        )
        OR NEW.issued_at_seconds < authority.request_bearer_iat_seconds
        OR NEW.not_before_seconds < authority.request_bearer_iat_seconds
        OR NEW.expires_at_seconds > authority.request_bearer_exp_seconds
        OR NOT automata_github_oidc_authority_is_current(
            authority,
            NEW.issued_at_seconds * 1000,
            (NEW.issued_at_seconds + 1) * 1000
        )
    THEN
        RAISE EXCEPTION 'GitHub-compatible OIDC issuance lacks current authority'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_oidc_issuance_current_authority';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.generation <> 1
            OR NEW.created_at_seconds <> NEW.issued_at_seconds
        THEN
            RAISE EXCEPTION 'GitHub-compatible OIDC initial issuance is invalid'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'github_oidc_issuance_slot_initial';
        END IF;
        SELECT count(*) INTO slot_count
        FROM github_oidc_issuance_slots
        WHERE authority_id = NEW.authority_id;
        IF slot_count >= 64 THEN
            RAISE EXCEPTION 'GitHub-compatible OIDC audience slot bound exceeded'
                USING ERRCODE = 'program_limit_exceeded',
                      CONSTRAINT = 'github_oidc_issuance_slot_bound';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_runtime_authority_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state <> 'claimed'
        OR NEW.mint_attempt_count <> 1
        OR NEW.mint_claim_fence <> 1
        OR NOT automata_github_runtime_authority_is_current(
            NEW, NEW.mint_claimed_at_ms
        )
    THEN
        RAISE EXCEPTION 'GitHub runtime authority does not match current JobIR attempt authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_current_attempt_insert';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_runtime_authority_lease_renewal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT;
BEGIN
    -- Match the Store's global runner/session -> attempt -> authority order.
    -- These separate row-lock phases also make direct SQL writers deterministic
    -- instead of relying on a multi-relation plan's row-mark order.
    PERFORM 1
    FROM runners AS runner
    JOIN runner_sessions AS session
      ON session.runner_id = runner.id
     AND session.id = NEW.runner_session_id
     AND session.session_epoch = NEW.runner_session_epoch
     AND session.runner_generation = NEW.runner_generation
    WHERE runner.id = NEW.runner_id
      AND runner.generation = NEW.runner_generation
      AND runner.session_epoch = NEW.runner_session_epoch
      AND runner.status = 'online'
      AND runner.desired_state IN ('active', 'draining')
      AND session.disconnected_at_ms IS NULL
      AND session.job_ir_schema = 1
    FOR SHARE OF runner, session;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'GitHub runtime authority lease renewal lacks a live runner session'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_lease_renewal_receipts_authority';
    END IF;

    PERFORM 1
    FROM job_attempts AS attempt
    WHERE attempt.id = NEW.attempt_id
      AND attempt.fencing_token = NEW.fencing_token
      AND attempt.lease_id = NEW.lease_id
      AND attempt.lease_expires_at_ms = NEW.previous_lease_expires_at_ms
      AND attempt.runner_id = NEW.runner_id
      AND attempt.runner_session_id = NEW.runner_session_id
      AND attempt.runner_session_epoch = NEW.runner_session_epoch
      AND attempt.runner_generation = NEW.runner_generation
      AND attempt.lifecycle IN ('leased', 'preparing', 'running', 'cancelling')
      AND attempt.changed_at_ms <= NEW.authorized_at_ms
    FOR UPDATE OF attempt;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'GitHub runtime authority lease renewal lacks the exact current attempt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_lease_renewal_receipts_authority';
    END IF;

    -- Sample after every preceding row lock. A writer that queued while the
    -- predecessor was live must not renew it after waiting past its horizon.
    database_now := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
    IF NEW.authorized_at_ms > database_now
        OR NEW.previous_lease_expires_at_ms <= database_now
    THEN
        RAISE EXCEPTION 'GitHub runtime authority lease renewal uses a stale lease horizon'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_lease_renewal_receipts_authority';
    END IF;

    PERFORM 1
    FROM github_runtime_authority_issuances AS authority
    JOIN job_attempts AS exact_attempt
      ON exact_attempt.id = authority.attempt_id
     AND exact_attempt.job_id = authority.job_id
    WHERE authority.attempt_id = NEW.attempt_id
      AND authority.fencing_token = NEW.fencing_token
      AND authority.lease_id = NEW.lease_id
      AND authority.runner_id = NEW.runner_id
      AND authority.runner_session_id = NEW.runner_session_id
      AND authority.runner_session_epoch = NEW.runner_session_epoch
      AND authority.runner_generation = NEW.runner_generation
      AND authority.state = 'ready'
      AND authority.ready_at_ms <= NEW.authorized_at_ms
      AND authority.provider_expires_at_ms IS NOT NULL
      AND authority.provider_expires_at_ms - 60000
            >= NEW.renewed_lease_expires_at_ms
      AND exact_attempt.fencing_token = authority.fencing_token
      AND exact_attempt.lease_id = authority.lease_id
      AND exact_attempt.lease_issued_at_ms = authority.lease_issued_at_ms
      AND automata_github_runtime_authority_lease_horizon_is_tail(
          authority,
          NEW.previous_lease_expires_at_ms,
          NEW.authorized_at_ms
      )
    FOR SHARE OF authority;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'GitHub runtime authority lease renewal lacks exact durable authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_lease_renewal_receipts_authority';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_runtime_authority_operation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT := floor(
        extract(epoch FROM clock_timestamp()) * 1000
    )::BIGINT;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM github_runtime_authority_operation_transitions AS transition
        WHERE transition.attempt_id = NEW.attempt_id
          AND transition.fencing_token = NEW.fencing_token
          AND transition.tenant_id = NEW.tenant_id
          AND transition.operation_kind = NEW.operation_kind
          AND transition.claim_fence = NEW.claim_fence
          AND transition.operation_digest = NEW.operation_digest
          AND transition.disposition = NEW.disposition
          AND transition.claim_owner_id IS NOT DISTINCT FROM NEW.claim_owner_id
          AND transition.claim_claimed_at_ms
              IS NOT DISTINCT FROM NEW.claim_claimed_at_ms
          AND transition.claim_expires_at_ms
              IS NOT DISTINCT FROM NEW.claim_expires_at_ms
          AND transition.result_state = NEW.result_state
          AND transition.result_updated_at_ms = NEW.result_updated_at_ms
          AND transition.result_terminal_reason
              IS NOT DISTINCT FROM NEW.result_terminal_reason
        FOR KEY SHARE
    ) THEN
        RAISE EXCEPTION 'GitHub runtime-authority receipt lacks its canonical transition'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT =
                      'github_runtime_authority_operation_receipt_transition_exact';
    END IF;
    NEW.applied_at_ms := database_now;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_runtime_authority_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1
    FROM job_attempts AS attempt
    JOIN jobs AS job
      ON job.id = attempt.job_id
     AND job.id = NEW.job_id
     AND job.run_id = NEW.run_id
    JOIN workflow_runs AS run
      ON run.id = job.run_id
     AND run.repository_id = NEW.repository_id
    JOIN repositories AS repository
      ON repository.id = run.repository_id
     AND repository.tenant_id = NEW.tenant_id
    JOIN workflow_definitions AS workflow
      ON workflow.id = run.workflow_id
     AND workflow.repository_id = run.repository_id
    JOIN workflow_snapshots AS snapshot
      ON snapshot.id = run.snapshot_id
     AND snapshot.workflow_id = run.workflow_id
    JOIN logical_workflow_concrete_jobs AS concrete
      ON concrete.run_id = run.id
     AND concrete.job_id = job.id
    JOIN logical_workflow_invocations AS invocation
      ON invocation.run_id = concrete.run_id
     AND invocation.id = concrete.invocation_id
    JOIN logical_workflow_runs AS marker
      ON marker.run_id = concrete.run_id
    JOIN runners AS runner
      ON runner.id = NEW.runner_id
     AND runner.tenant_id = repository.tenant_id
    JOIN runner_sessions AS session
      ON session.id = NEW.runner_session_id
     AND session.runner_id = runner.id
    WHERE attempt.id = NEW.attempt_id
      AND attempt.job_id = NEW.job_id
      AND job.job_ir_schema = NEW.job_ir_schema
      AND job.job_ir_size_bytes = NEW.job_ir_size_bytes
      AND job.job_ir_digest = NEW.job_ir_digest
      AND job.job_ir_digest = NEW.policy_digest
      AND repository.scm_provider = 'github'
      AND repository.provider_repository_id = NEW.github_repository_id::TEXT
      AND repository.owner || '/' || repository.name = NEW.github_repository_name
      AND runner.id = NEW.runner_id
      AND session.id = NEW.runner_session_id
      AND session.session_epoch = NEW.runner_session_epoch
      AND session.runner_generation = NEW.runner_generation
      AND invocation.plan_schema = 1
      AND automata_logical_workflow_invocation_published(
          run.id, invocation.id
      )
    FOR SHARE OF attempt, job, run, repository, workflow, snapshot, concrete,
                 invocation, marker, runner, session;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'GitHub runtime authority lacks exact execution provenance'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_execution_provenance';
    END IF;

    IF NOT automata_github_runtime_authority_has_provenance(NEW) THEN
        RAISE EXCEPTION 'GitHub runtime authority lacks exact historical policy provenance'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'github_runtime_authority_historical_provenance';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_github_workflow_rerun_subject_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact BOOLEAN;
BEGIN
    SELECT TRUE INTO exact
    FROM workflow_rerun_attempts AS attempt
    JOIN workflow_rerun_requests AS request
      ON request.tenant_id = NEW.tenant_id
     AND request.operation_id = NEW.operation_id
     AND request.rerun_run_id = attempt.run_id
     AND request.source_run_id = attempt.source_run_id
    JOIN workflow_admission_receipts AS receipt
      ON receipt.tenant_id = request.tenant_id
     AND receipt.idempotency_kind = 'operation'
     AND receipt.idempotency_key =
         'workflow-rerun:' || request.operation_id::TEXT
     AND receipt.request_digest = request.request_digest
     AND receipt.repository_id = request.repository_id
     AND receipt.run_id = attempt.run_id
     AND receipt.committed_at_ms = attempt.created_at_ms
     AND receipt.github_subject_evidence_required
    JOIN workflow_runs AS run
      ON run.id = attempt.run_id
     AND run.repository_id = request.repository_id
    JOIN workflow_definitions AS workflow
      ON workflow.repository_id = run.repository_id
     AND workflow.id = run.workflow_id
    JOIN workflow_snapshots AS snapshot
      ON snapshot.id = run.snapshot_id
     AND snapshot.workflow_id = run.workflow_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = run.id
    JOIN workflow_rerun_check_evidence AS check_evidence
      ON check_evidence.tenant_id = request.tenant_id
     AND check_evidence.operation_id = request.operation_id
     AND check_evidence.run_id = attempt.run_id
     AND check_evidence.source_run_id = attempt.source_run_id
    JOIN github_check_subjects AS subject
      ON subject.tenant_id = check_evidence.tenant_id
     AND subject.id = check_evidence.github_check_subject_id
     AND subject.workflow_rerun_run_id = check_evidence.run_id
    JOIN github_workflow_run_base_manifest_origins AS origin
      ON origin.tenant_id = request.tenant_id
     AND origin.repository_id = request.repository_id
     AND origin.run_id = attempt.root_run_id
     AND origin.provider_connection_id = check_evidence.provider_connection_id
     AND origin.provider_manifest_revision =
         check_evidence.provider_manifest_revision
     AND origin.provider_manifest_digest = check_evidence.provider_manifest_digest
    WHERE attempt.run_id = NEW.run_id
      AND attempt.source_run_id = NEW.source_run_id
      AND attempt.source_run_id IS NOT NULL
      AND request.repository_id = NEW.repository_id
      AND request.committed_at_ms = NEW.admitted_at_ms
      AND request.committed_at_ms = attempt.created_at_ms
      AND run.workflow_id = NEW.workflow_id
      AND run.snapshot_id = NEW.snapshot_id
      AND run.head_sha = NEW.github_check_head_sha
      AND run.event_name = NEW.event_name
      AND run.event_digest = NEW.event_digest
      AND run.git_ref = NEW.git_ref
      AND run.plan_schema = NEW.workflow_plan_schema
      AND run.plan_digest = NEW.plan_digest
      AND run.created_at_ms = NEW.admitted_at_ms
      AND run.status = 'queued'
      AND workflow.path = NEW.workflow_path
      AND snapshot.source_digest = NEW.source_digest
      AND marker.root_invocation_id = NEW.root_invocation_id
      AND marker.admission_digest = NEW.logical_admission_digest
      AND marker.admitted_at_ms = NEW.admitted_at_ms
      AND check_evidence.github_check_subject_id =
          NEW.github_check_subject_id
      AND check_evidence.github_check_head_sha = NEW.github_check_head_sha
      AND check_evidence.recorded_at_ms = NEW.admitted_at_ms
      AND subject.workflow_run_id = run.id
      AND subject.linked_at_ms = NEW.admitted_at_ms
      AND subject.desired_state = 'in_progress'
      AND subject.desired_conclusion IS NULL
      AND subject.terminal_cause IS NULL
      AND subject.desired_revision = 2
      AND subject.desired_updated_at_ms = NEW.admitted_at_ms
      AND origin.github_check_head_sha = NEW.github_check_head_sha
      AND origin.github_repository_owner_id =
          NEW.github_repository_owner_id
      AND origin.workflow_path = NEW.workflow_path
      AND origin.source_digest = NEW.source_digest
      AND origin.event_name = NEW.event_name
      AND origin.event_digest = NEW.event_digest
      AND origin.git_ref = NEW.git_ref
      AND origin.workflow_plan_schema = NEW.workflow_plan_schema
      AND origin.plan_digest = NEW.plan_digest
    FOR KEY SHARE OF attempt, request, receipt, run, workflow, snapshot,
                     marker, check_evidence, subject;

    IF exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'GitHub workflow rerun run-subject evidence is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'github_workflow_rerun_subject_evidence_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_job_credential_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
    logical_job logical_workflow_jobs%ROWTYPE;
BEGIN
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.attempt_id FOR SHARE;
    SELECT * INTO STRICT logical_job FROM logical_workflow_jobs
    WHERE run_id = gate.run_id AND invocation_id = gate.invocation_id
      AND id = gate.logical_job_id;
    IF TG_TABLE_NAME LIKE '%secret%' THEN
        IF NOT NEW.canonical_name = ANY(logical_job.secret_reference_names) THEN
            RAISE EXCEPTION 'secret binding was not declared by the logical job'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'job_secret_bindings_declared';
        END IF;
    ELSE
        IF NOT NEW.canonical_name = ANY(logical_job.variable_reference_names) THEN
            RAISE EXCEPTION 'variable binding was not declared by the logical job'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'job_variable_bindings_declared';
        END IF;
    END IF;
    IF gate.state <> 'resolving' THEN
        RAISE EXCEPTION 'credential bindings require a live resolving gate'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_credential_bindings_gate_live';
    END IF;
    IF TG_TABLE_NAME = 'job_secret_selections' AND EXISTS (
        SELECT 1 FROM job_missing_secret_bindings
        WHERE attempt_id = NEW.attempt_id AND canonical_name = NEW.canonical_name
    ) OR TG_TABLE_NAME = 'job_missing_secret_bindings' AND EXISTS (
        SELECT 1 FROM job_secret_selections
        WHERE attempt_id = NEW.attempt_id AND canonical_name = NEW.canonical_name
    ) OR TG_TABLE_NAME = 'job_variable_bindings' AND EXISTS (
        SELECT 1 FROM job_missing_variable_bindings
        WHERE attempt_id = NEW.attempt_id AND canonical_name = NEW.canonical_name
    ) OR TG_TABLE_NAME = 'job_missing_variable_bindings' AND EXISTS (
        SELECT 1 FROM job_variable_bindings
        WHERE attempt_id = NEW.attempt_id AND canonical_name = NEW.canonical_name
    ) THEN
        RAISE EXCEPTION 'credential name already has an opposite resolution'
            USING ERRCODE = 'unique_violation',
                  CONSTRAINT = 'job_credential_bindings_one_resolution';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_job_environment_activation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    instance logical_workflow_instances%ROWTYPE;
    logical_job logical_workflow_jobs%ROWTYPE;
    root_invocation UUID;
    all_reusable_secret_references_bound BOOLEAN;
BEGIN
    SELECT * INTO STRICT instance
    FROM logical_workflow_instances
    WHERE id = NEW.instance_id
    FOR SHARE;
    SELECT * INTO STRICT logical_job
    FROM logical_workflow_jobs
    WHERE run_id = instance.run_id
      AND invocation_id = instance.invocation_id
      AND id = instance.logical_job_id
    FOR SHARE;
    SELECT marker.root_invocation_id INTO STRICT root_invocation
    FROM logical_workflow_runs AS marker
    WHERE marker.run_id = instance.run_id
    FOR SHARE;
    SELECT NOT EXISTS (
        SELECT 1
        FROM unnest(logical_job.secret_reference_names) AS referenced_secret(name)
        WHERE NOT automata_reusable_secret_identity_chain_is_exact(
            instance.run_id,
            instance.invocation_id,
            referenced_secret.name
        )
    ) INTO all_reusable_secret_references_bound;

    IF NEW.created_at_ms <> instance.created_at_ms
       OR logical_job.environment_requirement_kind = 'unclassified'
       OR (
           logical_job.environment_requirement_kind = 'environment'
           AND NEW.environment_normalized_name IS NULL
       )
       OR (
           logical_job.environment_requirement_kind = 'none'
           AND NEW.environment_normalized_name IS NOT NULL
       )
       OR (
           instance.invocation_id = root_invocation
           AND NEW.reusable_secret_permission <> 'none'
       )
       OR (
           instance.invocation_id <> root_invocation
           AND cardinality(logical_job.secret_reference_names) > 0
           AND (
               NOT all_reusable_secret_references_bound
               OR NEW.reusable_secret_permission <> 'explicit'
           )
       )
       OR (
           instance.invocation_id <> root_invocation
           AND cardinality(logical_job.secret_reference_names) = 0
           AND NEW.reusable_secret_permission <> 'none'
       ) THEN
        RAISE EXCEPTION 'activation environment evidence is not exact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_environment_evidence_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_job_secret_binding_exact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
    selection job_secret_selections%ROWTYPE;
    workload_grant secret_workload_grants%ROWTYPE;
    attempt job_attempts%ROWTYPE;
    database_now_ms BIGINT;
    expected_digest BYTEA;
BEGIN
    database_now_ms := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.attempt_id FOR SHARE;
    SELECT * INTO STRICT selection FROM job_secret_selections
    WHERE attempt_id = NEW.attempt_id AND canonical_name = NEW.canonical_name FOR SHARE;
    SELECT * INTO STRICT workload_grant FROM secret_workload_grants
    WHERE tenant_id = NEW.tenant_id AND id = NEW.grant_id FOR SHARE;
    SELECT * INTO STRICT attempt FROM job_attempts
    WHERE id = NEW.attempt_id FOR SHARE;
    expected_digest := automata_job_secret_binding_digest(
        NEW.attempt_id, NEW.canonical_name, NEW.tenant_id, NEW.grant_id,
        NEW.lease_id, NEW.fencing_token
    );
    IF attempt.lifecycle <> 'leased'
       OR attempt.lease_id <> NEW.lease_id
       OR attempt.fencing_token <> NEW.fencing_token
       OR attempt.lease_expires_at_ms IS NULL
       OR database_now_ms >= attempt.lease_expires_at_ms
       OR selection.tenant_id <> NEW.tenant_id
       OR workload_grant.repository_id <> gate.repository_id
       OR workload_grant.run_id <> gate.run_id
       OR workload_grant.job_id <> gate.job_id
       OR workload_grant.attempt_id <> gate.attempt_id
       OR workload_grant.secret_id <> selection.secret_id
       OR workload_grant.secret_version_id <> selection.secret_version_id
       OR workload_grant.secret_version_number <> selection.secret_version_number
       OR workload_grant.environment_id IS DISTINCT FROM gate.environment_id
       OR workload_grant.environment_approval_request_id IS DISTINCT FROM gate.approval_request_id
       OR workload_grant.event_trust <> gate.event_trust
       OR workload_grant.source_kind <> gate.source_kind
       OR workload_grant.invocation_kind <> gate.invocation_kind
       OR workload_grant.reusable_secret_permission <> gate.reusable_secret_permission
       OR workload_grant.grant_mode <> 'readable_secret'
       OR workload_grant.lease_id <> NEW.lease_id
       OR workload_grant.fencing_token <> NEW.fencing_token
       OR workload_grant.status <> 'active'
       OR workload_grant.issued_at_ms > database_now_ms
       OR database_now_ms >= workload_grant.expires_at_ms
       OR workload_grant.expires_at_ms > attempt.lease_expires_at_ms
       OR expected_digest IS NULL
       OR NEW.binding_digest IS DISTINCT FROM expected_digest THEN
        RAISE EXCEPTION 'secret binding is not exact for the live lease fence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_secret_bindings_live_lease_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_job_secret_selection_exact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
    secret secrets%ROWTYPE;
    policy secret_policies%ROWTYPE;
    expected_digest BYTEA;
BEGIN
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.attempt_id FOR SHARE;
    SELECT * INTO STRICT secret FROM secrets
    WHERE tenant_id = NEW.tenant_id AND id = NEW.secret_id FOR SHARE;
    SELECT * INTO STRICT policy FROM secret_policies
    WHERE tenant_id = NEW.tenant_id AND secret_id = NEW.secret_id FOR SHARE;
    expected_digest := automata_job_secret_selection_digest(
        NEW.attempt_id, NEW.canonical_name, NEW.tenant_id, NEW.secret_id,
        NEW.secret_version_id, NEW.secret_version_number,
        NEW.scope_kind, NEW.environment_id
    );
    IF secret.canonical_name <> NEW.canonical_name
       OR secret.scope_kind <> NEW.scope_kind
       OR secret.environment_id IS DISTINCT FROM NEW.environment_id
       OR secret.current_version_id <> NEW.secret_version_id
       OR secret.current_version_number <> NEW.secret_version_number
       OR NOT automata_secret_is_available_to_gate(secret, policy, gate)
       OR expected_digest IS NULL
       OR NEW.binding_digest IS DISTINCT FROM expected_digest
       OR (NEW.scope_kind = 'repository' AND EXISTS (
           SELECT 1 FROM secrets AS higher
           JOIN secret_policies AS higher_policy
             ON higher_policy.tenant_id = higher.tenant_id
            AND higher_policy.secret_id = higher.id
           WHERE higher.tenant_id = gate.tenant_id
             AND higher.repository_id = gate.repository_id
             AND higher.environment_id = gate.environment_id
             AND higher.scope_kind = 'environment'
             AND higher.canonical_name = NEW.canonical_name
             AND automata_secret_is_available_to_gate(higher, higher_policy, gate)
       ))
       OR (NEW.scope_kind = 'tenant' AND EXISTS (
           SELECT 1 FROM secrets AS higher
           JOIN secret_policies AS higher_policy
             ON higher_policy.tenant_id = higher.tenant_id
            AND higher_policy.secret_id = higher.id
           WHERE higher.tenant_id = gate.tenant_id
             AND higher.repository_id = gate.repository_id
             AND higher.canonical_name = NEW.canonical_name
             AND higher.scope_kind IN ('repository', 'environment')
             AND (higher.scope_kind = 'repository'
                  OR higher.environment_id = gate.environment_id)
             AND automata_secret_is_available_to_gate(higher, higher_policy, gate)
       )) THEN
        RAISE EXCEPTION 'secret selection is not current, permitted, or highest precedence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_secret_selections_current_precedence';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_job_variable_binding_exact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
    variable workflow_variables%ROWTYPE;
    expected_digest BYTEA;
BEGIN
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.attempt_id FOR SHARE;
    SELECT * INTO STRICT variable FROM workflow_variables
    WHERE tenant_id = NEW.tenant_id AND id = NEW.variable_id FOR SHARE;
    expected_digest := automata_job_variable_binding_digest(
        NEW.attempt_id, NEW.canonical_name, NEW.tenant_id, NEW.variable_id,
        NEW.variable_version_id, NEW.variable_version_number,
        NEW.scope_kind, NEW.environment_id
    );
    IF variable.status <> 'active'
       OR variable.repository_id <> gate.repository_id
       OR variable.canonical_name <> NEW.canonical_name
       OR variable.scope_kind <> NEW.scope_kind
       OR variable.environment_id IS DISTINCT FROM NEW.environment_id
       OR variable.current_version_id <> NEW.variable_version_id
       OR variable.current_version_number <> NEW.variable_version_number
       OR expected_digest IS NULL
       OR NEW.binding_digest IS DISTINCT FROM expected_digest
       OR (NEW.scope_kind = 'environment'
           AND NEW.environment_id IS DISTINCT FROM gate.environment_id)
       OR (NEW.scope_kind = 'repository' AND EXISTS (
           SELECT 1 FROM workflow_variables AS higher
           WHERE higher.tenant_id = gate.tenant_id
             AND higher.repository_id = gate.repository_id
             AND higher.environment_id = gate.environment_id
             AND higher.scope_kind = 'environment'
             AND higher.canonical_name = NEW.canonical_name
             AND higher.status = 'active'
       )) THEN
        RAISE EXCEPTION 'variable binding is not the current highest-precedence version'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_variable_bindings_current_precedence';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_activation_preparation_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_activation_preparation_claims AS claim
        WHERE claim.logical_job_id = NEW.logical_job_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.state = 'preparing'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_started_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND NEW.bound_at_ms >= claim.claimed_at_ms
          AND NEW.bound_at_ms < claim.expires_at_ms
    ) THEN
        RAISE EXCEPTION 'logical activation preparation binding lacks a live exact fence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_activation_preparation_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_count BIGINT;
    finalized_count BIGINT;
    latest_ready BIGINT;
    expected_status TEXT;
BEGIN
    SELECT count(dependency.prerequisite_job_id),
           count(result.logical_job_id),
           greatest(job.created_at_ms, coalesce(max(result.finalized_at_ms), 0)),
           CASE
               WHEN coalesce(bool_or(
                   result.closure_has_failure
                   OR result.effective_conclusion IN ('failure', 'timed_out')
               ), FALSE) THEN 'failure'
               WHEN coalesce(bool_or(
                   result.closure_has_cancelled
                   OR result.effective_conclusion = 'cancelled'
               ), FALSE) THEN 'cancelled'
               WHEN coalesce(bool_or(
                   result.closure_has_skipped
                   OR result.effective_conclusion = 'skipped'
               ), FALSE) THEN 'skipped'
               ELSE 'success'
           END
      INTO expected_count, finalized_count, latest_ready, expected_status
    FROM logical_workflow_jobs AS job
    JOIN logical_workflow_invocations AS invocation
      ON invocation.run_id = job.run_id AND invocation.id = job.invocation_id
    JOIN logical_workflow_runs AS marker ON marker.run_id = job.run_id
    JOIN workflow_runs AS run ON run.id = marker.run_id
    LEFT JOIN logical_workflow_dependencies AS dependency
      ON dependency.run_id = job.run_id
     AND dependency.invocation_id = job.invocation_id
     AND dependency.logical_job_id = job.id
    LEFT JOIN logical_workflow_effective_job_results AS result
      ON result.run_id = dependency.run_id
     AND result.invocation_id = dependency.invocation_id
     AND result.logical_job_id = dependency.prerequisite_job_id
     AND result.claim_state = 'finalized'
    WHERE job.run_id = NEW.run_id
      AND job.invocation_id = NEW.invocation_id
      AND job.id = NEW.logical_job_id
      AND job.logical_key = NEW.logical_key
      AND job.source_order = NEW.source_order
      AND job.execution_kind = 'steps'
      AND job.state = 'pending'
      AND automata_logical_workflow_invocation_published(
          marker.run_id, invocation.id
      )
      AND invocation.plan_digest = NEW.plan_digest
      AND invocation.plan_object_key = NEW.plan_object_key
      AND invocation.plan_size_bytes = NEW.plan_size_bytes
      AND invocation.plan_media_type = NEW.plan_media_type
      AND invocation.plan_schema = NEW.plan_schema
      AND invocation.state IN ('pending', 'active')
      AND marker.orchestration_schema = 1
      AND marker.state IN ('pending', 'active')
      AND run.admission_epoch = 1
      AND run.plan_schema = 1
      AND run.workflow_id = NEW.workflow_id
      AND run.workflow_name = NEW.workflow_name
      AND run.git_ref = NEW.git_ref
      AND run.actor IS NOT DISTINCT FROM NEW.actor
      AND run.run_number = NEW.run_number
      AND run.run_attempt = NEW.run_attempt
      AND run.event_digest = NEW.event_digest
      AND run.event_object_key = NEW.event_object_key
      AND run.event_size_bytes = NEW.event_size_bytes
      AND run.event_media_type = NEW.event_media_type
    GROUP BY job.created_at_ms;

    IF NOT FOUND
        OR expected_count <> finalized_count
        OR expected_count <> NEW.prerequisite_count
        OR latest_ready <> NEW.evidence_ready_at_ms
        OR expected_status <> NEW.aggregate_status
        OR NEW.claimed_at_ms < latest_ready
        OR NEW.created_at_ms <> NEW.claimed_at_ms
    THEN
        RAISE EXCEPTION 'logical activation preparation claim lacks exact current evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_activation_preparation_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_prerequisites INTEGER;
    actual_prerequisites BIGINT;
BEGIN
    SELECT claim.prerequisite_count
      INTO expected_prerequisites
    FROM logical_workflow_activation_preparation_claims AS claim
    WHERE claim.logical_job_id = NEW.logical_job_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT count(*) INTO actual_prerequisites
    FROM logical_workflow_activation_preparation_prerequisites AS pin
    WHERE pin.logical_job_id = NEW.logical_job_id
      AND pin.output_count = (
          SELECT count(*)
          FROM logical_workflow_activation_preparation_outputs AS output
          WHERE output.logical_job_id = pin.logical_job_id
            AND output.prerequisite_job_id = pin.prerequisite_job_id
      );
    IF actual_prerequisites <> expected_prerequisites THEN
        RAISE EXCEPTION 'logical activation preparation pin set is incomplete'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_logical_activation_preparation_output() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_activation_preparation_prerequisites AS pin
        JOIN logical_workflow_activation_preparation_claims AS claim
          ON claim.logical_job_id = pin.logical_job_id
         AND claim.state = 'preparing'
        JOIN logical_workflow_effective_job_result_outputs AS output
          ON output.logical_job_id = pin.prerequisite_job_id
         AND output.output_name = NEW.output_name
        WHERE pin.logical_job_id = NEW.logical_job_id
          AND pin.prerequisite_job_id = NEW.prerequisite_job_id
          AND output.sensitivity = NEW.sensitivity
          AND output.public_value IS NOT DISTINCT FROM NEW.public_value
    ) THEN
        RAISE EXCEPTION 'logical activation output pin lacks exact classified result output'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_activation_preparation_prerequisite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_activation_preparation_claims AS claim
        JOIN logical_workflow_dependencies AS dependency
          ON dependency.run_id = claim.run_id
         AND dependency.invocation_id = claim.invocation_id
         AND dependency.logical_job_id = claim.logical_job_id
         AND dependency.prerequisite_job_id = NEW.prerequisite_job_id
        JOIN logical_workflow_jobs AS prerequisite_job
          ON prerequisite_job.run_id = dependency.run_id
         AND prerequisite_job.invocation_id = dependency.invocation_id
         AND prerequisite_job.id = dependency.prerequisite_job_id
        JOIN logical_workflow_effective_job_results AS result
          ON result.run_id = dependency.run_id
         AND result.invocation_id = dependency.invocation_id
         AND result.logical_job_id = dependency.prerequisite_job_id
         AND result.claim_state = 'finalized'
        WHERE claim.logical_job_id = NEW.logical_job_id
          AND claim.state = 'preparing'
          AND prerequisite_job.logical_key = NEW.logical_key
          AND prerequisite_job.source_order = NEW.source_order
          AND result.descriptor_digest = NEW.result_descriptor_digest
          AND result.outputs_digest = NEW.outputs_digest
          AND result.commit_digest = NEW.commit_digest
          AND result.effective_conclusion = NEW.effective_conclusion
          AND result.closure_has_failure = NEW.closure_has_failure
          AND result.closure_has_cancelled = NEW.closure_has_cancelled
          AND result.closure_has_skipped = NEW.closure_has_skipped
          AND result.output_count = NEW.output_count
          AND result.finalized_at_ms = NEW.finalized_at_ms
          AND NEW.finalized_at_ms <= claim.evidence_ready_at_ms
    ) THEN
        RAISE EXCEPTION 'logical activation prerequisite pin lacks exact finalized result'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_job_credential_requirements() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    name TEXT;
    previous TEXT;
BEGIN
    IF TG_OP = 'UPDATE' AND (
        NEW.environment_requirement_kind IS DISTINCT FROM OLD.environment_requirement_kind
        OR NEW.environment_template_digest IS DISTINCT FROM OLD.environment_template_digest
        OR NEW.secret_reference_names IS DISTINCT FROM OLD.secret_reference_names
        OR NEW.variable_reference_names IS DISTINCT FROM OLD.variable_reference_names
        OR NEW.credential_requirements_schema IS DISTINCT FROM OLD.credential_requirements_schema
    ) THEN
        RAISE EXCEPTION 'logical job credential requirements are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'logical_workflow_jobs_credential_requirements_immutable';
    END IF;

    IF COALESCE(array_ndims(NEW.secret_reference_names), 1) <> 1
       OR COALESCE(array_lower(NEW.secret_reference_names, 1), 1) <> 1
       OR array_position(NEW.secret_reference_names, NULL) IS NOT NULL
       OR COALESCE(array_ndims(NEW.variable_reference_names), 1) <> 1
       OR COALESCE(array_lower(NEW.variable_reference_names, 1), 1) <> 1
       OR array_position(NEW.variable_reference_names, NULL) IS NOT NULL THEN
        RAISE EXCEPTION 'credential references require dense one-dimensional arrays'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_jobs_credential_reference_arrays';
    END IF;

    FOREACH name IN ARRAY NEW.secret_reference_names LOOP
        IF name !~ '^[A-Z_][A-Z0-9_]*$'
           OR name ~ '^(GITHUB_|ACTIONS_|RUNNER_|AUTOMATA_)'
           OR octet_length(name) > 255
           OR (previous IS NOT NULL AND name <= previous) THEN
            RAISE EXCEPTION 'secret references must be sorted unique canonical names'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'logical_workflow_jobs_secret_references_canonical';
        END IF;
        previous := name;
    END LOOP;

    previous := NULL;
    FOREACH name IN ARRAY NEW.variable_reference_names LOOP
        IF name !~ '^[A-Z_][A-Z0-9_]*$'
           OR name ~ '^(GITHUB_|ACTIONS_|RUNNER_|AUTOMATA_)'
           OR octet_length(name) > 255
           OR (previous IS NOT NULL AND name <= previous) THEN
            RAISE EXCEPTION 'variable references must be sorted unique canonical names'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'logical_workflow_jobs_variable_references_canonical';
        END IF;
        previous := name;
    END LOOP;
    RETURN NEW;
END;
$_$;

CREATE FUNCTION automata_validate_logical_preparation_base_context() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_runs AS marker
        WHERE marker.run_id = NEW.run_id
          AND (
              (
                  marker.root_invocation_id = NEW.invocation_id
                  AND (
                      (
                          NEW.base_context_kind = 'root_empty'
                          AND marker.base_context_digest IS NULL
                          AND marker.base_context_object_key IS NULL
                          AND marker.base_context_size_bytes IS NULL
                          AND marker.base_context_media_type IS NULL
                          AND marker.base_context_schema IS NULL
                      ) OR (
                          NEW.base_context_kind = 'admission'
                          AND marker.base_context_digest = NEW.base_context_digest
                          AND marker.base_context_object_key =
                              NEW.base_context_object_key
                          AND marker.base_context_size_bytes =
                              NEW.base_context_size_bytes
                          AND marker.base_context_media_type =
                              NEW.base_context_media_type
                          AND marker.base_context_schema = NEW.base_context_schema
                          AND marker.base_context_schema = 1
                      )
                  )
              ) OR (
                  marker.root_invocation_id <> NEW.invocation_id
                  AND NEW.base_context_kind = 'admission'
                  AND automata_logical_workflow_invocation_published(
                      NEW.run_id, NEW.invocation_id
                  )
                  AND EXISTS (
                      SELECT 1
                      FROM logical_workflow_reusable_call_publications AS publication
                      WHERE publication.run_id = NEW.run_id
                        AND publication.child_invocation_id = NEW.invocation_id
                        AND publication.condition_matched
                        AND publication.child_graph_sealed_at_ms =
                            publication.published_at_ms
                        AND publication.runtime_context_digest =
                            NEW.base_context_digest
                        AND publication.runtime_context_object_key =
                            NEW.base_context_object_key
                        AND publication.runtime_context_size_bytes =
                            NEW.base_context_size_bytes
                        AND publication.runtime_context_media_type =
                            NEW.base_context_media_type
                        AND publication.runtime_context_schema =
                            NEW.base_context_schema
                        AND publication.runtime_context_schema = 1
                  )
              )
          )
    ) THEN
        RAISE EXCEPTION 'logical preparation base context disagrees with admission'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_workflow_activation_preparation_base_context_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_materialization_authority_profile() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_instances AS instance
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = instance.run_id
         AND publication.invocation_id = instance.invocation_id
         AND publication.logical_job_id = instance.logical_job_id
        WHERE instance.id = NEW.instance_id
          AND instance.run_id = NEW.run_id
          AND instance.invocation_id = NEW.invocation_id
          AND instance.logical_job_id = NEW.logical_job_id
          AND publication.authority_profile = NEW.authority_profile
    ) THEN
        RAISE EXCEPTION 'materialization claim authority profile is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_workflow_materialization_claims_profile_binding';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_materialization_real_claim_quarantine() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT;
    receipt logical_workflow_materialization_work_selections%ROWTYPE;
    existing_quarantine logical_workflow_materialization_work_quarantines%ROWTYPE;
    authority RECORD;
    internal_poison BOOLEAN := FALSE;
BEGIN
    SELECT * INTO receipt
    FROM logical_workflow_materialization_work_selections
    WHERE selection_id = NEW.selection_id
    FOR UPDATE;
    PERFORM 1
    FROM logical_workflow_work_selection_replay_horizons
    WHERE queue_name = 'materialization'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'materialization quarantine replay horizon is absent'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_quarantine_horizon_required';
    END IF;
    SELECT * INTO existing_quarantine
    FROM logical_workflow_materialization_work_quarantines
    WHERE instance_id = NEW.instance_id
    FOR UPDATE;
    IF existing_quarantine.instance_id IS NOT NULL THEN
        RAISE EXCEPTION 'materialization quarantine already has immutable evidence'
            USING ERRCODE = 'unique_violation',
                  CONSTRAINT = 'workflow_materialization_quarantine_already_exists';
    END IF;

    PERFORM automata_require_active_unquarantined_workflow_phase(
        NEW.run_id, NEW.invocation_id, NEW.logical_job_id, NEW.instance_id
    );

    SELECT repository.tenant_id, instance.run_id, instance.invocation_id,
           instance.logical_job_id, claim.origin_selection_id,
           claim.owner_id, claim.generation,
           claim.descriptor_digest AS digest, claim.claimed_at_ms,
           claim.expires_at_ms, claim.state
      INTO authority
    FROM logical_workflow_materialization_claims AS claim
    JOIN logical_workflow_instances AS instance ON instance.id = claim.instance_id
    JOIN workflow_runs AS run ON run.id = instance.run_id
    JOIN repositories AS repository ON repository.id = run.repository_id
    WHERE claim.instance_id = NEW.instance_id
    FOR UPDATE OF claim, instance;

    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    internal_poison := NEW.failure_kind = 'generation_exhausted'
        AND receipt.outcome = 'selecting';
    IF receipt.selection_id IS NULL
        OR receipt.owner_id IS DISTINCT FROM NEW.selection_owner_id
        OR receipt.requested_at_ms IS DISTINCT FROM NEW.selection_requested_at_ms
        OR receipt.duration_ms IS DISTINCT FROM NEW.selection_duration_ms
    THEN
        RAISE EXCEPTION 'materialization quarantine lacks its exact selection request'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_quarantine_selection_request_exact';
    END IF;
    IF internal_poison THEN
        IF receipt.claimed_at_ms IS NOT NULL OR receipt.expires_at_ms IS NOT NULL
            OR receipt.tenant_id IS NOT NULL OR receipt.run_id IS NOT NULL
            OR receipt.invocation_id IS NOT NULL OR receipt.logical_job_id IS NOT NULL
            OR receipt.instance_id IS NOT NULL OR receipt.generation IS NOT NULL
            OR receipt.authority_digest IS NOT NULL
            OR NEW.selection_generation <> NEW.authority_generation
            OR NEW.selection_claimed_at_ms > database_now
            OR database_now - NEW.selection_claimed_at_ms > 60000
            OR NEW.selection_expires_at_ms - database_now < 1000
            OR NEW.authority_generation <> 9223372036854775807
            OR NEW.authority_expires_at_ms > database_now
        THEN
            RAISE EXCEPTION 'materialization generation poison is not an exact provisional capture'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_materialization_quarantine_generation_poison_exact';
        END IF;
    ELSIF NEW.failure_kind = 'generation_exhausted'
        OR receipt.outcome <> 'claimed'
        OR receipt.claimed_at_ms IS DISTINCT FROM NEW.selection_claimed_at_ms
        OR receipt.expires_at_ms IS DISTINCT FROM NEW.selection_expires_at_ms
        OR receipt.tenant_id IS DISTINCT FROM NEW.tenant_id
        OR receipt.run_id IS DISTINCT FROM NEW.run_id
        OR receipt.invocation_id IS DISTINCT FROM NEW.invocation_id
        OR receipt.logical_job_id IS DISTINCT FROM NEW.logical_job_id
        OR receipt.instance_id IS DISTINCT FROM NEW.instance_id
        OR receipt.generation IS DISTINCT FROM NEW.selection_generation
        OR receipt.authority_digest IS DISTINCT FROM NEW.authority_digest
    THEN
        RAISE EXCEPTION 'materialization quarantine lacks the exact claimed receipt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_quarantine_selection_exact';
    END IF;

    IF authority IS NULL
        OR (authority.tenant_id, authority.run_id, authority.invocation_id,
            authority.logical_job_id)
           IS DISTINCT FROM
           (NEW.tenant_id, NEW.run_id, NEW.invocation_id, NEW.logical_job_id)
        OR authority.owner_id IS DISTINCT FROM NEW.authority_owner_id
        OR authority.generation IS DISTINCT FROM NEW.authority_generation
        OR authority.generation < NEW.selection_generation
        OR authority.digest IS DISTINCT FROM NEW.authority_digest
        OR authority.claimed_at_ms IS DISTINCT FROM NEW.authority_claimed_at_ms
        OR authority.expires_at_ms IS DISTINCT FROM NEW.authority_expires_at_ms
        OR authority.claimed_at_ms > database_now
        OR authority.state IS DISTINCT FROM 'materializing'
        OR (NOT internal_poison AND (
            authority.origin_selection_id IS DISTINCT FROM NEW.selection_id
            OR authority.owner_id IS DISTINCT FROM NEW.selection_owner_id))
    THEN
        RAISE EXCEPTION 'materialization quarantine lacks exact unsuperseded authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_quarantine_authority_exact';
    END IF;
    NEW.quarantined_at_ms := database_now;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_materialization_real_claim_renewal_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    selection logical_workflow_materialization_work_selections%ROWTYPE;
    authority RECORD;
    database_now BIGINT;
    receipt_count BIGINT;
    predecessor_exact BOOLEAN := FALSE;
BEGIN
    SELECT * INTO selection
    FROM logical_workflow_materialization_work_selections
    WHERE selection_id = NEW.selection_id;
    SELECT count(*) INTO receipt_count
    FROM logical_workflow_materialization_renewal_receipts
    WHERE selection_id = NEW.selection_id;
    SELECT claim.state, claim.origin_selection_id, claim.owner_id,
           claim.generation, claim.claimed_at_ms, claim.expires_at_ms,
           claim.descriptor_digest AS authority_digest,
           claim.runtime_policy_revision, claim.runtime_policy_digest,
           claim.expected_job_id, claim.expected_attempt_id
      INTO authority
    FROM logical_workflow_materialization_claims AS claim
    WHERE claim.instance_id = NEW.instance_id
    FOR UPDATE;
    IF selection.selection_id IS NULL OR selection.outcome <> 'claimed'
        OR (selection.tenant_id, selection.run_id, selection.invocation_id,
            selection.logical_job_id, selection.instance_id,
            selection.owner_id, selection.authority_digest)
           IS DISTINCT FROM
           (NEW.tenant_id, NEW.run_id, NEW.invocation_id,
            NEW.logical_job_id, NEW.instance_id,
            NEW.owner_id, NEW.authority_digest)
        OR (authority.expected_job_id, authority.expected_attempt_id)
           IS DISTINCT FROM (NEW.expected_job_id, NEW.expected_attempt_id)
    THEN
        RAISE EXCEPTION 'materialization renewal lacks its exact selection origin'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_renewal_selection_exact';
    END IF;
    IF NEW.predecessor_generation = selection.generation THEN
        predecessor_exact :=
            (NEW.predecessor_claimed_at_ms, NEW.predecessor_expires_at_ms,
             NEW.owner_id, NEW.authority_digest)
            IS NOT DISTINCT FROM
            (selection.claimed_at_ms, selection.expires_at_ms,
             selection.owner_id, selection.authority_digest);
    ELSE
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_materialization_renewal_receipts AS prior
            WHERE prior.selection_id = NEW.selection_id
              AND prior.instance_id = NEW.instance_id
              AND prior.successor_generation = NEW.predecessor_generation
              AND prior.successor_claimed_at_ms = NEW.predecessor_claimed_at_ms
              AND prior.successor_expires_at_ms = NEW.predecessor_expires_at_ms
              AND prior.owner_id = NEW.owner_id
              AND prior.runtime_policy_revision = NEW.runtime_policy_revision
              AND prior.runtime_policy_digest = NEW.runtime_policy_digest
              AND prior.authority_digest = NEW.authority_digest
              AND prior.expected_job_id = NEW.expected_job_id
              AND prior.expected_attempt_id = NEW.expected_attempt_id
        ) INTO predecessor_exact;
    END IF;
    IF predecessor_exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'materialization renewal does not extend its exact predecessor chain'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_renewal_predecessor_exact';
    END IF;
    IF receipt_count >= 64 THEN
        RAISE EXCEPTION 'materialization selection renewal history is full'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_renewal_history_bounded';
    END IF;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF authority IS NULL OR authority.state IS DISTINCT FROM 'materializing'
        OR authority.origin_selection_id IS DISTINCT FROM NEW.selection_id
        OR authority.owner_id IS DISTINCT FROM NEW.owner_id
        OR authority.generation IS DISTINCT FROM NEW.successor_generation
        OR authority.claimed_at_ms IS DISTINCT FROM NEW.successor_claimed_at_ms
        OR authority.expires_at_ms IS DISTINCT FROM NEW.successor_expires_at_ms
        OR authority.authority_digest IS DISTINCT FROM NEW.authority_digest
        OR (authority.runtime_policy_revision, authority.runtime_policy_digest)
           IS DISTINCT FROM
           (NEW.runtime_policy_revision, NEW.runtime_policy_digest)
        OR (authority.expected_job_id, authority.expected_attempt_id)
           IS DISTINCT FROM (NEW.expected_job_id, NEW.expected_attempt_id)
        OR NEW.successor_expires_at_ms - database_now < 1000
    THEN
        RAISE EXCEPTION 'materialization renewal lacks the exact live successor authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_renewal_successor_exact';
    END IF;
    NEW.validated_at_ms := database_now;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_materialization_work_selection_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    database_now BIGINT;
    replay_floor BIGINT;
    exact_evidence BOOLEAN := FALSE;
    ready_exists BOOLEAN := FALSE;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.outcome <> 'selecting' THEN
            RAISE EXCEPTION 'materialization selection must begin as a provisional reservation'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'workflow_materialization_selection_reservation_first';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.outcome <> 'selecting'
        OR NEW.selection_id IS DISTINCT FROM OLD.selection_id
        OR NEW.owner_id IS DISTINCT FROM OLD.owner_id
        OR NEW.requested_at_ms IS DISTINCT FROM OLD.requested_at_ms
        OR NEW.duration_ms IS DISTINCT FROM OLD.duration_ms
        OR NEW.outcome = 'selecting'
    THEN
        RAISE EXCEPTION 'materialization selection transition is immutable or invalid'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_transition';
    END IF;
    SELECT replay_floor_ms INTO replay_floor
    FROM logical_workflow_work_selection_replay_horizons
    WHERE queue_name = 'materialization'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'materialization selection replay authority is absent'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_horizon_required';
    END IF;
    database_now := floor(extract(epoch FROM clock_timestamp()) * 1000)::BIGINT;
    IF NEW.requested_at_ms <= replay_floor
        OR NEW.requested_at_ms < database_now - 60000
        OR NEW.requested_at_ms > database_now + 60000
    THEN
        RAISE EXCEPTION 'materialization selection request is outside replay authority'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_request_time';
    END IF;
    IF NEW.claimed_at_ms > database_now
        OR database_now - NEW.claimed_at_ms > 60000
        OR (NEW.outcome <> 'quarantined' AND (
            NEW.expires_at_ms <= database_now
            OR NEW.expires_at_ms - database_now < 1000
        ))
    THEN
        RAISE EXCEPTION 'materialization selection issue time is not database-current'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_database_time';
    END IF;

    IF NEW.outcome = 'claimed' THEN
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_materialization_claims AS claim
            JOIN logical_workflow_instances AS instance
              ON instance.id = claim.instance_id
            JOIN workflow_runs AS run ON run.id = instance.run_id
            JOIN repositories AS repository ON repository.id = run.repository_id
            WHERE claim.instance_id = NEW.instance_id
              AND repository.tenant_id = NEW.tenant_id
              AND instance.run_id = NEW.run_id
              AND instance.invocation_id = NEW.invocation_id
              AND instance.logical_job_id = NEW.logical_job_id
              AND claim.origin_selection_id = NEW.selection_id
              AND claim.owner_id = NEW.owner_id
              AND claim.generation = NEW.generation
              AND claim.descriptor_digest = NEW.authority_digest
              AND claim.claimed_at_ms = NEW.claimed_at_ms
              AND claim.expires_at_ms = NEW.expires_at_ms
              AND claim.state = 'materializing'
        ) INTO exact_evidence;
    ELSIF NEW.outcome = 'quarantined' THEN
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_materialization_work_quarantines AS quarantine
            WHERE quarantine.instance_id = NEW.instance_id
              AND quarantine.tenant_id = NEW.tenant_id
              AND quarantine.run_id = NEW.run_id
              AND quarantine.invocation_id = NEW.invocation_id
              AND quarantine.logical_job_id = NEW.logical_job_id
              AND quarantine.selection_id = NEW.selection_id
              AND quarantine.selection_owner_id = NEW.owner_id
              AND quarantine.selection_requested_at_ms = NEW.requested_at_ms
              AND quarantine.selection_duration_ms = NEW.duration_ms
              AND quarantine.selection_generation = NEW.generation
              AND quarantine.selection_claimed_at_ms = NEW.claimed_at_ms
              AND quarantine.selection_expires_at_ms = NEW.expires_at_ms
              AND quarantine.authority_digest = NEW.authority_digest
        ) INTO exact_evidence;
    ELSIF NEW.outcome = 'contended' THEN
        exact_evidence := TRUE;
    ELSE
        SELECT EXISTS (
            SELECT 1
            FROM logical_workflow_instances AS instance
            JOIN logical_workflow_activation_publications AS activation_publication
              ON activation_publication.run_id = instance.run_id
             AND activation_publication.invocation_id = instance.invocation_id
             AND activation_publication.logical_job_id = instance.logical_job_id
            JOIN logical_workflow_jobs AS job ON job.id = instance.logical_job_id
            JOIN logical_workflow_invocations AS invocation
              ON invocation.run_id = instance.run_id
             AND invocation.id = instance.invocation_id
            JOIN logical_workflow_runs AS marker ON marker.run_id = instance.run_id
            JOIN workflow_runs AS run ON run.id = marker.run_id
            LEFT JOIN logical_workflow_materialization_claims AS claim
              ON claim.instance_id = instance.id
            LEFT JOIN logical_workflow_materialization_work_quarantines AS quarantine
              ON quarantine.instance_id = instance.id
            WHERE activation_publication.condition_matched
              AND activation_publication.instance_count > 0
              AND job.state = 'activated'
              AND automata_logical_workflow_invocation_published(
                  marker.run_id, invocation.id
              )
              AND invocation.state IN ('pending', 'active')
              AND marker.state IN ('pending', 'active')
              AND run.status IN ('queued', 'in_progress')
              AND quarantine.instance_id IS NULL
              AND (claim.instance_id IS NULL OR (
                  claim.state = 'materializing'
                  AND claim.expires_at_ms <= NEW.claimed_at_ms
              ))
        ) INTO ready_exists;
        exact_evidence := NOT ready_exists;
    END IF;
    IF exact_evidence IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'materialization selection lacks exact durable evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_materialization_selection_receipt_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_missing_job_secret() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
BEGIN
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.attempt_id FOR SHARE;
    IF EXISTS (
        SELECT 1 FROM secrets AS secret
        JOIN secret_policies AS policy
          ON policy.tenant_id = secret.tenant_id AND policy.secret_id = secret.id
        WHERE secret.tenant_id = gate.tenant_id
          AND secret.canonical_name = NEW.canonical_name
          AND automata_secret_is_available_to_gate(secret, policy, gate)
    ) THEN
        RAISE EXCEPTION 'an available secret cannot resolve as missing'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_missing_secret_bindings_unavailable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_missing_job_variable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    gate job_environment_gates%ROWTYPE;
BEGIN
    SELECT * INTO STRICT gate FROM job_environment_gates
    WHERE attempt_id = NEW.attempt_id FOR SHARE;
    IF EXISTS (
        SELECT 1 FROM workflow_variables AS variable
        WHERE variable.tenant_id = gate.tenant_id
          AND variable.repository_id = gate.repository_id
          AND variable.canonical_name = NEW.canonical_name
          AND variable.status = 'active'
          AND (variable.scope_kind = 'repository'
               OR (variable.scope_kind = 'environment'
                   AND variable.environment_id = gate.environment_id))
    ) THEN
        RAISE EXCEPTION 'an available variable cannot resolve as missing'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'job_missing_variable_bindings_unavailable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_prepared_authority_profile() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_activation_preparation_claims AS claim
        JOIN logical_workflow_jobs AS job ON job.id = claim.logical_job_id
        WHERE claim.logical_job_id = NEW.logical_job_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.authority_profile = NEW.authority_profile
          AND job.authority_profile = NEW.authority_profile
    ) THEN
        RAISE EXCEPTION 'prepared activation authority profile is inconsistent'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'logical_workflow_activation_preparations_profile_binding';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_reusable_call_output_contract() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_call_output_contracts AS contract
        WHERE contract.run_id = NEW.run_id
          AND contract.child_invocation_id = NEW.child_invocation_id
          AND contract.mapping_count = (
              SELECT count(*)
              FROM logical_workflow_reusable_call_output_mappings AS mapping
              WHERE mapping.run_id = contract.run_id
                AND mapping.child_invocation_id = contract.child_invocation_id
          )
    ) OR EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_call_output_mappings AS mapping
        JOIN logical_workflow_reusable_outputs AS callee
          ON callee.run_id = mapping.run_id
         AND callee.invocation_id = mapping.child_invocation_id
         AND callee.output_key = mapping.child_output_name
        WHERE mapping.run_id = NEW.run_id
          AND mapping.child_invocation_id = NEW.child_invocation_id
          AND mapping.sensitivity = 'public'
          AND callee.sensitivity = 'secret_derived'
    ) THEN
        RAISE EXCEPTION 'reusable call output aliases disagree with their fixed contract'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_output_contract_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_reusable_call_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    durable logical_workflow_reusable_call_publications%ROWTYPE;
BEGIN
    SELECT * INTO durable
    FROM logical_workflow_reusable_call_publications AS publication
    WHERE publication.run_id = NEW.run_id
      AND publication.parent_invocation_id = NEW.parent_invocation_id
      AND publication.caller_logical_job_id = NEW.caller_logical_job_id;

    IF NOT FOUND
        OR durable.child_graph_sealed_at_ms IS NULL
        OR NOT EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_invocation_expansions AS planned
            JOIN logical_workflow_jobs AS caller
              ON caller.run_id = planned.run_id
             AND caller.invocation_id = planned.parent_invocation_id
             AND caller.id = planned.caller_logical_job_id
            WHERE planned.run_id = durable.run_id
              AND planned.invocation_id = durable.child_invocation_id
              AND planned.parent_invocation_id = durable.parent_invocation_id
              AND planned.caller_logical_job_id = durable.caller_logical_job_id
              AND caller.execution_kind = 'reusable_workflow'
              AND caller.state = CASE WHEN durable.condition_matched
                  THEN 'activated' ELSE 'skipped' END
              AND caller.activation_fence = durable.activation_generation
              AND caller.activation_input_digest = durable.activation_input_digest
              AND caller.authority_profile = durable.authority_profile
              AND caller.activation_owner_id IS NULL
              AND caller.activation_claimed_at_ms IS NULL
              AND caller.activation_expires_at_ms IS NULL
              AND caller.activation_origin_selection_id IS NULL
              AND caller.updated_at_ms = durable.published_at_ms
        )
        OR NOT EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_call_output_contracts AS contract
            WHERE contract.run_id = durable.run_id
              AND contract.child_invocation_id = durable.child_invocation_id
              AND contract.mapping_count = durable.output_mapping_count
              AND contract.mapping_digest = durable.output_mapping_digest
        )
        OR (durable.condition_matched AND NOT EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_invocation_expansions AS planned
            JOIN logical_workflow_reusable_workflow_catalog AS catalog
              ON catalog.run_id = planned.run_id
             AND catalog.catalog_entry_id = planned.catalog_entry_id
            JOIN logical_workflow_invocations AS child
              ON child.run_id = planned.run_id
             AND child.id = planned.invocation_id
            WHERE planned.run_id = durable.run_id
              AND planned.invocation_id = durable.child_invocation_id
              AND child.invocation_kind = 'reusable'
              AND child.plan_digest = catalog.plan_digest
              AND child.plan_object_key = catalog.plan_object_key
              AND child.plan_size_bytes = catalog.plan_size_bytes
              AND child.plan_media_type = catalog.plan_media_type
              AND child.plan_schema = catalog.plan_schema
              AND child.state = 'active'
        ))
        OR (durable.condition_matched AND (SELECT count(*)
            FROM logical_workflow_jobs
            WHERE run_id = durable.run_id
              AND invocation_id = durable.child_invocation_id)
           <> (SELECT count(*)
               FROM logical_workflow_reusable_expanded_jobs
               WHERE run_id = durable.run_id
                 AND invocation_id = durable.child_invocation_id))
        OR (durable.condition_matched AND EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_expanded_jobs AS planned
            LEFT JOIN logical_workflow_jobs AS active
              ON active.run_id = planned.run_id
             AND active.invocation_id = planned.invocation_id
             AND active.id = planned.logical_job_id
             AND active.logical_key = planned.logical_key
             AND active.source_order = planned.source_order
             AND active.execution_kind = planned.execution_kind
             AND active.state = 'pending'
             AND active.activation_fence = 0
             AND active.runtime_policy_revision = durable.runtime_policy_revision
             AND active.runtime_policy_digest = durable.runtime_policy_digest
            WHERE planned.run_id = durable.run_id
              AND planned.invocation_id = durable.child_invocation_id
              AND active.id IS NULL
        ))
        OR (durable.condition_matched AND (SELECT count(*)
            FROM logical_workflow_dependencies
            WHERE run_id = durable.run_id
              AND invocation_id = durable.child_invocation_id)
           <> (SELECT count(*)
               FROM logical_workflow_reusable_expanded_dependencies
               WHERE run_id = durable.run_id
                 AND invocation_id = durable.child_invocation_id))
        OR (durable.condition_matched AND EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_expanded_dependencies AS planned
            LEFT JOIN logical_workflow_dependencies AS active
              ON active.run_id = planned.run_id
             AND active.invocation_id = planned.invocation_id
             AND active.logical_job_id = planned.logical_job_id
             AND active.prerequisite_job_id = planned.prerequisite_job_id
            WHERE planned.run_id = durable.run_id
              AND planned.invocation_id = durable.child_invocation_id
              AND active.logical_job_id IS NULL
        ))
        OR (NOT durable.condition_matched AND EXISTS (
            SELECT 1
            FROM logical_workflow_invocations AS child
            WHERE child.run_id = durable.run_id
              AND child.id = durable.child_invocation_id
        ))
    THEN
        RAISE EXCEPTION 'reusable call publication did not seal its exact child graph'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_graph_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_reusable_call_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matched BOOLEAN;
    expected_conclusion TEXT;
    durable logical_workflow_reusable_call_results%ROWTYPE;
BEGIN
    SELECT * INTO durable
    FROM logical_workflow_reusable_call_results AS result
    WHERE result.run_id = NEW.run_id
      AND result.parent_invocation_id = NEW.parent_invocation_id
      AND result.caller_logical_job_id = NEW.caller_logical_job_id;

    SELECT publication.condition_matched
      INTO matched
    FROM logical_workflow_reusable_call_publications AS publication
    WHERE publication.run_id = NEW.run_id
      AND publication.parent_invocation_id = NEW.parent_invocation_id
      AND publication.caller_logical_job_id = NEW.caller_logical_job_id;

    IF durable.run_id IS NULL
        OR durable.sealed_at_ms IS NULL
        OR matched IS NULL
        OR durable.child_job_count <> (
            SELECT count(*)
            FROM logical_workflow_reusable_call_result_jobs AS evidence
            WHERE evidence.run_id = NEW.run_id
              AND evidence.parent_invocation_id = NEW.parent_invocation_id
              AND evidence.caller_logical_job_id = NEW.caller_logical_job_id
        )
        OR durable.output_count <> (
            SELECT count(*)
            FROM logical_workflow_reusable_call_result_outputs AS output
            WHERE output.run_id = NEW.run_id
              AND output.parent_invocation_id = NEW.parent_invocation_id
              AND output.caller_logical_job_id = NEW.caller_logical_job_id
        )
        OR EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_call_result_jobs AS evidence
            LEFT JOIN logical_workflow_jobs AS child_job
              ON child_job.run_id = evidence.run_id
             AND child_job.invocation_id = durable.child_invocation_id
             AND child_job.id = evidence.child_logical_job_id
             AND child_job.source_order = evidence.source_order
            LEFT JOIN logical_workflow_job_results AS child_result
              ON child_result.run_id = child_job.run_id
             AND child_result.invocation_id = child_job.invocation_id
             AND child_result.logical_job_id = child_job.id
             AND child_result.descriptor_digest = evidence.descriptor_digest
             AND child_result.outputs_digest = evidence.outputs_digest
             AND child_result.commit_digest = evidence.commit_digest
             AND child_result.effective_conclusion = evidence.effective_conclusion
             AND child_result.closure_has_failure = evidence.closure_has_failure
             AND child_result.closure_has_cancelled = evidence.closure_has_cancelled
             AND child_result.closure_has_skipped = evidence.closure_has_skipped
            LEFT JOIN logical_workflow_job_result_claims AS child_claim
              ON child_claim.logical_job_id = child_result.logical_job_id
             AND child_claim.state = 'finalized'
            WHERE evidence.run_id = NEW.run_id
              AND evidence.parent_invocation_id = NEW.parent_invocation_id
              AND evidence.caller_logical_job_id = NEW.caller_logical_job_id
              AND (child_result.logical_job_id IS NULL
                   OR child_claim.logical_job_id IS NULL)
        )
        OR EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_call_result_outputs AS output
            LEFT JOIN logical_workflow_reusable_outputs AS declared
              ON declared.run_id = output.run_id
             AND declared.invocation_id = durable.child_invocation_id
             AND declared.output_key = output.callee_output_name
             AND declared.source_order = output.source_order
             AND declared.sensitivity = output.sensitivity
            WHERE output.run_id = NEW.run_id
              AND output.parent_invocation_id = NEW.parent_invocation_id
              AND output.caller_logical_job_id = NEW.caller_logical_job_id
              AND declared.output_key IS NULL
        )
    THEN
        RAISE EXCEPTION 'reusable call result did not seal exact child evidence and outputs'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_result_exact';
    END IF;

    IF NOT matched THEN
        IF durable.child_job_count <> 0
            OR durable.output_count <> 0
            OR durable.effective_conclusion <> 'skipped'
        THEN
            RAISE EXCEPTION 'skipped reusable call result is not exact'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'logical_workflow_reusable_call_result_skipped';
        END IF;
        RETURN NULL;
    END IF;

    SELECT CASE
        WHEN bool_or(evidence.effective_conclusion = 'failure') THEN 'failure'
        WHEN bool_or(evidence.effective_conclusion = 'timed_out') THEN 'timed_out'
        WHEN bool_or(evidence.effective_conclusion = 'cancelled') THEN 'cancelled'
        WHEN bool_or(evidence.effective_conclusion = 'success') THEN 'success'
        ELSE 'skipped'
    END
      INTO expected_conclusion
    FROM logical_workflow_reusable_call_result_jobs AS evidence
    WHERE evidence.run_id = NEW.run_id
      AND evidence.parent_invocation_id = NEW.parent_invocation_id
      AND evidence.caller_logical_job_id = NEW.caller_logical_job_id;
    IF expected_conclusion IS DISTINCT FROM durable.effective_conclusion THEN
        RAISE EXCEPTION 'reusable call result conclusion is inexact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_call_result_conclusion';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_reusable_workflow_expansion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_catalog_count BIGINT;
    expected_invocation_count BIGINT;
    expected_job_count BIGINT;
    expected_maximum_depth SMALLINT;
    expected_root_invocation_id UUID;
    durable_catalog_count BIGINT;
    durable_invocation_count BIGINT;
    durable_job_count BIGINT;
    durable_maximum_depth SMALLINT;
BEGIN
    SELECT catalog_entry_count,
           invocation_count,
           expanded_job_count,
           maximum_depth,
           root_invocation_id
      INTO expected_catalog_count,
           expected_invocation_count,
           expected_job_count,
           expected_maximum_depth,
           expected_root_invocation_id
    FROM logical_workflow_reusable_workflow_runs
    WHERE run_id = NEW.run_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'reusable workflow expansion lacks its replay receipt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_receipt_required';
    END IF;

    SELECT count(*) INTO durable_catalog_count
    FROM logical_workflow_reusable_workflow_catalog
    WHERE run_id = NEW.run_id;

    SELECT count(*) INTO durable_invocation_count
    FROM logical_workflow_reusable_invocation_expansions
    WHERE run_id = NEW.run_id;

    SELECT count(*) INTO durable_job_count
    FROM logical_workflow_reusable_expanded_jobs
    WHERE run_id = NEW.run_id;

    SELECT COALESCE(max(depth), 0) INTO durable_maximum_depth
    FROM logical_workflow_reusable_invocation_expansions
    WHERE run_id = NEW.run_id;

    IF durable_catalog_count <> expected_catalog_count
        OR durable_invocation_count <> expected_invocation_count
        OR durable_job_count <> expected_job_count
        OR durable_maximum_depth <> expected_maximum_depth
    THEN
        RAISE EXCEPTION 'reusable workflow expansion counts disagree with its replay receipt'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_counts_exact';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_runs AS marker
        JOIN workflow_runs AS run ON run.id = marker.run_id
        JOIN workflow_definitions AS workflow ON workflow.id = run.workflow_id
        JOIN workflow_snapshots AS snapshot ON snapshot.id = run.snapshot_id
        JOIN logical_workflow_reusable_invocation_expansions AS root
          ON root.run_id = marker.run_id
         AND root.invocation_id = marker.root_invocation_id
         AND root.depth = 0
        JOIN logical_workflow_reusable_workflow_catalog AS catalog
          ON catalog.run_id = root.run_id
         AND catalog.catalog_entry_id = root.catalog_entry_id
        WHERE marker.run_id = NEW.run_id
          AND marker.root_invocation_id = expected_root_invocation_id
          AND marker.admission_graph_sealed_at_ms IS NOT NULL
          AND catalog.workflow_path = workflow.path
          AND catalog.source_digest = snapshot.source_digest
          AND catalog.source_revision = encode(run.head_sha, 'hex')
          AND catalog.source_object_key = snapshot.source_object_key
          AND catalog.source_size_bytes = snapshot.source_size_bytes
          AND catalog.source_media_type = snapshot.source_media_type
          AND catalog.plan_digest = run.plan_digest
          AND catalog.plan_object_key = run.plan_object_key
          AND catalog.plan_size_bytes = run.plan_size_bytes
          AND catalog.plan_media_type = run.plan_media_type
          AND catalog.plan_schema = run.plan_schema
    ) THEN
        RAISE EXCEPTION 'reusable workflow expansion lacks its exact sealed root'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_root_exact';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS child
        LEFT JOIN logical_workflow_reusable_invocation_expansions AS parent
          ON parent.run_id = child.run_id
         AND parent.invocation_id = child.parent_invocation_id
        WHERE child.run_id = NEW.run_id
          AND child.depth > 0
          AND (
              parent.invocation_id IS NULL
              OR child.depth <> parent.depth + 1
              OR child.call_path[1:parent.depth + 1] <> parent.call_path
          )
    ) THEN
        RAISE EXCEPTION 'reusable workflow expansion parent lineage is inexact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_parent_exact';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS invocation
        JOIN logical_workflow_reusable_workflow_catalog AS catalog
          ON catalog.run_id = invocation.run_id
         AND catalog.catalog_entry_id = invocation.catalog_entry_id
        JOIN workflow_runs AS run ON run.id = invocation.run_id
        WHERE invocation.run_id = NEW.run_id
          AND (
              invocation.workflow_path <> catalog.workflow_path
              OR catalog.source_revision <> encode(run.head_sha, 'hex')
              OR (
                  invocation.depth > 0
                  AND catalog.invocation_contract_digest IS NULL
              )
              OR (
                  SELECT count(*)
                  FROM logical_workflow_reusable_expanded_jobs AS job
                  WHERE job.run_id = invocation.run_id
                    AND job.invocation_id = invocation.invocation_id
              ) <> catalog.logical_job_count
              OR (
                  SELECT count(*)
                  FROM logical_workflow_reusable_expanded_jobs AS job
                  WHERE job.run_id = invocation.run_id
                    AND job.invocation_id = invocation.invocation_id
                    AND job.execution_kind = 'reusable_workflow'
              ) <> catalog.reusable_call_count
          )
    ) THEN
        RAISE EXCEPTION 'reusable workflow catalog and expanded invocation disagree'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_catalog_exact';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS invocation
        CROSS JOIN LATERAL unnest(invocation.call_path) AS path(value)
        WHERE invocation.run_id = NEW.run_id
        GROUP BY invocation.invocation_id
        HAVING count(*) <> count(DISTINCT path.value)
    ) THEN
        RAISE EXCEPTION 'reusable workflow expansion contains a call cycle'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_acyclic';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS child
        JOIN logical_workflow_reusable_expanded_jobs AS caller
          ON caller.run_id = child.run_id
         AND caller.invocation_id = child.parent_invocation_id
         AND caller.logical_job_id = child.caller_logical_job_id
        WHERE child.run_id = NEW.run_id
          AND child.depth > 0
          AND caller.execution_kind <> 'reusable_workflow'
    ) OR EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_expanded_jobs AS caller
        WHERE caller.run_id = NEW.run_id
          AND caller.execution_kind = 'reusable_workflow'
          AND NOT EXISTS (
              SELECT 1
              FROM logical_workflow_reusable_invocation_expansions AS child
              WHERE child.run_id = caller.run_id
                AND child.parent_invocation_id = caller.invocation_id
                AND child.caller_logical_job_id = caller.logical_job_id
          )
    ) THEN
        RAISE EXCEPTION 'reusable workflow callsites and child invocations disagree'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_callsites_exact';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS invocation
        LEFT JOIN logical_workflow_reusable_permission_snapshots AS permissions
          ON permissions.run_id = invocation.run_id
         AND permissions.invocation_id = invocation.invocation_id
         AND permissions.permission_digest = invocation.permission_digest
        WHERE invocation.run_id = NEW.run_id
          AND permissions.invocation_id IS NULL
    ) THEN
        RAISE EXCEPTION 'reusable workflow expansion lacks an exact permission reduction'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_permissions_exact';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS child
        JOIN logical_workflow_reusable_invocation_expansions AS parent
          ON parent.run_id = child.run_id
         AND parent.invocation_id = child.parent_invocation_id
        JOIN logical_workflow_reusable_permission_snapshots AS child_permissions
          ON child_permissions.run_id = child.run_id
         AND child_permissions.invocation_id = child.invocation_id
        JOIN logical_workflow_reusable_permission_snapshots AS parent_permissions
          ON parent_permissions.run_id = parent.run_id
         AND parent_permissions.invocation_id = parent.invocation_id
        WHERE child.run_id = NEW.run_id
          AND child.depth > 0
          AND (
              CASE child_permissions.default_level
                  WHEN 'none' THEN 0 WHEN 'read' THEN 1 ELSE 2
              END > CASE parent_permissions.default_level
                  WHEN 'none' THEN 0 WHEN 'read' THEN 1 ELSE 2
              END
              OR EXISTS (
                  SELECT 1
                  FROM (
                      SELECT permission_name
                      FROM logical_workflow_reusable_permission_grants
                      WHERE run_id = child.run_id
                        AND invocation_id = child.invocation_id
                      UNION
                      SELECT permission_name
                      FROM logical_workflow_reusable_permission_grants
                      WHERE run_id = parent.run_id
                        AND invocation_id = parent.invocation_id
                  ) AS scope
                  LEFT JOIN logical_workflow_reusable_permission_grants AS child_grant
                    ON child_grant.run_id = child.run_id
                   AND child_grant.invocation_id = child.invocation_id
                   AND child_grant.permission_name = scope.permission_name
                  LEFT JOIN logical_workflow_reusable_permission_grants AS parent_grant
                    ON parent_grant.run_id = parent.run_id
                   AND parent_grant.invocation_id = parent.invocation_id
                   AND parent_grant.permission_name = scope.permission_name
                  WHERE CASE COALESCE(
                      child_grant.permission_level,
                      child_permissions.default_level
                  ) WHEN 'none' THEN 0 WHEN 'read' THEN 1 ELSE 2 END
                  > CASE COALESCE(
                      parent_grant.permission_level,
                      parent_permissions.default_level
                  ) WHEN 'none' THEN 0 WHEN 'read' THEN 1 ELSE 2 END
              )
          )
    ) THEN
        RAISE EXCEPTION 'reusable workflow permissions exceed their caller ceiling'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_permission_reduction';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS invocation
        WHERE invocation.run_id = NEW.run_id
          AND (
              invocation.input_binding_count <> (
                  SELECT count(*)
                  FROM logical_workflow_reusable_input_bindings AS input
                  WHERE input.run_id = invocation.run_id
                    AND input.invocation_id = invocation.invocation_id
              )
              OR invocation.secret_binding_count <> (
                  SELECT count(*)
                  FROM logical_workflow_reusable_secret_bindings AS secret
                  WHERE secret.run_id = invocation.run_id
                    AND secret.invocation_id = invocation.invocation_id
              )
              OR invocation.output_count <> (
                  SELECT count(*)
                  FROM logical_workflow_reusable_outputs AS output
                  WHERE output.run_id = invocation.run_id
                    AND output.invocation_id = invocation.invocation_id
              )
              OR invocation.permission_grant_count <> (
                  SELECT count(*)
                  FROM logical_workflow_reusable_permission_grants AS permission_grant
                  WHERE permission_grant.run_id = invocation.run_id
                    AND permission_grant.invocation_id = invocation.invocation_id
              )
              OR invocation.dependency_count <> (
                  SELECT count(*)
                  FROM logical_workflow_reusable_expanded_dependencies AS dependency
                  WHERE dependency.run_id = invocation.run_id
                    AND dependency.invocation_id = invocation.invocation_id
              )
          )
    ) THEN
        RAISE EXCEPTION 'reusable workflow typed boundary counts are inexact'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_expansion_contract_counts_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_secret_key_rotation_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM secret_version_envelopes
        WHERE tenant_id = NEW.tenant_id
          AND secret_version_id = NEW.secret_version_id
          AND envelope_generation = NEW.previous_envelope_generation
    ) THEN
        RAISE EXCEPTION 'rotation source envelope does not exist'
            USING ERRCODE = 'foreign_key_violation',
                  CONSTRAINT = 'secret_key_rotation_items_previous_envelope';
    END IF;
    IF NEW.replacement_envelope_generation IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM secret_version_envelopes
           WHERE tenant_id = NEW.tenant_id
             AND secret_version_id = NEW.secret_version_id
             AND envelope_generation = NEW.replacement_envelope_generation
       ) THEN
        RAISE EXCEPTION 'rotation replacement envelope does not exist'
            USING ERRCODE = 'foreign_key_violation',
                  CONSTRAINT = 'secret_key_rotation_items_replacement_envelope';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_secret_workload_grant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    stored_scope TEXT;
    stored_repository UUID;
    stored_environment UUID;
    stored_secret_status TEXT;
    stored_version_status TEXT;
    repository_access_mode TEXT;
    minimum_trust TEXT;
    permits_forks BOOLEAN;
    permits_dependabot BOOLEAN;
    attempt_exposure TEXT;
    environment_protection TEXT;
    approval_status TEXT;
BEGIN
    SELECT
        secret.scope_kind,
        secret.repository_id,
        secret.environment_id,
        secret.status,
        policy.tenant_repository_access_mode,
        policy.minimum_event_trust,
        policy.allow_fork_pull_requests,
        policy.allow_dependabot
    INTO STRICT
        stored_scope,
        stored_repository,
        stored_environment,
        stored_secret_status,
        repository_access_mode,
        minimum_trust,
        permits_forks,
        permits_dependabot
    FROM secrets AS secret
    JOIN secret_policies AS policy
      ON policy.tenant_id = secret.tenant_id
     AND policy.secret_id = secret.id
    WHERE secret.tenant_id = NEW.tenant_id
      AND secret.id = NEW.secret_id;

    IF stored_secret_status <> 'active' THEN
        RAISE EXCEPTION 'only active secrets may be granted to workloads'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_active_secret';
    END IF;

    SELECT status
    INTO STRICT stored_version_status
    FROM secret_version_lifecycle
    WHERE tenant_id = NEW.tenant_id
      AND secret_version_id = NEW.secret_version_id;

    IF stored_version_status <> 'active' THEN
        RAISE EXCEPTION 'only active secret versions may be granted to workloads'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_active_version';
    END IF;

    IF stored_scope = 'tenant' THEN
        IF repository_access_mode = 'selected_repositories'
           AND NOT EXISTS (
               SELECT 1
               FROM secret_repository_access AS access
               WHERE access.tenant_id = NEW.tenant_id
                 AND access.secret_id = NEW.secret_id
                 AND access.repository_id = NEW.repository_id
           ) THEN
            RAISE EXCEPTION 'tenant secret is not granted to this repository'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'secret_workload_grants_scope';
        END IF;
    ELSIF stored_scope = 'repository' THEN
        IF stored_repository <> NEW.repository_id THEN
            RAISE EXCEPTION 'repository secret does not enclose this workload'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'secret_workload_grants_scope';
        END IF;
    ELSIF stored_scope = 'environment' THEN
        IF stored_repository <> NEW.repository_id
           OR stored_environment IS DISTINCT FROM NEW.environment_id THEN
            RAISE EXCEPTION 'environment secret does not enclose this workload'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'secret_workload_grants_scope';
        END IF;
    ELSE
        RAISE EXCEPTION 'unknown secret scope'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_scope';
    END IF;

    IF minimum_trust = 'trusted' AND NEW.event_trust <> 'trusted' THEN
        RAISE EXCEPTION 'secret policy rejects untrusted events'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_event_policy';
    END IF;
    IF NEW.source_kind = 'fork' AND NOT permits_forks THEN
        RAISE EXCEPTION 'secret policy rejects fork pull requests'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_event_policy';
    END IF;
    IF NEW.source_kind = 'dependabot' AND NOT permits_dependabot THEN
        RAISE EXCEPTION 'secret policy rejects Dependabot workloads'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_event_policy';
    END IF;

    SELECT secret_exposure_class
    INTO STRICT attempt_exposure
    FROM job_attempts
    WHERE id = NEW.attempt_id;

    IF NEW.grant_mode = 'readable_secret'
       AND attempt_exposure <> 'readable_secret' THEN
        RAISE EXCEPTION 'readable grants require a readable-secret attempt cap'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_exposure_class';
    END IF;
    IF NEW.grant_mode = 'capability_only'
       AND attempt_exposure = 'secretless' THEN
        RAISE EXCEPTION 'capability grants require a credential-aware attempt cap'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'secret_workload_grants_exposure_class';
    END IF;

    IF NEW.environment_id IS NOT NULL THEN
        SELECT protection_mode
        INTO STRICT environment_protection
        FROM repository_environments
        WHERE tenant_id = NEW.tenant_id
          AND repository_id = NEW.repository_id
          AND id = NEW.environment_id;

        IF environment_protection = 'required_approvals' THEN
            IF NEW.environment_approval_request_id IS NULL THEN
                RAISE EXCEPTION 'protected environment approval is required'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'secret_workload_grants_environment_approval';
            END IF;
            SELECT status
            INTO STRICT approval_status
            FROM protected_environment_approval_requests
            WHERE tenant_id = NEW.tenant_id
              AND id = NEW.environment_approval_request_id;
            IF approval_status <> 'approved' THEN
                RAISE EXCEPTION 'protected environment is not approved'
                    USING ERRCODE = 'check_violation',
                          CONSTRAINT = 'secret_workload_grants_environment_approval';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_server_cancellation_terminal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    cancellation attempt_cancellation_intents%ROWTYPE;
    attempt job_attempts%ROWTYPE;
    expected_digest BYTEA;
BEGIN
    IF NEW.terminal_authority IS DISTINCT FROM 'server_cancellation' THEN
        RETURN NEW;
    END IF;

    SELECT * INTO STRICT cancellation
    FROM attempt_cancellation_intents
    WHERE attempt_id = NEW.attempt_id
      AND operation_id = NEW.server_cancellation_operation_id;

    SELECT * INTO STRICT attempt
    FROM job_attempts
    WHERE id = NEW.attempt_id;

    expected_digest := automata_server_cancellation_terminal_digest(
        cancellation.attempt_id,
        cancellation.operation_id,
        cancellation.requested_by,
        cancellation.reason,
        cancellation.requested_at_ms
    );
    IF cancellation.delivery_session_id IS NOT NULL
       OR cancellation.delivery_command_sequence IS NOT NULL
       OR cancellation.acknowledged_at_ms IS NOT NULL
       OR attempt.lifecycle <> 'queued'
       OR attempt.fencing_token <> 0
       OR attempt.lease_id IS NOT NULL
       OR attempt.runner_id IS NOT NULL
       OR attempt.runner_session_id IS NOT NULL
       OR attempt.runner_session_epoch IS NOT NULL
       OR attempt.runner_generation IS NOT NULL
       OR attempt.runner_slot IS NOT NULL
       OR attempt.lease_issued_at_ms IS NOT NULL
       OR attempt.lease_expires_at_ms IS NOT NULL
       OR NEW.server_cancellation_digest IS DISTINCT FROM expected_digest
       OR NEW.conclusion <> 'cancelled'
       OR NEW.completed_at_ms <> cancellation.requested_at_ms
       OR NEW.committed_at_ms <> cancellation.requested_at_ms
    THEN
        RAISE EXCEPTION 'server cancellation terminal lacks exact queued intent authority'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
EXCEPTION
    WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION 'server cancellation terminal lacks exact queued intent authority'
            USING ERRCODE = '23514';
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_activation_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_jobs AS job
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = job.run_id
         AND invocation.id = job.invocation_id
        JOIN logical_workflow_runs AS marker ON marker.run_id = job.run_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        JOIN logical_workflow_activation_preparations AS preparation
          ON preparation.run_id = job.run_id
         AND preparation.invocation_id = job.invocation_id
         AND preparation.logical_job_id = job.id
        JOIN logical_workflow_activation_preparation_claims AS preparation_claim
          ON preparation_claim.logical_job_id = preparation.logical_job_id
         AND preparation_claim.state = 'prepared'
        WHERE job.run_id = NEW.run_id
          AND job.invocation_id = NEW.invocation_id
          AND job.id = NEW.logical_job_id
          AND job.execution_kind = 'steps'
          AND job.state = 'activating'
          AND job.activation_owner_id = NEW.activation_owner_id
          AND job.activation_fence = NEW.activation_generation
          AND job.activation_input_digest = NEW.activation_input_digest
          AND job.activation_claimed_at_ms = NEW.activation_claimed_at_ms
          AND job.activation_expires_at_ms = NEW.activation_expires_at_ms
          AND job.activation_claimed_at_ms <= NEW.published_at_ms
          AND job.activation_expires_at_ms > NEW.published_at_ms
          AND preparation.activation_input_digest = NEW.activation_input_digest
          AND preparation.bound_at_ms <= job.activation_claimed_at_ms
          AND invocation.plan_schema = 1
          AND invocation.state IN ('pending', 'active')
          AND automata_logical_workflow_invocation_published(
              marker.run_id, invocation.id
          )
          AND marker.orchestration_schema = 1
          AND marker.state IN ('pending', 'active')
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
    ) THEN
        RAISE EXCEPTION 'logical workflow publication lacks an exact prepared live claim'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_activation_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.state = 'pending'
        AND NEW.state IN ('activated', 'skipped')
        AND EXISTS (
            SELECT 1
            FROM logical_workflow_reusable_call_publications AS publication
            WHERE publication.run_id = NEW.run_id
              AND publication.parent_invocation_id = NEW.invocation_id
              AND publication.caller_logical_job_id = NEW.id
              AND publication.child_graph_sealed_at_ms IS NOT NULL
              AND publication.activation_generation = NEW.activation_fence
              AND publication.activation_input_digest = NEW.activation_input_digest
              AND publication.authority_profile = NEW.authority_profile
              AND publication.published_at_ms = NEW.updated_at_ms
              AND NEW.state = CASE WHEN publication.condition_matched
                  THEN 'activated' ELSE 'skipped' END
        )
    THEN
        RETURN NEW;
    END IF;

    IF NEW.state IN ('completed', 'failed', 'cancelled', 'skipped')
        AND NEW.state IS DISTINCT FROM OLD.state
        AND OLD.state IN ('activated', 'skipped')
        AND EXISTS (
            SELECT 1
            FROM logical_workflow_job_results AS result
            WHERE result.run_id = NEW.run_id
              AND result.invocation_id = NEW.invocation_id
              AND result.logical_job_id = NEW.id
              AND result.finalized_at_ms = NEW.updated_at_ms
              AND NEW.state = CASE result.effective_conclusion
                  WHEN 'success' THEN 'completed'
                  WHEN 'failure' THEN 'failed'
                  WHEN 'timed_out' THEN 'failed'
                  WHEN 'cancelled' THEN 'cancelled'
                  WHEN 'skipped' THEN 'skipped'
              END
        )
    THEN
        RETURN NEW;
    END IF;

    IF NEW.state IN ('activated', 'skipped')
        AND NEW.state IS DISTINCT FROM OLD.state
        AND NOT (
            OLD.state = 'activating'
            AND NEW.activation_owner_id IS NULL
            AND NEW.activation_claimed_at_ms IS NULL
            AND NEW.activation_expires_at_ms IS NULL
            AND EXISTS (
                SELECT 1
                FROM logical_workflow_activation_publications AS publication
                WHERE publication.run_id = NEW.run_id
                  AND publication.invocation_id = NEW.invocation_id
                  AND publication.logical_job_id = NEW.id
                  AND publication.activation_owner_id = OLD.activation_owner_id
                  AND publication.activation_generation = OLD.activation_fence
                  AND publication.activation_input_digest = OLD.activation_input_digest
                  AND publication.activation_claimed_at_ms = OLD.activation_claimed_at_ms
                  AND publication.activation_expires_at_ms = OLD.activation_expires_at_ms
                  AND publication.published_at_ms = NEW.updated_at_ms
                  AND (
                      (NEW.state = 'activated' AND publication.condition_matched)
                      OR (NEW.state = 'skipped'
                          AND NOT publication.condition_matched
                          AND publication.instance_count = 0)
                  )
            )
        )
    THEN
        RAISE EXCEPTION 'logical workflow activation transition lacks exact publication'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_concrete_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_materialization_claims AS claim
        JOIN logical_workflow_instances AS instance
          ON instance.id = claim.instance_id
         AND instance.run_id = claim.run_id
         AND instance.invocation_id = claim.invocation_id
         AND instance.logical_job_id = claim.logical_job_id
        JOIN logical_workflow_jobs AS logical_job
          ON logical_job.run_id = instance.run_id
         AND logical_job.invocation_id = instance.invocation_id
         AND logical_job.id = instance.logical_job_id
        JOIN workflow_runs AS run ON run.id = instance.run_id
        JOIN jobs AS job ON job.id = NEW.job_id
        JOIN job_attempts AS attempt ON attempt.id = NEW.initial_attempt_id
        WHERE claim.instance_id = NEW.instance_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.logical_job_id = NEW.logical_job_id
          AND claim.state = 'materializing'
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.expected_job_id = NEW.job_id
          AND claim.expected_attempt_id = NEW.initial_attempt_id
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_started_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND NEW.committed_at_ms >= claim.claimed_at_ms
          AND NEW.committed_at_ms < claim.expires_at_ms
          AND logical_job.state = 'activated'
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
          AND run.event_digest = NEW.event_digest
          AND run.event_object_key = NEW.event_object_key
          AND run.event_size_bytes = NEW.event_size_bytes
          AND run.event_media_type = NEW.event_media_type
          AND instance.job_ir_digest = job.job_ir_digest
          AND instance.job_ir_object_key = job.job_ir_object_key
          AND instance.job_ir_size_bytes = job.job_ir_size_bytes
          AND instance.job_ir_version = job.job_ir_schema
          AND instance.runtime_context_digest = NEW.runtime_context_digest
          AND instance.runtime_context_object_key =
              NEW.runtime_context_object_key
          AND instance.runtime_context_size_bytes =
              NEW.runtime_context_size_bytes
          AND instance.runtime_context_media_type =
              NEW.runtime_context_media_type
          AND instance.runtime_context_schema = NEW.runtime_context_schema
          AND job.run_id = NEW.run_id
          AND job.job_key = NEW.job_key
          AND job.display_name = NEW.display_name
          AND job.requirements = NEW.requirements
          AND job.admission_epoch = 1
          AND job.job_ir_schema = 1
          AND attempt.job_id = job.id
          AND attempt.attempt_number = 1
          AND attempt.lifecycle = 'queued'
          AND attempt.fencing_token = 0
          AND attempt.lease_id IS NULL
          AND attempt.runner_id IS NULL
          AND attempt.lease_issued_at_ms IS NULL
          AND attempt.lease_expires_at_ms IS NULL
          AND attempt.lease_failures = 0
          AND attempt.queued_at_ms = NEW.committed_at_ms
          AND attempt.changed_at_ms = NEW.committed_at_ms
    ) THEN
        RAISE EXCEPTION 'logical workflow concrete job lacks exact live materialization evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_concurrency_cancellation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM workflow_runs AS target
        JOIN logical_workflow_runs AS marker ON marker.run_id = target.id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = marker.run_id
         AND invocation.id = marker.root_invocation_id
        JOIN workflow_runs AS preempting ON preempting.id = NEW.preempting_run_id
        WHERE target.id = NEW.run_id
          AND target.repository_id = preempting.repository_id
          AND target.concurrency_group_key IS NOT NULL
          AND target.concurrency_group_key = preempting.concurrency_group_key
          AND target.status = NEW.prior_workflow_status
          AND target.updated_at_ms = NEW.prior_workflow_updated_at_ms
          AND marker.root_invocation_id = NEW.root_invocation_id
          AND marker.state = NEW.prior_marker_state
          AND marker.revision = NEW.prior_marker_revision
          AND marker.updated_at_ms = NEW.prior_marker_updated_at_ms
          AND invocation.state = NEW.prior_invocation_state
          AND invocation.revision = NEW.prior_invocation_revision
          AND invocation.updated_at_ms = NEW.prior_invocation_updated_at_ms
          AND preempting.status IN ('queued', 'in_progress')
          AND preempting.created_at_ms <= NEW.cancelled_at_ms
        FOR KEY SHARE OF target, marker, invocation, preempting
    ) THEN
        RAISE EXCEPTION 'Logical concurrency cancellation lacks exact active-run evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_concurrency_cancellation_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_instance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_count INTEGER;
    expected_time BIGINT;
BEGIN
    SELECT publication.instance_count, publication.published_at_ms
      INTO expected_count, expected_time
    FROM logical_workflow_activation_publications AS publication
    WHERE publication.run_id = NEW.run_id
      AND publication.invocation_id = NEW.invocation_id
      AND publication.logical_job_id = NEW.logical_job_id;
    IF NOT FOUND
        OR expected_count = 0
        OR NEW.matrix_total <> expected_count
        OR NEW.matrix_index >= expected_count
        OR NEW.created_at_ms <> expected_time
    THEN
        RAISE EXCEPTION 'logical workflow instance disagrees with its publication'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_instance_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_run UUID;
    target_invocation UUID;
    target_job UUID;
    expected_count INTEGER;
    actual_count BIGINT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_run := OLD.run_id;
        target_invocation := OLD.invocation_id;
        target_job := OLD.logical_job_id;
    ELSE
        target_run := NEW.run_id;
        target_invocation := NEW.invocation_id;
        target_job := NEW.logical_job_id;
    END IF;
    SELECT publication.instance_count
      INTO expected_count
    FROM logical_workflow_activation_publications AS publication
    WHERE publication.run_id = target_run
      AND publication.invocation_id = target_invocation
      AND publication.logical_job_id = target_job;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT count(*) INTO actual_count
    FROM logical_workflow_instances AS instance
    WHERE instance.run_id = target_run
      AND instance.invocation_id = target_invocation
      AND instance.logical_job_id = target_job;
    IF actual_count <> expected_count THEN
        RAISE EXCEPTION 'logical workflow publication instance count is incomplete'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_instance_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_instance_result_claims AS claim
        JOIN attempt_terminal_results AS terminal
          ON terminal.attempt_id = claim.attempt_id
        JOIN job_attempts AS attempt ON attempt.id = terminal.attempt_id
        JOIN jobs AS job ON job.id = attempt.job_id
        JOIN logical_workflow_concrete_jobs AS concrete
          ON concrete.instance_id = claim.instance_id
         AND concrete.job_id = claim.job_id
         AND concrete.initial_attempt_id = claim.attempt_id
        JOIN logical_workflow_instances AS instance
          ON instance.id = concrete.instance_id
        JOIN workflow_runs AS run ON run.id = concrete.run_id
        WHERE claim.attempt_id = NEW.attempt_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.logical_job_id = NEW.logical_job_id
          AND claim.instance_id = NEW.instance_id
          AND claim.job_id = NEW.job_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.state = 'projecting'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_started_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND NEW.finalized_at_ms >= claim.claimed_at_ms
          AND NEW.finalized_at_ms < claim.expires_at_ms
          AND terminal.terminal_authority = NEW.terminal_authority
          AND (
              (
                  terminal.terminal_authority = 'runner'
                  AND terminal.result_digest = NEW.result_digest
                  AND terminal.result_object_key = NEW.result_object_key
                  AND terminal.result_size_bytes = NEW.result_size_bytes
                  AND terminal.result_schema = NEW.result_schema
                  AND NEW.server_cancellation_operation_id IS NULL
                  AND NEW.server_cancellation_digest IS NULL
                  AND (
                      (attempt.secret_exposure_class = 'secretless'
                       AND NEW.secret_exposure_class = 'secretless')
                      OR (attempt.secret_exposure_class = 'capability_only'
                          AND NEW.secret_exposure_class IN (
                              'secretless', 'capability_only'
                          ))
                      OR (attempt.secret_exposure_class = 'readable_secret'
                          AND NEW.secret_exposure_class = 'readable_secret')
                  )
              ) OR (
                  terminal.terminal_authority = 'server_cancellation'
                  AND terminal.server_cancellation_operation_id =
                      NEW.server_cancellation_operation_id
                  AND terminal.server_cancellation_digest =
                      NEW.server_cancellation_digest
                  AND NEW.result_digest IS NULL
                  AND NEW.result_object_key IS NULL
                  AND NEW.result_size_bytes IS NULL
                  AND NEW.result_schema IS NULL
                  AND NEW.secret_exposure_class = 'secretless'
                  AND NEW.output_count = 0
              )
          )
          AND terminal.conclusion = NEW.raw_conclusion
          AND terminal.completed_at_ms = NEW.result_completed_at_ms
          AND terminal.committed_at_ms = NEW.result_committed_at_ms
          AND terminal.logical_workflow_logical_job_id = NEW.logical_job_id
          AND terminal.logical_workflow_terminal_ordinal = NEW.terminal_ordinal
          AND job.run_id = NEW.run_id
          AND job.job_ir_digest = NEW.job_ir_digest
          AND job.job_ir_object_key = NEW.job_ir_object_key
          AND job.job_ir_size_bytes = NEW.job_ir_size_bytes
          AND job.job_ir_schema = NEW.job_ir_schema
          AND job.admission_epoch = 1
          AND instance.run_id = NEW.run_id
          AND instance.invocation_id = NEW.invocation_id
          AND instance.logical_job_id = NEW.logical_job_id
          AND instance.job_ir_digest = NEW.job_ir_digest
          AND instance.job_ir_object_key = NEW.job_ir_object_key
          AND instance.job_ir_size_bytes = NEW.job_ir_size_bytes
          AND instance.job_ir_media_type = NEW.job_ir_media_type
          AND instance.job_ir_version = NEW.job_ir_schema
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
    ) THEN
        RAISE EXCEPTION 'logical workflow instance result lacks exact terminal authority/fence evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_instance_result_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM attempt_terminal_results AS terminal
        JOIN job_attempts AS attempt ON attempt.id = terminal.attempt_id
        JOIN jobs AS job ON job.id = attempt.job_id
        JOIN logical_workflow_concrete_jobs AS concrete
          ON concrete.job_id = job.id
         AND concrete.initial_attempt_id = attempt.id
        JOIN logical_workflow_materialization_claims AS materialization
          ON materialization.instance_id = concrete.instance_id
        JOIN logical_workflow_instances AS instance
          ON instance.id = concrete.instance_id
         AND instance.run_id = concrete.run_id
         AND instance.invocation_id = concrete.invocation_id
         AND instance.logical_job_id = concrete.logical_job_id
        JOIN logical_workflow_jobs AS logical_job
          ON logical_job.run_id = concrete.run_id
         AND logical_job.invocation_id = concrete.invocation_id
         AND logical_job.id = concrete.logical_job_id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = logical_job.run_id
         AND invocation.id = logical_job.invocation_id
        JOIN logical_workflow_runs AS marker ON marker.run_id = concrete.run_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        WHERE terminal.attempt_id = NEW.attempt_id
          AND concrete.run_id = NEW.run_id
          AND concrete.invocation_id = NEW.invocation_id
          AND concrete.logical_job_id = NEW.logical_job_id
          AND concrete.instance_id = NEW.instance_id
          AND concrete.job_id = NEW.job_id
          AND materialization.state = 'materialized'
          AND job.run_id = concrete.run_id
          AND job.admission_epoch = 1
          AND job.job_ir_schema = 1
          AND job.job_ir_digest = instance.job_ir_digest
          AND job.job_ir_object_key = instance.job_ir_object_key
          AND job.job_ir_size_bytes = instance.job_ir_size_bytes
          AND instance.job_ir_version = 1
          AND instance.job_ir_media_type =
              'application/vnd.automata.job-ir.protobuf'
          AND (
              (terminal.terminal_authority = 'runner'
               AND terminal.result_schema = 1)
              OR terminal.terminal_authority = 'server_cancellation'
          )
          AND terminal.completed_at_ms >= 0
          AND terminal.committed_at_ms >= terminal.completed_at_ms
          AND NEW.claimed_at_ms >= terminal.committed_at_ms
          AND (
              (terminal.conclusion = 'success' AND attempt.lifecycle = 'succeeded')
              OR (terminal.conclusion = 'failure' AND attempt.lifecycle = 'failed')
              OR (terminal.conclusion = 'cancelled' AND attempt.lifecycle = 'cancelled')
              OR (terminal.conclusion = 'timed_out' AND attempt.lifecycle = 'timed_out')
              OR (terminal.conclusion = 'skipped' AND attempt.lifecycle = 'skipped')
          )
          AND logical_job.execution_kind = 'steps'
          AND logical_job.state = 'activated'
          AND invocation.plan_schema = 1
          AND invocation.state IN ('pending', 'active')
          AND marker.orchestration_schema = 1
          AND marker.state IN ('pending', 'active')
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
    ) THEN
        RAISE EXCEPTION 'logical workflow result claim lacks one exact current terminal attempt'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_instance_result_output() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_instance_results AS result
        JOIN logical_workflow_instance_result_claims AS claim
          ON claim.instance_id = result.instance_id
        WHERE result.instance_id = NEW.instance_id
          AND claim.state = 'projecting'
          AND result.claim_owner_id = claim.owner_id
          AND result.claim_generation = claim.generation
          AND result.claim_started_at_ms = claim.claimed_at_ms
          AND result.claim_expires_at_ms = claim.expires_at_ms
    ) THEN
        RAISE EXCEPTION 'logical workflow output lacks a live instance-result fence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_instance_result_quarantine() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_due logical_workflow_instance_result_due%ROWTYPE;
BEGIN
    SELECT due.* INTO current_due
    FROM logical_workflow_instance_result_due AS due
    WHERE due.attempt_id = NEW.attempt_id
    FOR UPDATE;
    IF NOT FOUND OR ROW(
        NEW.tenant_id, NEW.run_id, NEW.invocation_id, NEW.logical_job_id,
        NEW.source_order, NEW.ready_at_ms, NEW.available_at_ms
    ) IS DISTINCT FROM ROW(
        current_due.tenant_id, current_due.run_id, current_due.invocation_id,
        current_due.logical_job_id, current_due.source_order,
        current_due.ready_at_ms, current_due.available_at_ms
    ) THEN
        RAISE EXCEPTION 'instance-result quarantine lacks its exact current due target'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'logical_workflow_instance_result_quarantines_due_exact';
    END IF;

    IF NEW.claim_owner_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_instance_result_claims AS claim
        WHERE claim.attempt_id = NEW.attempt_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.logical_job_id = NEW.logical_job_id
          AND claim.state = 'projecting'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_claimed_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND claim.descriptor_digest = NEW.claim_descriptor_digest
    ) THEN
        RAISE EXCEPTION 'instance-result quarantine lacks its exact live claim'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'logical_workflow_instance_result_quarantines_claim_exact';
    END IF;

    NEW.quarantined_at_ms :=
        floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_job_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_result_claims AS claim
        JOIN logical_workflow_jobs AS job
          ON job.id = claim.logical_job_id
         AND job.run_id = claim.run_id
         AND job.invocation_id = claim.invocation_id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = job.run_id
         AND invocation.id = job.invocation_id
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = job.run_id
         AND publication.invocation_id = job.invocation_id
         AND publication.logical_job_id = job.id
        WHERE claim.logical_job_id = NEW.logical_job_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.state = 'aggregating'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_started_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND NEW.finalized_at_ms >= claim.claimed_at_ms
          AND NEW.finalized_at_ms < claim.expires_at_ms
          AND job.logical_key = NEW.logical_key
          AND job.source_order = NEW.source_order
          AND job.execution_kind = 'steps'
          AND job.state IN ('activated', 'skipped')
          AND invocation.plan_digest = NEW.plan_digest
          AND invocation.plan_object_key = NEW.plan_object_key
          AND invocation.plan_size_bytes = NEW.plan_size_bytes
          AND invocation.plan_media_type = NEW.plan_media_type
          AND invocation.plan_schema = NEW.plan_schema
          AND publication.activation_output_digest = NEW.activation_output_digest
          AND publication.condition_matched = NEW.condition_matched
          AND publication.instance_count = NEW.instance_count
    ) AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_result_claims AS claim
        JOIN logical_workflow_jobs AS job
          ON job.id = claim.logical_job_id
         AND job.run_id = claim.run_id
         AND job.invocation_id = claim.invocation_id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = job.run_id
         AND invocation.id = job.invocation_id
        JOIN logical_workflow_reusable_call_publications AS publication
          ON publication.run_id = job.run_id
         AND publication.parent_invocation_id = job.invocation_id
         AND publication.caller_logical_job_id = job.id
        JOIN logical_workflow_reusable_call_results AS call_result
          ON call_result.run_id = publication.run_id
         AND call_result.parent_invocation_id = publication.parent_invocation_id
         AND call_result.caller_logical_job_id = publication.caller_logical_job_id
        WHERE claim.logical_job_id = NEW.logical_job_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.state = 'aggregating'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_started_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND NEW.finalized_at_ms >= claim.claimed_at_ms
          AND NEW.finalized_at_ms < claim.expires_at_ms
          AND job.logical_key = NEW.logical_key
          AND job.source_order = NEW.source_order
          AND job.execution_kind = 'reusable_workflow'
          AND job.state IN ('activated', 'skipped')
          AND invocation.plan_digest = NEW.plan_digest
          AND invocation.plan_object_key = NEW.plan_object_key
          AND invocation.plan_size_bytes = NEW.plan_size_bytes
          AND invocation.plan_media_type = NEW.plan_media_type
          AND invocation.plan_schema = NEW.plan_schema
          AND publication.publication_digest = NEW.activation_output_digest
          AND publication.condition_matched = NEW.condition_matched
          AND NEW.instance_count = CASE WHEN publication.condition_matched
              THEN 1 ELSE 0 END
          AND call_result.sealed_at_ms IS NOT NULL
          AND call_result.parent_result_descriptor_digest = NEW.descriptor_digest
          AND call_result.parent_instances_digest = NEW.instances_digest
          AND call_result.parent_prerequisites_digest = NEW.prerequisites_digest
          AND call_result.parent_outputs_digest = NEW.outputs_digest
          AND call_result.parent_commit_digest = NEW.commit_digest
          AND call_result.effective_conclusion = NEW.effective_conclusion
          AND NEW.output_count = CASE WHEN publication.condition_matched
              THEN publication.output_mapping_count ELSE 0 END
          AND NEW.prerequisite_count = (
              SELECT count(*)
              FROM logical_workflow_dependencies AS dependency
              WHERE dependency.run_id = job.run_id
                AND dependency.invocation_id = job.invocation_id
                AND dependency.logical_job_id = job.id
          )
    ) THEN
        RAISE EXCEPTION 'logical workflow job result lacks exact plan/publication/fence evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_job_result_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_jobs AS job
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = job.run_id
         AND invocation.id = job.invocation_id
        JOIN logical_workflow_runs AS marker ON marker.run_id = job.run_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = job.run_id
         AND publication.invocation_id = job.invocation_id
         AND publication.logical_job_id = job.id
        WHERE job.run_id = NEW.run_id
          AND job.invocation_id = NEW.invocation_id
          AND job.id = NEW.logical_job_id
          AND job.execution_kind = 'steps'
          AND job.state IN ('activated', 'skipped')
          AND invocation.plan_schema = 1
          AND invocation.plan_media_type =
              'application/vnd.automata.workflow-plan+json'
          AND invocation.state IN ('pending', 'active')
          AND marker.orchestration_schema = 1
          AND marker.state IN ('pending', 'active')
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
          AND NEW.claimed_at_ms >= publication.published_at_ms
          AND (
              (publication.instance_count = 0 AND NOT EXISTS (
                  SELECT 1 FROM logical_workflow_instances AS instance
                  WHERE instance.run_id = job.run_id
                    AND instance.invocation_id = job.invocation_id
                    AND instance.logical_job_id = job.id
              )) OR (
                  publication.instance_count > 0
                  AND publication.instance_count = (
                      SELECT count(*)
                      FROM logical_workflow_instances AS instance
                      JOIN logical_workflow_instance_results AS result
                        ON result.instance_id = instance.id
                       AND result.run_id = instance.run_id
                       AND result.invocation_id = instance.invocation_id
                       AND result.logical_job_id = instance.logical_job_id
                      JOIN logical_workflow_instance_result_claims AS claim
                        ON claim.instance_id = result.instance_id
                       AND claim.state = 'finalized'
                      WHERE instance.run_id = job.run_id
                        AND instance.invocation_id = job.invocation_id
                        AND instance.logical_job_id = job.id
                  )
                  AND NEW.claimed_at_ms >= COALESCE((
                      SELECT max(result.finalized_at_ms)
                      FROM logical_workflow_instance_results AS result
                      WHERE result.run_id = job.run_id
                        AND result.invocation_id = job.invocation_id
                        AND result.logical_job_id = job.id
                  ), 0)
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM logical_workflow_dependencies AS dependency
              LEFT JOIN logical_workflow_effective_job_results AS prerequisite
                ON prerequisite.logical_job_id = dependency.prerequisite_job_id
               AND prerequisite.run_id = dependency.run_id
               AND prerequisite.invocation_id = dependency.invocation_id
              WHERE dependency.run_id = job.run_id
                AND dependency.invocation_id = job.invocation_id
                AND dependency.logical_job_id = job.id
                AND (prerequisite.logical_job_id IS NULL
                     OR prerequisite.claim_state IS DISTINCT FROM 'finalized'
                     OR NEW.claimed_at_ms < prerequisite.finalized_at_ms)
          )
    ) AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_jobs AS job
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = job.run_id
         AND invocation.id = job.invocation_id
        JOIN logical_workflow_runs AS marker ON marker.run_id = job.run_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        JOIN logical_workflow_reusable_call_publications AS publication
          ON publication.run_id = job.run_id
         AND publication.parent_invocation_id = job.invocation_id
         AND publication.caller_logical_job_id = job.id
        JOIN logical_workflow_reusable_call_results AS call_result
          ON call_result.run_id = publication.run_id
         AND call_result.parent_invocation_id = publication.parent_invocation_id
         AND call_result.caller_logical_job_id = publication.caller_logical_job_id
        WHERE job.run_id = NEW.run_id
          AND job.invocation_id = NEW.invocation_id
          AND job.id = NEW.logical_job_id
          AND job.execution_kind = 'reusable_workflow'
          AND job.state IN ('activated', 'skipped')
          AND invocation.plan_schema = 1
          AND invocation.plan_media_type =
              'application/vnd.automata.workflow-plan+json'
          AND invocation.state IN ('pending', 'active')
          AND marker.orchestration_schema = 1
          AND marker.state IN ('pending', 'active')
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
          AND publication.child_graph_sealed_at_ms IS NOT NULL
          AND call_result.sealed_at_ms IS NOT NULL
          AND call_result.parent_result_descriptor_digest = NEW.descriptor_digest
          AND NEW.claimed_at_ms >= call_result.completed_at_ms
          AND NOT EXISTS (
              SELECT 1
              FROM logical_workflow_dependencies AS dependency
              LEFT JOIN logical_workflow_effective_job_results AS prerequisite
                ON prerequisite.logical_job_id = dependency.prerequisite_job_id
               AND prerequisite.run_id = dependency.run_id
               AND prerequisite.invocation_id = dependency.invocation_id
              WHERE dependency.run_id = job.run_id
                AND dependency.invocation_id = job.invocation_id
                AND dependency.logical_job_id = job.id
                AND (prerequisite.logical_job_id IS NULL
                     OR prerequisite.claim_state IS DISTINCT FROM 'finalized'
                     OR NEW.claimed_at_ms < prerequisite.finalized_at_ms)
          )
    ) THEN
        RAISE EXCEPTION 'logical workflow job-result claim is not exactly ready'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_job_result_instance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_results AS logical_result
        JOIN logical_workflow_job_result_claims AS logical_claim
          ON logical_claim.logical_job_id = logical_result.logical_job_id
        JOIN logical_workflow_instance_results AS instance_result
          ON instance_result.logical_job_id = logical_result.logical_job_id
         AND instance_result.instance_id = NEW.instance_id
        JOIN logical_workflow_instances AS instance
          ON instance.id = instance_result.instance_id
         AND instance.logical_job_id = instance_result.logical_job_id
        JOIN logical_workflow_instance_result_claims AS instance_claim
          ON instance_claim.instance_id = instance_result.instance_id
        WHERE logical_result.logical_job_id = NEW.logical_job_id
          AND logical_claim.state = 'aggregating'
          AND logical_result.claim_owner_id = logical_claim.owner_id
          AND logical_result.claim_generation = logical_claim.generation
          AND instance.matrix_index = NEW.matrix_index
          AND instance_result.terminal_ordinal = NEW.terminal_ordinal
          AND instance_result.descriptor_digest = NEW.instance_descriptor_digest
          AND instance_result.outputs_digest = NEW.instance_outputs_digest
          AND instance_result.commit_digest = NEW.instance_commit_digest
          AND instance_result.raw_conclusion = NEW.raw_conclusion
          AND instance_result.effective_conclusion = NEW.effective_conclusion
          AND instance_claim.state = 'finalized'
    ) AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_results AS logical_result
        JOIN logical_workflow_job_result_claims AS logical_claim
          ON logical_claim.logical_job_id = logical_result.logical_job_id
        JOIN logical_workflow_reusable_call_results AS call_result
          ON call_result.run_id = logical_result.run_id
         AND call_result.parent_invocation_id = logical_result.invocation_id
         AND call_result.caller_logical_job_id = logical_result.logical_job_id
        JOIN logical_workflow_reusable_call_publications AS publication
          ON publication.run_id = call_result.run_id
         AND publication.parent_invocation_id = call_result.parent_invocation_id
         AND publication.caller_logical_job_id = call_result.caller_logical_job_id
        WHERE logical_result.logical_job_id = NEW.logical_job_id
          AND logical_claim.state = 'aggregating'
          AND logical_result.claim_owner_id = logical_claim.owner_id
          AND logical_result.claim_generation = logical_claim.generation
          AND publication.condition_matched
          AND call_result.sealed_at_ms IS NOT NULL
          AND call_result.caller_instance_id = NEW.instance_id
          AND NEW.matrix_index = 0
          AND NEW.terminal_ordinal = 1
          AND call_result.descriptor_digest = NEW.instance_descriptor_digest
          AND call_result.outputs_digest = NEW.instance_outputs_digest
          AND call_result.commit_digest = NEW.instance_commit_digest
          AND call_result.effective_conclusion = NEW.raw_conclusion
          AND call_result.effective_conclusion = NEW.effective_conclusion
    ) THEN
        RAISE EXCEPTION 'logical workflow logical result instance evidence is not exact'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_job_result_output() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_results AS logical_result
        JOIN logical_workflow_job_result_claims AS claim
          ON claim.logical_job_id = logical_result.logical_job_id
        JOIN logical_workflow_jobs AS job
          ON job.run_id = logical_result.run_id
         AND job.invocation_id = logical_result.invocation_id
         AND job.id = logical_result.logical_job_id
        WHERE logical_result.logical_job_id = NEW.logical_job_id
          AND claim.state = 'aggregating'
          AND logical_result.claim_owner_id = claim.owner_id
          AND logical_result.claim_generation = claim.generation
          AND logical_result.claim_started_at_ms = claim.claimed_at_ms
          AND logical_result.claim_expires_at_ms = claim.expires_at_ms
          AND (
              job.execution_kind = 'steps'
              OR (
                  job.execution_kind = 'reusable_workflow'
                  AND EXISTS (
                      SELECT 1
                      FROM logical_workflow_reusable_call_output_mappings AS mapping
                      JOIN logical_workflow_reusable_call_results AS call_result
                        ON call_result.run_id = mapping.run_id
                       AND call_result.child_invocation_id =
                           mapping.child_invocation_id
                       AND call_result.parent_invocation_id = job.invocation_id
                       AND call_result.caller_logical_job_id = job.id
                       AND call_result.sealed_at_ms IS NOT NULL
                      JOIN logical_workflow_reusable_call_result_outputs AS child_output
                        ON child_output.run_id = call_result.run_id
                       AND child_output.parent_invocation_id =
                           call_result.parent_invocation_id
                       AND child_output.caller_logical_job_id =
                           call_result.caller_logical_job_id
                       AND child_output.callee_output_name =
                           mapping.child_output_name
                      WHERE mapping.run_id = job.run_id
                        AND mapping.parent_output_name = NEW.output_name
                        AND mapping.sensitivity = NEW.sensitivity
                        AND NEW.public_value IS NOT DISTINCT FROM CASE
                            WHEN mapping.sensitivity = 'public'
                            THEN child_output.public_value
                            ELSE NULL
                        END
                  )
              )
          )
    ) THEN
        RAISE EXCEPTION 'logical workflow logical output lacks exact result evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_job_result_prerequisite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_results AS logical_result
        JOIN logical_workflow_job_result_claims AS logical_claim
          ON logical_claim.logical_job_id = logical_result.logical_job_id
        JOIN logical_workflow_dependencies AS dependency
          ON dependency.logical_job_id = logical_result.logical_job_id
         AND dependency.run_id = logical_result.run_id
         AND dependency.invocation_id = logical_result.invocation_id
         AND dependency.prerequisite_job_id = NEW.prerequisite_job_id
        JOIN logical_workflow_jobs AS prerequisite_job
          ON prerequisite_job.id = dependency.prerequisite_job_id
        JOIN logical_workflow_effective_job_results AS prerequisite
          ON prerequisite.run_id = dependency.run_id
         AND prerequisite.invocation_id = dependency.invocation_id
         AND prerequisite.logical_job_id = dependency.prerequisite_job_id
         AND prerequisite.claim_state = 'finalized'
        WHERE logical_result.logical_job_id = NEW.logical_job_id
          AND logical_claim.state = 'aggregating'
          AND prerequisite_job.source_order = NEW.prerequisite_source_order
          AND prerequisite.commit_digest = NEW.prerequisite_commit_digest
          AND prerequisite.outputs_digest = NEW.prerequisite_outputs_digest
          AND prerequisite.effective_conclusion = NEW.effective_conclusion
          AND prerequisite.closure_has_failure = NEW.closure_has_failure
          AND prerequisite.closure_has_cancelled = NEW.closure_has_cancelled
          AND prerequisite.closure_has_skipped = NEW.closure_has_skipped
    ) THEN
        RAISE EXCEPTION 'logical workflow prerequisite closure evidence is not exact'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_job_result_quarantine() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_due logical_workflow_job_result_due%ROWTYPE;
BEGIN
    SELECT due.* INTO current_due
    FROM logical_workflow_job_result_due AS due
    WHERE due.logical_job_id = NEW.logical_job_id
    FOR UPDATE;
    IF NOT FOUND OR ROW(
        NEW.tenant_id, NEW.run_id, NEW.invocation_id, NEW.source_order,
        NEW.ready_at_ms, NEW.available_at_ms
    ) IS DISTINCT FROM ROW(
        current_due.tenant_id, current_due.run_id, current_due.invocation_id,
        current_due.source_order, current_due.ready_at_ms,
        current_due.available_at_ms
    ) THEN
        RAISE EXCEPTION 'job-result quarantine lacks its exact current due target'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'logical_workflow_job_result_quarantines_due_exact';
    END IF;

    IF NEW.claim_owner_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM logical_workflow_job_result_claims AS claim
        WHERE claim.logical_job_id = NEW.logical_job_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.state = 'aggregating'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_claimed_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND claim.descriptor_digest = NEW.claim_descriptor_digest
    ) THEN
        RAISE EXCEPTION 'job-result quarantine lacks its exact live claim'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'logical_workflow_job_result_quarantines_claim_exact';
    END IF;

    NEW.quarantined_at_ms :=
        floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_materialization_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_instances AS instance
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = instance.run_id
         AND publication.invocation_id = instance.invocation_id
         AND publication.logical_job_id = instance.logical_job_id
        JOIN logical_workflow_jobs AS logical_job
          ON logical_job.run_id = instance.run_id
         AND logical_job.invocation_id = instance.invocation_id
         AND logical_job.id = instance.logical_job_id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = logical_job.run_id
         AND invocation.id = logical_job.invocation_id
        JOIN logical_workflow_runs AS marker
          ON marker.run_id = instance.run_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        WHERE instance.id = NEW.instance_id
          AND instance.run_id = NEW.run_id
          AND instance.invocation_id = NEW.invocation_id
          AND instance.logical_job_id = NEW.logical_job_id
          AND instance.job_ir_version = 1
          AND instance.job_ir_media_type =
              'application/vnd.automata.job-ir.protobuf'
          AND instance.runtime_context_schema = 1
          AND instance.runtime_context_media_type =
              'application/vnd.automata.job-runtime-context.protobuf'
          AND publication.condition_matched
          AND publication.instance_count > 0
          AND logical_job.execution_kind = 'steps'
          AND logical_job.state = 'activated'
          AND invocation.plan_schema = 1
          AND invocation.state IN ('pending', 'active')
          AND marker.orchestration_schema = 1
          AND marker.state IN ('pending', 'active')
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
    ) THEN
        RAISE EXCEPTION 'logical workflow materialization lacks an activated current instance'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_root() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.invocation_kind = 'root' THEN
        IF NOT EXISTS (
            SELECT 1
            FROM logical_workflow_runs AS marker
            JOIN workflow_runs AS run ON run.id = marker.run_id
            WHERE marker.run_id = NEW.run_id
              AND marker.root_invocation_id = NEW.id
              AND run.admission_epoch = 1
              AND run.plan_schema = 1
              AND run.plan_digest = NEW.plan_digest
              AND run.plan_object_key = NEW.plan_object_key
              AND run.plan_size_bytes = NEW.plan_size_bytes
              AND run.plan_media_type = NEW.plan_media_type
              AND run.created_at_ms = NEW.created_at_ms
        ) THEN
            RAISE EXCEPTION 'logical workflow root descriptor does not match its admitted run'
                USING ERRCODE = 'check_violation',
                      CONSTRAINT = 'logical_workflow_invocation_root_exact';
        END IF;
    ELSIF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_reusable_invocation_expansions AS expansion
        JOIN logical_workflow_reusable_workflow_catalog AS catalog
          ON catalog.run_id = expansion.run_id
         AND catalog.catalog_entry_id = expansion.catalog_entry_id
        WHERE expansion.run_id = NEW.run_id
          AND expansion.invocation_id = NEW.id
          AND expansion.depth > 0
          AND catalog.plan_digest = NEW.plan_digest
          AND catalog.plan_object_key = NEW.plan_object_key
          AND catalog.plan_size_bytes = NEW.plan_size_bytes
          AND catalog.plan_media_type = NEW.plan_media_type
          AND catalog.plan_schema = NEW.plan_schema
    ) THEN
        RAISE EXCEPTION 'logical workflow reusable invocation lacks exact planned evidence'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'logical_workflow_reusable_invocation_plan_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_run_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_run_result_claims AS claim
        JOIN logical_workflow_runs AS marker ON marker.run_id = claim.run_id
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = marker.run_id
         AND invocation.id = marker.root_invocation_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        WHERE claim.run_id = NEW.run_id
          AND claim.root_invocation_id = NEW.root_invocation_id
          AND claim.descriptor_digest = NEW.descriptor_digest
          AND claim.state = 'aggregating'
          AND claim.owner_id = NEW.claim_owner_id
          AND claim.generation = NEW.claim_generation
          AND claim.claimed_at_ms = NEW.claim_started_at_ms
          AND claim.expires_at_ms = NEW.claim_expires_at_ms
          AND marker.root_invocation_id = NEW.root_invocation_id
          AND marker.admission_digest = NEW.admission_digest
          AND marker.state = NEW.marker_state
          AND marker.revision = NEW.marker_revision
          AND marker.updated_at_ms = NEW.marker_updated_at_ms
          AND invocation.state = NEW.invocation_state
          AND invocation.revision = NEW.invocation_revision
          AND invocation.updated_at_ms = NEW.invocation_updated_at_ms
          AND run.status = NEW.workflow_status
          AND run.updated_at_ms = NEW.workflow_updated_at_ms
          AND NEW.job_count = (
              SELECT count(*)::INTEGER
              FROM logical_workflow_jobs AS job
              WHERE job.run_id = NEW.run_id
                AND job.invocation_id = NEW.root_invocation_id
          )
          AND NEW.finalized_at_ms >= greatest(
              NEW.marker_updated_at_ms,
              NEW.invocation_updated_at_ms,
              NEW.workflow_updated_at_ms,
              COALESCE((
                  SELECT max(result.finalized_at_ms)
                  FROM logical_workflow_effective_job_results AS result
                  WHERE result.run_id = NEW.run_id
                    AND result.invocation_id = NEW.root_invocation_id
              ), 0)
          )
          AND NEW.finalized_at_ms < claim.expires_at_ms
    ) THEN
        RAISE EXCEPTION 'logical workflow run result lacks exact descriptor/fence evidence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_run_result_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state <> 'aggregating' THEN
        RETURN NEW;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_runs AS marker
        JOIN logical_workflow_invocations AS invocation
          ON invocation.run_id = marker.run_id
         AND invocation.id = marker.root_invocation_id
        JOIN workflow_runs AS run ON run.id = marker.run_id
        WHERE marker.run_id = NEW.run_id
          AND marker.root_invocation_id = NEW.root_invocation_id
          AND marker.orchestration_schema = 1
          AND marker.state IN ('pending', 'active')
          AND marker.revision < 9223372036854775807
          AND invocation.plan_schema = 1
          AND invocation.state IN ('pending', 'active')
          AND invocation.revision < 9223372036854775807
          AND run.admission_epoch = 1
          AND run.plan_schema = 1
          AND run.status IN ('queued', 'in_progress', 'cancelled')
          AND NEW.claimed_at_ms >= greatest(
              marker.updated_at_ms,
              invocation.updated_at_ms,
              run.updated_at_ms,
              COALESCE((
                  SELECT max(result.finalized_at_ms)
                  FROM logical_workflow_effective_job_results AS result
                  WHERE result.run_id = marker.run_id
                    AND result.invocation_id = marker.root_invocation_id
              ), 0)
          )
          AND (SELECT count(*)
               FROM logical_workflow_jobs AS job
               WHERE job.run_id = marker.run_id
                 AND job.invocation_id = marker.root_invocation_id)
              BETWEEN 1 AND 1024
          AND NOT EXISTS (
              SELECT 1
              FROM logical_workflow_jobs AS job
              LEFT JOIN logical_workflow_effective_job_results AS result
                ON result.run_id = job.run_id
               AND result.invocation_id = job.invocation_id
               AND result.logical_job_id = job.id
              WHERE job.run_id = marker.run_id
                AND job.invocation_id = marker.root_invocation_id
                AND (
                    result.logical_job_id IS NULL
                    OR result.claim_state IS DISTINCT FROM 'finalized'
                    OR result.logical_key IS DISTINCT FROM job.logical_key
                    OR result.source_order IS DISTINCT FROM job.source_order
                    OR job.state IS DISTINCT FROM CASE result.effective_conclusion
                        WHEN 'success' THEN 'completed'
                        WHEN 'failure' THEN 'failed'
                        WHEN 'timed_out' THEN 'failed'
                        WHEN 'cancelled' THEN 'cancelled'
                        WHEN 'skipped' THEN 'skipped'
                    END
                    OR result.prerequisite_count IS DISTINCT FROM (
                        SELECT count(*)::INTEGER
                        FROM logical_workflow_dependencies AS dependency
                        WHERE dependency.run_id = job.run_id
                          AND dependency.invocation_id = job.invocation_id
                          AND dependency.logical_job_id = job.id
                    )
                )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM (
                  SELECT job.source_order,
                         row_number() OVER (ORDER BY job.source_order) - 1 AS expected_order
                  FROM logical_workflow_jobs AS job
                  WHERE job.run_id = marker.run_id
                    AND job.invocation_id = marker.root_invocation_id
              ) AS ordered
              WHERE ordered.source_order <> ordered.expected_order
          )
    ) THEN
        RAISE EXCEPTION 'logical workflow run-result claim is not exactly ready'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_logical_workflow_run_result_job() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM logical_workflow_run_results AS run_result
        JOIN logical_workflow_run_result_claims AS run_claim
          ON run_claim.run_id = run_result.run_id
        JOIN logical_workflow_jobs AS job
          ON job.run_id = run_result.run_id
         AND job.invocation_id = run_result.root_invocation_id
         AND job.id = NEW.logical_job_id
        JOIN logical_workflow_effective_job_results AS logical_result
          ON logical_result.run_id = job.run_id
         AND logical_result.invocation_id = job.invocation_id
         AND logical_result.logical_job_id = job.id
        WHERE run_result.run_id = NEW.run_id
          AND run_result.root_invocation_id = NEW.root_invocation_id
          AND run_claim.state = 'aggregating'
          AND job.logical_key = NEW.logical_key
          AND job.source_order = NEW.source_order
          AND logical_result.claim_state = 'finalized'
          AND logical_result.descriptor_digest = NEW.descriptor_digest
          AND logical_result.effective_conclusion = NEW.effective_conclusion
          AND logical_result.closure_has_failure = NEW.closure_has_failure
          AND logical_result.closure_has_cancelled = NEW.closure_has_cancelled
          AND logical_result.closure_has_skipped = NEW.closure_has_skipped
          AND logical_result.instance_count = NEW.instance_count
          AND logical_result.instances_digest = NEW.instances_digest
          AND logical_result.prerequisite_count = NEW.prerequisite_count
          AND logical_result.prerequisites_digest = NEW.prerequisites_digest
          AND logical_result.output_count = NEW.output_count
          AND logical_result.outputs_digest = NEW.outputs_digest
          AND logical_result.commit_digest = NEW.job_commit_digest
          AND logical_result.finalized_at_ms = NEW.job_finalized_at_ms
    ) THEN
        RAISE EXCEPTION 'logical workflow run-result job evidence is not exact'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_attempt_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM workflow_runs AS run
        JOIN workflow_runs AS root ON root.id = NEW.root_run_id
        JOIN workflow_runs AS source_run
          ON source_run.id = COALESCE(NEW.source_run_id, NEW.run_id)
        JOIN logical_workflow_runs AS source_marker
          ON source_marker.run_id = source_run.id
        LEFT JOIN workflow_rerun_attempts AS source
          ON source.run_id = NEW.source_run_id
        WHERE run.id = NEW.run_id
          AND run.run_attempt = NEW.attempt
          AND run.created_at_ms = NEW.created_at_ms
          AND run.workflow_id = root.workflow_id
          AND run.public_run_id_alias = root.public_run_id_alias
          AND run.run_number = root.run_number
          AND root.run_attempt = 1
          AND run.repository_id = source_run.repository_id
          AND source_run.workflow_id = root.workflow_id
          AND source_run.public_run_id_alias = root.public_run_id_alias
          AND run.snapshot_id = source_run.snapshot_id
          AND run.run_number = source_run.run_number
          AND run.event_name = source_run.event_name
          AND run.event_object_key = source_run.event_object_key
          AND run.head_sha = source_run.head_sha
          AND run.concurrency_group_key IS NOT DISTINCT FROM
              source_run.concurrency_group_key
          AND run.concurrency_queue_policy IS NOT DISTINCT FROM
              source_run.concurrency_queue_policy
          AND run.concurrency_cancel_in_progress IS NOT DISTINCT FROM
              source_run.concurrency_cancel_in_progress
          AND (
              run.concurrency_group_key IS NULL
              AND run.concurrency_queue_policy IS NULL
              AND run.concurrency_cancel_in_progress IS NULL
              OR run.concurrency_group_key IS NOT NULL
              AND run.concurrency_queue_policy IS NOT NULL
              AND run.concurrency_cancel_in_progress IS NOT NULL
          )
          AND run.admission_epoch = source_run.admission_epoch
          AND run.event_digest = source_run.event_digest
          AND run.event_size_bytes = source_run.event_size_bytes
          AND run.event_media_type = source_run.event_media_type
          AND run.plan_digest = source_run.plan_digest
          AND run.plan_object_key = source_run.plan_object_key
          AND run.plan_size_bytes = source_run.plan_size_bytes
          AND run.plan_media_type = source_run.plan_media_type
          AND run.plan_schema = source_run.plan_schema
          AND run.workflow_name IS NOT DISTINCT FROM source_run.workflow_name
          AND run.git_ref IS NOT DISTINCT FROM source_run.git_ref
          AND run.actor IS NOT DISTINCT FROM source_run.actor
          AND run.display_title IS NOT DISTINCT FROM source_run.display_title
          AND run.commit_subject IS NOT DISTINCT FROM source_run.commit_subject
          AND run.publication_policy_revision IS NOT DISTINCT FROM
              source_run.publication_policy_revision
          AND run.requested_dashboard_visibility IS NOT DISTINCT FROM
              source_run.requested_dashboard_visibility
          AND run.effective_dashboard_visibility IS NOT DISTINCT FROM
              source_run.effective_dashboard_visibility
          AND run.requested_log_visibility IS NOT DISTINCT FROM
              source_run.requested_log_visibility
          AND run.requested_artifact_visibility IS NOT DISTINCT FROM
              source_run.requested_artifact_visibility
          AND run.publication_safety_reason IS NOT DISTINCT FROM
              source_run.publication_safety_reason
          AND run.publication_safety_schema IS NOT DISTINCT FROM
              source_run.publication_safety_schema
          AND source_marker.admission_digest = NEW.source_admission_digest
          AND source_run.plan_digest = NEW.source_plan_digest
          AND source_run.event_digest = NEW.source_event_digest
          AND (
              NEW.attempt = 1
              AND NEW.run_id = NEW.root_run_id
              AND NEW.source_run_id IS NULL
              OR NEW.attempt > 1
              AND NEW.run_id <> NEW.root_run_id
              AND NEW.source_run_id IS NOT NULL
              AND source.root_run_id = NEW.root_run_id
              AND source.attempt < NEW.attempt
          )
    ) OR EXISTS (
        SELECT 1
        FROM generate_series(1, NEW.attempt) AS expected(attempt)
        WHERE NOT EXISTS (
            SELECT 1
            FROM workflow_rerun_attempts AS durable
            WHERE durable.root_run_id = NEW.root_run_id
              AND durable.attempt = expected.attempt
        )
    ) THEN
        RAISE EXCEPTION 'workflow rerun attempt lineage is not contiguous and exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_attempts_lineage_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_audit_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM workflow_rerun_attempts AS attempt
        JOIN workflow_rerun_requests AS request
          ON request.tenant_id = NEW.tenant_id
         AND request.operation_id = NEW.operation_id
         AND request.rerun_run_id = attempt.run_id
         AND request.source_run_id = attempt.source_run_id
        JOIN security_audit_events AS audit
          ON audit.event_id = NEW.event_id
         AND audit.tenant_id = request.tenant_id
        WHERE attempt.run_id = NEW.run_id
          AND attempt.source_run_id IS NOT NULL
          AND request.request_digest = NEW.request_digest
          AND request.committed_at_ms = attempt.created_at_ms
          AND NEW.recorded_at_ms = attempt.created_at_ms
          AND audit.occurred_at_ms = attempt.created_at_ms
          AND audit.actor_kind = 'human'
          AND audit.actor_principal_id = request.actor_principal_id
          AND audit.actor_session_id = request.actor_session_id
          AND audit.authorization_revision = request.authorization_revision
          AND audit.action = 'workflow.rerun'
          AND audit.outcome = 'succeeded'
          AND audit.resource_kind = 'workflow_run'
          AND audit.resource_id = attempt.run_id::TEXT
    ) THEN
        RAISE EXCEPTION 'workflow rerun audit evidence is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_audit_evidence_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_carried_result_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    carried workflow_rerun_carried_job_results%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'workflow_rerun_carried_job_results' THEN
        carried := NEW;
    ELSE
        SELECT * INTO carried
        FROM workflow_rerun_carried_job_results
        WHERE logical_job_id = NEW.logical_job_id;
    END IF;

    IF carried.logical_job_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM logical_workflow_effective_job_results AS source
        WHERE source.run_id = carried.source_run_id
          AND source.logical_job_id = carried.source_logical_job_id
          AND source.claim_state = 'finalized'
          AND source.descriptor_digest = carried.result_descriptor_digest
          AND source.logical_key = carried.logical_key
          AND source.source_order = carried.source_order
          AND source.plan_digest = carried.plan_digest
          AND source.plan_object_key = carried.plan_object_key
          AND source.plan_size_bytes = carried.plan_size_bytes
          AND source.plan_media_type = carried.plan_media_type
          AND source.plan_schema = carried.plan_schema
          AND source.activation_output_digest = carried.activation_output_digest
          AND source.condition_matched = carried.condition_matched
          AND source.instance_count = carried.instance_count
          AND source.instances_digest = carried.instances_digest
          AND source.prerequisite_count = carried.prerequisite_count
          AND source.prerequisites_digest = carried.prerequisites_digest
          AND source.effective_conclusion = carried.effective_conclusion
          AND source.closure_has_failure = carried.closure_has_failure
          AND source.closure_has_cancelled = carried.closure_has_cancelled
          AND source.closure_has_skipped = carried.closure_has_skipped
          AND source.output_count = carried.output_count
          AND source.outputs_digest = carried.outputs_digest
          AND source.commit_digest = carried.commit_digest
          AND source.claim_owner_id = carried.claim_owner_id
          AND source.claim_generation = carried.claim_generation
          AND source.claim_started_at_ms = carried.claim_started_at_ms
          AND source.claim_expires_at_ms = carried.claim_expires_at_ms
          AND source.finalized_at_ms = carried.finalized_at_ms
          AND NOT EXISTS (
              (SELECT output_name, sensitivity, public_value
               FROM logical_workflow_effective_job_result_outputs
               WHERE logical_job_id = carried.source_logical_job_id)
              EXCEPT
              (SELECT output_name, sensitivity, public_value
               FROM workflow_rerun_carried_job_outputs
               WHERE logical_job_id = carried.logical_job_id)
          )
          AND NOT EXISTS (
              (SELECT output_name, sensitivity, public_value
               FROM workflow_rerun_carried_job_outputs
               WHERE logical_job_id = carried.logical_job_id)
              EXCEPT
              (SELECT output_name, sensitivity, public_value
               FROM logical_workflow_effective_job_result_outputs
               WHERE logical_job_id = carried.source_logical_job_id)
          )
    ) THEN
        RAISE EXCEPTION 'carried workflow result differs from its immutable source result'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_carried_job_source_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_check_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact BOOLEAN;
    private_exact BOOLEAN := TRUE;
BEGIN
    SELECT TRUE INTO exact
    FROM workflow_rerun_attempts AS attempt
    JOIN workflow_rerun_requests AS request
      ON request.tenant_id = NEW.tenant_id
     AND request.operation_id = NEW.operation_id
     AND request.rerun_run_id = attempt.run_id
     AND request.source_run_id = attempt.source_run_id
    JOIN workflow_admission_receipts AS receipt
      ON receipt.tenant_id = request.tenant_id
     AND receipt.idempotency_kind = 'operation'
     AND receipt.idempotency_key =
         'workflow-rerun:' || request.operation_id::TEXT
     AND receipt.request_digest = request.request_digest
     AND receipt.repository_id = request.repository_id
     AND receipt.run_id = attempt.run_id
     AND receipt.committed_at_ms = attempt.created_at_ms
     AND receipt.github_subject_evidence_required
    JOIN workflow_runs AS run ON run.id = attempt.run_id
    JOIN github_workflow_run_base_manifest_origins AS origin
      ON origin.run_id = attempt.root_run_id
     AND origin.tenant_id = request.tenant_id
     AND origin.repository_id = request.repository_id
    JOIN github_provider_manifest_revisions AS manifest
      ON manifest.tenant_id = origin.tenant_id
     AND manifest.repository_id = origin.repository_id
     AND manifest.provider_connection_id = origin.provider_connection_id
     AND manifest.manifest_revision = origin.provider_manifest_revision
     AND manifest.manifest_digest = origin.provider_manifest_digest
    JOIN github_server_service_authorities AS authority
      ON authority.tenant_id = origin.tenant_id
     AND authority.id = NEW.checks_authority_id
     AND authority.repository_id = origin.repository_id
     AND authority.provider_connection_id = origin.provider_connection_id
     AND authority.provider_installation_id = origin.provider_installation_id
     AND authority.github_app_id = manifest.github_app_id
     AND authority.github_repository_id = origin.github_repository_id
     AND authority.github_repository_name = origin.github_repository_name
     AND authority.service_scope = 'checks_write'
     AND authority.github_app_client_id = manifest.github_app_client_id
     AND authority.github_app_jwt_issuer_kind =
         manifest.github_app_jwt_issuer_kind
     AND authority.app_key_spki_sha256 = manifest.app_key_spki_sha256
     AND authority.app_configuration_revision =
         manifest.app_configuration_revision
     AND authority.policy_revision = manifest.policy_revision
     AND authority.identity_digest = NEW.checks_authority_identity_digest
     AND authority.state = 'active'
     AND authority.created_at_ms <= NEW.recorded_at_ms
     AND authority.state_updated_at_ms <= NEW.recorded_at_ms
    JOIN github_check_subjects AS source
      ON source.id = NEW.source_github_check_subject_id
     AND source.workflow_run_id = attempt.source_run_id
    JOIN github_check_subjects AS target
      ON target.id = NEW.github_check_subject_id
     AND target.workflow_run_id = attempt.run_id
    WHERE attempt.run_id = NEW.run_id
      AND attempt.source_run_id = NEW.source_run_id
      AND attempt.source_run_id IS NOT NULL
      AND request.tenant_id = NEW.tenant_id
      AND request.operation_id = NEW.operation_id
      AND request.repository_id = NEW.repository_id
      AND request.committed_at_ms = attempt.created_at_ms
      AND run.repository_id = NEW.repository_id
      AND run.status = 'queued'
      AND origin.tenant_id = NEW.tenant_id
      AND origin.repository_id = NEW.repository_id
      AND origin.provider_connection_id = NEW.provider_connection_id
      AND origin.provider_manifest_revision = NEW.provider_manifest_revision
      AND origin.provider_manifest_digest = NEW.provider_manifest_digest
      AND manifest.app_configuration_revision =
          NEW.checks_authority_app_configuration_revision
      AND manifest.policy_revision =
          NEW.checks_authority_policy_revision
      AND (
          origin.repository_visibility = 'public'
          AND origin.private_source_authority_id IS NULL
          AND NEW.private_source_authority_id IS NULL
          AND NEW.private_source_authority_identity_digest IS NULL
          AND NEW.private_source_authority_app_configuration_revision IS NULL
          AND NEW.private_source_authority_policy_revision IS NULL
          OR origin.repository_visibility = 'private'
          AND NEW.private_source_authority_id =
              origin.private_source_authority_id
          AND NEW.private_source_authority_identity_digest =
              origin.private_source_authority_identity_digest
          AND NEW.private_source_authority_app_configuration_revision =
              origin.private_source_authority_app_configuration_revision
          AND NEW.private_source_authority_policy_revision =
              origin.private_source_authority_policy_revision
          AND EXISTS (
              SELECT 1
              FROM github_server_service_authorities AS private_authority
              WHERE private_authority.tenant_id = origin.tenant_id
                AND private_authority.id =
                    origin.private_source_authority_id
                AND private_authority.repository_id = origin.repository_id
                AND private_authority.provider_connection_id =
                    origin.provider_connection_id
                AND private_authority.provider_installation_id =
                    origin.provider_installation_id
                AND private_authority.github_app_id = manifest.github_app_id
                AND private_authority.github_repository_id =
                    origin.github_repository_id
                AND private_authority.github_repository_name =
                    origin.github_repository_name
                AND private_authority.service_scope =
                    'private_repository_source_read'
                AND private_authority.github_app_client_id =
                    manifest.github_app_client_id
                AND private_authority.github_app_jwt_issuer_kind =
                    manifest.github_app_jwt_issuer_kind
                AND private_authority.app_key_spki_sha256 =
                    manifest.app_key_spki_sha256
                AND private_authority.identity_digest =
                    NEW.private_source_authority_identity_digest
                AND private_authority.app_configuration_revision =
                    NEW.private_source_authority_app_configuration_revision
                AND private_authority.policy_revision =
                    NEW.private_source_authority_policy_revision
                AND private_authority.state = 'active'
                AND private_authority.created_at_ms <= NEW.recorded_at_ms
                AND private_authority.state_updated_at_ms <= NEW.recorded_at_ms
          )
      )
      AND source.tenant_id = NEW.tenant_id
      AND source.repository_id = NEW.repository_id
      AND source.provider_connection_id = NEW.provider_connection_id
      AND source.head_sha = origin.github_check_head_sha
      AND source.provider_installation_id = origin.provider_installation_id
      AND source.github_repository_id = origin.github_repository_id
      AND source.github_repository_name = origin.github_repository_name
      AND source.github_app_id = manifest.github_app_id
      AND source.subject_key = manifest.check_subject_key
      AND source.check_name = manifest.check_name
      AND source.desired_state = 'completed'
      AND source.desired_conclusion IS NOT NULL
      AND source.terminal_cause IS NOT NULL
      AND source.desired_revision = 3
      AND target.tenant_id = source.tenant_id
      AND target.repository_id = source.repository_id
      AND target.origin_kind = 'workflow_rerun'
      AND target.provider_delivery_id IS NULL
      AND target.schedule_fire_id IS NULL
      AND target.workflow_rerun_run_id = attempt.run_id
      AND target.subject_key = source.subject_key
      AND target.provider_connection_id = source.provider_connection_id
      AND target.provider_installation_id = source.provider_installation_id
      AND target.github_repository_id = source.github_repository_id
      AND target.github_repository_name = source.github_repository_name
      AND target.github_app_id = source.github_app_id
      AND target.head_sha = source.head_sha
      AND target.head_sha = run.head_sha
      AND target.head_sha = NEW.github_check_head_sha
      AND target.check_name = source.check_name
      AND target.workflow_run_id = attempt.run_id
      AND target.linked_at_ms = attempt.created_at_ms
      AND target.desired_state = 'in_progress'
      AND target.desired_conclusion IS NULL
      AND target.terminal_cause IS NULL
      AND target.desired_revision = 2
      AND target.created_at_ms = attempt.created_at_ms
      AND target.desired_updated_at_ms = attempt.created_at_ms
      AND NEW.recorded_at_ms = attempt.created_at_ms
    FOR SHARE OF attempt, request, receipt, run, manifest, authority,
                 source, target;

    IF NEW.private_source_authority_id IS NOT NULL THEN
        SELECT TRUE INTO private_exact
        FROM workflow_rerun_attempts AS attempt
        JOIN workflow_rerun_requests AS request
          ON request.tenant_id = NEW.tenant_id
         AND request.operation_id = NEW.operation_id
         AND request.rerun_run_id = attempt.run_id
        JOIN github_workflow_run_base_manifest_origins AS origin
          ON origin.run_id = attempt.root_run_id
         AND origin.tenant_id = request.tenant_id
         AND origin.repository_id = request.repository_id
        JOIN github_provider_manifest_revisions AS manifest
          ON manifest.tenant_id = origin.tenant_id
         AND manifest.repository_id = origin.repository_id
         AND manifest.provider_connection_id = origin.provider_connection_id
         AND manifest.manifest_revision = origin.provider_manifest_revision
         AND manifest.manifest_digest = origin.provider_manifest_digest
        JOIN github_server_service_authorities AS private_authority
          ON private_authority.tenant_id = origin.tenant_id
         AND private_authority.id = NEW.private_source_authority_id
         AND private_authority.repository_id = origin.repository_id
         AND private_authority.provider_connection_id =
             origin.provider_connection_id
         AND private_authority.provider_installation_id =
             origin.provider_installation_id
         AND private_authority.github_app_id = manifest.github_app_id
         AND private_authority.github_repository_id =
             origin.github_repository_id
         AND private_authority.github_repository_name =
             origin.github_repository_name
         AND private_authority.service_scope =
             'private_repository_source_read'
         AND private_authority.github_app_client_id =
             manifest.github_app_client_id
         AND private_authority.github_app_jwt_issuer_kind =
             manifest.github_app_jwt_issuer_kind
         AND private_authority.app_key_spki_sha256 =
             manifest.app_key_spki_sha256
         AND private_authority.identity_digest =
             NEW.private_source_authority_identity_digest
         AND private_authority.app_configuration_revision =
             NEW.private_source_authority_app_configuration_revision
         AND private_authority.policy_revision =
             NEW.private_source_authority_policy_revision
         AND private_authority.state = 'active'
         AND private_authority.created_at_ms <= NEW.recorded_at_ms
         AND private_authority.state_updated_at_ms <= NEW.recorded_at_ms
        WHERE attempt.run_id = NEW.run_id
          AND origin.repository_visibility = 'private'
          AND origin.private_source_authority_id =
              NEW.private_source_authority_id
          AND origin.private_source_authority_identity_digest =
              NEW.private_source_authority_identity_digest
          AND origin.private_source_authority_app_configuration_revision =
              NEW.private_source_authority_app_configuration_revision
          AND origin.private_source_authority_policy_revision =
              NEW.private_source_authority_policy_revision
        FOR SHARE OF manifest, private_authority;
    END IF;

    IF exact IS DISTINCT FROM TRUE OR private_exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'workflow rerun Check evidence is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_check_evidence_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_concurrency_slot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_run_id UUID;
    exact_slot_count BIGINT;
    all_slot_count BIGINT;
    concurrency_key TEXT;
    repository UUID;
    admitted_at BIGINT;
BEGIN
    candidate_run_id := NEW.run_id;
    SELECT run.repository_id, run.concurrency_group_key, attempt.created_at_ms
      INTO repository, concurrency_key, admitted_at
    FROM workflow_rerun_attempts AS attempt
    JOIN workflow_runs AS run ON run.id = attempt.run_id
    WHERE attempt.run_id = candidate_run_id
      AND attempt.source_run_id IS NOT NULL;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    SELECT count(*) INTO all_slot_count
    FROM (
        SELECT concurrency.repository_id, concurrency.normalized_key,
               concurrency.running_run_id AS run_id,
               concurrency.updated_at_ms AS slot_at_ms
        FROM concurrency_groups AS concurrency
        WHERE concurrency.running_run_id = candidate_run_id
        UNION ALL
        SELECT pending.repository_id, pending.normalized_key,
               pending.run_id, pending.enqueued_at_ms
        FROM concurrency_group_pending_runs AS pending
        WHERE pending.run_id = candidate_run_id
    ) AS slots;

    IF concurrency_key IS NULL THEN
        exact_slot_count := 0;
    ELSE
        SELECT count(*) INTO exact_slot_count
        FROM (
            SELECT concurrency.repository_id, concurrency.normalized_key,
                   concurrency.running_run_id AS run_id,
                   concurrency.updated_at_ms AS slot_at_ms
            FROM concurrency_groups AS concurrency
            WHERE concurrency.repository_id = repository
              AND concurrency.normalized_key = concurrency_key
              AND concurrency.running_run_id = candidate_run_id
            UNION ALL
            SELECT pending.repository_id, pending.normalized_key,
                   pending.run_id, pending.enqueued_at_ms
            FROM concurrency_group_pending_runs AS pending
            WHERE pending.repository_id = repository
              AND pending.normalized_key = concurrency_key
              AND pending.run_id = candidate_run_id
        ) AS exact_slots
        WHERE exact_slots.slot_at_ms = admitted_at;
    END IF;

    IF all_slot_count <> exact_slot_count
        OR concurrency_key IS NULL AND exact_slot_count <> 0
        OR concurrency_key IS NOT NULL AND exact_slot_count <> 1
    THEN
        RAISE EXCEPTION 'workflow rerun concurrency slot is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_concurrency_slot_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_graph_exact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_run_id UUID;
    candidate_source_run_id UUID;
    exact BOOLEAN;
BEGIN
    IF TG_TABLE_NAME = 'workflow_rerun_requests' THEN
        candidate_run_id := NEW.rerun_run_id;
    ELSE
        candidate_run_id := NEW.run_id;
    END IF;
    IF candidate_run_id IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT source_run_id INTO candidate_source_run_id
    FROM workflow_rerun_attempts
    WHERE run_id = candidate_run_id;
    IF NOT FOUND OR candidate_source_run_id IS NULL THEN
        RETURN NULL;
    END IF;

    WITH RECURSIVE
    context AS (
        SELECT attempt.run_id, attempt.source_run_id, attempt.created_at_ms,
               target_marker.root_invocation_id AS target_invocation_id,
               source_marker.root_invocation_id AS source_invocation_id,
               request.selection_kind, request.selected_source_job_id
        FROM workflow_rerun_attempts AS attempt
        JOIN workflow_rerun_requests AS request
          ON request.rerun_run_id = attempt.run_id
         AND request.source_run_id = attempt.source_run_id
         AND request.committed_at_ms = attempt.created_at_ms
        JOIN logical_workflow_runs AS target_marker
          ON target_marker.run_id = attempt.run_id
         AND target_marker.admission_graph_sealed_at_ms IS NOT NULL
        JOIN logical_workflow_runs AS source_marker
          ON source_marker.run_id = attempt.source_run_id
         AND target_marker.orchestration_schema = source_marker.orchestration_schema
         AND target_marker.runner_requirements_schema = 1
         AND source_marker.runner_requirements_schema = 1
         AND target_marker.state = 'pending'
         AND target_marker.revision = 1
         AND target_marker.admitted_at_ms = attempt.created_at_ms
         AND target_marker.updated_at_ms >= attempt.created_at_ms
         AND source_marker.base_context_digest IS NOT NULL
         AND source_marker.base_context_object_key IS NOT NULL
         AND source_marker.base_context_size_bytes IS NOT NULL
         AND source_marker.base_context_media_type =
             'application/vnd.automata.job-runtime-context.protobuf'
         AND source_marker.base_context_schema = 1
         AND target_marker.base_context_digest = source_marker.base_context_digest
         AND target_marker.base_context_object_key =
             source_marker.base_context_object_key
         AND target_marker.base_context_size_bytes =
             source_marker.base_context_size_bytes
         AND target_marker.base_context_media_type =
             source_marker.base_context_media_type
         AND target_marker.base_context_schema = source_marker.base_context_schema
        JOIN logical_workflow_invocations AS target_invocation
          ON target_invocation.run_id = attempt.run_id
         AND target_invocation.id = target_marker.root_invocation_id
         AND target_invocation.invocation_kind = 'root'
         AND target_invocation.state = 'pending'
         AND target_invocation.revision = 1
         AND target_invocation.created_at_ms = attempt.created_at_ms
         AND target_invocation.updated_at_ms = attempt.created_at_ms
        JOIN human_provider_identities AS identity
          ON identity.principal_id = request.actor_principal_id
        JOIN human_sessions AS session
          ON session.tenant_id = request.tenant_id
         AND session.principal_id = request.actor_principal_id
         AND session.id = request.actor_session_id
         AND session.provider_id = identity.provider_id
         AND session.provider_subject = identity.provider_subject
        JOIN workflow_runs AS target_run
          ON target_run.id = attempt.run_id
         AND target_run.triggering_actor = identity.provider_login
         AND target_run.runner_requirements_schema = 1
         AND target_run.status = 'queued'
         AND target_run.created_at_ms = attempt.created_at_ms
         AND target_run.updated_at_ms = attempt.created_at_ms
         AND target_run.concurrency_group_key IS NULL
         AND target_run.concurrency_queue_policy IS NULL
         AND target_run.concurrency_cancel_in_progress IS NULL
        JOIN workflow_runs AS source_run
          ON source_run.id = attempt.source_run_id
         AND source_run.runner_requirements_schema = 1
         AND source_run.concurrency_group_key IS NULL
         AND source_run.concurrency_queue_policy IS NULL
         AND source_run.concurrency_cancel_in_progress IS NULL
        WHERE attempt.run_id = candidate_run_id
          AND attempt.source_run_id = candidate_source_run_id
    ),
    source_jobs AS (
        SELECT job.*
        FROM context
        JOIN logical_workflow_jobs AS job
          ON job.run_id = context.source_run_id
         AND job.invocation_id = context.source_invocation_id
        JOIN logical_workflow_run_result_jobs AS aggregate
          ON aggregate.run_id = job.run_id
         AND aggregate.root_invocation_id = job.invocation_id
         AND aggregate.logical_job_id = job.id
    ),
    target_jobs AS (
        SELECT job.*
        FROM context
        JOIN logical_workflow_jobs AS job
          ON job.run_id = context.run_id
         AND job.invocation_id = context.target_invocation_id
    ),
    mapping AS (
        SELECT mapped.*
        FROM context
        JOIN workflow_rerun_attempt_jobs AS mapped
          ON mapped.run_id = context.run_id
         AND mapped.source_run_id = context.source_run_id
    ),
    expected_selected(source_logical_job_id) AS (
        SELECT source.id
        FROM context
        JOIN source_jobs AS source ON TRUE
        LEFT JOIN logical_workflow_effective_job_results AS result
          ON result.run_id = context.source_run_id
         AND result.logical_job_id = source.id
         AND result.claim_state = 'finalized'
        WHERE context.selection_kind = 'entire_workflow'
           OR context.selection_kind = 'job_and_dependents'
              AND source.id = context.selected_source_job_id
           OR context.selection_kind = 'failed_jobs_and_dependents'
              AND result.effective_conclusion IN ('failure', 'timed_out')
        UNION
        SELECT dependency.logical_job_id
        FROM expected_selected AS selected
        JOIN context ON TRUE
        JOIN logical_workflow_dependencies AS dependency
          ON dependency.run_id = context.source_run_id
         AND dependency.invocation_id = context.source_invocation_id
         AND dependency.prerequisite_job_id = selected.source_logical_job_id
    ),
    expected_edges AS (
        SELECT dependent.logical_job_id,
               prerequisite.logical_job_id AS prerequisite_job_id
        FROM context
        JOIN logical_workflow_dependencies AS source_edge
          ON source_edge.run_id = context.source_run_id
         AND source_edge.invocation_id = context.source_invocation_id
        JOIN mapping AS dependent
          ON dependent.source_logical_job_id = source_edge.logical_job_id
        JOIN mapping AS prerequisite
          ON prerequisite.source_logical_job_id = source_edge.prerequisite_job_id
    ),
    target_edges AS (
        SELECT dependency.logical_job_id, dependency.prerequisite_job_id
        FROM context
        JOIN logical_workflow_dependencies AS dependency
          ON dependency.run_id = context.run_id
         AND dependency.invocation_id = context.target_invocation_id
    )
    SELECT EXISTS (SELECT 1 FROM context)
       AND EXISTS (SELECT 1 FROM expected_selected)
       AND (SELECT count(*) FROM logical_workflow_invocations AS invocation
            JOIN context ON invocation.run_id = context.source_run_id) = 1
       AND (SELECT count(*) FROM logical_workflow_invocations AS invocation
            JOIN context ON invocation.run_id = context.run_id) = 1
       AND NOT EXISTS (
           SELECT 1 FROM source_jobs WHERE execution_kind <> 'steps'
       )
       AND NOT EXISTS (
           SELECT 1 FROM target_jobs WHERE execution_kind <> 'steps'
       )
       AND NOT EXISTS (
           SELECT 1
           FROM context
           JOIN logical_workflow_effective_job_results AS result
             ON result.run_id = context.source_run_id
            AND result.claim_state = 'finalized'
           WHERE context.selection_kind <> 'entire_workflow'
             AND result.instance_count > 1
       )
       AND NOT EXISTS (
           (SELECT id FROM source_jobs)
           EXCEPT
           (SELECT source_logical_job_id FROM mapping)
       )
       AND NOT EXISTS (
           (SELECT source_logical_job_id FROM mapping)
           EXCEPT
           (SELECT id FROM source_jobs)
       )
       AND NOT EXISTS (
           (SELECT id FROM target_jobs)
           EXCEPT
           (SELECT logical_job_id FROM mapping)
       )
       AND NOT EXISTS (
           (SELECT logical_job_id FROM mapping)
           EXCEPT
           (SELECT id FROM target_jobs)
       )
       AND NOT EXISTS (
           (SELECT source_logical_job_id FROM mapping WHERE selected)
           EXCEPT
           (SELECT source_logical_job_id FROM expected_selected)
       )
       AND NOT EXISTS (
           (SELECT source_logical_job_id FROM expected_selected)
           EXCEPT
           (SELECT source_logical_job_id FROM mapping WHERE selected)
       )
       AND NOT EXISTS (
           SELECT 1
           FROM mapping AS mapped
           JOIN context ON TRUE
           JOIN source_jobs AS source ON source.id = mapped.source_logical_job_id
           JOIN target_jobs AS target ON target.id = mapped.logical_job_id
           WHERE target.logical_key IS DISTINCT FROM source.logical_key
              OR target.source_order IS DISTINCT FROM source.source_order
              OR target.execution_kind IS DISTINCT FROM source.execution_kind
              OR target.runtime_policy_revision IS DISTINCT FROM
                 source.runtime_policy_revision
              OR target.runtime_policy_digest IS DISTINCT FROM
                 source.runtime_policy_digest
              OR target.environment_requirement_kind IS DISTINCT FROM
                 source.environment_requirement_kind
              OR target.environment_template_digest IS DISTINCT FROM
                 source.environment_template_digest
              OR target.secret_reference_names IS DISTINCT FROM
                 source.secret_reference_names
              OR target.variable_reference_names IS DISTINCT FROM
                 source.variable_reference_names
              OR target.credential_requirements_schema IS DISTINCT FROM
                 source.credential_requirements_schema
              OR target.rerun_carried IS DISTINCT FROM NOT mapped.selected
              OR target.created_at_ms IS DISTINCT FROM context.created_at_ms
              OR target.updated_at_ms IS DISTINCT FROM context.created_at_ms
              OR mapped.selected AND (
                  target.state IS DISTINCT FROM 'pending'
                  OR target.activation_fence IS DISTINCT FROM 0
                  OR target.activation_input_digest IS NOT NULL
                  OR target.authority_profile IS NOT NULL
                  OR target.activation_origin_selection_id IS NOT NULL
              )
              OR NOT mapped.selected AND (
                  target.state IS DISTINCT FROM source.state
                  OR target.activation_fence IS DISTINCT FROM
                     source.activation_fence
                  OR target.activation_input_digest IS DISTINCT FROM
                     source.activation_input_digest
                  OR target.authority_profile IS DISTINCT FROM
                     source.authority_profile
                  OR target.activation_origin_selection_id IS DISTINCT FROM
                     source.activation_origin_selection_id
              )
       )
       AND NOT EXISTS (
           (SELECT logical_job_id, prerequisite_job_id FROM expected_edges)
           EXCEPT
           (SELECT logical_job_id, prerequisite_job_id FROM target_edges)
       )
       AND NOT EXISTS (
           (SELECT logical_job_id, prerequisite_job_id FROM target_edges)
           EXCEPT
           (SELECT logical_job_id, prerequisite_job_id FROM expected_edges)
       )
    INTO exact;

    IF exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'workflow rerun graph or selection closure is not exact'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_graph_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_job_classification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    durable_job logical_workflow_jobs%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'logical_workflow_jobs' THEN
        durable_job := NEW;
    ELSE
        SELECT * INTO durable_job
        FROM logical_workflow_jobs
        WHERE run_id = NEW.run_id
          AND id = NEW.logical_job_id;
    END IF;

    IF durable_job.id IS NULL THEN
        RAISE EXCEPTION 'workflow rerun classification has no exact logical job'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_carried_job_exact';
    ELSIF durable_job.rerun_carried THEN
        IF EXISTS (
            SELECT 1
            FROM logical_workflow_job_results AS executed
            WHERE executed.run_id = durable_job.run_id
              AND executed.logical_job_id = durable_job.id
        ) OR NOT EXISTS (
            SELECT 1
            FROM workflow_rerun_attempt_jobs AS mapping
            JOIN workflow_rerun_carried_job_results AS carried
              ON carried.run_id = mapping.run_id
             AND carried.logical_job_id = mapping.logical_job_id
             AND carried.source_run_id = mapping.source_run_id
             AND carried.source_logical_job_id = mapping.source_logical_job_id
            WHERE mapping.run_id = durable_job.run_id
              AND mapping.logical_job_id = durable_job.id
              AND NOT mapping.selected
              AND durable_job.state = CASE carried.effective_conclusion
                  WHEN 'success' THEN 'completed'
                  WHEN 'failure' THEN 'failed'
                  WHEN 'timed_out' THEN 'failed'
                  WHEN 'cancelled' THEN 'cancelled'
                  WHEN 'skipped' THEN 'skipped'
              END
        ) THEN
            RAISE EXCEPTION 'carried logical job lacks exact immutable source evidence'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'workflow_rerun_carried_job_exact';
        END IF;
    ELSIF EXISTS (
        SELECT 1
        FROM workflow_rerun_attempt_jobs AS mapping
        WHERE mapping.run_id = durable_job.run_id
          AND mapping.logical_job_id = durable_job.id
          AND NOT mapping.selected
    ) OR EXISTS (
        SELECT 1
        FROM workflow_rerun_carried_job_results AS carried
        WHERE carried.run_id = durable_job.run_id
          AND carried.logical_job_id = durable_job.id
    ) THEN
        RAISE EXCEPTION 'unselected rerun job is not classified as carried'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_carried_job_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_workflow_rerun_request_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    admitted_at BIGINT;
    root_created_at BIGINT;
    actor_exact BOOLEAN;
    mapped_snapshot_id UUID;
    mapped_organization_id BIGINT;
    mapped_team_id BIGINT;
BEGIN
    IF NEW.rerun_run_id IS NULL OR NEW.committed_at_ms IS NULL THEN
        RAISE EXCEPTION 'workflow rerun requests must commit complete'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'workflow_rerun_requests_completion_exact';
    END IF;
    SELECT attempt.created_at_ms, root.created_at_ms
      INTO admitted_at, root_created_at
    FROM workflow_rerun_attempts AS attempt
    JOIN workflow_runs AS root ON root.id = attempt.root_run_id
    WHERE attempt.run_id = NEW.rerun_run_id
      AND attempt.source_run_id = NEW.source_run_id;
    IF NOT FOUND
        OR root_created_at > admitted_at
        OR admitted_at - root_created_at > 2592000000
        OR automata_workflow_rerun_now_ms() - root_created_at > 2592000000
        OR admitted_at <> automata_workflow_rerun_now_ms()
    THEN
        RAISE EXCEPTION 'workflow rerun request age is not exact'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'workflow_rerun_requests_age_exact';
    END IF;

    SELECT TRUE INTO actor_exact
    FROM human_sessions AS session
    JOIN human_principals AS principal
      ON principal.id = session.principal_id
    JOIN tenant_human_memberships AS membership
      ON membership.tenant_id = session.tenant_id
     AND membership.principal_id = session.principal_id
    WHERE session.tenant_id = NEW.tenant_id
      AND session.principal_id = NEW.actor_principal_id
      AND session.id = NEW.actor_session_id
      AND principal.status = 'active'
      AND membership.status = 'active'
      AND membership.authorization_revision = NEW.authorization_revision
      AND session.authorization_revision = NEW.authorization_revision
      AND session.revoked_at_ms IS NULL
      AND session.issued_at_ms <= admitted_at
      AND session.idle_expires_at_ms > admitted_at
      AND session.expires_at_ms > admitted_at
      AND (
          session.session_kind = 'browser'
          AND session.audience = 'automata.web'
          OR session.session_kind = 'cli'
          AND session.audience = 'automata.cli'
      )
      AND EXISTS (
          SELECT 1
          FROM rbac_role_bindings AS binding
          JOIN rbac_role_permissions AS permission
            ON permission.tenant_id = binding.tenant_id
           AND permission.role_id = binding.role_id
          WHERE binding.tenant_id = NEW.tenant_id
            AND binding.principal_id = NEW.actor_principal_id
            AND binding.status = 'active'
            AND (
                binding.valid_until_ms IS NULL
                OR binding.valid_until_ms > admitted_at
            )
            AND permission.permission_name = 'runs:rerun'
            AND (
                binding.scope_kind = 'tenant'
                AND binding.repository_id IS NULL
                AND binding.runner_group_id IS NULL
                OR binding.scope_kind = 'repository'
                AND binding.repository_id = NEW.repository_id
                AND binding.runner_group_id IS NULL
            )
          UNION ALL
          SELECT 1
          FROM github_membership_snapshots AS snapshot
          JOIN human_provider_identities AS identity
            ON identity.principal_id = snapshot.principal_id
           AND identity.provider_id = snapshot.provider_id
           AND identity.provider_subject = snapshot.provider_subject
          JOIN human_provider_tokens AS provider_token
            ON provider_token.tenant_id = snapshot.tenant_id
           AND provider_token.principal_id = snapshot.principal_id
           AND provider_token.provider_id = snapshot.provider_id
           AND provider_token.provider_subject = snapshot.provider_subject
           AND provider_token.version = snapshot.provider_token_version
          JOIN github_role_mappings AS mapping
            ON mapping.tenant_id = snapshot.tenant_id
           AND mapping.provider_id = snapshot.provider_id
           AND mapping.status = 'active'
          JOIN rbac_role_permissions AS mapped_permission
            ON mapped_permission.tenant_id = mapping.tenant_id
           AND mapped_permission.role_id = mapping.role_id
          WHERE snapshot.tenant_id = NEW.tenant_id
            AND snapshot.principal_id = NEW.actor_principal_id
            AND snapshot.provider_id = 'github'
            AND snapshot.provider_id = session.provider_id
            AND snapshot.provider_subject = session.provider_subject
            AND snapshot.observed_at_ms <= admitted_at
            AND snapshot.valid_until_ms > admitted_at
            AND provider_token.revoked_at_ms IS NULL
            AND provider_token.issued_at_ms <= snapshot.observed_at_ms
            AND (
                provider_token.access_expires_at_ms IS NULL
                OR provider_token.access_expires_at_ms > admitted_at
                AND snapshot.valid_until_ms <=
                    provider_token.access_expires_at_ms
            )
            AND mapped_permission.permission_name = 'runs:rerun'
            AND (
                mapping.scope_kind = 'tenant'
                AND mapping.repository_id IS NULL
                AND mapping.runner_group_id IS NULL
                OR mapping.scope_kind = 'repository'
                AND mapping.repository_id = NEW.repository_id
                AND mapping.runner_group_id IS NULL
            )
            AND (
                mapping.team_id IS NULL
                AND EXISTS (
                    SELECT 1
                    FROM github_organization_membership_observations AS organization
                    WHERE organization.tenant_id = snapshot.tenant_id
                      AND organization.snapshot_id = snapshot.id
                      AND organization.organization_id =
                          mapping.organization_id
                )
                OR mapping.team_id IS NOT NULL
                AND EXISTS (
                    SELECT 1
                    FROM github_team_membership_observations AS team
                    WHERE team.tenant_id = snapshot.tenant_id
                      AND team.snapshot_id = snapshot.id
                      AND team.organization_id = mapping.organization_id
                      AND team.team_id = mapping.team_id
                )
            )
            AND NOT EXISTS (
                SELECT 1
                FROM github_membership_snapshots AS newer
                WHERE newer.tenant_id = snapshot.tenant_id
                  AND newer.principal_id = snapshot.principal_id
                  AND newer.provider_id = snapshot.provider_id
                  AND newer.provider_subject = snapshot.provider_subject
                  AND newer.observed_at_ms <= admitted_at
                  AND (
                      newer.observed_at_ms > snapshot.observed_at_ms
                      OR newer.observed_at_ms = snapshot.observed_at_ms
                      AND newer.id <> snapshot.id
                  )
            )
      )
    FOR SHARE OF session, principal, membership;
    IF actor_exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'workflow rerun request actor is not currently authorized'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'workflow_rerun_requests_authority_exact';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM rbac_role_bindings AS binding
        JOIN rbac_role_permissions AS permission
          ON permission.tenant_id = binding.tenant_id
         AND permission.role_id = binding.role_id
        WHERE binding.tenant_id = NEW.tenant_id
          AND binding.principal_id = NEW.actor_principal_id
          AND binding.status = 'active'
          AND (binding.valid_until_ms IS NULL OR binding.valid_until_ms > admitted_at)
          AND permission.permission_name = 'runs:rerun'
          AND (
              binding.scope_kind = 'tenant'
              AND binding.repository_id IS NULL
              AND binding.runner_group_id IS NULL
              OR binding.scope_kind = 'repository'
              AND binding.repository_id = NEW.repository_id
              AND binding.runner_group_id IS NULL
          )
    ) THEN
        SELECT snapshot.id, mapping.organization_id, mapping.team_id
          INTO mapped_snapshot_id, mapped_organization_id, mapped_team_id
        FROM github_membership_snapshots AS snapshot
        JOIN human_provider_identities AS identity
          ON identity.principal_id = snapshot.principal_id
         AND identity.provider_id = snapshot.provider_id
         AND identity.provider_subject = snapshot.provider_subject
        JOIN human_provider_tokens AS provider_token
          ON provider_token.tenant_id = snapshot.tenant_id
         AND provider_token.principal_id = snapshot.principal_id
         AND provider_token.provider_id = snapshot.provider_id
         AND provider_token.provider_subject = snapshot.provider_subject
         AND provider_token.version = snapshot.provider_token_version
        JOIN github_role_mappings AS mapping
          ON mapping.tenant_id = snapshot.tenant_id
         AND mapping.provider_id = snapshot.provider_id
         AND mapping.status = 'active'
        JOIN rbac_role_permissions AS mapped_permission
          ON mapped_permission.tenant_id = mapping.tenant_id
         AND mapped_permission.role_id = mapping.role_id
        WHERE snapshot.tenant_id = NEW.tenant_id
          AND snapshot.principal_id = NEW.actor_principal_id
          AND snapshot.provider_id = 'github'
          AND snapshot.provider_id = (
              SELECT session.provider_id FROM human_sessions AS session
              WHERE session.tenant_id = NEW.tenant_id
                AND session.principal_id = NEW.actor_principal_id
                AND session.id = NEW.actor_session_id
          )
          AND snapshot.provider_subject = (
              SELECT session.provider_subject FROM human_sessions AS session
              WHERE session.tenant_id = NEW.tenant_id
                AND session.principal_id = NEW.actor_principal_id
                AND session.id = NEW.actor_session_id
          )
          AND snapshot.provider_subject ~ '^[1-9][0-9]*$'
          AND length(snapshot.provider_subject) <= 20
          AND snapshot.provider_subject::NUMERIC <= 18446744073709551615
          AND snapshot.observed_at_ms <= admitted_at
          AND snapshot.valid_until_ms > admitted_at
          AND provider_token.revoked_at_ms IS NULL
          AND provider_token.issued_at_ms <= snapshot.observed_at_ms
          AND (
              provider_token.access_expires_at_ms IS NULL
              OR provider_token.access_expires_at_ms > admitted_at
              AND snapshot.valid_until_ms <= provider_token.access_expires_at_ms
          )
          AND mapped_permission.permission_name = 'runs:rerun'
          AND (
              mapping.scope_kind = 'tenant'
              AND mapping.repository_id IS NULL
              AND mapping.runner_group_id IS NULL
              OR mapping.scope_kind = 'repository'
              AND mapping.repository_id = NEW.repository_id
              AND mapping.runner_group_id IS NULL
          )
          AND (
              mapping.team_id IS NULL
              AND
              EXISTS (
                  SELECT 1
                  FROM github_organization_membership_observations AS organization
                  WHERE organization.tenant_id = snapshot.tenant_id
                    AND organization.snapshot_id = snapshot.id
                    AND organization.organization_id = mapping.organization_id
              )
              OR mapping.team_id IS NOT NULL
              AND EXISTS (
                  SELECT 1
                  FROM github_team_membership_observations AS team
                  WHERE team.tenant_id = snapshot.tenant_id
                    AND team.snapshot_id = snapshot.id
                    AND team.organization_id = mapping.organization_id
                    AND team.team_id = mapping.team_id
              )
          )
          AND NOT EXISTS (
              SELECT 1 FROM github_membership_snapshots AS newer
              WHERE newer.tenant_id = snapshot.tenant_id
                AND newer.principal_id = snapshot.principal_id
                AND newer.provider_id = snapshot.provider_id
                AND newer.provider_subject = snapshot.provider_subject
                AND newer.observed_at_ms <= admitted_at
                AND (
                    newer.observed_at_ms > snapshot.observed_at_ms
                    OR newer.observed_at_ms = snapshot.observed_at_ms
                    AND newer.id <> snapshot.id
                )
          )
        ORDER BY snapshot.observed_at_ms DESC, snapshot.id DESC
        LIMIT 1
        FOR SHARE OF snapshot, identity, provider_token, mapping,
                     mapped_permission;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'workflow rerun mapped actor evidence is not exact'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'workflow_rerun_requests_authority_exact';
        END IF;
        IF mapped_team_id IS NULL THEN
            PERFORM 1
            FROM github_organization_membership_observations AS organization
            WHERE organization.tenant_id = NEW.tenant_id
              AND organization.snapshot_id = mapped_snapshot_id
              AND organization.organization_id = mapped_organization_id
            FOR SHARE OF organization;
        ELSE
            PERFORM 1
            FROM github_organization_membership_observations AS organization
            JOIN github_team_membership_observations AS team
              ON team.tenant_id = organization.tenant_id
             AND team.snapshot_id = organization.snapshot_id
             AND team.organization_id = organization.organization_id
            WHERE organization.tenant_id = NEW.tenant_id
              AND organization.snapshot_id = mapped_snapshot_id
              AND organization.organization_id = mapped_organization_id
              AND team.team_id = mapped_team_id
            FOR SHARE OF organization, team;
        END IF;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'workflow rerun mapped membership evidence is not exact'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'workflow_rerun_requests_authority_exact';
        END IF;
    END IF;
    RETURN NEW;
END;
$_$;

CREATE FUNCTION automata_validate_workflow_run_public_rerun_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate workflow_runs%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'workflow_runs' THEN
        candidate := NEW;
    ELSE
        SELECT * INTO candidate FROM workflow_runs WHERE id = NEW.run_id;
    END IF;
    IF candidate.id IS NULL THEN
        RAISE EXCEPTION 'workflow rerun public identity has no physical run'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_run_public_rerun_identity_exact';
    ELSIF candidate.public_run_id_alias = candidate.run_id_alias THEN
        IF EXISTS (
            SELECT 1 FROM workflow_rerun_attempts AS attempt
            WHERE attempt.run_id = candidate.id
              AND attempt.source_run_id IS NOT NULL
        ) THEN
            RAISE EXCEPTION 'workflow run root public identity is not exact'
                USING ERRCODE = 'integrity_constraint_violation',
                      CONSTRAINT = 'workflow_run_public_rerun_identity_exact';
        END IF;
    ELSIF NOT EXISTS (
        SELECT 1
        FROM workflow_rerun_attempts AS attempt
        JOIN workflow_runs AS root ON root.id = attempt.root_run_id
        WHERE attempt.run_id = candidate.id
          AND attempt.source_run_id IS NOT NULL
          AND attempt.attempt = candidate.run_attempt
          AND root.run_attempt = 1
          AND root.run_id_alias = root.public_run_id_alias
          AND root.public_run_id_alias = candidate.public_run_id_alias
          AND root.workflow_id = candidate.workflow_id
          AND root.run_number = candidate.run_number
    ) THEN
        RAISE EXCEPTION 'workflow run public identity lacks exact rerun lineage'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_run_public_rerun_identity_exact';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_validate_workflow_runtime_policy_propagation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_revision BIGINT;
    expected_digest BYTEA;
    upstream_exact BOOLEAN := FALSE;
BEGIN
    SELECT policy_revision, policy_digest
      INTO expected_revision, expected_digest
    FROM logical_workflow_runtime_policy_pins AS pin
    WHERE run_id = NEW.run_id
    FOR KEY SHARE OF pin;
    IF NOT FOUND
        OR NEW.runtime_policy_revision IS DISTINCT FROM expected_revision
        OR NEW.runtime_policy_digest IS DISTINCT FROM expected_digest
    THEN
        RAISE EXCEPTION 'logical workflow row lacks its exact runtime policy pin'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runtime_policy_propagation_exact';
    END IF;

    -- The run pin is necessary but not sufficient: lock and compare the exact
    -- immediate historical chain so no direct SQL writer can splice two rows
    -- which happen to name the same run. No current pointer participates.
    IF TG_TABLE_NAME = 'logical_workflow_activation_preparation_claims' THEN
        SELECT (job.runtime_policy_revision, job.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
          INTO upstream_exact
        FROM logical_workflow_jobs AS job
        WHERE job.run_id = NEW.run_id
          AND job.invocation_id = NEW.invocation_id
          AND job.id = NEW.logical_job_id
        FOR KEY SHARE OF job;
    ELSIF TG_TABLE_NAME = 'logical_workflow_activation_preparations' THEN
        SELECT (claim.runtime_policy_revision, claim.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (job.runtime_policy_revision, job.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
          INTO upstream_exact
        FROM logical_workflow_activation_preparation_claims AS claim
        JOIN logical_workflow_jobs AS job
          ON job.run_id = claim.run_id
         AND job.invocation_id = claim.invocation_id
         AND job.id = claim.logical_job_id
        WHERE claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.logical_job_id = NEW.logical_job_id
        FOR KEY SHARE OF claim, job;
    ELSIF TG_TABLE_NAME = 'logical_workflow_activation_publications' THEN
        SELECT (preparation.runtime_policy_revision,
                preparation.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (job.runtime_policy_revision, job.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
          INTO upstream_exact
        FROM logical_workflow_activation_preparations AS preparation
        JOIN logical_workflow_jobs AS job
          ON job.run_id = preparation.run_id
         AND job.invocation_id = preparation.invocation_id
         AND job.id = preparation.logical_job_id
        WHERE preparation.run_id = NEW.run_id
          AND preparation.invocation_id = NEW.invocation_id
          AND preparation.logical_job_id = NEW.logical_job_id
        FOR KEY SHARE OF preparation, job;
    ELSIF TG_TABLE_NAME = 'logical_workflow_instances' THEN
        SELECT (publication.runtime_policy_revision,
                publication.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (job.runtime_policy_revision, job.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
          INTO upstream_exact
        FROM logical_workflow_activation_publications AS publication
        JOIN logical_workflow_jobs AS job
          ON job.run_id = publication.run_id
         AND job.invocation_id = publication.invocation_id
         AND job.id = publication.logical_job_id
        WHERE publication.run_id = NEW.run_id
          AND publication.invocation_id = NEW.invocation_id
          AND publication.logical_job_id = NEW.logical_job_id
        FOR KEY SHARE OF publication, job;
    ELSIF TG_TABLE_NAME = 'logical_workflow_materialization_claims' THEN
        SELECT (instance.runtime_policy_revision, instance.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (publication.runtime_policy_revision,
                    publication.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (job.runtime_policy_revision, job.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
          INTO upstream_exact
        FROM logical_workflow_instances AS instance
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = instance.run_id
         AND publication.invocation_id = instance.invocation_id
         AND publication.logical_job_id = instance.logical_job_id
        JOIN logical_workflow_jobs AS job
          ON job.run_id = instance.run_id
         AND job.invocation_id = instance.invocation_id
         AND job.id = instance.logical_job_id
        WHERE instance.id = NEW.instance_id
          AND instance.run_id = NEW.run_id
          AND instance.invocation_id = NEW.invocation_id
          AND instance.logical_job_id = NEW.logical_job_id
        FOR KEY SHARE OF instance, publication, job;
    ELSIF TG_TABLE_NAME = 'logical_workflow_concrete_jobs' THEN
        SELECT (claim.runtime_policy_revision, claim.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (instance.runtime_policy_revision, instance.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (publication.runtime_policy_revision,
                    publication.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
               AND (job.runtime_policy_revision, job.runtime_policy_digest)
                   IS NOT DISTINCT FROM (expected_revision, expected_digest)
          INTO upstream_exact
        FROM logical_workflow_materialization_claims AS claim
        JOIN logical_workflow_instances AS instance
          ON instance.id = claim.instance_id
         AND instance.run_id = claim.run_id
         AND instance.invocation_id = claim.invocation_id
         AND instance.logical_job_id = claim.logical_job_id
        JOIN logical_workflow_activation_publications AS publication
          ON publication.run_id = instance.run_id
         AND publication.invocation_id = instance.invocation_id
         AND publication.logical_job_id = instance.logical_job_id
        JOIN logical_workflow_jobs AS job
          ON job.run_id = instance.run_id
         AND job.invocation_id = instance.invocation_id
         AND job.id = instance.logical_job_id
        WHERE claim.instance_id = NEW.instance_id
          AND claim.run_id = NEW.run_id
          AND claim.invocation_id = NEW.invocation_id
          AND claim.logical_job_id = NEW.logical_job_id
        FOR KEY SHARE OF claim, instance, publication, job;
    ELSE
        RAISE EXCEPTION 'runtime policy propagation trigger is attached to an unknown table'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runtime_policy_propagation_table';
    END IF;

    IF upstream_exact IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'logical workflow runtime policy differs from its locked upstream chain'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_runtime_policy_upstream_exact';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_verify_provider_delivery_workflow_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    inventory provider_delivery_workflow_inventories%ROWTYPE;
    entry_count INTEGER;
BEGIN
    SELECT * INTO inventory
    FROM provider_delivery_workflow_inventories
    WHERE inbox_id = NEW.inbox_id;
    SELECT count(*) INTO entry_count
    FROM provider_delivery_workflow_inventory_entries
    WHERE inbox_id = NEW.inbox_id;
    IF inventory.inbox_id IS NULL
        OR inventory.workflow_count <> entry_count
        OR inventory.inventory_digest <>
            automata_provider_delivery_workflow_inventory_digest(NEW.inbox_id)
    THEN
        RAISE EXCEPTION 'provider delivery workflow inventory digest is not canonical'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'provider_delivery_workflow_inventory_digest_canonical';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_wake_github_check_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.desired_revision <> OLD.desired_revision THEN
        UPDATE github_check_projection_outbox
        SET state = 'pending',
            next_attempt_at_ms = NULL,
            last_failure_kind = NULL,
            blocked_reason = NULL,
            state_updated_at_ms = NEW.desired_updated_at_ms
        WHERE subject_id = NEW.id
          AND state IN ('pending', 'retry', 'delivered');
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_workflow_admission_github_evidence_flag_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.github_subject_evidence_required IS DISTINCT FROM
        OLD.github_subject_evidence_required
    THEN
        RAISE EXCEPTION 'workflow admission GitHub evidence expectation is immutable'
            USING ERRCODE = 'check_violation',
                  CONSTRAINT = 'workflow_admission_github_evidence_flag_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_logical_workflow_invocation_published(target_run_id uuid, target_invocation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM logical_workflow_runs AS marker
        WHERE marker.run_id = target_run_id
          AND (
              marker.root_invocation_id = target_invocation_id
              OR EXISTS (
                  SELECT 1
                  FROM logical_workflow_reusable_call_publications AS publication
                  JOIN workflow_runs AS run
                    ON run.id = publication.run_id
                  JOIN repositories AS repository
                    ON repository.id = run.repository_id
                   AND repository.tenant_id = publication.tenant_id
                   AND repository.id = publication.repository_id
                  JOIN logical_workflow_reusable_invocation_expansions AS planned
                    ON planned.run_id = publication.run_id
                   AND planned.parent_invocation_id = publication.parent_invocation_id
                   AND planned.caller_logical_job_id = publication.caller_logical_job_id
                   AND planned.invocation_id = publication.child_invocation_id
                  JOIN logical_workflow_reusable_workflow_catalog AS catalog
                    ON catalog.run_id = planned.run_id
                   AND catalog.catalog_entry_id = planned.catalog_entry_id
                  JOIN logical_workflow_invocations AS child
                    ON child.run_id = planned.run_id
                   AND child.id = planned.invocation_id
                  JOIN logical_workflow_jobs AS caller
                    ON caller.run_id = planned.run_id
                   AND caller.invocation_id = planned.parent_invocation_id
                   AND caller.id = planned.caller_logical_job_id
                  JOIN logical_workflow_reusable_permission_snapshots AS permissions
                    ON permissions.run_id = planned.run_id
                   AND permissions.invocation_id = planned.invocation_id
                   AND permissions.permission_digest = publication.permission_digest
                  JOIN logical_workflow_reusable_call_output_contracts AS output_contract
                    ON output_contract.run_id = publication.run_id
                   AND output_contract.child_invocation_id = publication.child_invocation_id
                   AND output_contract.mapping_count = publication.output_mapping_count
                   AND output_contract.mapping_digest = publication.output_mapping_digest
                  JOIN logical_workflow_runtime_policy_pins AS pin
                    ON pin.run_id = publication.run_id
                   AND pin.policy_revision = publication.runtime_policy_revision
                   AND pin.policy_digest = publication.runtime_policy_digest
                  WHERE publication.run_id = marker.run_id
                    AND publication.child_invocation_id = target_invocation_id
                    AND publication.condition_matched
                    AND publication.child_graph_sealed_at_ms = publication.published_at_ms
                    AND planned.depth > 0
                    AND child.invocation_kind = 'reusable'
                    AND child.plan_digest = catalog.plan_digest
                    AND child.plan_object_key = catalog.plan_object_key
                    AND child.plan_size_bytes = catalog.plan_size_bytes
                    AND child.plan_media_type = catalog.plan_media_type
                    AND child.plan_schema = catalog.plan_schema
                    AND child.state = 'active'
                    AND caller.execution_kind = 'reusable_workflow'
                    AND caller.state = 'activated'
                    AND caller.activation_fence = publication.activation_generation
                    AND caller.activation_input_digest = publication.activation_input_digest
                    AND caller.authority_profile = publication.authority_profile
                    AND caller.activation_owner_id IS NULL
                    AND caller.activation_claimed_at_ms IS NULL
                    AND caller.activation_expires_at_ms IS NULL
                    AND caller.activation_origin_selection_id IS NULL
                    AND (SELECT count(*)
                         FROM logical_workflow_jobs AS active
                         WHERE active.run_id = planned.run_id
                           AND active.invocation_id = planned.invocation_id)
                        = (SELECT count(*)
                           FROM logical_workflow_reusable_expanded_jobs AS expected
                           WHERE expected.run_id = planned.run_id
                             AND expected.invocation_id = planned.invocation_id)
                    AND NOT EXISTS (
                        SELECT 1
                        FROM logical_workflow_reusable_expanded_jobs AS expected
                        LEFT JOIN logical_workflow_jobs AS active
                          ON active.run_id = expected.run_id
                         AND active.invocation_id = expected.invocation_id
                         AND active.id = expected.logical_job_id
                         AND active.logical_key = expected.logical_key
                         AND active.source_order = expected.source_order
                         AND active.execution_kind = expected.execution_kind
                         AND active.runtime_policy_revision = publication.runtime_policy_revision
                         AND active.runtime_policy_digest = publication.runtime_policy_digest
                        WHERE expected.run_id = planned.run_id
                          AND expected.invocation_id = planned.invocation_id
                          AND active.id IS NULL
                    )
                    AND (SELECT count(*)
                         FROM logical_workflow_dependencies AS active
                         WHERE active.run_id = planned.run_id
                           AND active.invocation_id = planned.invocation_id)
                        = (SELECT count(*)
                           FROM logical_workflow_reusable_expanded_dependencies AS expected
                           WHERE expected.run_id = planned.run_id
                             AND expected.invocation_id = planned.invocation_id)
                    AND NOT EXISTS (
                        SELECT 1
                        FROM logical_workflow_reusable_expanded_dependencies AS expected
                        LEFT JOIN logical_workflow_dependencies AS active
                          ON active.run_id = expected.run_id
                         AND active.invocation_id = expected.invocation_id
                         AND active.logical_job_id = expected.logical_job_id
                         AND active.prerequisite_job_id = expected.prerequisite_job_id
                        WHERE expected.run_id = planned.run_id
                          AND expected.invocation_id = planned.invocation_id
                          AND active.logical_job_id IS NULL
                    )
              )
          )
    )
$$;

CREATE FUNCTION automata_workflow_rerun_check_requires_atomic_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    durable github_check_subjects%ROWTYPE;
    evidence workflow_rerun_check_evidence%ROWTYPE;
    run_evidence github_workflow_rerun_subject_evidence%ROWTYPE;
    outbox github_check_projection_outbox%ROWTYPE;
BEGIN
    IF NEW.origin_kind <> 'workflow_rerun' THEN
        RETURN NULL;
    END IF;
    SELECT * INTO durable
    FROM github_check_subjects
    WHERE id = NEW.id;
    SELECT * INTO evidence
    FROM workflow_rerun_check_evidence
    WHERE run_id = NEW.workflow_rerun_run_id
      AND github_check_subject_id = NEW.id;
    SELECT * INTO run_evidence
    FROM github_workflow_rerun_subject_evidence
    WHERE tenant_id = NEW.tenant_id
      AND run_id = NEW.workflow_rerun_run_id
      AND github_check_subject_id = NEW.id;
    SELECT * INTO outbox
    FROM github_check_projection_outbox
    WHERE subject_id = NEW.id;
    IF durable.id IS NULL
        OR durable.workflow_run_id <> NEW.workflow_rerun_run_id
        OR durable.linked_at_ms <> durable.created_at_ms
        OR durable.desired_state <> 'in_progress'
        OR durable.desired_conclusion IS NOT NULL
        OR durable.terminal_cause IS NOT NULL
        OR durable.desired_revision <> 2
        OR durable.desired_updated_at_ms <> durable.created_at_ms
        OR evidence.run_id IS NULL
        OR evidence.recorded_at_ms <> durable.created_at_ms
        OR run_evidence.run_id IS NULL
        OR run_evidence.github_check_head_sha <> durable.head_sha
        OR run_evidence.admitted_at_ms <> durable.created_at_ms
        OR octet_length(run_evidence.subject_evidence_sha256) <> 32
        OR outbox.subject_id IS NULL
        OR outbox.state <> 'pending'
        OR outbox.attempted_revision IS NOT NULL
        OR outbox.attempt_count <> 0
        OR outbox.claim_fence <> 0
        OR outbox.projected_revision <> 0
        OR outbox.state_updated_at_ms <> durable.created_at_ms
    THEN
        RAISE EXCEPTION 'workflow rerun Check requires atomic evidence and outbox'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_check_atomic_evidence_required';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_workflow_rerun_link_requires_run_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    evidence github_workflow_rerun_subject_evidence%ROWTYPE;
BEGIN
    IF NEW.origin_kind <> 'workflow_rerun'
        OR OLD.workflow_run_id IS NOT NULL
        OR NEW.workflow_run_id IS NULL
    THEN
        RETURN NULL;
    END IF;
    SELECT * INTO evidence
    FROM github_workflow_rerun_subject_evidence
    WHERE tenant_id = NEW.tenant_id
      AND repository_id = NEW.repository_id
      AND run_id = NEW.workflow_run_id
      AND github_check_subject_id = NEW.id;
    IF evidence.run_id IS NULL
        OR NEW.workflow_run_id <> NEW.workflow_rerun_run_id
        OR NEW.linked_at_ms <> evidence.admitted_at_ms
        OR NEW.desired_state <> 'in_progress'
        OR NEW.desired_conclusion IS NOT NULL
        OR NEW.terminal_cause IS NOT NULL
        OR NEW.desired_revision <> 2
        OR NEW.desired_updated_at_ms <> evidence.admitted_at_ms
        OR NEW.head_sha <> evidence.github_check_head_sha
    THEN
        RAISE EXCEPTION 'workflow rerun Check link requires exact run evidence'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_rerun_check_link_evidence_required';
    END IF;
    RETURN NULL;
END;
$$;

CREATE FUNCTION automata_workflow_rerun_now_ms() RETURNS bigint
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
    SELECT floor(extract(epoch FROM transaction_timestamp()) * 1000)::BIGINT
$$;

CREATE FUNCTION automata_workflow_run_publication_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.publication_policy_revision IS DISTINCT FROM OLD.publication_policy_revision
       OR NEW.requested_dashboard_visibility IS DISTINCT FROM OLD.requested_dashboard_visibility
       OR NEW.effective_dashboard_visibility IS DISTINCT FROM OLD.effective_dashboard_visibility
       OR NEW.requested_log_visibility IS DISTINCT FROM OLD.requested_log_visibility
       OR NEW.requested_artifact_visibility IS DISTINCT FROM OLD.requested_artifact_visibility
       OR NEW.publication_safety_reason IS DISTINCT FROM OLD.publication_safety_reason
       OR NEW.publication_safety_schema IS DISTINCT FROM OLD.publication_safety_schema THEN
        RAISE EXCEPTION 'workflow run publication snapshots are immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_runs_publication_snapshot_immutable';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION automata_workflow_runtime_permission_policy_digest(bytea) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
    document JSONB;
    permission_map JSONB;
    section_name TEXT;
    digest_label TEXT;
    section_index INTEGER := 0;
    entry_count BIGINT;
    map_canonical TEXT;
    canonical TEXT := '{';
    encoded BYTEA := pg_catalog.convert_to('permissions', 'UTF8')
        || pg_catalog.decode('00', 'hex');
    permission_entry RECORD;
BEGIN
    document := pg_catalog.convert_from($1, 'UTF8')::JSONB;
    IF pg_catalog.jsonb_typeof(document) <> 'object'
        OR (SELECT count(*) FROM pg_catalog.jsonb_object_keys(document)) <> 3
        OR NOT document ? 'provider_default'
        OR NOT document ? 'read_all'
        OR NOT document ? 'write_all'
    THEN
        RETURN NULL;
    END IF;

    FOR section_name, digest_label IN
        SELECT sections.section_name, sections.digest_label FROM (VALUES
            (1, 'provider_default', 'provider-default'),
            (2, 'read_all', 'read-all'),
            (3, 'write_all', 'write-all')
        ) AS sections(ordinal, section_name, digest_label)
        ORDER BY sections.ordinal
    LOOP
        permission_map := document->section_name;
        IF pg_catalog.jsonb_typeof(permission_map) <> 'object' THEN
            RETURN NULL;
        END IF;
        SELECT count(*) INTO entry_count
        FROM pg_catalog.jsonb_object_keys(permission_map);
        IF entry_count NOT BETWEEN 1 AND 64 THEN
            RETURN NULL;
        END IF;

        encoded := encoded
            || pg_catalog.convert_to(digest_label, 'UTF8')
            || pg_catalog.decode('00', 'hex')
            || pg_catalog.int8send(entry_count);
        FOR permission_entry IN
            SELECT key, value
            FROM pg_catalog.jsonb_each_text(permission_map)
            ORDER BY key COLLATE "C"
        LOOP
            IF pg_catalog.octet_length(permission_entry.key) NOT BETWEEN 1 AND 64
                OR permission_entry.key !~ '^[a-z]([a-z0-9]|-[a-z0-9])*$'
                OR permission_entry.value NOT IN ('read', 'write')
                OR (permission_entry.key = 'id-token' AND permission_entry.value = 'read')
                OR (section_name = 'read_all' AND permission_entry.value <> 'read')
            THEN
                RETURN NULL;
            END IF;
            encoded := encoded
                || automata_workflow_runtime_policy_digest_part(
                    pg_catalog.convert_to(permission_entry.key, 'UTF8')
                )
                || CASE permission_entry.value
                    WHEN 'read' THEN pg_catalog.decode('01', 'hex')
                    WHEN 'write' THEN pg_catalog.decode('02', 'hex')
                   END;
        END LOOP;

        SELECT string_agg(
            pg_catalog.to_json(key)::TEXT || ':' || pg_catalog.to_json(value)::TEXT,
            ',' ORDER BY key COLLATE "C"
        ) INTO map_canonical
        FROM pg_catalog.jsonb_each_text(permission_map);
        IF section_index > 0 THEN
            canonical := canonical || ',';
        END IF;
        canonical := canonical || pg_catalog.to_json(section_name)::TEXT
            || ':{' || map_canonical || '}';
        section_index := section_index + 1;
    END LOOP;
    canonical := canonical || '}';

    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_each_text(document->'read_all') AS read_permission
        WHERE NOT ((document->'write_all') ? (read_permission.key))
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_each_text(document->'write_all') AS write_permission
        WHERE write_permission.key <> 'id-token'
          AND NOT ((document->'read_all') ? (write_permission.key))
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_each_text(document->'provider_default') AS default_permission
        WHERE NOT ((document->'read_all') ? (default_permission.key))
           OR NOT ((document->'write_all') ? (default_permission.key))
           OR CASE default_permission.value WHEN 'read' THEN 1 WHEN 'write' THEN 2 END
              > CASE ((document->'write_all')->>(default_permission.key))
                    WHEN 'read' THEN 1 WHEN 'write' THEN 2 ELSE 0
                END
    ) OR pg_catalog.convert_to(canonical, 'UTF8') IS DISTINCT FROM $1 THEN
        RETURN NULL;
    END IF;
    RETURN encoded;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$_$;

CREATE FUNCTION automata_workflow_runtime_policy_canonical(text, uuid, bigint) RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
    AS $_$
WITH header AS (
    SELECT policy_schema, workspace_root, workspace_derivation_version,
           mapping_count, permission_policy_canonical, resource_policy_canonical
    FROM workflow_runtime_policy_revisions
    WHERE tenant_id = $1 AND repository_id = $2 AND policy_revision = $3
), mapping_parts AS (
    SELECT mapping.selector,
           '{"selector":' || pg_catalog.to_json(mapping.selector)::TEXT
           || ',"environment_profile":{"id":'
           || pg_catalog.to_json(mapping.environment_profile_id)::TEXT
           || ',"manifest_sha256":"'
           || pg_catalog.encode(mapping.environment_profile_digest, 'hex')
           || '"},"operating_system":'
           || pg_catalog.to_json(mapping.operating_system)::TEXT
           || ',"architecture":'
           || pg_catalog.to_json(mapping.architecture)::TEXT
           || ',"container_features":['
           || COALESCE(
                string_agg(
                    pg_catalog.to_json(feature.feature)::TEXT,
                    ',' ORDER BY feature.feature
                ),
                ''
              )
           || ']}' AS encoded,
           count(feature.feature)::INTEGER AS actual_feature_count,
           mapping.feature_count
    FROM workflow_runtime_policy_mappings AS mapping
    LEFT JOIN workflow_runtime_policy_features AS feature
      ON feature.tenant_id = mapping.tenant_id
     AND feature.repository_id = mapping.repository_id
     AND feature.policy_revision = mapping.policy_revision
     AND feature.selector = mapping.selector
    WHERE mapping.tenant_id = $1
      AND mapping.repository_id = $2
      AND mapping.policy_revision = $3
    GROUP BY mapping.selector, mapping.environment_profile_id,
             mapping.environment_profile_digest, mapping.operating_system,
             mapping.architecture, mapping.feature_count
), catalog AS (
    SELECT count(*)::INTEGER AS actual_mapping_count,
           bool_and(actual_feature_count = feature_count) AS features_exact,
           COALESCE(string_agg(encoded, ',' ORDER BY selector), '') AS encoded
    FROM mapping_parts
)
SELECT pg_catalog.convert_to(
    '{"schema":1,"workspace":{"schema":1,"root":"/__w","derivation":1},"mappings":['
    || catalog.encoded || '],"permissions":'
    || pg_catalog.convert_from(header.permission_policy_canonical, 'UTF8')
    || ',"resources":'
    || pg_catalog.convert_from(header.resource_policy_canonical, 'UTF8')
    || '}',
    'UTF8'
)
FROM header CROSS JOIN catalog
WHERE header.policy_schema = 1
  AND header.workspace_root = '/__w'
  AND header.workspace_derivation_version = 1
  AND automata_workflow_runtime_permission_policy_digest(
      header.permission_policy_canonical
  ) IS NOT NULL
  AND header.mapping_count = catalog.actual_mapping_count
  AND catalog.features_exact IS TRUE
$_$;

CREATE FUNCTION automata_workflow_runtime_policy_digest(text, uuid, bigint) RETURNS bytea
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
    AS $_$
WITH header AS (
    SELECT policy_schema, workspace_root, workspace_derivation_version,
           mapping_count, permission_policy_canonical, resource_policy_canonical
    FROM workflow_runtime_policy_revisions
    WHERE tenant_id = $1 AND repository_id = $2 AND policy_revision = $3
), mapping_parts AS (
    SELECT mapping.selector,
           automata_workflow_runtime_policy_digest_part(
               pg_catalog.convert_to(mapping.selector, 'UTF8')
           )
           || automata_workflow_runtime_policy_digest_part(
               pg_catalog.convert_to(mapping.environment_profile_id, 'UTF8')
           )
           || mapping.environment_profile_digest
           || CASE mapping.operating_system
                WHEN 'linux' THEN pg_catalog.decode('01', 'hex')
                WHEN 'windows' THEN pg_catalog.decode('02', 'hex')
                WHEN 'macos' THEN pg_catalog.decode('03', 'hex')
              END
           || CASE mapping.architecture
                WHEN 'x86_64' THEN pg_catalog.decode('01', 'hex')
                WHEN 'aarch64' THEN pg_catalog.decode('02', 'hex')
              END
           || pg_catalog.int8send(count(feature.feature)::BIGINT)
           || COALESCE(
                string_agg(
                    automata_workflow_runtime_policy_digest_part(
                        pg_catalog.convert_to(feature.feature, 'UTF8')
                    ),
                    pg_catalog.decode('', 'hex') ORDER BY feature.feature
                ),
                pg_catalog.decode('', 'hex')
              ) AS encoded,
           count(feature.feature)::INTEGER AS actual_feature_count,
           mapping.feature_count
    FROM workflow_runtime_policy_mappings AS mapping
    LEFT JOIN workflow_runtime_policy_features AS feature
      ON feature.tenant_id = mapping.tenant_id
     AND feature.repository_id = mapping.repository_id
     AND feature.policy_revision = mapping.policy_revision
     AND feature.selector = mapping.selector
    WHERE mapping.tenant_id = $1
      AND mapping.repository_id = $2
      AND mapping.policy_revision = $3
    GROUP BY mapping.selector, mapping.environment_profile_id,
             mapping.environment_profile_digest, mapping.operating_system,
             mapping.architecture, mapping.feature_count
), catalog AS (
    SELECT count(*)::INTEGER AS actual_mapping_count,
           bool_and(actual_feature_count = feature_count) AS features_exact,
           COALESCE(
               string_agg(encoded, pg_catalog.decode('', 'hex') ORDER BY selector),
               pg_catalog.decode('', 'hex')
           ) AS encoded
    FROM mapping_parts
)
SELECT pg_catalog.sha256(
    pg_catalog.convert_to('automata.store.workflow-runtime-policy.v2', 'UTF8')
    || pg_catalog.decode('00', 'hex')
    || pg_catalog.int2send(header.policy_schema)
    || pg_catalog.int2send(header.workspace_derivation_version)
    || automata_workflow_runtime_policy_digest_part(
        pg_catalog.convert_to(header.workspace_root, 'UTF8')
    )
    || pg_catalog.int8send(header.mapping_count::BIGINT)
    || catalog.encoded
    || automata_workflow_runtime_permission_policy_digest(
        header.permission_policy_canonical
    )
    || automata_workflow_runtime_resource_policy_digest(
        header.resource_policy_canonical
    )
)
FROM header CROSS JOIN catalog
WHERE header.policy_schema = 1
  AND automata_workflow_runtime_permission_policy_digest(
      header.permission_policy_canonical
  ) IS NOT NULL
  AND automata_workflow_runtime_resource_policy_digest(
      header.resource_policy_canonical
  ) IS NOT NULL
  AND header.mapping_count = catalog.actual_mapping_count
  AND catalog.features_exact IS TRUE
$_$;

CREATE FUNCTION automata_workflow_runtime_policy_digest_part(bytea) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
SELECT pg_catalog.int8send(pg_catalog.octet_length($1)::BIGINT) || $1
$_$;

CREATE FUNCTION automata_workflow_runtime_resource_policy_digest(bytea) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
DECLARE
    document JSONB;
    capacity JSONB;
    encoded BYTEA := pg_catalog.convert_to('resources', 'UTF8')
        || pg_catalog.decode('00', 'hex');
    cpu NUMERIC;
    memory NUMERIC;
    ephemeral NUMERIC;
    gpu BIGINT;
    canonical TEXT;
BEGIN
    document := pg_catalog.convert_from($1, 'UTF8')::JSONB;
    IF pg_catalog.jsonb_typeof(document) <> 'object'
        OR (SELECT count(*) FROM pg_catalog.jsonb_object_keys(document)) <> 3
        OR pg_catalog.jsonb_typeof(document->'defaults') <> 'object'
        OR (SELECT count(*) FROM pg_catalog.jsonb_object_keys(document->'defaults')) <> 2
        OR pg_catalog.jsonb_typeof(document#>'{defaults,requests}') <> 'object'
        OR pg_catalog.jsonb_typeof(document#>'{defaults,limits}') <> 'object'
        OR pg_catalog.jsonb_typeof(document->'minimum_requests') <> 'object'
        OR pg_catalog.jsonb_typeof(document->'maximum_limits') <> 'object'
    THEN
        RETURN NULL;
    END IF;

    FOR capacity IN
        SELECT value
        FROM pg_catalog.jsonb_array_elements(pg_catalog.jsonb_build_array(
            document#>'{defaults,requests}',
            document#>'{defaults,limits}',
            document->'minimum_requests',
            document->'maximum_limits'
        ))
    LOOP
        IF (SELECT count(*) FROM pg_catalog.jsonb_object_keys(capacity)) <> 4 THEN
            RETURN NULL;
        END IF;
        IF pg_catalog.jsonb_typeof(capacity->'cpu_millis') <> 'number'
            OR pg_catalog.jsonb_typeof(capacity->'memory_bytes') <> 'number'
            OR pg_catalog.jsonb_typeof(capacity->'ephemeral_disk_bytes') <> 'number'
            OR pg_catalog.jsonb_typeof(capacity->'gpu_count') <> 'number'
            OR capacity->>'cpu_millis' !~ '^(0|[1-9][0-9]*)$'
            OR capacity->>'memory_bytes' !~ '^(0|[1-9][0-9]*)$'
            OR capacity->>'ephemeral_disk_bytes' !~ '^(0|[1-9][0-9]*)$'
            OR capacity->>'gpu_count' !~ '^(0|[1-9][0-9]*)$'
        THEN
            RETURN NULL;
        END IF;
        cpu := (capacity->>'cpu_millis')::NUMERIC;
        memory := (capacity->>'memory_bytes')::NUMERIC;
        ephemeral := (capacity->>'ephemeral_disk_bytes')::NUMERIC;
        gpu := (capacity->>'gpu_count')::BIGINT;
        IF cpu NOT BETWEEN 0 AND 4294967295
            OR memory NOT BETWEEN 0 AND 18446744073709551615
            OR ephemeral NOT BETWEEN 0 AND 18446744073709551615
            OR gpu NOT BETWEEN 0 AND 65535
        THEN
            RETURN NULL;
        END IF;
        encoded := encoded
            || pg_catalog.decode(
                pg_catalog.lpad(pg_catalog.to_hex(cpu::BIGINT), 8, '0'), 'hex'
            )
            || pg_catalog.decode(
                pg_catalog.lpad(
                    pg_catalog.to_hex(pg_catalog.trunc(memory / 4294967296)::BIGINT),
                    8, '0'
                )
                || pg_catalog.lpad(
                    pg_catalog.to_hex(pg_catalog.mod(memory, 4294967296)::BIGINT),
                    8, '0'
                ),
                'hex'
            )
            || pg_catalog.decode(
                pg_catalog.lpad(
                    pg_catalog.to_hex(pg_catalog.trunc(ephemeral / 4294967296)::BIGINT),
                    8, '0'
                )
                || pg_catalog.lpad(
                    pg_catalog.to_hex(pg_catalog.mod(ephemeral, 4294967296)::BIGINT),
                    8, '0'
                ),
                'hex'
            )
            || pg_catalog.decode(pg_catalog.lpad(pg_catalog.to_hex(gpu), 4, '0'), 'hex');
    END LOOP;

    IF (document#>>'{defaults,requests,cpu_millis}')::NUMERIC <= 0
        OR (document#>>'{defaults,requests,memory_bytes}')::NUMERIC <= 0
        OR (document#>>'{defaults,limits,cpu_millis}')::NUMERIC <= 0
        OR (document#>>'{defaults,limits,memory_bytes}')::NUMERIC <= 0
        OR (document#>>'{minimum_requests,cpu_millis}')::NUMERIC <= 0
        OR (document#>>'{minimum_requests,memory_bytes}')::NUMERIC <= 0
        OR (document#>>'{maximum_limits,cpu_millis}')::NUMERIC <= 0
        OR (document#>>'{maximum_limits,memory_bytes}')::NUMERIC <= 0
        OR (document#>>'{defaults,requests,cpu_millis}')::NUMERIC
            > (document#>>'{defaults,limits,cpu_millis}')::NUMERIC
        OR (document#>>'{defaults,requests,memory_bytes}')::NUMERIC
            > (document#>>'{defaults,limits,memory_bytes}')::NUMERIC
        OR (document#>>'{defaults,requests,ephemeral_disk_bytes}')::NUMERIC
            > (document#>>'{defaults,limits,ephemeral_disk_bytes}')::NUMERIC
        OR (document#>>'{defaults,requests,gpu_count}')::NUMERIC
            <> (document#>>'{defaults,limits,gpu_count}')::NUMERIC
        OR (document#>>'{minimum_requests,cpu_millis}')::NUMERIC
            > (document#>>'{defaults,requests,cpu_millis}')::NUMERIC
        OR (document#>>'{minimum_requests,memory_bytes}')::NUMERIC
            > (document#>>'{defaults,requests,memory_bytes}')::NUMERIC
        OR (document#>>'{minimum_requests,ephemeral_disk_bytes}')::NUMERIC
            > (document#>>'{defaults,requests,ephemeral_disk_bytes}')::NUMERIC
        OR (document#>>'{minimum_requests,gpu_count}')::NUMERIC
            > (document#>>'{defaults,requests,gpu_count}')::NUMERIC
        OR (document#>>'{defaults,limits,cpu_millis}')::NUMERIC
            > (document#>>'{maximum_limits,cpu_millis}')::NUMERIC
        OR (document#>>'{defaults,limits,memory_bytes}')::NUMERIC
            > (document#>>'{maximum_limits,memory_bytes}')::NUMERIC
        OR (document#>>'{defaults,limits,ephemeral_disk_bytes}')::NUMERIC
            > (document#>>'{maximum_limits,ephemeral_disk_bytes}')::NUMERIC
        OR (document#>>'{defaults,limits,gpu_count}')::NUMERIC
            > (document#>>'{maximum_limits,gpu_count}')::NUMERIC
    THEN
        RETURN NULL;
    END IF;
    canonical := '{"defaults":{"requests":{"cpu_millis":'
        || (document#>>'{defaults,requests,cpu_millis}')
        || ',"memory_bytes":' || (document#>>'{defaults,requests,memory_bytes}')
        || ',"ephemeral_disk_bytes":'
        || (document#>>'{defaults,requests,ephemeral_disk_bytes}')
        || ',"gpu_count":' || (document#>>'{defaults,requests,gpu_count}')
        || '},"limits":{"cpu_millis":'
        || (document#>>'{defaults,limits,cpu_millis}')
        || ',"memory_bytes":' || (document#>>'{defaults,limits,memory_bytes}')
        || ',"ephemeral_disk_bytes":'
        || (document#>>'{defaults,limits,ephemeral_disk_bytes}')
        || ',"gpu_count":' || (document#>>'{defaults,limits,gpu_count}')
        || '}},"minimum_requests":{"cpu_millis":'
        || (document#>>'{minimum_requests,cpu_millis}')
        || ',"memory_bytes":' || (document#>>'{minimum_requests,memory_bytes}')
        || ',"ephemeral_disk_bytes":'
        || (document#>>'{minimum_requests,ephemeral_disk_bytes}')
        || ',"gpu_count":' || (document#>>'{minimum_requests,gpu_count}')
        || '},"maximum_limits":{"cpu_millis":'
        || (document#>>'{maximum_limits,cpu_millis}')
        || ',"memory_bytes":' || (document#>>'{maximum_limits,memory_bytes}')
        || ',"ephemeral_disk_bytes":'
        || (document#>>'{maximum_limits,ephemeral_disk_bytes}')
        || ',"gpu_count":' || (document#>>'{maximum_limits,gpu_count}')
        || '}}';
    IF pg_catalog.convert_to(canonical, 'UTF8') IS DISTINCT FROM $1 THEN
        RETURN NULL;
    END IF;
    RETURN encoded;
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$_$;

CREATE FUNCTION automata_workflow_variable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.repository_id IS DISTINCT FROM OLD.repository_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
       OR NEW.canonical_name IS DISTINCT FROM OLD.canonical_name
       OR NEW.created_by_principal_id IS DISTINCT FROM OLD.created_by_principal_id
       OR NEW.created_at_ms IS DISTINCT FROM OLD.created_at_ms THEN
        RAISE EXCEPTION 'workflow variable identity is immutable'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_variables_identity_immutable';
    END IF;
    IF NEW IS DISTINCT FROM OLD AND NEW.revision <> OLD.revision + 1 THEN
        RAISE EXCEPTION 'workflow variable mutation requires one revision increment'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_variables_revision_guard';
    END IF;
    IF NEW.current_version_number IS DISTINCT FROM OLD.current_version_number
       AND NEW.current_version_number <> COALESCE(OLD.current_version_number, 0) + 1 THEN
        RAISE EXCEPTION 'workflow variable versions are monotonic'
            USING ERRCODE = 'integrity_constraint_violation',
                  CONSTRAINT = 'workflow_variables_version_guard';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION guard_human_session_activation_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.session_kind = 'browser' THEN
            IF NEW.lifecycle_status <> 'active'
               OR NEW.activation_deadline_ms IS NOT NULL
               OR NEW.activated_at_ms IS NOT NULL THEN
                RAISE EXCEPTION 'browser sessions are immediately active'
                    USING ERRCODE = '23514';
            END IF;
        ELSIF NEW.session_kind = 'cli' THEN
            IF NEW.lifecycle_status <> 'pending_activation'
               OR NEW.activation_deadline_ms IS NULL
               OR NEW.activated_at_ms IS NOT NULL THEN
                RAISE EXCEPTION 'new CLI sessions must await activation'
                    USING ERRCODE = '23514';
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.session_kind IS DISTINCT FROM OLD.session_kind
       OR NEW.audience IS DISTINCT FROM OLD.audience
       OR NEW.issued_at_ms IS DISTINCT FROM OLD.issued_at_ms
       OR NEW.expires_at_ms IS DISTINCT FROM OLD.expires_at_ms
       OR NEW.activation_deadline_ms IS DISTINCT FROM OLD.activation_deadline_ms THEN
        RAISE EXCEPTION 'session activation identity and deadline are immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.lifecycle_status = 'pending_activation'
       AND NEW.lifecycle_status = 'active' THEN
        IF OLD.session_kind <> 'cli'
           OR OLD.audience <> 'automata.cli'
           OR OLD.activated_at_ms IS NOT NULL
           OR NEW.activated_at_ms IS NULL
           OR NEW.activated_at_ms < OLD.issued_at_ms
           OR NEW.activated_at_ms >= OLD.activation_deadline_ms
           OR NEW.revision <> OLD.revision + 1 THEN
            RAISE EXCEPTION 'invalid CLI session activation transition'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.lifecycle_status IS DISTINCT FROM OLD.lifecycle_status
       OR NEW.activated_at_ms IS DISTINCT FROM OLD.activated_at_ms THEN
        RAISE EXCEPTION 'session activation lifecycle is monotonic'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;

CREATE TABLE attempt_cancellation_intents (
    attempt_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    requested_by text NOT NULL,
    reason text,
    requested_at_ms bigint NOT NULL,
    acknowledged_at_ms bigint,
    delivery_session_id uuid,
    delivery_command_sequence bigint,
    CONSTRAINT attempt_cancellation_ack_monotonic CHECK (((acknowledged_at_ms IS NULL) OR (acknowledged_at_ms >= requested_at_ms))),
    CONSTRAINT attempt_cancellation_actor_shape CHECK ((((octet_length(requested_by) >= 1) AND (octet_length(requested_by) <= 255)) AND (requested_by !~ '[[:cntrl:]]'::text))),
    CONSTRAINT attempt_cancellation_delivery_complete CHECK ((((delivery_session_id IS NULL) AND (delivery_command_sequence IS NULL)) OR ((delivery_session_id IS NOT NULL) AND (delivery_command_sequence IS NOT NULL)))),
    CONSTRAINT attempt_cancellation_reason_shape CHECK (((reason IS NULL) OR (((octet_length(reason) >= 1) AND (octet_length(reason) <= 1024)) AND (reason !~ '[[:cntrl:]]'::text))))
);

CREATE TABLE attempt_log_segments (
    stream_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    first_sequence bigint NOT NULL,
    last_sequence bigint NOT NULL,
    object_key text NOT NULL,
    object_digest bytea NOT NULL,
    encoded_size_bytes bigint NOT NULL,
    uncompressed_size_bytes bigint NOT NULL,
    stored_at_ms bigint NOT NULL,
    end_of_stream boolean DEFAULT false NOT NULL,
    CONSTRAINT attempt_log_segments_encoded_size CHECK (((encoded_size_bytes >= 1) AND (encoded_size_bytes <= 67108864))),
    CONSTRAINT attempt_log_segments_object_key_shape CHECK ((((octet_length(object_key) >= 1) AND (octet_length(object_key) <= 1024)) AND (object_key !~ '[[:cntrl:]]'::text))),
    CONSTRAINT attempt_log_segments_sequence_range CHECK (((first_sequence >= 0) AND (last_sequence >= first_sequence))),
    CONSTRAINT attempt_log_segments_sha256 CHECK ((octet_length(object_digest) = 32)),
    CONSTRAINT attempt_log_segments_uncompressed_size CHECK (((uncompressed_size_bytes >= 1) AND (uncompressed_size_bytes <= 268435456)))
);

CREATE TABLE attempt_log_streams (
    id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    runner_session_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    runner_id uuid NOT NULL,
    runner_session_epoch bigint NOT NULL,
    runner_generation bigint NOT NULL,
    runner_slot integer NOT NULL,
    lease_id uuid NOT NULL,
    fencing_token bigint NOT NULL,
    log_schema integer NOT NULL,
    opened_at_ms bigint NOT NULL,
    closed_at_ms bigint,
    secret_exposure_class text DEFAULT 'readable_secret'::text NOT NULL,
    raw_log_disposition text DEFAULT 'persist'::text NOT NULL,
    requested_visibility text DEFAULT 'private'::text NOT NULL,
    effective_visibility text DEFAULT 'private'::text NOT NULL,
    output_safety_reason text DEFAULT 'repository_policy'::text NOT NULL,
    output_safety_schema integer DEFAULT 1 NOT NULL,
    CONSTRAINT attempt_log_streams_close_monotonic CHECK (((closed_at_ms IS NULL) OR (closed_at_ms >= opened_at_ms))),
    CONSTRAINT attempt_log_streams_exposure_safety CHECK (((output_safety_schema = 1) AND (raw_log_disposition = 'persist'::text) AND ((secret_exposure_class <> 'readable_secret'::text) OR (effective_visibility = 'private'::text)))),
    CONSTRAINT attempt_log_streams_fence_positive CHECK ((fencing_token > 0)),
    CONSTRAINT attempt_log_streams_output_safety_reason_code CHECK ((output_safety_reason = ANY (ARRAY['repository_policy'::text, 'secret_exposure'::text]))),
    CONSTRAINT attempt_log_streams_output_safety_schema CHECK ((output_safety_schema = 1)),
    CONSTRAINT attempt_log_streams_raw_log_disposition CHECK ((raw_log_disposition = 'persist'::text)),
    CONSTRAINT attempt_log_streams_schema_range CHECK (((log_schema >= 1) AND (log_schema <= 65535))),
    CONSTRAINT attempt_log_streams_secret_exposure_class CHECK ((secret_exposure_class = ANY (ARRAY['secretless'::text, 'capability_only'::text, 'readable_secret'::text]))),
    CONSTRAINT attempt_log_streams_slot_range CHECK (((runner_slot >= 1) AND (runner_slot <= 65535))),
    CONSTRAINT attempt_log_streams_visibility CHECK (((requested_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])) AND (effective_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])))),
    CONSTRAINT attempt_log_streams_visibility_cap CHECK (((effective_visibility = 'private'::text) OR ((effective_visibility = 'authenticated'::text) AND (requested_visibility = ANY (ARRAY['authenticated'::text, 'public'::text]))) OR ((effective_visibility = 'public'::text) AND (requested_visibility = 'public'::text))))
);

CREATE TABLE attempt_terminal_results (
    attempt_id uuid NOT NULL,
    runner_session_id uuid,
    operation_id uuid,
    runner_id uuid,
    runner_session_epoch bigint,
    runner_generation bigint,
    runner_slot integer,
    lease_id uuid,
    fencing_token bigint,
    result_schema integer,
    result_size_bytes bigint,
    result_digest bytea,
    result_object_key text,
    conclusion text NOT NULL,
    completed_at_ms bigint NOT NULL,
    committed_at_ms bigint NOT NULL,
    logical_workflow_logical_job_id uuid,
    logical_workflow_terminal_ordinal bigint,
    terminal_authority text NOT NULL,
    server_cancellation_operation_id uuid,
    server_cancellation_digest bytea,
    CONSTRAINT attempt_terminal_results_conclusion CHECK ((conclusion = ANY (ARRAY['success'::text, 'failure'::text, 'cancelled'::text, 'timed_out'::text, 'skipped'::text]))),
    CONSTRAINT attempt_terminal_results_fence_positive CHECK ((fencing_token > 0)),
    CONSTRAINT attempt_terminal_results_object_key_shape CHECK ((((octet_length(result_object_key) >= 1) AND (octet_length(result_object_key) <= 1024)) AND (result_object_key !~ '[[:cntrl:]]'::text))),
    CONSTRAINT attempt_terminal_results_schema_range CHECK (((result_schema >= 1) AND (result_schema <= 65535))),
    CONSTRAINT attempt_terminal_results_server_cancellation_digest_sha256 CHECK (((server_cancellation_digest IS NULL) OR (octet_length(server_cancellation_digest) = 32))),
    CONSTRAINT attempt_terminal_results_sha256 CHECK ((octet_length(result_digest) = 32)),
    CONSTRAINT attempt_terminal_results_size_range CHECK (((result_size_bytes >= 1) AND (result_size_bytes <= 16777216))),
    CONSTRAINT attempt_terminal_results_slot_range CHECK (((runner_slot >= 1) AND (runner_slot <= 65535))),
    CONSTRAINT attempt_terminal_results_terminal_authority_shape CHECK (((((terminal_authority = 'runner'::text) AND (runner_session_id IS NOT NULL) AND (operation_id IS NOT NULL) AND (runner_id IS NOT NULL) AND (runner_session_epoch IS NOT NULL) AND (runner_generation IS NOT NULL) AND (runner_slot IS NOT NULL) AND (lease_id IS NOT NULL) AND (fencing_token IS NOT NULL) AND (result_schema IS NOT NULL) AND (result_size_bytes IS NOT NULL) AND (result_digest IS NOT NULL) AND (result_object_key IS NOT NULL) AND (server_cancellation_operation_id IS NULL) AND (server_cancellation_digest IS NULL)) OR ((terminal_authority = 'server_cancellation'::text) AND (runner_session_id IS NULL) AND (operation_id IS NULL) AND (runner_id IS NULL) AND (runner_session_epoch IS NULL) AND (runner_generation IS NULL) AND (runner_slot IS NULL) AND (lease_id IS NULL) AND (fencing_token IS NULL) AND (result_schema IS NULL) AND (result_size_bytes IS NULL) AND (result_digest IS NULL) AND (result_object_key IS NULL) AND (server_cancellation_operation_id IS NOT NULL) AND (server_cancellation_operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (server_cancellation_digest IS NOT NULL) AND (conclusion = 'cancelled'::text))) IS TRUE)),
    CONSTRAINT attempt_terminal_results_time_monotonic CHECK ((committed_at_ms >= completed_at_ms)),
    CONSTRAINT attempt_terminal_results_logical_workflow_order_shape CHECK (((((logical_workflow_logical_job_id IS NULL) AND (logical_workflow_terminal_ordinal IS NULL)) OR ((logical_workflow_logical_job_id IS NOT NULL) AND (logical_workflow_terminal_ordinal > 0))) IS TRUE))
);

CREATE TABLE automata_cluster_compatibility (
    singleton boolean DEFAULT true NOT NULL,
    minimum_admission_epoch integer NOT NULL,
    job_ir_schema integer NOT NULL,
    runner_requirements_schema integer CONSTRAINT automata_cluster_compatibil_runner_requirements_schema_not_null NOT NULL,
    CONSTRAINT automata_cluster_compatibility_job_ir_current CHECK (((minimum_admission_epoch = 1) AND (job_ir_schema = 1) AND (runner_requirements_schema = 1))),
    CONSTRAINT automata_cluster_compatibility_singleton CHECK (singleton)
);

CREATE TABLE concurrency_group_pending_runs (
