);

ALTER TABLE concurrency_group_pending_runs ALTER COLUMN queue_sequence ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME concurrency_group_pending_runs_queue_sequence_seq
    START WITH 1
