    CONSTRAINT github_team_membership_observations_slug_shape CHECK ((((octet_length(team_slug) >= 1) AND (octet_length(team_slug) <= 255)) AND (team_slug !~ '[[:space:][:cntrl:]]'::text)))
);

CREATE TABLE github_workflow_rerun_subject_evidence (
    operation_id uuid NOT NULL,
    tenant_id text NOT NULL,
    repository_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    run_id uuid NOT NULL,
    source_run_id uuid NOT NULL,
    root_invocation_id uuid CONSTRAINT github_workflow_rerun_subject_evide_root_invocation_id_not_null NOT NULL,
    github_repository_owner_id bigint CONSTRAINT github_workflow_rerun_subje_github_repository_owner_id_not_null NOT NULL,
    github_check_subject_id uuid CONSTRAINT github_workflow_rerun_subject__github_check_subject_id_not_null NOT NULL,
    github_check_head_sha bytea CONSTRAINT github_workflow_rerun_subject_ev_github_check_head_sha_not_null NOT NULL,
    workflow_path text NOT NULL COLLATE pg_catalog."C",
    source_digest bytea NOT NULL,
    event_name text NOT NULL COLLATE pg_catalog."C",
    event_digest bytea NOT NULL,
    git_ref text NOT NULL COLLATE pg_catalog."C",
    workflow_plan_schema smallint CONSTRAINT github_workflow_rerun_subject_evi_workflow_plan_schema_not_null NOT NULL,
    plan_digest bytea NOT NULL,
    logical_admission_digest bytea CONSTRAINT github_workflow_rerun_subject_logical_admission_digest_not_null NOT NULL,
    admitted_at_ms bigint NOT NULL,
    subject_evidence_sha256 bytea GENERATED ALWAYS AS (automata_github_workflow_rerun_subject_evidence_digest(operation_id, tenant_id, repository_id, workflow_id, snapshot_id, run_id, source_run_id, root_invocation_id, github_repository_owner_id, github_check_subject_id, github_check_head_sha, workflow_path, source_digest, event_name, event_digest, git_ref, workflow_plan_schema, plan_digest, logical_admission_digest, admitted_at_ms)) STORED,
    CONSTRAINT github_workflow_rerun_subject_evidence_non_nil CHECK (((operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (repository_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (workflow_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (snapshot_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (root_invocation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (github_check_subject_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT github_workflow_rerun_subject_evidence_shape CHECK (((github_repository_owner_id > 0) AND (octet_length(github_check_head_sha) = 20) AND (github_check_head_sha <> decode(repeat('00'::text, 20), 'hex'::text)) AND (octet_length(source_digest) = 32) AND ((octet_length(event_name) >= 1) AND (octet_length(event_name) <= 1024)) AND (event_name !~ '[[:cntrl:]]'::text) AND (octet_length(event_digest) = 32) AND automata_github_provider_git_ref_canonical(git_ref) AND (workflow_plan_schema = 1) AND (octet_length(plan_digest) = 32) AND (octet_length(logical_admission_digest) = 32) AND (admitted_at_ms >= 0) AND (octet_length(subject_evidence_sha256) = 32) AND (workflow_path ~ '^\.ci/workflows/[^/]+\.ya?ml$'::text) AND (workflow_path !~ '[[:cntrl:]\\]'::text)))
);

CREATE TABLE github_workflow_run_subject_evidence (
    tenant_id text NOT NULL,
    repository_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    run_id uuid NOT NULL,
    root_invocation_id uuid CONSTRAINT github_workflow_run_subject_evidenc_root_invocation_id_not_null NOT NULL,
    provider_delivery_id uuid CONSTRAINT github_workflow_run_subject_evide_provider_delivery_id_not_null NOT NULL,
    provider_delivery_idempotency_key text CONSTRAINT github_workflow_run_subject_provider_delivery_idempote_not_null NOT NULL COLLATE pg_catalog."C",
    admission_claim_owner_id uuid CONSTRAINT github_workflow_run_subject_e_admission_claim_owner_id_not_null NOT NULL,
    admission_claim_attempt smallint CONSTRAINT github_workflow_run_subject_ev_admission_claim_attempt_not_null NOT NULL,
    admission_claim_fence bigint CONSTRAINT github_workflow_run_subject_evid_admission_claim_fence_not_null NOT NULL,
    admission_claimed_at_ms bigint CONSTRAINT github_workflow_run_subject_ev_admission_claimed_at_ms_not_null NOT NULL,
    admission_claim_expires_at_ms bigint CONSTRAINT github_workflow_run_subject_admission_claim_expires_at_not_null NOT NULL,
    github_check_subject_id uuid CONSTRAINT github_workflow_run_subject_ev_github_check_subject_id_not_null NOT NULL,
    github_check_head_sha bytea CONSTRAINT github_workflow_run_subject_evid_github_check_head_sha_not_null NOT NULL,
    workflow_path text NOT NULL COLLATE pg_catalog."C",
    source_digest bytea NOT NULL,
    event_name text NOT NULL COLLATE pg_catalog."C",
    event_digest bytea NOT NULL,
    git_ref text NOT NULL COLLATE pg_catalog."C",
    workflow_plan_schema smallint CONSTRAINT github_workflow_run_subject_evide_workflow_plan_schema_not_null NOT NULL,
    plan_digest bytea NOT NULL,
    logical_admission_digest bytea CONSTRAINT github_workflow_run_subject_e_logical_admission_digest_not_null NOT NULL,
    subject_evidence_sha256 bytea CONSTRAINT github_workflow_run_subject_ev_subject_evidence_sha256_not_null NOT NULL,
    admitted_at_ms bigint NOT NULL,
    CONSTRAINT github_workflow_run_subject_evidence_digest_shape CHECK (((octet_length(github_check_head_sha) = 20) AND (github_check_head_sha <> decode(repeat('00'::text, 20), 'hex'::text)) AND (octet_length(source_digest) = 32) AND (octet_length(event_digest) = 32) AND (octet_length(plan_digest) = 32) AND (octet_length(logical_admission_digest) = 32) AND (octet_length(subject_evidence_sha256) = 32))),
    CONSTRAINT github_workflow_run_subject_evidence_non_nil CHECK (((repository_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (workflow_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (snapshot_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (root_invocation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provider_delivery_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (admission_claim_owner_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (github_check_subject_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT github_workflow_run_subject_evidence_selector_shape CHECK ((((octet_length(provider_delivery_idempotency_key) >= 1) AND (octet_length(provider_delivery_idempotency_key) <= 1024)) AND (provider_delivery_idempotency_key !~ '[[:cntrl:]]'::text) AND ((octet_length(workflow_path) >= 1) AND (octet_length(workflow_path) <= 1024)) AND (btrim(workflow_path) = workflow_path) AND (workflow_path !~ '[[:cntrl:]\\]'::text) AND ("left"(workflow_path, 1) <> '/'::text) AND (workflow_path !~ '(^|/)(\.|\.\.)(/|$)'::text) AND (workflow_path !~ '//'::text) AND ((octet_length(event_name) >= 1) AND (octet_length(event_name) <= 1024)) AND (event_name !~ '[[:cntrl:]]'::text) AND ((octet_length(git_ref) >= 6) AND (octet_length(git_ref) <= 1024)) AND (git_ref ~~ 'refs/%'::text) AND (git_ref !~ '[[:cntrl:]]'::text) AND (workflow_plan_schema = 1))),
    CONSTRAINT github_workflow_run_subject_evidence_time CHECK ((((admission_claim_attempt >= 1) AND (admission_claim_attempt <= 16)) AND (admission_claim_fence > 0) AND (admission_claimed_at_ms >= 0) AND (admission_claim_expires_at_ms > admission_claimed_at_ms) AND ((admission_claim_expires_at_ms - admission_claimed_at_ms) <= 3600000) AND (admitted_at_ms >= admission_claimed_at_ms) AND (admitted_at_ms < admission_claim_expires_at_ms)))
);

CREATE VIEW github_workflow_run_base_manifest_origins AS
 SELECT delivery_run.tenant_id,
    delivery_run.repository_id,
    delivery_run.workflow_id,
    delivery_run.snapshot_id,
    delivery_run.run_id,
    delivery_run.root_invocation_id,
    'provider_delivery'::text AS origin_kind,
    delivery_run.provider_delivery_id AS origin_id,
    'provider_delivery'::text AS admission_idempotency_kind,
    delivery_run.provider_delivery_idempotency_key AS admission_idempotency_key,
    delivery_run.github_check_subject_id,
    delivery_run.github_check_head_sha,
    delivery_run.workflow_path,
    delivery_run.source_digest,
    delivery_run.event_name,
    delivery_run.event_digest,
    delivery_run.git_ref,
    delivery_run.workflow_plan_schema,
    delivery_run.plan_digest,
    delivery_run.logical_admission_digest,
    delivery_run.admitted_at_ms,
    delivery_run.subject_evidence_sha256,
    delivery.provider_connection_id,
    delivery.provider_installation_id,
    delivery.github_repository_id,
    delivery.github_repository_owner_id,
    delivery.github_repository_name,
    delivery.repository_visibility,
    delivery.provider_manifest_revision,
    delivery.provider_manifest_digest,
    delivery.authenticated_webhook_verifier_fingerprint_sha256,
    delivery.authenticated_webhook_verifier_revision,
    delivery.checks_authority_id,
    delivery.checks_authority_identity_digest,
    delivery.checks_authority_app_configuration_revision,
    delivery.checks_authority_policy_revision,
    delivery.private_source_authority_id,
    delivery.private_source_authority_identity_digest,
    delivery.private_source_authority_app_configuration_revision,
    delivery.private_source_authority_policy_revision
   FROM (github_workflow_run_subject_evidence delivery_run
     JOIN github_provider_delivery_evidence delivery ON (((delivery.tenant_id = delivery_run.tenant_id) AND (delivery.repository_id = delivery_run.repository_id) AND (delivery.provider_delivery_id = delivery_run.provider_delivery_id))))
UNION ALL
 SELECT schedule_run.tenant_id,
    schedule_run.repository_id,
    schedule_run.workflow_id,
    schedule_run.snapshot_id,
    schedule_run.run_id,
    schedule_run.root_invocation_id,
    'scheduled_fire'::text AS origin_kind,
    schedule_run.schedule_fire_id AS origin_id,
    'operation'::text AS admission_idempotency_kind,
    (schedule_run.schedule_fire_id)::text AS admission_idempotency_key,
    schedule_run.github_check_subject_id,
    schedule_run.github_check_head_sha,
    schedule_run.workflow_path,
    schedule_run.source_digest,
    schedule_run.event_name,
    schedule_run.event_digest,
    schedule_run.git_ref,
    schedule_run.workflow_plan_schema,
    schedule_run.plan_digest,
    schedule_run.logical_admission_digest,
    schedule_run.admitted_at_ms,
    schedule_run.subject_evidence_sha256,
    schedule_check.provider_connection_id,
    manifest.provider_installation_id,
    manifest.github_repository_id,
    schedule_run.github_repository_owner_id,
    manifest.github_repository_name,
    manifest.repository_visibility,
    schedule_check.provider_manifest_revision,
    schedule_check.provider_manifest_digest,
    manifest.webhook_verifier_fingerprint_sha256 AS authenticated_webhook_verifier_fingerprint_sha256,
    manifest.webhook_verifier_revision AS authenticated_webhook_verifier_revision,
    schedule_check.checks_authority_id,
    schedule_check.checks_authority_identity_digest,
    schedule_check.checks_authority_app_configuration_revision,
    schedule_check.checks_authority_policy_revision,
    registry.private_source_authority_id,
    registry.private_source_authority_identity_digest,
    registry.private_source_authority_app_configuration_revision,
    registry.private_source_authority_policy_revision
   FROM (((github_schedule_workflow_run_subject_evidence schedule_run
     JOIN github_schedule_check_evidence schedule_check ON (((schedule_check.schedule_fire_id = schedule_run.schedule_fire_id) AND (schedule_check.tenant_id = schedule_run.tenant_id) AND (schedule_check.repository_id = schedule_run.repository_id) AND (schedule_check.github_check_subject_id = schedule_run.github_check_subject_id))))
     JOIN github_schedule_registry_revisions registry ON (((registry.tenant_id = schedule_check.tenant_id) AND (registry.repository_id = schedule_check.repository_id) AND (registry.provider_connection_id = schedule_check.provider_connection_id) AND (registry.registry_id = schedule_check.registry_id) AND (registry.manifest_revision = schedule_check.provider_manifest_revision) AND (registry.manifest_digest = schedule_check.provider_manifest_digest) AND (registry.default_branch_ref = schedule_check.default_branch_ref) AND (registry.source_revision = schedule_check.source_revision))))
     JOIN github_provider_manifest_revisions manifest ON (((manifest.tenant_id = schedule_check.tenant_id) AND (manifest.repository_id = schedule_check.repository_id) AND (manifest.provider_connection_id = schedule_check.provider_connection_id) AND (manifest.manifest_revision = schedule_check.provider_manifest_revision) AND (manifest.manifest_digest = schedule_check.provider_manifest_digest))));

CREATE TABLE logical_workflow_runs (
    run_id uuid NOT NULL,
    root_invocation_id uuid NOT NULL,
    orchestration_schema smallint DEFAULT 1 NOT NULL,
    admission_digest bytea NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    admitted_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    admission_graph_sealed_at_ms bigint,
    base_context_digest bytea,
    base_context_object_key text COLLATE pg_catalog."C",
    base_context_size_bytes bigint,
    base_context_media_type text COLLATE pg_catalog."C",
    base_context_schema smallint,
    runner_requirements_schema smallint NOT NULL,
    CONSTRAINT logical_workflow_runs_admission_graph_seal_time CHECK (((admission_graph_sealed_at_ms IS NULL) OR (admission_graph_sealed_at_ms >= admitted_at_ms))),
    CONSTRAINT logical_workflow_runs_base_context CHECK ((((base_context_digest IS NULL) AND (base_context_object_key IS NULL) AND (base_context_size_bytes IS NULL) AND (base_context_media_type IS NULL) AND (base_context_schema IS NULL)) OR ((base_context_digest IS NOT NULL) AND (base_context_object_key IS NOT NULL) AND (base_context_size_bytes IS NOT NULL) AND (base_context_media_type IS NOT NULL) AND (base_context_schema IS NOT NULL) AND (octet_length(base_context_digest) = 32) AND ((octet_length(base_context_object_key) >= 1) AND (octet_length(base_context_object_key) <= 1024)) AND (base_context_object_key !~ '[[:cntrl:]]'::text) AND ("left"(base_context_object_key, 1) <> '/'::text) AND (base_context_object_key !~ '(^|/)\.\.(/|$)'::text) AND ((base_context_size_bytes >= 1) AND (base_context_size_bytes <= 16777216)) AND (base_context_media_type = 'application/vnd.automata.job-runtime-context.protobuf'::text) AND (base_context_schema = 1)))),
    CONSTRAINT logical_workflow_runs_digest_sha256 CHECK ((octet_length(admission_digest) = 32)),
    CONSTRAINT logical_workflow_runs_revision_positive CHECK ((revision > 0)),
    CONSTRAINT logical_workflow_runs_root_non_nil CHECK ((root_invocation_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT logical_workflow_runs_run_non_nil CHECK ((run_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT logical_workflow_runs_runner_requirements_schema CHECK ((runner_requirements_schema = 1)),
    CONSTRAINT logical_workflow_runs_schema_exact CHECK ((orchestration_schema = 1)),
    CONSTRAINT logical_workflow_runs_state CHECK ((state = ANY (ARRAY['pending'::text, 'active'::text, 'completed'::text, 'cancelled'::text, 'failed'::text]))),
    CONSTRAINT logical_workflow_runs_time_monotonic CHECK (((admitted_at_ms >= 0) AND (updated_at_ms >= admitted_at_ms)))
);

COMMENT ON COLUMN logical_workflow_runs.runner_requirements_schema IS 'Immutable runner-requirements schema authenticated by this admitted plan.';

CREATE TABLE workflow_rerun_attempts (
    run_id uuid NOT NULL,
    root_run_id uuid NOT NULL,
    source_run_id uuid,
    attempt integer NOT NULL,
    source_admission_digest bytea NOT NULL,
    source_plan_digest bytea NOT NULL,
    source_event_digest bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT workflow_rerun_attempts_digest_shape CHECK (((octet_length(source_admission_digest) = 32) AND (octet_length(source_plan_digest) = 32) AND (octet_length(source_event_digest) = 32))),
    CONSTRAINT workflow_rerun_attempts_ids_non_nil CHECK (((run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (root_run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((source_run_id IS NULL) OR (source_run_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT workflow_rerun_attempts_root_shape CHECK ((((source_run_id IS NULL) AND (run_id = root_run_id) AND (attempt = 1)) OR ((source_run_id IS NOT NULL) AND (run_id <> root_run_id) AND ((attempt >= 2) AND (attempt <= 51))))),
    CONSTRAINT workflow_rerun_attempts_time CHECK ((created_at_ms >= 0))
);

CREATE TABLE workflow_rerun_check_evidence (
    run_id uuid NOT NULL,
    source_run_id uuid NOT NULL,
    tenant_id text NOT NULL,
    operation_id uuid NOT NULL,
    repository_id uuid NOT NULL,
    provider_connection_id uuid NOT NULL,
    provider_manifest_revision bigint CONSTRAINT workflow_rerun_check_eviden_provider_manifest_revision_not_null NOT NULL,
    provider_manifest_digest bytea NOT NULL,
    source_github_check_subject_id uuid CONSTRAINT workflow_rerun_check_eviden_source_github_check_subjec_not_null NOT NULL,
    github_check_subject_id uuid NOT NULL,
    github_check_head_sha bytea NOT NULL,
    checks_authority_id uuid NOT NULL,
    checks_authority_identity_digest bytea CONSTRAINT workflow_rerun_check_eviden_checks_authority_identity__not_null NOT NULL,
    checks_authority_app_configuration_revision bigint CONSTRAINT workflow_rerun_check_eviden_checks_authority_app_confi_not_null NOT NULL,
    checks_authority_policy_revision bigint CONSTRAINT workflow_rerun_check_eviden_checks_authority_policy_re_not_null NOT NULL,
    private_source_authority_id uuid,
    private_source_authority_identity_digest bytea,
    private_source_authority_app_configuration_revision bigint,
    private_source_authority_policy_revision bigint,
    recorded_at_ms bigint NOT NULL,
    CONSTRAINT workflow_rerun_check_evidence_ids_non_nil CHECK (((run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (repository_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (provider_connection_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_github_check_subject_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (github_check_subject_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (checks_authority_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((private_source_authority_id IS NULL) OR (private_source_authority_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT workflow_rerun_check_evidence_shape CHECK (((provider_manifest_revision > 0) AND (octet_length(provider_manifest_digest) = 32) AND (octet_length(github_check_head_sha) = 20) AND (github_check_head_sha <> decode(repeat('00'::text, 20), 'hex'::text)) AND (octet_length(checks_authority_identity_digest) = 32) AND (checks_authority_app_configuration_revision > 0) AND (checks_authority_policy_revision > 0) AND (num_nonnulls(private_source_authority_id, private_source_authority_identity_digest, private_source_authority_app_configuration_revision, private_source_authority_policy_revision) = ANY (ARRAY[0, 4])) AND ((private_source_authority_identity_digest IS NULL) OR ((octet_length(private_source_authority_identity_digest) = 32) AND (private_source_authority_app_configuration_revision > 0) AND (private_source_authority_policy_revision > 0))) AND (recorded_at_ms >= 0)))
);

CREATE TABLE workflow_rerun_requests (
    tenant_id text NOT NULL,
    operation_id uuid NOT NULL,
    request_digest bytea NOT NULL,
    repository_id uuid NOT NULL,
    source_run_id uuid NOT NULL,
    selection_kind text NOT NULL,
    selected_source_job_id uuid,
    actor_principal_id uuid NOT NULL,
    actor_session_id uuid NOT NULL,
    authorization_revision bigint NOT NULL,
    rerun_run_id uuid,
    committed_at_ms bigint,
    CONSTRAINT workflow_rerun_requests_completion_shape CHECK ((((rerun_run_id IS NULL) AND (committed_at_ms IS NULL)) OR ((rerun_run_id IS NOT NULL) AND (committed_at_ms IS NOT NULL) AND (committed_at_ms >= 0)))),
    CONSTRAINT workflow_rerun_requests_digest_shape CHECK ((octet_length(request_digest) = 32)),
    CONSTRAINT workflow_rerun_requests_ids_non_nil CHECK (((operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (repository_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (source_run_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (actor_principal_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (actor_session_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((rerun_run_id IS NULL) OR (rerun_run_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT workflow_rerun_requests_revision_positive CHECK ((authorization_revision > 0)),
    CONSTRAINT workflow_rerun_requests_selection_shape CHECK ((((selection_kind = ANY (ARRAY['entire_workflow'::text, 'failed_jobs_and_dependents'::text])) AND (selected_source_job_id IS NULL)) OR ((selection_kind = 'job_and_dependents'::text) AND (selected_source_job_id IS NOT NULL))))
);

CREATE TABLE workflow_runs (
    id uuid NOT NULL,
    repository_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    run_number bigint NOT NULL,
    run_attempt integer DEFAULT 1 NOT NULL,
    event_name text NOT NULL,
    event_object_key text NOT NULL,
    head_sha bytea NOT NULL,
    status text NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    concurrency_group_key text,
    admission_epoch integer DEFAULT 1 NOT NULL,
    event_digest bytea NOT NULL,
    event_size_bytes bigint NOT NULL,
    event_media_type text NOT NULL,
    plan_digest bytea NOT NULL,
    plan_object_key text NOT NULL,
    plan_size_bytes bigint NOT NULL,
    plan_media_type text NOT NULL,
    plan_schema integer NOT NULL,
    workflow_name text NOT NULL,
    git_ref text,
    actor text,
    display_title text,
    commit_subject text,
    publication_policy_revision bigint DEFAULT 1 NOT NULL,
    requested_dashboard_visibility text DEFAULT 'private'::text NOT NULL,
    effective_dashboard_visibility text DEFAULT 'private'::text NOT NULL,
    requested_log_visibility text DEFAULT 'private'::text NOT NULL,
    requested_artifact_visibility text DEFAULT 'private'::text NOT NULL,
    publication_safety_reason text DEFAULT 'repository_policy'::text NOT NULL,
    publication_safety_schema integer DEFAULT 1 NOT NULL,
    run_id_alias bigint NOT NULL,
    concurrency_queue_policy text,
    runner_requirements_schema smallint NOT NULL,
    public_run_id_alias bigint NOT NULL,
    triggering_actor text,
    concurrency_cancel_in_progress boolean,
    CONSTRAINT workflow_runs_actor_shape CHECK (((actor IS NULL) OR (((octet_length(actor) >= 1) AND (octet_length(actor) <= 1024)) AND (actor !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT workflow_runs_admission_epoch CHECK ((admission_epoch = 1)),
    CONSTRAINT workflow_runs_attempt_positive CHECK ((run_attempt > 0)),
    CONSTRAINT workflow_runs_commit_subject_shape CHECK (((commit_subject IS NULL) OR (((octet_length(commit_subject) >= 1) AND (octet_length(commit_subject) <= 1024)) AND (commit_subject !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT workflow_runs_concurrency_cancel_shape CHECK (((concurrency_group_key IS NOT NULL) OR (concurrency_cancel_in_progress IS NULL))),
    CONSTRAINT workflow_runs_concurrency_key_shape CHECK (((concurrency_group_key IS NULL) OR (((octet_length(concurrency_group_key) >= 1) AND (octet_length(concurrency_group_key) <= 255)) AND (concurrency_group_key !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT workflow_runs_concurrency_queue_policy_shape CHECK ((((concurrency_group_key IS NULL) AND (concurrency_queue_policy IS NULL)) OR ((concurrency_group_key IS NOT NULL) AND (concurrency_queue_policy = ANY (ARRAY['single'::text, 'max'::text]))))),
    CONSTRAINT workflow_runs_current_event_metadata CHECK (((admission_epoch = 1) AND (octet_length(event_digest) = 32) AND ((event_size_bytes >= 1) AND (event_size_bytes <= 26214400)) AND ((octet_length(event_media_type) >= 3) AND (octet_length(event_media_type) <= 128)) AND (event_media_type ~~ '%/%'::text) AND (event_media_type !~ '[[:space:][:cntrl:];]'::text) AND (octet_length(plan_digest) = 32) AND ((octet_length(plan_object_key) >= 1) AND (octet_length(plan_object_key) <= 1024)) AND (plan_object_key !~ '[[:cntrl:]]'::text) AND ((plan_size_bytes >= 1) AND (plan_size_bytes <= 16777216)) AND ((octet_length(plan_media_type) >= 3) AND (octet_length(plan_media_type) <= 128)) AND (plan_media_type ~~ '%/%'::text) AND (plan_media_type !~ '[[:space:][:cntrl:];]'::text) AND (plan_schema = 1))),
    CONSTRAINT workflow_runs_dashboard_visibility_cap CHECK (((effective_dashboard_visibility = 'private'::text) OR ((effective_dashboard_visibility = 'authenticated'::text) AND (requested_dashboard_visibility = ANY (ARRAY['authenticated'::text, 'public'::text]))) OR ((effective_dashboard_visibility = 'public'::text) AND (requested_dashboard_visibility = 'public'::text)))),
    CONSTRAINT workflow_runs_display_title_shape CHECK (((display_title IS NULL) OR (((octet_length(display_title) >= 1) AND (octet_length(display_title) <= 1024)) AND (display_title !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT workflow_runs_effective_dashboard_visibility CHECK ((effective_dashboard_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text]))),
    CONSTRAINT workflow_runs_git_ref_shape CHECK (((git_ref IS NULL) OR (((octet_length(git_ref) >= 6) AND (octet_length(git_ref) <= 1024)) AND (git_ref ~~ 'refs/%'::text) AND (git_ref !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT workflow_runs_id_alias_exact_positive CHECK (((run_id_alias >= 1) AND (run_id_alias <= '9007199254740991'::bigint))),
    CONSTRAINT workflow_runs_number_positive CHECK ((run_number > 0)),
    CONSTRAINT workflow_runs_public_id_alias_positive CHECK (((public_run_id_alias IS NULL) OR ((public_run_id_alias >= 1) AND (public_run_id_alias <= '9007199254740991'::bigint)))),
    CONSTRAINT workflow_runs_publication_policy_revision_positive CHECK ((publication_policy_revision > 0)),
    CONSTRAINT workflow_runs_publication_safety_reason_code CHECK ((publication_safety_reason = ANY (ARRAY['repository_policy'::text, 'secret_exposure'::text]))),
    CONSTRAINT workflow_runs_publication_safety_schema CHECK ((publication_safety_schema = 1)),
    CONSTRAINT workflow_runs_requested_visibility CHECK (((requested_dashboard_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])) AND (requested_log_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])) AND (requested_artifact_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])))),
    CONSTRAINT workflow_runs_runner_requirements_schema CHECK ((runner_requirements_schema = 1)),
    CONSTRAINT workflow_runs_sha CHECK ((octet_length(head_sha) = ANY (ARRAY[20, 32]))),
    CONSTRAINT workflow_runs_status CHECK ((status = ANY (ARRAY['queued'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text]))),
    CONSTRAINT workflow_runs_triggering_actor_shape CHECK (((triggering_actor IS NULL) OR (((octet_length(triggering_actor) >= 1) AND (octet_length(triggering_actor) <= 1024)) AND (triggering_actor !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT workflow_runs_workflow_name_shape CHECK ((((octet_length(workflow_name) >= 1) AND (octet_length(workflow_name) <= 1024)) AND (workflow_name !~ '[[:cntrl:]]'::text)))
);

CREATE VIEW github_workflow_run_manifest_origins AS
 SELECT github_workflow_run_base_manifest_origins.tenant_id,
    github_workflow_run_base_manifest_origins.repository_id,
    github_workflow_run_base_manifest_origins.workflow_id,
    github_workflow_run_base_manifest_origins.snapshot_id,
    github_workflow_run_base_manifest_origins.run_id,
    github_workflow_run_base_manifest_origins.root_invocation_id,
    github_workflow_run_base_manifest_origins.origin_kind,
    github_workflow_run_base_manifest_origins.origin_id,
    github_workflow_run_base_manifest_origins.admission_idempotency_kind,
    github_workflow_run_base_manifest_origins.admission_idempotency_key,
    github_workflow_run_base_manifest_origins.github_check_subject_id,
    github_workflow_run_base_manifest_origins.github_check_head_sha,
    github_workflow_run_base_manifest_origins.workflow_path,
    github_workflow_run_base_manifest_origins.source_digest,
    github_workflow_run_base_manifest_origins.event_name,
    github_workflow_run_base_manifest_origins.event_digest,
    github_workflow_run_base_manifest_origins.git_ref,
    github_workflow_run_base_manifest_origins.workflow_plan_schema,
    github_workflow_run_base_manifest_origins.plan_digest,
    github_workflow_run_base_manifest_origins.logical_admission_digest,
    github_workflow_run_base_manifest_origins.admitted_at_ms,
    github_workflow_run_base_manifest_origins.subject_evidence_sha256,
    github_workflow_run_base_manifest_origins.provider_connection_id,
    github_workflow_run_base_manifest_origins.provider_installation_id,
    github_workflow_run_base_manifest_origins.github_repository_id,
    github_workflow_run_base_manifest_origins.github_repository_owner_id,
    github_workflow_run_base_manifest_origins.github_repository_name,
    github_workflow_run_base_manifest_origins.repository_visibility,
    github_workflow_run_base_manifest_origins.provider_manifest_revision,
    github_workflow_run_base_manifest_origins.provider_manifest_digest,
    github_workflow_run_base_manifest_origins.authenticated_webhook_verifier_fingerprint_sha256,
    github_workflow_run_base_manifest_origins.authenticated_webhook_verifier_revision,
    github_workflow_run_base_manifest_origins.checks_authority_id,
    github_workflow_run_base_manifest_origins.checks_authority_identity_digest,
    github_workflow_run_base_manifest_origins.checks_authority_app_configuration_revision,
    github_workflow_run_base_manifest_origins.checks_authority_policy_revision,
    github_workflow_run_base_manifest_origins.private_source_authority_id,
    github_workflow_run_base_manifest_origins.private_source_authority_identity_digest,
    github_workflow_run_base_manifest_origins.private_source_authority_app_configuration_revision,
    github_workflow_run_base_manifest_origins.private_source_authority_policy_revision
   FROM github_workflow_run_base_manifest_origins
UNION ALL
 SELECT origin.tenant_id,
    origin.repository_id,
    rerun.workflow_id,
    rerun.snapshot_id,
    attempt.run_id,
    marker.root_invocation_id,
    'workflow_rerun'::text AS origin_kind,
    request.operation_id AS origin_id,
    'operation'::text AS admission_idempotency_kind,
    ('workflow-rerun:'::text || (request.operation_id)::text) AS admission_idempotency_key,
    run_evidence.github_check_subject_id,
    run_evidence.github_check_head_sha,
    run_evidence.workflow_path,
    run_evidence.source_digest,
    run_evidence.event_name,
    run_evidence.event_digest,
    run_evidence.git_ref,
    run_evidence.workflow_plan_schema,
    run_evidence.plan_digest,
    run_evidence.logical_admission_digest,
    run_evidence.admitted_at_ms,
    run_evidence.subject_evidence_sha256,
    check_evidence.provider_connection_id,
    origin.provider_installation_id,
    origin.github_repository_id,
    origin.github_repository_owner_id,
    origin.github_repository_name,
    origin.repository_visibility,
    check_evidence.provider_manifest_revision,
    check_evidence.provider_manifest_digest,
    origin.authenticated_webhook_verifier_fingerprint_sha256,
    origin.authenticated_webhook_verifier_revision,
    check_evidence.checks_authority_id,
    check_evidence.checks_authority_identity_digest,
    check_evidence.checks_authority_app_configuration_revision,
    check_evidence.checks_authority_policy_revision,
    check_evidence.private_source_authority_id,
    check_evidence.private_source_authority_identity_digest,
    check_evidence.private_source_authority_app_configuration_revision,
    check_evidence.private_source_authority_policy_revision
   FROM ((((((workflow_rerun_attempts attempt
     JOIN workflow_rerun_check_evidence check_evidence ON (((check_evidence.run_id = attempt.run_id) AND (check_evidence.source_run_id = attempt.source_run_id))))
     JOIN workflow_rerun_requests request ON (((request.tenant_id = check_evidence.tenant_id) AND (request.operation_id = check_evidence.operation_id) AND (request.rerun_run_id = attempt.run_id) AND (request.committed_at_ms = attempt.created_at_ms))))
     JOIN workflow_runs rerun ON ((rerun.id = attempt.run_id)))
     JOIN logical_workflow_runs marker ON ((marker.run_id = attempt.run_id)))
     JOIN github_workflow_rerun_subject_evidence run_evidence ON (((run_evidence.tenant_id = check_evidence.tenant_id) AND (run_evidence.operation_id = check_evidence.operation_id) AND (run_evidence.run_id = check_evidence.run_id) AND (run_evidence.source_run_id = check_evidence.source_run_id) AND (run_evidence.github_check_subject_id = check_evidence.github_check_subject_id) AND (run_evidence.github_check_head_sha = check_evidence.github_check_head_sha) AND (run_evidence.admitted_at_ms = check_evidence.recorded_at_ms))))
     JOIN github_workflow_run_base_manifest_origins origin ON (((origin.run_id = attempt.root_run_id) AND (origin.tenant_id = check_evidence.tenant_id) AND (origin.repository_id = check_evidence.repository_id) AND (origin.provider_connection_id = check_evidence.provider_connection_id) AND (origin.provider_manifest_revision = check_evidence.provider_manifest_revision) AND (origin.provider_manifest_digest = check_evidence.provider_manifest_digest))))
  WHERE (attempt.source_run_id IS NOT NULL);

CREATE TABLE human_auth_installation_state (
    singleton boolean DEFAULT true NOT NULL,
    state text NOT NULL,
    bootstrap_token_hash bytea,
    bootstrap_hash_key_id text,
    expected_provider_id text,
    expected_provider_subject text,
    challenge_expires_at_ms bigint,
    configured_tenant_id text,
    configured_principal_id uuid,
    configured_at_ms bigint,
    revision bigint DEFAULT 1 NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    target_tenant_id text,
    target_tenant_display_name text,
    setup_transaction_id uuid,
    CONSTRAINT human_auth_installation_state_revision_positive CHECK ((revision > 0)),
    CONSTRAINT human_auth_installation_state_shape CHECK (((((state = 'unconfigured'::text) AND (bootstrap_token_hash IS NULL) AND (bootstrap_hash_key_id IS NULL) AND (expected_provider_id IS NULL) AND (expected_provider_subject IS NULL) AND (challenge_expires_at_ms IS NULL) AND (target_tenant_id IS NULL) AND (target_tenant_display_name IS NULL) AND (setup_transaction_id IS NULL) AND (configured_tenant_id IS NULL) AND (configured_principal_id IS NULL) AND (configured_at_ms IS NULL)) OR ((state = 'pending'::text) AND (octet_length(bootstrap_token_hash) = 32) AND ((octet_length(bootstrap_hash_key_id) >= 1) AND (octet_length(bootstrap_hash_key_id) <= 128)) AND (bootstrap_hash_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text) AND ((octet_length(expected_provider_id) >= 1) AND (octet_length(expected_provider_id) <= 128)) AND (expected_provider_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text) AND ((octet_length(expected_provider_subject) >= 1) AND (octet_length(expected_provider_subject) <= 255)) AND (expected_provider_subject !~ '[[:cntrl:]]'::text) AND (target_tenant_id IS NOT NULL) AND (target_tenant_display_name IS NOT NULL) AND (challenge_expires_at_ms > updated_at_ms) AND (configured_tenant_id IS NULL) AND (configured_principal_id IS NULL) AND (configured_at_ms IS NULL)) OR ((state = 'configured'::text) AND (bootstrap_token_hash IS NULL) AND (bootstrap_hash_key_id IS NULL) AND ((octet_length(expected_provider_id) >= 1) AND (octet_length(expected_provider_id) <= 128)) AND ((octet_length(expected_provider_subject) >= 1) AND (octet_length(expected_provider_subject) <= 255)) AND (challenge_expires_at_ms IS NULL) AND (target_tenant_id = configured_tenant_id) AND (target_tenant_display_name IS NOT NULL) AND (setup_transaction_id IS NOT NULL) AND (configured_tenant_id IS NOT NULL) AND (configured_principal_id IS NOT NULL) AND (configured_at_ms >= created_at_ms))) IS TRUE)),
    CONSTRAINT human_auth_installation_state_singleton CHECK (singleton),
    CONSTRAINT human_auth_installation_state_state CHECK ((state = ANY (ARRAY['unconfigured'::text, 'pending'::text, 'configured'::text]))),
    CONSTRAINT human_auth_installation_state_target_display_name_shape CHECK (((target_tenant_display_name IS NULL) OR (((octet_length(target_tenant_display_name) >= 1) AND (octet_length(target_tenant_display_name) <= 255)) AND (target_tenant_display_name !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT human_auth_installation_state_target_tenant_shape CHECK (((target_tenant_id IS NULL) OR (((octet_length(target_tenant_id) >= 1) AND (octet_length(target_tenant_id) <= 255)) AND (target_tenant_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT human_auth_installation_state_time_monotonic CHECK ((updated_at_ms >= created_at_ms))
);

CREATE TABLE human_login_transactions (
    id uuid NOT NULL,
    tenant_id text,
    purpose text NOT NULL,
    flow_kind text NOT NULL,
    provider_id text NOT NULL,
    return_path text,
    state_hash bytea,
    state_hash_key_id text,
    browser_binding_hash bytea,
    browser_binding_hash_key_id text,
    poll_proof_hash bytea,
    poll_proof_hash_key_id text,
    encrypted_payload bytea NOT NULL,
    payload_nonce bytea NOT NULL,
    wrapped_data_key bytea NOT NULL,
    encryption_key_id text NOT NULL,
    encryption_schema integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    completed_principal_id uuid,
    poll_interval_ms bigint,
    next_poll_at_ms bigint,
    poll_attempts integer DEFAULT 0 NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    expires_at_ms bigint NOT NULL,
    consumed_at_ms bigint,
    revision bigint DEFAULT 1 NOT NULL,
    CONSTRAINT human_login_transactions_envelope_shape CHECK ((((octet_length(encrypted_payload) >= 17) AND (octet_length(encrypted_payload) <= 67681)) AND (octet_length(payload_nonce) = 12) AND ((octet_length(wrapped_data_key) >= 1) AND (octet_length(wrapped_data_key) <= 65536)) AND ((octet_length(encryption_key_id) >= 1) AND (octet_length(encryption_key_id) <= 128)) AND (encryption_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]*$'::text) AND (encryption_schema = 1))),
    CONSTRAINT human_login_transactions_flow_kind CHECK ((flow_kind = ANY (ARRAY['browser'::text, 'device'::text]))),
    CONSTRAINT human_login_transactions_flow_shape CHECK (((((flow_kind = 'browser'::text) AND (octet_length(state_hash) = 32) AND (state_hash_key_id IS NOT NULL) AND (octet_length(browser_binding_hash) = 32) AND (browser_binding_hash_key_id IS NOT NULL) AND (poll_proof_hash IS NULL) AND (poll_proof_hash_key_id IS NULL) AND (poll_interval_ms IS NULL) AND (next_poll_at_ms IS NULL)) OR ((flow_kind = 'device'::text) AND (state_hash IS NULL) AND (state_hash_key_id IS NULL) AND (browser_binding_hash IS NULL) AND (browser_binding_hash_key_id IS NULL) AND (octet_length(poll_proof_hash) = 32) AND (poll_proof_hash_key_id IS NOT NULL) AND ((poll_interval_ms >= 1000) AND (poll_interval_ms <= 300000)) AND (next_poll_at_ms > created_at_ms))) IS TRUE)),
    CONSTRAINT human_login_transactions_hash_key_shape CHECK ((((state_hash_key_id IS NULL) OR (((octet_length(state_hash_key_id) >= 1) AND (octet_length(state_hash_key_id) <= 128)) AND (state_hash_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text))) AND ((browser_binding_hash_key_id IS NULL) OR (((octet_length(browser_binding_hash_key_id) >= 1) AND (octet_length(browser_binding_hash_key_id) <= 128)) AND (browser_binding_hash_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text))) AND ((poll_proof_hash_key_id IS NULL) OR (((octet_length(poll_proof_hash_key_id) >= 1) AND (octet_length(poll_proof_hash_key_id) <= 128)) AND (poll_proof_hash_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text))))),
    CONSTRAINT human_login_transactions_lifetime CHECK (((updated_at_ms >= created_at_ms) AND (expires_at_ms > created_at_ms) AND ((consumed_at_ms IS NULL) OR (consumed_at_ms <= updated_at_ms)))),
    CONSTRAINT human_login_transactions_poll_attempts_nonnegative CHECK ((poll_attempts >= 0)),
    CONSTRAINT human_login_transactions_provider_shape CHECK ((((octet_length(provider_id) >= 1) AND (octet_length(provider_id) <= 128)) AND (provider_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text))),
    CONSTRAINT human_login_transactions_purpose CHECK ((purpose = ANY (ARRAY['sign_in'::text, 'installation_setup'::text]))),
    CONSTRAINT human_login_transactions_purpose_tenant CHECK (((((purpose = 'sign_in'::text) AND (tenant_id IS NOT NULL)) OR ((purpose = 'installation_setup'::text) AND (tenant_id IS NULL))) IS TRUE)),
    CONSTRAINT human_login_transactions_return_path_shape CHECK (((return_path IS NULL) OR (((octet_length(return_path) >= 1) AND (octet_length(return_path) <= 2048)) AND ("left"(return_path, 1) = '/'::text) AND ("left"(return_path, 2) <> '//'::text) AND (return_path !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT human_login_transactions_revision_positive CHECK ((revision > 0)),
    CONSTRAINT human_login_transactions_status CHECK ((status = ANY (ARRAY['pending'::text, 'consumed'::text, 'succeeded'::text, 'denied'::text, 'expired'::text]))),
    CONSTRAINT human_login_transactions_status_shape CHECK (((((status = 'pending'::text) AND (completed_principal_id IS NULL) AND (consumed_at_ms IS NULL)) OR ((status = 'succeeded'::text) AND (completed_principal_id IS NOT NULL) AND (consumed_at_ms >= created_at_ms)) OR ((status = ANY (ARRAY['consumed'::text, 'denied'::text, 'expired'::text])) AND (completed_principal_id IS NULL) AND (consumed_at_ms >= created_at_ms))) IS TRUE))
);

CREATE TABLE human_principals (
    id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    display_name text,
    revision bigint DEFAULT 1 NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    disabled_at_ms bigint,
    disabled_reason text,
    CONSTRAINT human_principals_disabled_shape CHECK (((((status = 'active'::text) AND (disabled_at_ms IS NULL) AND (disabled_reason IS NULL)) OR ((status = 'disabled'::text) AND (disabled_at_ms >= created_at_ms) AND ((octet_length(disabled_reason) >= 1) AND (octet_length(disabled_reason) <= 1024)) AND (disabled_reason !~ '[[:cntrl:]]'::text))) IS TRUE)),
    CONSTRAINT human_principals_display_name_shape CHECK (((display_name IS NULL) OR ((octet_length(display_name) <= 1024) AND (display_name !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT human_principals_revision_positive CHECK ((revision > 0)),
    CONSTRAINT human_principals_status CHECK ((status = ANY (ARRAY['active'::text, 'disabled'::text]))),
    CONSTRAINT human_principals_time_monotonic CHECK ((updated_at_ms >= created_at_ms))
);

CREATE TABLE human_provider_identities (
    principal_id uuid NOT NULL,
    provider_id text NOT NULL,
    provider_subject text NOT NULL,
    provider_login text NOT NULL,
    normalized_login text NOT NULL,
    display_name text,
    first_authenticated_at_ms bigint NOT NULL,
    last_authenticated_at_ms bigint NOT NULL,
    last_observed_at_ms bigint NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    CONSTRAINT human_provider_identities_display_name_shape CHECK (((display_name IS NULL) OR ((octet_length(display_name) <= 1024) AND (display_name !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT human_provider_identities_login_shape CHECK ((((octet_length(provider_login) >= 1) AND (octet_length(provider_login) <= 255)) AND (provider_login !~ '[[:cntrl:]]'::text) AND ((octet_length(normalized_login) >= 1) AND (octet_length(normalized_login) <= 255)) AND (normalized_login !~ '[[:cntrl:]]'::text))),
    CONSTRAINT human_provider_identities_provider_shape CHECK ((((octet_length(provider_id) >= 1) AND (octet_length(provider_id) <= 128)) AND (provider_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text))),
    CONSTRAINT human_provider_identities_revision_positive CHECK ((revision > 0)),
    CONSTRAINT human_provider_identities_subject_shape CHECK ((((octet_length(provider_subject) >= 1) AND (octet_length(provider_subject) <= 255)) AND (provider_subject !~ '[[:cntrl:]]'::text))),
    CONSTRAINT human_provider_identities_time_monotonic CHECK (((updated_at_ms >= created_at_ms) AND (last_authenticated_at_ms >= first_authenticated_at_ms) AND (last_observed_at_ms >= first_authenticated_at_ms)))
);

CREATE TABLE human_provider_tokens (
    tenant_id text NOT NULL,
    principal_id uuid NOT NULL,
    provider_id text NOT NULL,
    provider_subject text NOT NULL,
    version bigint NOT NULL,
    grant_kind text NOT NULL,
    scopes text[] DEFAULT '{}'::text[] NOT NULL,
    encrypted_payload bytea,
    payload_nonce bytea,
    wrapped_data_key bytea,
    encryption_key_id text,
    encryption_schema integer,
    issued_at_ms bigint NOT NULL,
    access_expires_at_ms bigint,
    refresh_expires_at_ms bigint,
    created_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    revoked_at_ms bigint,
    revocation_reason text,
    envelope_record_id uuid NOT NULL,
    token_type text NOT NULL,
    CONSTRAINT human_provider_tokens_envelope_shape CHECK (((((revoked_at_ms IS NULL) AND (revocation_reason IS NULL) AND ((octet_length(encrypted_payload) >= 17) AND (octet_length(encrypted_payload) <= 1048592)) AND (octet_length(payload_nonce) = 12) AND ((octet_length(wrapped_data_key) >= 1) AND (octet_length(wrapped_data_key) <= 65536)) AND ((octet_length(encryption_key_id) >= 1) AND (octet_length(encryption_key_id) <= 64)) AND (encryption_key_id ~ '^[a-z0-9][a-z0-9._-]*$'::text) AND ("right"(encryption_key_id, 1) ~ '^[a-z0-9]$'::text) AND (encryption_schema = 1)) OR ((revoked_at_ms >= issued_at_ms) AND (revocation_reason = ANY (ARRAY['explicit'::text, 'provider_authorization_revoked'::text, 'refresh_rejected'::text, 'principal_disabled'::text, 'provider_identity_unlinked'::text])) AND (encrypted_payload IS NULL) AND (payload_nonce IS NULL) AND (wrapped_data_key IS NULL) AND (encryption_key_id IS NULL) AND (encryption_schema IS NULL))) IS TRUE)),
    CONSTRAINT human_provider_tokens_grant_kind CHECK ((grant_kind = ANY (ARRAY['browser_authorization_code'::text, 'device_authorization'::text]))),
    CONSTRAINT human_provider_tokens_lifetime CHECK (((issued_at_ms >= 0) AND ((access_expires_at_ms IS NULL) OR (access_expires_at_ms > issued_at_ms)) AND ((refresh_expires_at_ms IS NULL) OR (refresh_expires_at_ms > issued_at_ms)) AND (created_at_ms >= 0) AND (updated_at_ms >= created_at_ms))),
    CONSTRAINT human_provider_tokens_scopes_canonical CHECK (automata_provider_token_scopes_are_canonical(scopes)),
    CONSTRAINT human_provider_tokens_token_type_shape CHECK ((((octet_length(token_type) >= 1) AND (octet_length(token_type) <= 255)) AND (token_type ~ '^[!-~]+$'::text))),
    CONSTRAINT human_provider_tokens_version_positive CHECK ((version > 0))
);

CREATE TABLE human_sessions (
    id uuid NOT NULL,
    tenant_id text NOT NULL,
    principal_id uuid NOT NULL,
    provider_id text NOT NULL,
    provider_subject text NOT NULL,
    session_kind text NOT NULL,
    audience text NOT NULL,
    token_hash bytea NOT NULL,
    token_hash_key_id text NOT NULL,
    authorization_revision bigint NOT NULL,
    predecessor_session_id uuid,
    issued_at_ms bigint NOT NULL,
    last_seen_at_ms bigint NOT NULL,
    idle_expires_at_ms bigint NOT NULL,
    expires_at_ms bigint NOT NULL,
    revoked_at_ms bigint,
    revocation_reason text,
    revision bigint DEFAULT 1 NOT NULL,
    lifecycle_status text DEFAULT 'active'::text NOT NULL,
    activation_deadline_ms bigint,
    activated_at_ms bigint,
    CONSTRAINT human_sessions_activation_shape CHECK (((((session_kind = 'browser'::text) AND (audience = 'automata.web'::text) AND (lifecycle_status = 'active'::text) AND (activation_deadline_ms IS NULL) AND (activated_at_ms IS NULL)) OR ((session_kind = 'cli'::text) AND (audience = 'automata.cli'::text) AND (lifecycle_status = 'pending_activation'::text) AND (issued_at_ms >= 0) AND (activation_deadline_ms > issued_at_ms) AND (activation_deadline_ms <= expires_at_ms) AND (((activation_deadline_ms - issued_at_ms) >= 1) AND ((activation_deadline_ms - issued_at_ms) <= 300000)) AND (activated_at_ms IS NULL)) OR ((session_kind = 'cli'::text) AND (audience = 'automata.cli'::text) AND (lifecycle_status = 'active'::text) AND (issued_at_ms >= 0) AND (activation_deadline_ms > issued_at_ms) AND (activation_deadline_ms <= expires_at_ms) AND (((activation_deadline_ms - issued_at_ms) >= 1) AND ((activation_deadline_ms - issued_at_ms) <= 300000)) AND (activated_at_ms >= issued_at_ms) AND (activated_at_ms < activation_deadline_ms))) IS TRUE)),
    CONSTRAINT human_sessions_authorization_revision_positive CHECK ((authorization_revision > 0)),
    CONSTRAINT human_sessions_kind_audience CHECK ((((session_kind = 'browser'::text) AND (audience = 'automata.web'::text)) OR ((session_kind = 'cli'::text) AND (audience = 'automata.cli'::text)))),
    CONSTRAINT human_sessions_lifetime CHECK (((last_seen_at_ms >= issued_at_ms) AND (idle_expires_at_ms > last_seen_at_ms) AND (idle_expires_at_ms <= expires_at_ms) AND (expires_at_ms > issued_at_ms))),
    CONSTRAINT human_sessions_revision_positive CHECK ((revision > 0)),
    CONSTRAINT human_sessions_revocation_shape CHECK (((((revoked_at_ms IS NULL) AND (revocation_reason IS NULL)) OR ((revoked_at_ms >= issued_at_ms) AND ((octet_length(revocation_reason) >= 1) AND (octet_length(revocation_reason) <= 1024)) AND (revocation_reason !~ '[[:cntrl:]]'::text))) IS TRUE)),
    CONSTRAINT human_sessions_token_hash CHECK ((octet_length(token_hash) = 32)),
    CONSTRAINT human_sessions_token_hash_key_shape CHECK ((((octet_length(token_hash_key_id) >= 1) AND (octet_length(token_hash_key_id) <= 128)) AND (token_hash_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text)))
);

CREATE TABLE job_attempts (
    id uuid NOT NULL,
    job_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    lifecycle text NOT NULL,
    fencing_token bigint DEFAULT 0 NOT NULL,
    lease_id uuid,
    runner_id uuid,
    lease_issued_at_ms bigint,
    lease_expires_at_ms bigint,
    lease_failures integer DEFAULT 0 NOT NULL,
    queued_at_ms bigint NOT NULL,
    changed_at_ms bigint NOT NULL,
    runner_session_id uuid,
    runner_session_epoch bigint,
    runner_generation bigint,
    runner_slot integer,
    secret_exposure_class text DEFAULT 'readable_secret'::text NOT NULL,
    raw_log_disposition text DEFAULT 'persist'::text NOT NULL,
    requested_log_visibility text DEFAULT 'private'::text NOT NULL,
    effective_log_visibility text DEFAULT 'private'::text NOT NULL,
    output_safety_reason text DEFAULT 'repository_policy'::text NOT NULL,
    output_safety_schema integer DEFAULT 1 NOT NULL,
    classified_at_ms bigint DEFAULT 0 NOT NULL,
    started_at_ms bigint,
    CONSTRAINT job_attempts_active_lease_consistent CHECK (((lifecycle = ANY (ARRAY['leased'::text, 'preparing'::text, 'running'::text, 'cancelling'::text, 'finalizing'::text])) = (lease_id IS NOT NULL))),
    CONSTRAINT job_attempts_active_lease_fenced CHECK (((lease_id IS NULL) OR (fencing_token > 0))),
    CONSTRAINT job_attempts_active_observation_within_lease CHECK (((lease_id IS NULL) OR (lease_expires_at_ms <= lease_issued_at_ms) OR ((changed_at_ms >= lease_issued_at_ms) AND (changed_at_ms < lease_expires_at_ms)))),
    CONSTRAINT job_attempts_classification_time_nonnegative CHECK ((classified_at_ms >= 0)),
    CONSTRAINT job_attempts_exposure_safety CHECK (((output_safety_schema = 1) AND (raw_log_disposition = 'persist'::text) AND ((secret_exposure_class <> 'readable_secret'::text) OR (effective_log_visibility = 'private'::text)))),
    CONSTRAINT job_attempts_failures_nonnegative CHECK ((lease_failures >= 0)),
    CONSTRAINT job_attempts_fence_nonnegative CHECK ((fencing_token >= 0)),
    CONSTRAINT job_attempts_lease_after_start CHECK (((lease_issued_at_ms IS NULL) OR ((started_at_ms IS NOT NULL) AND (lease_issued_at_ms >= started_at_ms)))),
    CONSTRAINT job_attempts_lease_fields_consistent CHECK ((((lease_id IS NULL) AND (runner_id IS NULL) AND (lease_issued_at_ms IS NULL) AND (lease_expires_at_ms IS NULL) AND (runner_session_id IS NULL) AND (runner_session_epoch IS NULL) AND (runner_generation IS NULL) AND (runner_slot IS NULL)) OR ((lease_id IS NOT NULL) AND (runner_id IS NOT NULL) AND (lease_issued_at_ms IS NOT NULL) AND (lease_expires_at_ms IS NOT NULL) AND (runner_session_id IS NOT NULL) AND (runner_session_epoch IS NOT NULL) AND (runner_generation IS NOT NULL) AND (runner_slot IS NOT NULL)))),
    CONSTRAINT job_attempts_lease_interval CHECK (((lease_id IS NULL) OR (lease_expires_at_ms > lease_issued_at_ms))),
    CONSTRAINT job_attempts_lifecycle CHECK ((lifecycle = ANY (ARRAY['queued'::text, 'leased'::text, 'preparing'::text, 'running'::text, 'cancelling'::text, 'finalizing'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text, 'timed_out'::text, 'skipped'::text, 'lost'::text]))),
    CONSTRAINT job_attempts_log_visibility CHECK (((requested_log_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])) AND (effective_log_visibility = ANY (ARRAY['private'::text, 'authenticated'::text, 'public'::text])))),
    CONSTRAINT job_attempts_log_visibility_cap CHECK (((effective_log_visibility = 'private'::text) OR ((effective_log_visibility = 'authenticated'::text) AND (requested_log_visibility = ANY (ARRAY['authenticated'::text, 'public'::text]))) OR ((effective_log_visibility = 'public'::text) AND (requested_log_visibility = 'public'::text)))),
    CONSTRAINT job_attempts_number_positive CHECK ((attempt_number > 0)),
    CONSTRAINT job_attempts_output_safety_reason_code CHECK ((output_safety_reason = ANY (ARRAY['repository_policy'::text, 'secret_exposure'::text]))),
    CONSTRAINT job_attempts_output_safety_schema CHECK ((output_safety_schema = 1)),
    CONSTRAINT job_attempts_raw_log_disposition CHECK ((raw_log_disposition = 'persist'::text)),
    CONSTRAINT job_attempts_runner_generation_positive CHECK (((runner_generation IS NULL) OR (runner_generation > 0))),
    CONSTRAINT job_attempts_runner_slot_range CHECK (((runner_slot IS NULL) OR ((runner_slot >= 1) AND (runner_slot <= 65535)))),
    CONSTRAINT job_attempts_secret_exposure_class CHECK ((secret_exposure_class = ANY (ARRAY['secretless'::text, 'capability_only'::text, 'readable_secret'::text]))),
    CONSTRAINT job_attempts_session_epoch_positive CHECK (((runner_session_epoch IS NULL) OR (runner_session_epoch > 0))),
    CONSTRAINT job_attempts_started_at_shape CHECK (((started_at_ms IS NULL) OR ((started_at_ms >= 0) AND (started_at_ms <= changed_at_ms)))),
    CONSTRAINT job_attempts_state_time_monotonic CHECK ((changed_at_ms >= queued_at_ms))
);

CREATE TABLE job_dependencies (
    run_id uuid NOT NULL,
    job_id uuid NOT NULL,
    prerequisite_job_id uuid NOT NULL,
    CONSTRAINT job_dependencies_no_self_edge CHECK ((job_id <> prerequisite_job_id))
);

CREATE TABLE job_missing_secret_bindings (
    attempt_id uuid NOT NULL,
    canonical_name text NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT job_missing_secret_bindings_created_at CHECK ((created_at_ms >= 0)),
    CONSTRAINT job_missing_secret_bindings_name CHECK (((canonical_name ~ '^[A-Z_][A-Z0-9_]*$'::text) AND (octet_length(canonical_name) <= 255)))
);

CREATE TABLE job_missing_variable_bindings (
    attempt_id uuid NOT NULL,
    canonical_name text NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT job_missing_variable_bindings_created_at CHECK ((created_at_ms >= 0)),
    CONSTRAINT job_missing_variable_bindings_name CHECK (((canonical_name ~ '^[A-Z_][A-Z0-9_]*$'::text) AND (octet_length(canonical_name) <= 255)))
);

CREATE TABLE job_secret_bindings (
    attempt_id uuid NOT NULL,
    canonical_name text NOT NULL,
    tenant_id text NOT NULL,
    grant_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    fencing_token bigint NOT NULL,
    binding_digest bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT job_secret_bindings_created_at CHECK ((created_at_ms >= 0)),
    CONSTRAINT job_secret_bindings_digest CHECK ((octet_length(binding_digest) = 32)),
    CONSTRAINT job_secret_bindings_fence CHECK (((fencing_token > 0) AND (lease_id <> '00000000-0000-0000-0000-000000000000'::uuid)))
);

CREATE TABLE job_secret_selections (
    attempt_id uuid NOT NULL,
    canonical_name text NOT NULL,
    tenant_id text NOT NULL,
    secret_id uuid NOT NULL,
    secret_version_id uuid NOT NULL,
    secret_version_number bigint NOT NULL,
    scope_kind text NOT NULL,
    environment_id uuid,
    binding_digest bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT job_secret_selections_created_at CHECK ((created_at_ms >= 0)),
    CONSTRAINT job_secret_selections_digest CHECK ((octet_length(binding_digest) = 32)),
    CONSTRAINT job_secret_selections_environment_shape CHECK (((scope_kind = 'environment'::text) = (environment_id IS NOT NULL))),
    CONSTRAINT job_secret_selections_name CHECK (((canonical_name ~ '^[A-Z_][A-Z0-9_]*$'::text) AND (octet_length(canonical_name) <= 255))),
    CONSTRAINT job_secret_selections_scope CHECK ((scope_kind = ANY (ARRAY['tenant'::text, 'repository'::text, 'environment'::text])))
);

CREATE TABLE job_variable_bindings (
    attempt_id uuid NOT NULL,
    canonical_name text NOT NULL,
    tenant_id text NOT NULL,
    variable_id uuid NOT NULL,
    variable_version_id uuid NOT NULL,
    variable_version_number bigint NOT NULL,
    scope_kind text NOT NULL,
    environment_id uuid,
    binding_digest bytea NOT NULL,
    created_at_ms bigint NOT NULL,
    CONSTRAINT job_variable_bindings_created_at CHECK ((created_at_ms >= 0)),
    CONSTRAINT job_variable_bindings_digest CHECK ((octet_length(binding_digest) = 32)),
    CONSTRAINT job_variable_bindings_name CHECK (((canonical_name ~ '^[A-Z_][A-Z0-9_]*$'::text) AND (octet_length(canonical_name) <= 255))),
    CONSTRAINT job_variable_bindings_scope CHECK ((((scope_kind = 'repository'::text) AND (environment_id IS NULL)) OR ((scope_kind = 'environment'::text) AND (environment_id IS NOT NULL))))
);

CREATE TABLE jobs (
    id uuid NOT NULL,
    run_id uuid NOT NULL,
    job_key text NOT NULL,
    display_name text NOT NULL,
    job_ir_digest bytea NOT NULL,
    job_ir_object_key text NOT NULL,
    requirements jsonb NOT NULL,
    created_at_ms bigint NOT NULL,
    admission_epoch integer NOT NULL,
    job_ir_schema integer NOT NULL,
    job_ir_size_bytes bigint NOT NULL,
    CONSTRAINT jobs_admission_epoch_exact CHECK ((admission_epoch = 1)),
    CONSTRAINT jobs_current_admission_metadata CHECK (((admission_epoch = 1) AND (job_ir_schema = 1) AND ((job_ir_size_bytes >= 1) AND (job_ir_size_bytes <= 16777216)) AND (requirements @> '{"schema_version": 1}'::jsonb) AND (requirements ? 'resource_allocation'::text))),
    CONSTRAINT jobs_ir_object_key_nonempty CHECK ((length(job_ir_object_key) > 0)),
    CONSTRAINT jobs_ir_sha256 CHECK ((octet_length(job_ir_digest) = 32)),
    CONSTRAINT jobs_key_nonempty CHECK ((length(job_key) > 0))
);

CREATE TABLE managed_secret_delivery_operations (
    tenant_id text NOT NULL,
    operation_id uuid NOT NULL,
    repository_id uuid NOT NULL,
    run_id uuid NOT NULL,
    job_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    lease_id uuid NOT NULL,
    fencing_token bigint NOT NULL,
    runner_id uuid NOT NULL,
    runner_session_id uuid NOT NULL,
    runner_session_epoch bigint CONSTRAINT managed_secret_delivery_operation_runner_session_epoch_not_null NOT NULL,
    runner_generation bigint NOT NULL,
    runner_slot smallint NOT NULL,
    runtime_context_digest bytea CONSTRAINT managed_secret_delivery_operati_runtime_context_digest_not_null NOT NULL,
    binding_set_digest bytea NOT NULL,
    authority_evidence_digest bytea CONSTRAINT managed_secret_delivery_oper_authority_evidence_digest_not_null NOT NULL,
    credential_key_id text NOT NULL,
    credential_sha256 bytea NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    created_at_ms bigint NOT NULL,
    usable_until_ms bigint NOT NULL,
    acknowledged_at_ms bigint,
    CONSTRAINT managed_secret_delivery_operations_digests CHECK (((octet_length(runtime_context_digest) = 32) AND (octet_length(binding_set_digest) = 32) AND (octet_length(authority_evidence_digest) = 32) AND (octet_length(credential_sha256) = 32))),
    CONSTRAINT managed_secret_delivery_operations_fences_positive CHECK (((fencing_token > 0) AND (runner_session_epoch > 0) AND (runner_generation > 0) AND (runner_slot > 0))),
    CONSTRAINT managed_secret_delivery_operations_key_shape CHECK ((((octet_length(credential_key_id) >= 1) AND (octet_length(credential_key_id) <= 128)) AND (credential_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$'::text))),
    CONSTRAINT managed_secret_delivery_operations_lifetime CHECK (((created_at_ms >= 0) AND (usable_until_ms > created_at_ms))),
    CONSTRAINT managed_secret_delivery_operations_state CHECK ((state = ANY (ARRAY['pending'::text, 'acknowledged'::text, 'expired'::text]))),
    CONSTRAINT managed_secret_delivery_operations_state_shape CHECK (((((state = 'pending'::text) AND (acknowledged_at_ms IS NULL)) OR ((state = 'acknowledged'::text) AND (acknowledged_at_ms >= created_at_ms) AND (acknowledged_at_ms < usable_until_ms)) OR ((state = 'expired'::text) AND (acknowledged_at_ms IS NULL))) IS TRUE))
);

CREATE TABLE protected_environment_approval_decisions (
    tenant_id text NOT NULL,
    request_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    decision text NOT NULL,
    reason text,
    decided_at_ms bigint NOT NULL,
    CONSTRAINT protected_environment_approval_decisions_decision CHECK ((decision = ANY (ARRAY['approve'::text, 'reject'::text]))),
    CONSTRAINT protected_environment_approval_decisions_reason_code CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['policy_reviewed'::text, 'change_reviewed'::text, 'security_reviewed'::text, 'administrative_review'::text]))))
);

CREATE TABLE protected_environment_approval_requests (
    tenant_id text NOT NULL,
    repository_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    run_id uuid NOT NULL,
    job_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
