    CONSTRAINT runner_operation_receipts_sha256 CHECK ((octet_length(request_digest) = 32)),
    CONSTRAINT runner_operation_receipts_slot_range CHECK (((runner_slot >= 1) AND (runner_slot <= 65535)))
);

