    CONSTRAINT workflow_artifact_commits_digest CHECK ((octet_length(list_digest) = 32)),
    CONSTRAINT workflow_artifact_commits_size CHECK ((size_bytes >= 0))
);

CREATE TABLE workflow_artifact_blocks (
